/* ÇEVİRİ nl · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("nl","olay",{
"OLAYLAR:1299-01:0":{"b": ["Stichting van het Osmaanse beylik", "9f0b7c0a"], "d": ["Het moment waarop Osman Gazi van de Kayı-stam rond Söğüt en Domaniç zelfstandig begon op te treden, geldt traditioneel als het begin van de Osmaanse staat; sommige historici beschouwen de overwinning bij Bapheus in 1302 als het eigenlijke keerpunt. Dankzij zijn ligging aan de Byzantijnse grens groeide het beylik snel in macht door ghazi-strooptochten. In de context van het uiteenvallen van de Seltsjoekse erfenis verzamelde Osman Gazi ahi's, ghazi's en nomadische Turkmenen om zich heen; zijn band met sjeik Edebali wordt beschouwd als de basis van de morele legitimiteit van het beylik. Andere plaatsen die op dezelfde datum werden toegevoegd: İnegöl, Yarhisar.", "9d689d45"]},
"OLAYLAR:1326-04-06:0":{"b": ["Verovering van Bursa", "98c727fa"], "d": ["Bursa, dat jarenlang geblokkeerd was, gaf zich over aan Orhan Gazi, die de laatste fase van het beleg leidde; de stad werd de eerste grote hoofdstad van het beylik. Volgens de overlevering werd het nieuws van de verovering aan de stervende Osman Gazi gebracht; Osman Gazi werd conform zijn testament in Bursa begraven. De stad werd snel voorzien van moskeeën, imarets en madrasa's en werd het model voor het vroege Osmaanse stedenbouwkundige beleid.", "9ede6ee9"]},
"OLAYLAR:1331-03-02:0":{"b": ["Verovering van İznik", "a846a811"], "d": ["İznik (Nicaea), een van de belangrijkste centra van Byzantium in Anatolië, gaf zich na de overwinning bij Pelekanon in 1329 over aan Orhan Gazi omdat het alle hoop op verzet had verloren. Hier werd de eerste Osmaanse madrasa gesticht en geleerden zoals Dâvûd-i Kayserî begonnen er les te geven; de stad werd het wetenschappelijk centrum van de vroege periode. De Hagia Sophia-kerk werd tot moskee omgevormd, een vroeg voorbeeld van de veroveringstraditie.", "8fd3bfb5"]},
"OLAYLAR:1337-01-01:0":{"b": ["Verovering van İzmit", "06a35035"], "d": ["Met de val van İzmit (Nicomedia) kwam ook de laatste belangrijke vesting van Byzantium aan de Anatolische kant onder Osmaans bestuur; het hele schiereiland Kocaeli tot aan de overkant van Constantinopel werd Osmaans grondgebied. Zo beheerste het beylik de gehele zuid- en oostkust van de Zee van Marmara en legde het de basis voor de oversteek naar Rumelië.", "f677745c"]},
"OLAYLAR:1352-03-01:0":{"b": ["Burcht Çimpe — oversteek naar Rumelië", "c2f0a07d"], "d": ["Süleyman Pasja, zoon van Orhan Gazi, had de burcht Çimpe, die hem tijdens de Byzantijnse burgeroorlog was gegeven, in 1352 als basis genomen; na de grote aardbeving die Gallipoli in maart 1354 verwoestte, werden de verlaten vestingen snel versterkt en werd het schiereiland een blijvende Osmaanse bruggenhoofd. Deze stap, ondersteund door de vestiging van uit Anatolië overgebrachte Turkmeense bevolking, vormt het begin van de Osmaanse aanwezigheid op het Europese continent, die meer dan 550 jaar zou duren.", "4857333a"]},
"OLAYLAR:1361-05-05:0":{"b": ["Verovering van Edirne", "2f54ebb0"], "d": ["De inname van Edirne (Adrianopel), de sleutelstad van Thracië, bepaalde de hoofdbasis en de richting van de Balkanveroveringen; de datum van verovering is in de bronnen omstreden tussen 1361 en 1369. De stad werd kort daarna tot hoofdstad gemaakt, wat aankondigde dat het zwaartepunt van de staat naar Rumelië verschoof; het bleef ongeveer 90 jaar lang zetel van het rijk, tot de verovering van Constantinopel.", "25bd644f"]},
"OLAYLAR:1362-03:0":{"b": ["Murad I besteeg de troon", "f8d48a26"], "d": ["Murad I (Hüdavendigâr), die na de dood van Orhan Gazi de troon besteeg, voerde de staat tijdens zijn regering van 27 jaar van een grensbeylik naar het skelet van een keizerrijk. Met het pençik-systeem werd de basis gelegd voor het Janitsarenkorps, het timar-stelsel werd verbreed, het beylerbeylik van Rumelië werd opgericht en de vizierschap werd versterkt. De Balkanveroveringen werden onder zijn bewind een systematische staatspolitiek.", "d463078a"]},
"OLAYLAR:1389-06-15:0":{"b": ["Eerste Slag bij Kosovo — martelaarschap van Murad I", "10b8ddc9"], "d": ["De Balkanalliantie onder leiding van vorst Lazar werd op het Merelveld (Kosovo Polje) beslissend verslagen; Servië kwam onder Osmaanse opperheerschappij. Murad I, die het slagveld bezocht, werd door de Servische edelman Miloš Obilić met een dolk gedood — hij is de enige Osmaanse sultan die op het slagveld is omgekomen. In het legerkamp werd Yıldırım Bayezid in zijn plaats op de troon gezet; zijn broer Yakub Çelebi werd gewurgd, een van de eerste bekende voorbeelden van de praktijk van broedermoord.", "153449fe"]},
"OLAYLAR:1396-09-25:0":{"b": ["Overwinning bij Nikopolis", "75716e96"], "d": ["Het grote kruisvaardersleger dat op oproep van de Hongaarse koning Sigismund was bijeengekomen, waaraan ook Frans-Bourgondische ridders deelnamen, werd bij Nikopolis aan de Donau door Yıldırım Bayezid zwaar verslagen. De overwinning bevestigde de Osmaanse overheersing over Bulgarije; gedurende een generatie kon er in Europa geen grote kruistocht meer worden georganiseerd.", "0d06e36c"]},
"OLAYLAR:1402-07-28:0":{"b": ["Slag bij Ankara — begin van het Interregnum", "b4a99d96"], "d": ["In de zware nederlaag tegen het leger van Timur op de vlakte van Çubuk werd Yıldırım Bayezid gevangengenomen en hij stierf enkele maanden later in gevangenschap. Timur liet de Anatolische beyliks herrijzen; het Osmaanse grondgebied werd verdeeld onder de zonen van Bayezid en een 11 jaar durende troonstrijd (het Interregnum, Fetret Devri) begon. Deze periode, de zwaarste crisis sinds de oprichting van de staat, prentte het belang van een gecentraliseerde structuur in het Osmaanse geheugen. Andere plaatsen die op dezelfde datum verloren gingen: Datça, Marmaris, Fethiye (Makri), Söke, Kütahya, Afyon, Isparta, Manisa, Aydın, Denizli, Muğla, Antalya, Konya, Karaman, Kayseri, Kastamonu, Bartın, Safranbolu, Samsun, Sivas, Malatya, Beyşehir, Sivrihisar, Kırşehir, Çorum, Çankırı, Yenişehir (Bursa), İnegöl, Aydos Kalesi, Geyve, Köprühisar (Yenişehir), Marmaracık, Akhisar (Pamukova), Mekece, Kestel, Ulubat, Harmankaya, Akyazı, İmralı Adası, Kandıra, Mudanya, Yalova, Karamürsel, Armutlu, Gemlik (Kios), Söğüt, Bilecik, Eskişehir, Bursa, İznik, İzmit, Balıkesir, Çanakkale, Bergama, Amasya, Tokat, Çorlu, Lüleburgaz, Malkara, Keşan, İpsala, Kilitbahir, Çirmen, Eski Zağra (Stara Zagora), Tatarpazarcığı, İhtiman, Köstendil, Petriç, Nevrokop (Gotse Delčev), Drama, Gelibolu, Çimpe, Edirne, Dimetoka, Kırklareli, Tekirdağ, Filibe, Sofia, Niş, Vidin, Tırnova, Varna, Şumnu, Silistre, Nikopol, Rusçuk, Thessaloniki, Serez, Kavala, Üsküp, Manastır, Ohri, Yenişehir (Larissa), Tırhala, İzdin (Lamia), Plevne, Gümülcine, Biga, Domaniç, Kulacahisar, Karacahisar, Yarhisar, Dimbos, Kite (Kete), Lefke (Osmaneli), Leblebicihisar, Karaçepüş, Karatigin, Absu (Hypsu), Adranos (Orhaneli), Pelekanon (Eskihisar), Gebze, Hereke, Samandıra, Kirmasti (M.Kemalpaşa), Mihaliç (Karacabey), Köstence, Gölyazı (Apollonia).", "d34e55d5"]},
"OLAYLAR:1413-07-05:0":{"b": ["Çelebi Mehmed herstelde de eenheid", "03413dfd"], "d": ["In de laatste afrekening tussen de broers versloeg Mehmed I Mûsâ Çelebi bij Çamurlu en verenigde het grondgebied van het land onder één bestuur; daarom wordt hij beschouwd als de 'tweede stichter van de staat'. Tijdens zijn regering werd de aangetaste staatsstructuur hersteld, werden de betrekkingen met de Anatolische beyliks in evenwicht gebracht en werd in Rumelië een omzichtig vredesbeleid gevoerd.", "d8f535c2"]},
"OLAYLAR:1416-05-01:0":{"b": ["Opstand van sjeik Bedreddin", "e0a072ca"], "d": ["De religieus-maatschappelijke beweging rond sjeik Bedreddin, een groot jurist en mysticus die tijdens het Interregnum kazasker was geweest, brak gelijktijdig uit met de opstanden van Börklüce Mustafa in Karaburun en Torlak Kemal in Manisa. De opstanden werden bloedig neergeslagen; Bedreddin werd in Deliorman gevangengenomen en in Serres geëxecuteerd. De gebeurtenis liet diepe sporen na in de literatuur en geschiedschrijving als de vroegste grote sociaal-messiaanse opstand in de Osmaanse geschiedenis.", "1cf72ec4"]},
"OLAYLAR:1444-11-10:0":{"b": ["Overwinning bij Varna", "f739eedc"], "d": ["Het Hongaars-Poolse kruisvaardersleger, dat het verdrag van Szeged had verbroken en naar het zuiden was getrokken, werd bij Varna vernietigd door Murad II, die was teruggekeerd aan het hoofd van het leger terwijl hij van de troon had afgezien; de jonge koning Ladislaus III sneuvelde op het slagveld. De overwinning nam de laatste grote kans op buitenlandse interventie om de Osmaanse aanwezigheid op de Balkan te liquideren weg en verzekerde de weg naar de verovering van Constantinopel.", "43adf0fb"]},
"OLAYLAR:1448-10-17:0":{"b": ["Tweede Slag bij Kosovo", "ebe0b662"], "d": ["Het leger van János Hunyadi, dat wraak wilde nemen voor Varna, werd na een driedaagse verbeten strijd door Murad II beslissend verslagen. Dit is de laatste grote veldslag die de kruisvaarders op de Balkan tegen de Osmanen aangingen; met deze overwinning werd de Osmaanse heerschappij ten zuiden van de Donau onomkeerbaar gevestigd.", "ea3ae23b"]},
"OLAYLAR:1453-05-29:0":{"b": ["Verovering van Constantinopel", "583d5e3e"], "d": ["Na een beleg van vierenvijftig dagen (6 april–29 mei 1453) drong het Osmaanse leger op de ochtend van 29 mei over de muren de stad binnen; de laatste keizer Constantijn XI sneuvelde in de gevechten en het 1100 jaar oude Oost-Romeinse Rijk verdween uit de geschiedenis. De jonge sultan nam de titel 'Fâtih' (de Veroveraar) aan, maakte de stad tot hoofdstad en veranderde de Hagia Sophia in een moskee; de stad werd binnen korte tijd door vestiging en wederopbouw nieuw leven ingeblazen. Volgens de TDV werden Silivri en Vize pas in 1453 definitief veroverd; volgens het TDV-lemma Limnos kwam het eiland onmiddellijk na de verovering onder Osmaans bestuur en werd het onder voorwaarde van schatting aan de familie Gattilusio gelaten. In de atlas staan Silivri, Vize en Limnos vanaf deze dag van Byzantium naar het Osmaanse Rijk geschreven (Limnos als schatplichtig). Het gieten van reusachtige kanonnen, het over land slepen van schepen en de belegeringsopstelling voor de muren worden beschouwd als het toppunt van de militaire techniek van die tijd. De verovering geldt in de Europese geschiedschrijving als een van de symbolische data voor het einde van de Middeleeuwen.", "d4b39486"]},
"OLAYLAR:1461-08-15:0":{"b": ["Verovering van Trebizonde", "15f52403"], "d": ["Na een moeizame Zwarte Zee-veldtocht van Mehmed de Veroveraar, die gelijktijdig met leger en vloot werd gevoerd, gaf het Keizerrijk Trebizonde zich over; met het opruimen van dit laatste Byzantijnse restant in Anatolië kwam de gehele zuidkust van de Zwarte Zee onder Osmaanse heerschappij. Het beëindigen van de Komnenen-dynastie versterkte de aanspraak van de Veroveraar als 'heerser van twee zeeën en twee continenten'. Andere plaatsen die op dezelfde datum werden toegevoegd: Giresun, Rize.", "ca6ead13"]},
"OLAYLAR:1473-01-01:0":{"b": ["Definitieve verovering van Silifke — breken van het laatste verzet van de Karamanoğulları", "d988bee4"], "d": ["De burcht Silifke had zich in 1472 eenmaal overgegeven aan Gedik Ahmed Pasja, maar datzelfde jaar had Karamanoğlu Kasım Bey met hulp van de kruisvaardersvloot in de Middellandse Zee de burcht heroverd. Na de overwinning bij Otlukbeli droeg de Veroveraar zijn zoon en Gedik Ahmed Pasja op de regio definitief in te nemen; met hulp van de oude Osmaanse artilleristen werd het kruitmagazijn in brand gestoken en de burcht snel ingenomen. Zo werd het laatste verzet van de Karamanoğulları in het Taşeli-İçel-gebergte gebroken; de liquidatie van het beylik zou in 1474 worden voltooid.", "e9814184"]},
"OLAYLAR:1473-08-11:0":{"b": ["Slag bij Otlukbeli", "42c7194e"], "d": ["Uzun Hasan, de heerser van de Akkoyunlu, die in het oosten een grote macht was geworden en een bondgenootschap met Venetië had gesloten, werd bij Otlukbeli zwaar verslagen door het met vuurwapens uitgeruste leger van de Veroveraar. De overwinning bevestigde de Osmaanse superioriteit in Anatolië en was tevens een vroeg bewijs van de superioriteit van een centraal leger dat kanonnen en geweren gebruikte tegenover een klassiek leger. Volgens het TDV-lemma Gümüşhane stond de stad sinds 1467 onder Akkoyunlu-heerschappij; deze heerschappij eindigde met de nederlaag bij Otlukbeli en Gümüşhane kwam definitief onder Osmaanse heerschappij.", "63e0811f"]},
"OLAYLAR:1475-06-06:0":{"b": ["Krim komt onder Osmaanse bescherming", "44e3f7c8"], "d": ["De vloot onder bevel van Gedik Ahmed Pasja veroverde de zuidelijke kuststeden van de Krim, met name het Genuese Kaffa; deze kusten werden rechtstreeks Osmaanse sandjak. Het Krim-khanaat werd onder Mengli Giray een bevoorrechte vazalstaat die de Osmaanse opperheerschappij erkende en drie eeuwen lang een hoeksteen van de noordelijke politiek; de Zwarte Zee veranderde feitelijk in een Osmaanse binnenzee. Andere plaatsen die op dezelfde datum werden toegevoegd: Bahçesaray, Kerç, Azak.", "a3448d71"]},
"OLAYLAR:1481-05-03:0":{"b": ["Dood van de Veroveraar — kwestie Cem Sultan", "190ecf01"], "d": ["Bij de plotselinge dood van de Veroveraar tijdens de veldtocht besteeg Bayezid II de troon; zijn broer Cem Sultan liet in Bursa op eigen aanspraak op het sultanaat de khutba in zijn naam lezen en munten slaan. Na zijn nederlaag vond hij eerst onderdak bij de Mamelukken en daarna bij de ridders van Rhodos; in handen van de ridders en het pausdom werd Cem een pasmunt in de Europese diplomatie en hij stierf in 1495 in Napels. Dit voorval dwong het Osmaanse buitenlandse beleid vijftien jaar lang tot voorzichtigheid.", "7e488d7b"]},
"OLAYLAR:1514-08-23:0":{"b": ["Overwinning bij Çaldıran", "fea64ebb"], "d": ["Yavuz Sultan Selim, die de door de Safawidische propaganda in Anatolië ontstane dreiging bij de wortel wilde oplossen, bracht het leger van sjah Ismail op de vlakte van Çaldıran met zijn overwicht aan kanonnen en geweren een zware nederlaag toe. Tabriz werd binnengetrokken; Oost- en Zuidoost-Anatolië en de lijn Mosul–Diyarbakır werden bij het Osmaanse bestuur gevoegd. De aansluiting van de Koerdische beys bij de Osmanen dankzij de inspanningen van İdrîs-i Bitlisî legde het kader van de oostgrens vast dat eeuwenlang zou standhouden.", "67b03a64"]},
"OLAYLAR:1516-08-24:0":{"b": ["Overwinning bij Marj Dabiq", "07d254d3"], "d": ["Het Mamelukse leger werd binnen enkele uren bij Marj Dabiq, ten noorden van Aleppo, uiteengeslagen; de oude sultan Qansuh al-Ghawri stierf tijdens de slag. Met de overwinning, die de poorten van Aleppo en Damascus wijd opende, kwamen Syrië, Libanon en Palestina onder Osmaans bestuur; de weg naar de Egyptische veldtocht, die het einde van de Mamelukkenstaat zou betekenen, lag open.", "c4b15f39"]},
"OLAYLAR:1517-01-22:0":{"b": ["Ridaniya — verovering van Egypte en het kalifaat", "caf378d6"], "d": ["Het Osmaanse leger stak snel de Sinaïwoestijn over, doorbrak de verdedigingslinie van Tumanbay bij Ridaniya en trok Caïro binnen; Tumanbay, die het verzet voortzette, werd gevangengenomen en geëxecuteerd en de Mamelukkenstaat verdween uit de geschiedenis. Egypte, de Hidjaz en de heilige steden kwamen onder Osmaans bestuur; de Abbasidische kalief en de heilige relieken werden naar Constantinopel gebracht. Met de overgang van het kalifaat naar de Osmaanse dynastie namen de sultans de aanspraak op het leiderschap van de islamitische wereld op zich; de controle over de Specerijenroute bezorgde het rijk ook grote inkomsten. Andere plaatsen die op dezelfde datum werden toegevoegd: Akko, Ma'an, Sidon, Kerak.", "a0cc8fdc"]},
"OLAYLAR:1520-09-30:0":{"b": ["Süleyman de Wetgever besteeg de troon", "f6512269"], "d": ["De 46 jaar durende regering van Süleyman I, die na de dood van Yavuz als enige mannelijke erfgenaam de troon besteeg, wordt beschouwd als het politieke, militaire, juridische en culturele hoogtepunt van het rijk. Zijn kanunnames, die het gewoonterecht systematiseerden, bezorgden hem de titel 'Kanunî' (de Wetgever); in het Westen werd hij bekend als 'de Prachtige' (Magnificent). De werken van architect Sinan, de gouden eeuw van de divanliteratuur en de Middellandse Zee-overmacht van de vloot zijn de symbolen van deze periode.", "cda7a2fb"]},
"OLAYLAR:1521-08-29:0":{"b": ["Verovering van Belgrado", "59ef5cec"], "d": ["Belgrado, dat de Veroveraar in 1456 niet had kunnen innemen en dat gold als 'het slot van Midden-Europa', viel tijdens de eerste veldtocht van Süleyman na een beleg bij de samenvloeiing van Donau en Sava. De zuidelijke verdedigingslinie van Hongarije was daarmee ingestort; met deze verovering ging de deur open naar de Midden-Europese campagne die vijf jaar later naar Mohács en twintig jaar later naar de annexatie van Boeda zou leiden.", "69dbb7cc"]},
"OLAYLAR:1522-12-21:0":{"b": ["Verovering van Rhodos", "807bbb1e"], "d": ["Rhodos, de basis van de Johannieters die de zeeroutes van de oostelijke Middellandse Zee en de pelgrimsroute bedreigden, gaf zich na een maandenlang bloedig beleg bij verdrag over; de ridders kregen toestemming om de eilanden vrij te verlaten (later vestigden zij zich op Malta). De veiligheid van de Anatolische kusten was verzekerd en de zeeroute tussen Constantinopel en Egypte kwam onder ononderbroken Osmaanse controle.", "aeedfb16"]},
"OLAYLAR:1526-08-29:0":{"b": ["Slag bij Mohács", "f3418b0d"], "d": ["Het Hongaarse leger werd op de vlakte van Mohács binnen ongeveer twee uur vernietigd door kanonvuur en manoeuvreeroverwicht; koning Lodewijk II kwam om in een moeras terwijl hij vluchtte. Mohács, een van de snelst gewonnen grote veldslagen uit de Osmaanse geschiedenis, maakte feitelijk een einde aan het onafhankelijke Hongaarse koninkrijk en opende het tijdperk van de Osmaans-Habsburgse rivaliteit in Midden-Europa.", "48967894"]},
"OLAYLAR:1529-09-27:0":{"b": ["Eerste Beleg van Wenen", "dc49ea4f"], "d": ["Tijdens de veldtocht die werd ondernomen tegen de Habsburgse aanspraken op de Hongaarse troon, belegerde het Osmaanse leger Wenen; omdat de zware kanonnen onderweg waren achtergelaten, de winter vroeg inviel en er bevoorradingsproblemen waren, werd het beleg na drie weken opgeheven. Hoewel de stad niet werd ingenomen, bleef de Osmaanse invloed in Hongarije behouden; Wenen markeerde de grens van de logistische reikwijdte van het rijk in Midden-Europa.", "a49fc760"]},
"OLAYLAR:1534-12-04:0":{"b": ["Verovering van Bagdad — Irakeyn-veldtocht", "897092c3"], "d": ["Tijdens de veldtocht naar 'de twee Irak' (Arabisch Irak en Perzisch Irak) werd eerst Tabriz en daarna zonder strijd Bagdad binnengetrokken; de inname van de oude hoofdstad van de Abbasiden bezorgde de Osmaanse heerser groot aanzien in de islamitische wereld. Het mausoleum van Imam-ı Âzam Ebû Hanîfe werd hersteld; met de toevoeging van Bagdad en Basra bereikte het Osmaanse grondgebied de Perzische Golf. Andere plaatsen die op dezelfde datum werden toegevoegd: Kirkoek, Kerbela.", "f3f80434"]},
"OLAYLAR:1538-09-28:0":{"b": ["Zeeslag bij Preveza", "30dc0f97"], "d": ["De door de paus aangevoerde kruisvaardersvloot werd ondanks haar numerieke overwicht bij Preveza uiteengeslagen door Barbarossa's tactiek, waarbij hij wind en kust meesterlijk benutte; Andrea Doria verliet het slagveld. De overwinning vestigde de onbetwiste Osmaanse zeemacht in de Middellandse Zee, die ongeveer 33 jaar zou duren; zij is de symbolische datum van de dag van de marine in de Turkse zeevaartstraditie. Andere plaatsen die op dezelfde datum werden toegevoegd: Aden, Bender.", "0411d92f"]},
"OLAYLAR:1541-08-29:0":{"b": ["Annexatie van Boeda — Hongarije Osmaanse provincie", "db53b244"], "d": ["Nadat Süleyman op een veldtocht was uitgetrokken vanwege de Habsburgse belegering van Boeda, nam hij na de bevrijding van de stad Midden-Hongarije rechtstreeks onder Osmaans bestuur en stichtte het beylerbeylik Boeda; Transsylvanië werd een autonoom prinsdom onder Osmaanse bescherming. Deze driedeling van Hongarije duurde ongeveer 150 jaar en vormde het blijvende Osmaanse bestuurlijke skelet in Midden-Europa.", "1eb63e33"]},
"OLAYLAR:1555-05-29:0":{"b": ["Vrede van Amasya", "a5afe0d1"], "d": ["Dit is het eerste officiële vredesverdrag dat een einde maakte aan de jarenlange Osmaans-Safawidische oorlogen. Bagdad en Irak bleven Osmaans, de grens in Oost-Anatolië werd voor het eerst wederzijds erkend; de Safawiden namen op zich de sjiitische propaganda in Osmaans gebied te staken, de Osmanen de veiligheid van Iraanse pelgrims bij doorreis. Het verdrag werd het eerste voorbeeld van een juridisch kader voor de betrekkingen tussen beide staten.", "220b198f"]},
"OLAYLAR:1566-09-07:0":{"b": ["Szigetvár — overlijden van Süleyman de Wetgever", "e2917ed2"], "d": ["De 72-jarige Süleyman stierf in zijn tent, enkele uren voor de val van de burcht Szigetvár die hij tijdens zijn dertiende veldtocht belegerde; Sokollu Mehmed Pasja hield de dood weken geheim opdat het leger niet uiteen zou vallen. De burcht werd ingenomen, maar de staat had zijn langstregerende en meest luisterrijke sultan verloren; zijn zoon Selim II besteeg de troon en het gewicht van de grootveziers in het staatsbestuur begon toe te nemen.", "62c468a1"]},
"OLAYLAR:1571-08-01:0":{"b": ["Verovering van Cyprus", "e364a2b3"], "d": ["In 1570 werd een landing uitgevoerd op het door Venetië bestuurde Cyprus; Nicosia viel snel, Famagusta gaf zich pas na een beleg van elf maanden over in augustus 1571. Het eiland, cruciaal voor de veiligheid van de handels- en pelgrimsroutes in de oostelijke Middellandse Zee, werd als beylerbeylik georganiseerd en met bevolking uit Anatolië bevolkt; de verovering was ook de aanleiding voor de grote kruisvaardersalliantie die tot Lepanto zou leiden.", "6dcfdc0f"]},
"OLAYLAR:1571-10-07:0":{"b": ["Nederlaag bij Lepanto (İnebahtı)", "6a1d44a9"], "d": ["De kruisvaardersvloot, die zich na de verovering van Cyprus had verenigd, onderschepte de Osmaanse vloot in de baai van Lepanto en vernietigde het grootste deel ervan; kapudan pasja Müezzinzâde Ali Pasja sneuvelde en alleen de vloot van Uluç Ali bleef gespaard. Na de ramp benoemde grootvizier Sokollu Mehmed Pasja Uluç Ali Pasja tot kapudan pasja met de opdracht de verspreide vloot te verzamelen en liet hij op alle scheepswerven van Constantinopel tot Alanya een nieuwe vloot bouwen; toch was de absolute superioriteit in de Middellandse Zee psychologisch aangetast.", "4cb5c93e"]},
"OLAYLAR:1596-10-26:0":{"b": ["Slag bij Mezőkeresztes", "da308ec5"], "d": ["In de grootste veldslag van de Lange Oorlog (1593–1606) herstelde het leger, waarvan Mehmed III zelf het bevel voerde, zich op het punt van uiteenvallen dankzij de aansporing van Hoca Sâdeddin Efendi en bracht het het Habsburgse leger een nederlaag toe. Zij geldt als de laatste grote klassieke veldslag die de Osmanen wonnen; dat de slag het algemene verloop van de oorlog niet veranderde, werd echter gezien als een teken van de slijtage van het militaire stelsel.", "77f2a384"]},
"OLAYLAR:1606-11-11:0":{"b": ["Vrede van Zsitvatorok", "39c01142"], "d": ["Met het verdrag dat een einde maakte aan de dertien jaar durende uitputtingsoorlog werd de Habsburgse heerser voor het eerst als 'Romeins keizer' als gelijke van de sultan beschouwd en werd de jaarlijkse schatting afgeschaft. Het gebiedsverlies was nagenoeg nihil; maar deze verandering in diplomatiek taalgebruik wordt gelezen als symbool van het einde van de Osmaanse aanspraak op absolute superioriteit tegenover Europa.", "99a455e7"]},
"OLAYLAR:1639-05-17:0":{"b": ["Verdrag van Qasr-i Shirin", "c1acf3af"], "d": ["Het verdrag dat werd gesloten nadat Murad IV Bagdad had heroverd (1638), beëindigde de meer dan honderd jaar durende Osmaans-Safawidische oorlogen. Bagdad en Irak bleven definitief Osmaans, Revan werd aan de Safawiden gelaten; de getrokken lijn werd met kleine wijzigingen de basis van de huidige grens tussen Turkije en Iran en geldt als een van de langstlevende grenzen ter wereld. Het verdrag liet Badra, Jassan, Mandali, Derteng en Derna aan de Osmanen; de grensvesting Zencir zou worden afgebroken, de dorpen ten westen ervan bleven Osmaans, die ten oosten ervan Iraans. De omgeving van de Zalim-burcht bij Şehrizor en Kızılca Kale bleven Osmaans, Avroman en Mihriban bleven Iraans; de burchten Kotur, Makû en Mağazberd zouden door beide partijen worden afgebroken.", "c2d59f3f"]},
"OLAYLAR:1669-09-06:0":{"b": ["Verovering van Kreta voltooid", "e0d85604"], "d": ["Het beleg van Candia, het laatste bedrijf van de Kretenzische oorlog die in 1645 begon, werd afgesloten met de driejarige vastberaden campagne van Fâzıl Ahmed Pasja; de Venetiaanse commandant Morosini droeg de stad bij verdrag over. De strijd van ongeveer een kwart eeuw ging de geschiedenis in als het langste beleg uit de Osmaanse geschiedenis; ook het laatste grote Latijnse bolwerk van de oostelijke Middellandse Zee kwam onder Osmaans bestuur. Drie kleine rotsvestingen aan de noordkust van het eiland — Souda, Spinalonga en Grambousa — bleven nog Venetiaans; omdat zij op afzonderlijke eilandjes liggen, kunnen zij op de kaart niet los van de rest van Kreta worden weergegeven.", "314efa97"]},
"OLAYLAR:1672-10-18:0":{"b": ["Verdrag van Buczacz — grootste uitgestrektheid", "b17b6e5a"], "d": ["Met het Verdrag van Buczacz, gesloten na de verovering van Kamjanets-Podilsky tijdens de Poolse veldtocht, werd Podolië bij het Osmaanse Rijk gevoegd en een deel van Oekraïne onder bescherming genomen. Het rijk bereikte zo zijn grootste uitgestrektheid in Europa; dit punt wordt beschouwd als het hoogtepunt van het tijdperk van expansie en tegelijk als de laatste schakel ervan.", "6d489670"]},
"OLAYLAR:1683-09-12:0":{"b": ["Mislukking van het Tweede Beleg van Wenen", "7d889252"], "d": ["Het twee maanden durende beleg van Wenen door Merzifonlu Kara Mustafa Pasja eindigde in een nederlaag door de plotselinge aanval die de Poolse koning Jan Sobieski vanaf de Kahlenberg inzette; het leger trok zich terug en liet zijn bagage achter, Merzifonlu werd in Belgrado geëxecuteerd. De oorlog die volgde op de na deze overwinning gevormde Heilige Liga duurde 16 jaar; deze nederlaag wordt aangewezen als het beginmoment van de grote achteruitgang in de Osmaanse geschiedenis.", "88ceb19f"]},
"OLAYLAR:1692-01-01:0":{"b": ["Verovering van de burcht Grambousa — een van de rotsvestingen van Kreta die Venetiaans bleven", "3ddf9eeb"], "d": ["Hoewel de verovering van Kreta met de overgave van Candia in 1669 grotendeels voltooid werd geacht, bleef de rotsachtige eilandvesting Grambousa aan de noordwestpunt van het eiland nog drieëntwintig jaar in Venetiaanse handen. Met de inname ervan in 1692 werd een van de drie Venetiaanse overblijfselen op Kreta opgeruimd; Souda en Spinalonga zouden de Morea-veldtocht van 1715 moeten afwachten.", "05e94fe9"]},
"OLAYLAR:1699-01-26:0":{"b": ["Vrede van Karlowitz — eerste grote gebiedsverlies", "8f7e2546"], "d": ["Met Karlowitz, dat een einde maakte aan de zestien jaar durende oorlogen van de Heilige Liga, werden Hongarije en Transsylvanië aan Oostenrijk, Podolië aan Polen en de Morea en de kust van Dalmatië aan Venetië gelaten. Voor het eerst in de Osmaanse geschiedenis ging grondgebied op deze schaal aan de onderhandelingstafel en blijvend verloren; het verdrag wordt beschouwd als het inleidende document van het nieuwe tijdperk waarin het rijk tegenover Europa in de verdediging ging, en is ook een keerpunt in de Osmaanse diplomatieke geschiedenis. Plaatsen die op dezelfde dag in de atlas van hand wisselden: Kostajnica en Jasenovac (van de Osmanen naar de Habsburgers; de verdragstekst laat Castanoviz in handen van de keizer, de overdrachtsdag van Jasenovac staat niet in de bron, de verdragsdag is ingevuld) en Preveza (van Venetië naar de Osmanen; TDV karlofca: volgens de bepaling die op 24 Receb 1110 / 26 januari 1699 werd ondertekend, werden de door Venetië bezette plaatsen ten noorden van de Golf van Lepanto teruggegeven). De atlas schrijft Kostajnica en Jasenovac bovendien aan de Habsburgse kant toe, Uman en Vinnytsia in Rechteroever-Oekraïne van de Osmanen aan Polen (TDV merzifonlu-kara-mustafa-pasa; IEU Vinnytsia: 1672-99 Turkse heerschappij) en Nadin in Dalmatië aan Venetië (een plaatsspecifieke overdrachtsdag staat niet in de bron, de verdragsdag is ingevuld; de periodegrenzen van Nadin zijn niet met een bron bevestigd — verklaarde benadering). Ook Vonitsa ten noorden van de Golf van Lepanto wordt van Venetië aan de Osmanen teruggegeven (TDV karlofca); in Dalmatië behoort Vrana (Urana) tot de plaatsen die Venetiaans bleven (periodegrens niet bevestigd — verklaard).", "0909e24e"]},
"OLAYLAR:1711-07-19:0":{"b": ["Overwinning bij de Proet", "2583572f"], "d": ["Vanwege de kwestie van de Zweedse koning, die na de nederlaag bij Poltava bij de Osmanen onderdak had gezocht, werd in de oorlog die uitbrak het leger van tsaar Peter I aan de oever van de Proet omsingeld en gedwongen zich over te geven. Met het gesloten verdrag werd Azak teruggenomen; dat het leger niet werd vernietigd en de tsaar vrij werd gelaten, ging de geschiedenis in als een beslissing waarover tot op de dag van vandaag wordt gediscussieerd.", "ce9c2996"]},
"OLAYLAR:1715-01-01:0":{"b": ["Verovering van de burchten Souda en Spinalonga — uitwissing van het laatste Venetiaanse spoor op Kreta", "7261f7ba"], "d": ["Drieëntwintig jaar na de val van Grambousa in 1692 werden met een zijtak van de Morea-veldtocht ook de burchten Souda en Spinalonga, de laatste twee steunpunten van Venetië op Kreta, veroverd. Zo was de verovering van Kreta, die in 1645 begon, na zesenveertig jaar tot op de laatste centimeter van het eiland voltooid.", "d2044cae"]},
"OLAYLAR:1730-09-25:0":{"b": ["Opstand van Patrona Halil", "100941a4"], "d": ["De mislukking aan het Iraanse front, de belastingen en de woede over de weelde in de kringen rond het paleis ontaardden onder leiding van de badhuisknecht Patrona Halil in een grote opstand. Grootvizier İbrahim Pasja werd gedood, Ahmed III werd afgezet en het Tulpentijdperk kwam ten einde; dat de opstandelingen maandenlang over de stad heersten, toonde op treffende wijze de kwetsbaarheid van het centrale gezag.", "d87eea77"]},
"OLAYLAR:1739-09-18:0":{"b": ["Verdrag van Belgrado — herovering van Belgrado, Smederevo en Noord-Servië", "ba7f8e46"], "d": ["Aan het einde van de oorlog die aan twee fronten tegen Oostenrijk en Rusland werd gevoerd (1736–1739) werden Belgrado en Noord-Servië heroverd; Rusland nam op zich Azak te ontmantelen en geen vloot op de Zwarte Zee te hebben. Het verdrag, beschouwd als het laatste grote succes van de Osmaanse diplomatie en het Osmaanse leger in de 18e eeuw, bezorgde het rijk een vredesperiode van een kwart eeuw. Andere plaatsen die op dezelfde dag in de atlas van Oostenrijk naar de Osmanen terugkeerden: Hisarcık (Grocka) (abi-centrumketen van Belgrado; TDV belgrad), Craiova, Râmnicu Vâlcea (Rimnik) en Turnu Severin (terugkeer van Klein-Walachije naar de Osmanen, naar het vazalschap van Walachije). Bosanski Brod en Bosanska Dubica in de Sava-strook keren in de atlas op 28 september 1739 terug naar de Osmanen (TDV bosna-hersek; TDV mahmud-i--osmanli: 28 september 1739). Ook Târgu Jiu in Klein-Walachije keert op dezelfde dag terug naar de Osmanen.", "118d49db"]},
"OLAYLAR:1770-07-06:0":{"b": ["Overval bij Çeşme", "840b30bd"], "d": ["De Russische vloot, die met Engelse steun de Middellandse Zee had bereikt, overviel de Osmaanse vloot in de haven van Çeşme waar zij beschutting had gezocht met brandschepen en verbrandde haar nagenoeg volledig. Rusland verscheen voor het eerst als grote zeemacht in de Middellandse Zee; de ramp was een van de slagen die het lot van de oorlog naar Küçük Kaynarca in 1774 bepaalden en maakte de behoefte aan een grondige hervorming van de vloot duidelijk.", "5b133a56"]},
"OLAYLAR:1774-07-21:0":{"b": ["Verdrag van Küçük Kaynarca", "2776dcdb"], "d": ["Met Küçük Kaynarca, dat de oorlog van 1768–1774 beëindigde en geldt als een van de zwaarste verdragen uit de Osmaanse geschiedenis, kreeg het Krim-khanaat 'onafhankelijkheid' — in feite werd een Russische invloedssfeer geschapen. Rusland vestigde zich aan de Zwarte Zeekust, verkreeg het doorvaartrecht door de Zeestraten voor koopvaardijschepen en een permanente ambassade in Constantinopel; de vage bepaling over bescherming van de orthodoxe onderdanen opende de deur naar de interventiegronden van de volgende eeuw. Voor het eerst werd een gebied met een islamitische bevolking aan de Osmaanse heerschappij onttrokken.", "b677ebfc"]},
"OLAYLAR:1783-04-19:0":{"b": ["Annexatie van de Krim door Rusland", "bdf6faa8"], "d": ["De door Küçük Kaynarca geschapen 'onafhankelijke' Krim werd, onder het voorwendsel van de onrust tijdens de regering van de laatste khan Şahin Giray, bij manifest van Catharina II door Rusland geannexeerd. Het driehonderd jaar durende Osmaans-Krim-partnerschap kwam ten einde; het verlies van de noordelijke steppen nam de verdedigingsdiepte van Constantinopel weg en zette de eerste grote migratiegolf van tienduizenden Krimtataren naar Osmaans grondgebied in gang. Op deze dag werd het Krim-schiereiland (Alushta, Kaffa, Soedak, Jalta, Balaklava, Inkerman, Mangoep, Arabat) bij Rusland gevoegd; Taman en Koeban gingen bij dezelfde annexatie ook naar Rusland (TDV Kırım: 8 april 1783 Juliaans = 19 april Gregoriaans).", "aa59d3e1"]},
"OLAYLAR:1789-04-07:0":{"b": ["Selim III en de Nizâm-ı Cedîd", "d53aec21"], "d": ["Selim III, die midden in de oorlog de troon besteeg, begreep dat de nederlagen structureel waren en startte onder de naam 'Nizâm-ı Cedîd' (Nieuwe Orde) een omvattend hervormingsprogramma: een nieuw leger dat naar Europees model werd getraind, een afzonderlijke schatkist om dit te financieren (Îrâd-ı Cedîd), versterking van de ingenieursscholen en de eerste permanente ambassades in de Europese hoofdsteden. Het programma wordt beschouwd als het begin van de moderne Turkse hervormingstraditie; door het verzet van de korpsen en de ayans zou het in 1807 ten val komen.", "87394990"]},
"OLAYLAR:1798-06-12:0":{"b": ["Liquidatie van de Maltezer ridders — tussenstop van de Franse vloot", "d62f901d"], "d": ["De Franse vloot op weg naar Egypte deed Malta aan; de Sint-Jansridders (Malta) droegen het eiland zonder veel verzet over. De laatste burcht van de ridderorde die in 1522 uit Rhodos was verdreven en zich hier had gevestigd, kwam zo ten einde. Malta zou twee jaar later in Britse handen vallen, terwijl Napoleon vanaf het eiland rechtstreeks naar Alexandrië koers zette.", "aac1fe49"]},
"OLAYLAR:1798-07-01:0":{"b": ["Napoleons bezetting van Egypte", "93fede5f"], "d": ["Het leger van generaal Bonaparte landde bij Alexandrië en bezette Egypte; deze veldtocht, gericht op de Britse route naar India, was de eerste directe aanval van een Europese mogendheid op het kerngebied van het Osmaanse Rijk. Nelsons overval bij Aboukir en Cezzâr Ahmed Pasja's verdediging van Akko braken de Franse opmars; de bezetting eindigde in 1801, maar in het vacuüm dat zij achterliet begonnen de opkomst van Mehmed Ali Pasja van Kavala en het tijdperk van de 'Oosterse kwestie'.", "b1ca7226"]},
"OLAYLAR:1808-10-07:0":{"b": ["Sened-i İttifak", "cce49ef5"], "d": ["Document dat onder leiding van Alemdar Mustafa Pasja, de ayan van Rusçuk die Mahmud II op de troon bracht, werd ondertekend tussen het paleis en de machtige ayanfamilies in de provincie; de ayans beloofden de sultan trouw en militaire steun, terwijl de staat hun bestaan en rechten erkende. Omdat het het eerste voorbeeld in de Osmaanse geschiedenis was van beperking van het gezag van de sultan door een document, wordt het door sommige historici beschouwd als het verre begin van de constitutionele traditie; in de praktijk raakte het binnen enkele maanden buiten werking.", "2d97fdfe"]},
"OLAYLAR:1821-03-06:0":{"b": ["Griekse opstand begon", "a7293715"], "d": ["De opstand die door de organisatie Filiki Eteria werd voorbereid brak eerst uit in Walachije en vervolgens, met zijn eigenlijke kracht, in de Morea; de staat, die bezig was met de kwestie van Tepedelenli Ali Pasja, reageerde aanvankelijk te laat. Dankzij de intense Griekse sympathie in de Europese publieke opinie (filhellenisme) groeide de opstand snel uit tot een internationale zaak; zo werd de lont ontstoken voor de eerste succesvolle onafhankelijkheidsbeweging op Osmaans grondgebied in het tijdperk van het nationalisme. Andere plaatsen die op dezelfde datum verloren gingen: Athene, Balyabadra (Patras), İstefe (Thebe), Livadya, Eleusis (Attica), Missolonghi.", "f11097ac"]},
"OLAYLAR:1821-04-02:0":{"b": ["Eerste gewapende opstand in de Morea", "77e6250f"], "d": ["Na de oversteek van de Proet sloeg de opstand over naar de Morea: de gewapende actie die in Kalavryta begon (Juliaans 21 maart) werd gevolgd door bewegingen in Patras, Kalamata en Mani; de Morea veranderde snel in een algemene opstand en het Osmaanse bestuur verloor het grootste deel van het schiereiland. Andere plaatsen die op dezelfde datum verloren gingen: Athene, Balyabadra (Patras), İstefe (Thebe), Livadya, Eleusis (Attica), Missolonghi.", "143953b8"]},
"OLAYLAR:1826-06-15:0":{"b": ["Vak'a-i Hayriyye — Janitsarenkorps afgeschaft", "08c9372a"], "d": ["De janitsaren, die de ketels omkeerden tegen de training van het nieuw gevormde Eşkinci-korps, werden in hun kazernes op het Etmeydanı vernietigd door het kanonvuur van de door Mahmud II van tevoren voorbereide getrouwe troepen; het korps werd samen met al zijn takken en de verbonden Bektashi-tekkes opgeheven. Deze operatie, die onder de naam 'Gelukkige Gebeurtenis' de geschiedenis inging, liquideerde een vier eeuwen oude instelling en maakte de weg vrij voor het leger van de Asâkir-i Mansûre-i Muhammediyye en alle latere centralisatiehervormingen.", "9ee152dd"]},
"OLAYLAR:1827-10-20:0":{"b": ["Overval bij Navarino", "ee579e7f"], "d": ["De Osmaans-Egyptische vloot, die bezig was de Griekse opstand neer te slaan, werd bij Navarino verbrand door de gecombineerde Brits-Frans-Russische vloot die zonder oorlogsverklaring de haven binnenvoer; bijna zestig schepen en duizenden zeelieden gingen verloren. De overval, die in de Europese diplomatie werd weggewuifd als een 'ongelukkig voorval', waarborgde feitelijk de Griekse onafhankelijkheid en opende de weg naar de Osmaans-Russische oorlog van 1828–29.", "0d4b2c6f"]},
"OLAYLAR:1839-11-03:0":{"b": ["Edict van Tanzimat", "5042ce7b"], "d": ["Met het in Gülhane voorgelezen Hatt-ı Hümâyun werden de veiligheid van leven, eigendom en eer van alle onderdanen, zonder onderscheid van godsdienst, onder staatsgarantie gebracht; de beginselen van rechtvaardigheid in de belasting, ordelijkheid in de dienstplicht en geen straf zonder proces werden afgekondigd. Het edict, het werk van Mustafa Reşid Pasja, wordt beschouwd als het eerste grote document van constitutionele aard van de Osmaanse modernisering en gaf zijn naam aan het hervormingstijdperk 'Tanzimat-periode' (1839–1876); in dit kader werden grondige herstructureringen doorgevoerd in bestuur, recht, onderwijs en financiën.", "6ace4b82"]},
"OLAYLAR:1853-10-04:0":{"b": ["Krimoorlog begon", "3b9ca3c8"], "d": ["De crisis, begonnen met de kwestie van de heilige plaatsen en de Russische aanspraak op bescherming van de orthodoxe onderdanen, ontaardde in open conflict met de Osmaanse oorlogsverklaring; na de overval bij Sinope traden Engeland en Frankrijk (later Piëmont) aan Osmaanse zijde in de oorlog. De oorlog werd met de landing van de geallieerde legers op de Krim en de inname van Sebastopol gewonnen met het Verdrag van Parijs in 1856; maar de eerste buitenlandse lening, in de oorlogsjaren aangegaan (1854), bracht het rijk in een spiraal van financiële afhankelijkheid die een halve eeuw zou duren.", "bae16135"]},
"OLAYLAR:1856-02-18:0":{"b": ["Hervormingsedict (Islahat Fermanı)", "78ff234d"], "d": ["Het edict, afgekondigd voor de vredesonderhandelingen van Parijs, breidde de beginselen van de Tanzimat uit en kende aan niet-moslimonderdanen brede gelijkheidsrechten toe, waaronder ambtenarenposten, militaire dienst en het openen van scholen; de gemeenschapsorganisaties werden herordend. Met het daarna ondertekende Verdrag van Parijs werd de Osmaanse staat formeel toegelaten tot de familie van het Europese volkenrecht en kwam zijn territoriale integriteit onder de gezamenlijke garantie van de grote mogendheden — in de praktijk zou deze garantie een nieuwe deur voor interventies worden.", "cfe6d847"]},
"OLAYLAR:1876-12-23:0":{"b": ["Kanûn-ı Esâsî — Eerste Constitutionele Periode", "0fe052c1"], "d": ["Op de dag dat de internationale conferentie die in Constantinopel bijeen was gekomen om de Balkancrisis te bespreken werd geopend, werd met kanonschoten de eerste Osmaanse grondwet afgekondigd; met de Kanûn-ı Esâsî, het werk van de beweging van de 'Jonge Osmanen' onder leiding van Midhat Pasja, werd een tweekamerparlement gevormd. De Meclis-i Meb'ûsan werd in maart 1877 geopend; maar Abdülhamid II schorste het parlement in februari 1878 voor onbepaalde tijd met de Oorlog van '93 als reden en de grondwet bleef dertig jaar opgeschort.", "c0f01a41"]},
"OLAYLAR:1877-04-24:0":{"b": ["Oorlog van '93 (Osmaans-Russische oorlog van 1877–78)", "5bd96af7"], "d": ["In de oorlog die de 'Oorlog van '93' werd genoemd omdat hij overeenkwam met het jaar 1293 van de Rûmî-kalender, vielen de Russische legers aan twee fronten aan; hoewel Gazi Osman Pasja's verdediging van Plevna en de Kaukasische veldslagen van Ahmed Muhtar Pasja legendarisch werden, bezweek het front en rukten de Russen op tot Yeşilköy (San Stefano). De oorlog zette de grote golven van moslimmigratie van de Balkan en de Kaukasus naar Constantinopel in gang, waarvan de gevolgen tot op heden doorwerken; de demografische en financiële structuur van het rijk kwam nooit meer terug in de oude staat.", "3a2b2296"]},
"OLAYLAR:1878-07-13:0":{"b": ["Verdrag van Berlijn", "47f76a49"], "d": ["Het Congres van Berlijn, dat het door San Stefano ontstane 'Groot-Bulgarije' in naam van het evenwicht tussen de grote mogendheden herzag, liet toch een zwaar beeld achter: Servië, Montenegro en Roemenië werden onafhankelijk; het autonome Prinsdom Bulgarije werd gesticht; Bosnië-Herzegovina werd aan de Oostenrijkse bezetting, Cyprus aan het Britse bestuur en Kars-Ardahan-Batoem aan Rusland gelaten. De vijfhonderd jaar oude Osmaanse orde in Rumelië viel grotendeels uiteen; de 'Oosterse kwestie' werd een permanent onderwerp op de agenda van de Europese diplomatie. Andere plaatsen die op dezelfde datum verloren gingen: Filibe, Vidin, Tırnova, Varna, Şumnu, Silistre, Rusçuk, Boekarest, Iași, Köstence. Roemenië, dat Bessarabië aan Rusland moest afstaan, kreeg Tulcea en Dobroedzja: Tulcea, Babadag, Măcin, Isaccea, Hârșova en Mangalia in Noord-Dobroedzja gingen over naar Roemenië.", "5c7d5594"]},
"OLAYLAR:1881-05-12:0":{"b": ["Bezetting van Tunesië en Düyûn-ı Umûmiyye", "c7e25598"], "d": ["Frankrijk bezette Tunesië onder voorwendsel van de incidenten aan de Algerijnse grens en nam het met het Verdrag van Bardo onder zijn bescherming; de Osmaanse aanwezigheid in Noord-Afrika werd teruggebracht tot Tripolitanië. Met het Muharrem-decreet, uitgevaardigd in hetzelfde jaar, werd de Düyûn-ı Umûmiyye-administratie opgericht voor het beheer van de bankroete buitenlandse schulden, waarin de schuldeisers vertegenwoordigd waren: basisinkomsten zoals zout, tabak en zijde werden rechtstreeks aan dit buitenlandse bestuur gekoppeld en de financiële soevereiniteit werd zwaar beperkt. Andere plaatsen die op dezelfde datum verloren gingen: Kairouan, Gabès, Sfax, Djerba.", "64f23b86"]},
"OLAYLAR:1882-09-13:0":{"b": ["Britse bezetting van Egypte", "f1269768"], "d": ["De Urabi Pasja-beweging, die in Egypte opkwam tegen het financiële faillissement en buitenlandse controle, werd na het bombardement op Alexandrië verpletterd door de overwinning bij Tel el-Kebir van het aan land gegane Britse leger en Caïro werd bezet. Hoewel Egypte juridisch aan het Osmaanse Rijk gebonden bleef, kwam het feitelijk onder Brits bestuur; de controle over het Suezkanaal werd het middelpunt van de Britse imperiale strategie.", "b7bcf2d2"]},
"OLAYLAR:1908-07-23:0":{"b": ["Afkondiging van de Tweede Constitutionele Periode", "95ee2fd2"], "d": ["Tegenover de beweging die groeide doordat officieren van het Comité voor Eenheid en Vooruitgang in Macedonië de bergen introkken, herstelde Abdülhamid II de Kanûn-ı Esâsî; de 'afkondiging van de vrijheid' werd met enthousiasme ontvangen en er werden verkiezingen gehouden. Toch kwam er geen stabiliteit: nadat het Incident van 31 maart (april 1909) was onderdrukt, werd Abdülhamid afgezet; ook de onafhankelijkheid van Bulgarije, de annexatie van Bosnië en de oriëntatie van Kreta op Griekenland vonden in deze roerige maanden plaats.", "370f359f"]},
"OLAYLAR:1911-09-29:0":{"b": ["Italiaans-Turkse Oorlog (Tripolitaanse Oorlog)", "ed441994"], "d": ["Het koloniaal ingestelde Italië verklaarde de oorlog aan Tripolitanië, het laatste Osmaanse gebied in Noord-Afrika, en bezette de kusten; toen de staat zonder vloot geen reguliere troepen kon sturen, trokken jonge officieren zoals Mustafa Kemal en Enver Bey in het geheim naar de regio en organiseerden met de Senoessi-stammen een effectief verzet. Met het Verdrag van Ouchy (18 oktober 1912), dat werd ondertekend na het uitbreken van de Balkanoorlog, werd Libië aan Italië gelaten; Italië bezette bovendien Rhodos en de Dodekanesos.", "9820482a"]},
"OLAYLAR:1913-05-30:0":{"b": ["Verdrag van Londen — verlies van Rumelië", "f3f976df"], "d": ["Met het Verdrag van Londen, dat de Eerste Balkanoorlog beëindigde, gingen alle gebieden ten westen van de lijn Midye-Enez en de Egeïsche eilanden verloren; Albanië werd onafhankelijk. Van Rumelië, dat al meer dan vijfhonderd jaar het demografische, economische en culturele zwaartepunt van het rijk was, zou alleen Oost-Thracië overblijven (Edirne werd in de Tweede Balkanoorlog heroverd); het verlies verhardde het oorlogs- en vestigingsbeleid van het Unionistische bestuur ingrijpend. De volgende plaatsen ten westen van de lijn Midye-Enez gingen verloren: Üsküp, Köprülü (Veles), İştip (Štip), Ustrumca, Doyran, Gevgili (Gevgelija), Manastır, Ohri, Debre (Debar), Prizren, Priştine, Peç (Peja), Yenipazar (Novi Pazar), Kosova Ovası (Kosovo Polje); Serez, Drama, Kavala, Petriç, Nevrokop, İskeçe, Gümülcine, Dedeağaç, Dimetoka, Çirmen, Ferecik (Feres), Sofulu (Soufli), Orestiada (Kumçiftliği), Praviște (Eleftheroupoli), Stérna, Távri, Umur Fakih (Fakia), Malak Dervent (Lalkovo); op Kreta Chania, Candia, Kreta (Rethymno), Sitia (Sitiye) en Sfakia (İsfakiye).", "b193bdae"]},
"OLAYLAR:1914-11-01:0":{"b": ["Toetreding tot de Eerste Wereldoorlog", "05a0252e"], "d": ["Dat de aan Engeland ontsnapte pantserschepen Goeben en Breslau als gekocht werden voorgesteld en de Zeestraat binnen mochten, trok de staat stap voor stap naast Duitsland; toen de vloot onder bevel van admiraal Souchon Russische havens bombardeerde (29 oktober) begon de oorlog feitelijk, en de wederzijdse verklaringen volgden begin november. Ondanks de afkondiging van de Grote Jihad bleef het verwachte effect uit; het rijk raakte vier jaar lang op vijf afzonderlijke fronten, van de Kaukasus tot Palestina, verwikkeld in een strijd om het bestaan.", "a9f179e7"]},
"OLAYLAR:1915-03-18:0":{"b": ["Overwinning bij Çanakkale (Gallipoli)", "95d888e8"], "d": ["De geallieerde armada, die Constantinopel wilde laten vallen en Rusland wilde bereiken, werd op 18 maart door het vuur van de mijnenvelden en forten uit de Zeestraat teruggeslagen; de door het mijnenlegger Nusret gelegde mijnenlinie bepaalde het lot van de strijd. Ook de landoperatie op Gallipoli, begonnen in april, werd bij Anafartalar en Conkbayırı tot staan gebracht; de geallieerden ontruimden het schiereiland in januari 1916 volledig. Luitenant-kolonel Mustafa Kemal maakte zich aan dit front een naam; de overwinning, behaald tegen een prijs van ongeveer een kwart miljoen gesneuvelden en vermisten, wordt beschouwd als de geboorteplaats van de kaders en de geest van de Nationale Strijd.", "005303c3"]},
"OLAYLAR:1916-06-10:0":{"b": ["Opstand van sjerif Hoessein", "75f7c58c"], "d": ["De emir van Mekka, sjerif Hoessein, kwam na geheime briefwisseling met de Britten in opstand met de belofte van een onafhankelijk Arabisch koninkrijk; de Hidjaz-spoorlijn werd doelwit van aanvallen. Hoewel Fahreddin Pasja's legendarische verdediging van Medina, die tot na de wapenstilstand voortduurde, een symbool van verzet bleef, versnelde de opstand, in combinatie met de Britse opmars aan het Palestijnse front, het uiteenvallen van de Osmaanse heerschappij in de Arabische provincies. Andere plaatsen die op dezelfde datum verloren gingen: Ta'if.", "a0e859bd"]},
"OLAYLAR:1918-10-30:0":{"b": ["Wapenstilstand van Moudros", "9e87c767"], "d": ["De Osmaanse staat, wiens fronten door de ineenstorting van Bulgarije van elkaar waren afgesneden, trok zich terug uit de oorlog met de wapenstilstand die aan boord van het pantserschip Agamemnon werd getekend. Artikel 7, dat de opening van de Zeestraten toestond en de bezetting van plaatsen die de veiligheid bedreigden mogelijk maakte, werd binnen korte tijd het juridische deksel op de feitelijke verdeling: Mosul, Iskenderun, daarna Smyrna en Constantinopel werden bezet. De wapenstilstand wordt beschouwd als het document van het feitelijke einde van het rijk. Andere plaatsen die op dezelfde datum verloren gingen: Hama, Damascus, Homs.", "261b57f2"]},
"OLAYLAR:1919-05-19:0":{"b": ["Mustafa Kemal in Samsun — Nationale Strijd", "09a8f784"], "d": ["In het klimaat van verontwaardiging door de bezetting van Smyrna ging Mustafa Kemal Pasja, in de hoedanigheid van inspecteur van het 9e Leger, in Samsun aan land en richtte zijn officiële taak op het organiseren van het verzet in Anatolië. De Circulaire van Amasya en de congressen van Erzurum en Sivas zijn het vervolg van deze stap; het beginsel 'de onafhankelijkheid van de natie zal opnieuw door de vastberadenheid en het besluit van de natie worden gered' werd de kern van het politieke programma van de Nationale Strijd.", "330e4c51"]},
"OLAYLAR:1920-04-23:0":{"b": ["Opening van de TBMM en Sèvres", "2008feec"], "d": ["Na de formele bezetting van Constantinopel en de ontbinding van de Meclis-i Meb'ûsan werd op 23 april 1920 in Ankara de Grote Nationale Vergadering geopend; de vergadering, die buitengewone bevoegdheden in zich verenigde, werd de kern van de nieuwe staat gebaseerd op de nationale wil. Het in augustus door de regering van Constantinopel ondertekende Verdrag van Sèvres verdeelde Anatolië; de TBMM verklaarde de ondertekenaars tot vaderlandsverraders en Sèvres werd nooit uitgevoerd.", "9b4f7c0b"]},
"OLAYLAR:1921-09-13:0":{"b": ["Slag aan de Sakarya", "f2f970a6"], "d": ["Het Griekse offensief, dat tot op 50 kilometer van Ankara naderde, werd gebroken in de 22 dagen en 22 nachten durende slag die werd gevoerd onder het bevel 'er is geen verdedigingslinie, er is een verdedigingsvlak' van Mustafa Kemal Pasja, die de bevoegdheid van opperbevelhebber had overgenomen. Het Griekse leger ging voor het eerst over op strategische verdediging; de overwinning bezorgde Mustafa Kemal de titels gazi en müşir (maarschalk) en opende de deur naar het Verdrag van Ankara met Frankrijk en erkenning door het buitenland.", "f3372310"]},
"OLAYLAR:1922-09-09:0":{"b": ["Groot Offensief en bevrijding van Smyrna", "172a50c4"], "d": ["Het offensief dat op de ochtend van 26 augustus vanaf Kocatepe werd ingezet, bereikte op 30 augustus bij Dumlupınar met de Slag van de Opperbevelhebber de vernietiging van de belangrijkste Griekse strijdkrachten; met de achtervolging onder het bevel 'Legers, uw eerste doel is de Middellandse Zee, vooruit!' werd Smyrna op 9 september bevrijd. Met de Wapenstilstand van Mudanya (11 oktober) werd Oost-Thracië zonder strijd teruggenomen; de militaire overwinning bepaalde de onderhandelingskracht van de nieuwe staat die in Lausanne zou worden gevestigd.", "02bd94a5"]},
"OLAYLAR:1922-11-01:0":{"b": ["Afschaffing van het sultanaat", "9f36a9f6"], "d": ["Nadat ook de regering van Constantinopel was uitgenodigd voor de besprekingen in Lausanne, schafte de TBMM op 1 november 1922 het sultanaat af door sultanaat en kalifaat te scheiden; de 623 jaar durende Osmaanse dynastieke heerschappij kwam juridisch ten einde. Mehmed VI Vahideddin verliet op 17 november met een Brits oorlogsschip het land; Abdülmecid Efendi werd bij besluit van de TBMM tot het kalifaat benoemd en ook dit ambt zou op 3 maart 1924 worden afgeschaft.", "910b763d"]},
"OLAYLAR:1923-07-24:0":{"b": ["Verdrag van Lausanne", "38c27f7d"], "d": ["Met het Vredesverdrag van Lausanne, ondertekend na acht maanden moeizame onderhandelingen, werden de grenzen, de volledige onafhankelijkheid en de soevereiniteit van de nieuwe Turkse staat internationaal erkend; de capitulaties werden afgeschaft, de Düyûn-ı Umûmiyye werd in liquidatie gebracht en de bevolkingsuitwisseling werd geregeld. Lausanne, dat Sèvres feitelijk nietig maakte, wordt beschouwd als de diplomatieke overwinning van de Nationale Strijd en als het stichtende buitenlandse document van de Republiek.", "6d498c3f"]},
"OLAYLAR:1923-10-29:0":{"b": ["Uitroeping van de Republiek", "d5bfcdfb"], "d": ["Nadat de TBMM met een grondwetswijziging de bepaling 'de regeringsvorm van de Turkse Staat is de republiek' had aangenomen, werd de Republiek uitgeroepen; Mustafa Kemal Pasja werd tot eerste president gekozen. Het 624 jaar durende Osmaanse avontuur, dat in 1299 als grensbeylik was begonnen, was zo gesloten en de nieuwe staat, waarin de soevereiniteit onvoorwaardelijk aan de natie toebehoort, was gebouwd op de erfenis van het rijk.", "f5cabb8c"]},
"OLAYLAR_EK2:1327-01-01:0":{"b": ["Slaan van de eerste Osmaanse akçe", "38d2d638"], "d": ["De eerste zilveren akçe, geslagen in naam van Orhan Gazi, is de monetaire proclamatie van de onafhankelijke soevereiniteit van het beylik; de akçe bleef vijf eeuwen lang de basismunteenheid.", "8729ab5b"]},
"OLAYLAR_EK2:1362-09-01:0":{"b": ["Oprichting van het beylerbeylik van Rumelië", "ffa16089"], "d": ["De veroveringen aan de Europese kant werden onder één militair-administratief dak verzameld; het beylerbeylik-stelsel werd de ruggengraat van de provinciale organisatie van het rijk.", "9c13c8c3"]},
"OLAYLAR_EK2:1390-01-15:0":{"b": ["Huwelijk van Yıldırım Bayezid en Despina Hatun", "4b10dc6c"], "d": ["De vazalliteit die na Kosovo met het Servische despotaat werd gevestigd, werd bezegeld met het huwelijk van Lazars dochter Olivera met Bayezid — een typisch voorbeeld van huwelijksdiplomatie uit de vroege periode.", "7d87810a"]},
"OLAYLAR_EK2:1393-01-01:0":{"b": ["Oprichting van het beylerbeylik van Anatolië", "5ef8d3a7"], "d": ["Voor het bestuur van de geannexeerde beylikgebieden werd het beylerbeylik van Anatolië georganiseerd; de tweevleugelige bestuursorde Rumelië–Anatolië was voltooid.", "55429c02"]},
"OLAYLAR_EK2:1399-06-01:0":{"b": ["Voltooiing van de Ulu Camii van Bursa", "27bcc4a5"], "d": ["De grote moskee met twintig koepels, gebouwd met de buit van Nikopol, is een monumentaal voorbeeld van de vroege Osmaanse architectuur en een openluchtmuseum van de kalligrafie.", "b0e811e6"]},
"OLAYLAR_EK2:1453-06-01:0":{"b": ["Afzetting en executie van Çandarlı Halil Pasja", "5e19438f"], "d": ["Na de verovering werd de grootvizier uit de oude familie Çandarlı, die afstand had genomen van het beleg, geëxecuteerd; voor het eerst werd een grootvizier op bevel van de sultan gedood en brak het tijdperk van viziers van devşirme-afkomst aan.", "557b77f5"]},
"OLAYLAR_EK2:1456-06-01:0":{"b": ["Moldavië schatplichtig gemaakt", "25bd3693"], "d": ["Het woiwodschap Moldavië aanvaardde schatting te betalen; samen met Walachije en Transsylvanië werd de drievoudige vazalgordel ten noorden van de Donau de noordelijke bufferzone van het rijk. Andere plaatsen die op dezelfde datum werden toegevoegd: Iași.", "7cea09ea"]},
"OLAYLAR_EK2:1459-03-07:0":{"b": ["Schatting van Dubrovnik (Ragusa)", "d127c78a"], "d": ["De handelsrepubliek Ragusa verzekerde zich in ruil voor schatting van haar autonomie en handelsprivileges; zij werd rijk als het venster van de Osmanen op de Adriatische Zee. Ook het eiland Mljet (Mliyet), grondgebied van de republiek, deelde deze status.", "812b9f2b"]},
"OLAYLAR_EK2:1462-06-01:0":{"b": ["Veldtocht naar Walachije: de Spietser", "fd4530bb"], "d": ["Met de veldtocht tegen Vlad Tepeş, die weigerde schatting te betalen en gezanten doodde, werd Walachije weer vazal; de nachtelijke overval en de gruwelijke scènes van spietsing werden in Europa legende. Andere plaatsen die op dezelfde datum werden toegevoegd: Boekarest.", "6ae089b4"]},
"OLAYLAR_EK2:1470-12-01:0":{"b": ["Opening van het Fatih-complex", "a150ea55"], "d": ["Het complex met zijn acht madrasa's (Sahn-ı Semân) was de eerste grote stap in het programma om Constantinopel te veranderen in het wetenschappelijk centrum van de islamitische wereld.", "cbec7a2f"]},
"OLAYLAR_EK2:1472-01-01:0":{"b": ["Ali Kuşçu in Constantinopel", "8508229d"], "d": ["Ali Kuşçu, de laatste grote vertegenwoordiger van de sterrenwacht van Samarkand, werd op uitnodiging van de Veroveraar müderris aan de Hagia Sophia-madrasa; hij vestigde de wiskundig-astronomische traditie in Constantinopel.", "fd325f60"]},
"OLAYLAR_EK2:1477-01-01:0":{"b": ["Kanunname van de Veroveraar", "b08944c9"], "d": ["De eerste omvattende kanunname die de staatsorganisatie, het protocol en de straffen codificeerde; hij blijft omstreden vanwege het beroemde artikel dat broedermoord 'voor de orde van de wereld' toestaat.", "0e654de1"]},
"OLAYLAR_EK2:1478-06-01:0":{"b": ["Eerste Osmaanse gouden munt (sultanî) geslagen", "2fd5c0dd"], "d": ["De eerste Osmaanse gouden munt, gelijk aan de Venetiaanse dukaat, werd geslagen; de rijksfinanciën sloten zich aan bij de internationale monetaire orde.", "cac00614"]},
"OLAYLAR_EK2:1478-09-01:0":{"b": ["Verhuizing naar het Topkapı-paleis", "b9cd6a5e"], "d": ["Met de voltooiing van het Nieuwe Paleis (Topkapı) verhuisde het centrum van het staatsbestuur hierheen; het paleis bleef vier eeuwen lang het brein van het rijk.", "748ada37"]},
"OLAYLAR_EK2:1532-04-27:0":{"b": ["Republiek Florence omgevormd tot hertogdom — Alessandro de' Medici", "c08764e1"], "d": ["Onder druk van paus Clemens VII nam de regeringscommissie (Balìa) van Florence een nieuwe grondwet aan; het vijf eeuwen oude republikeinse bewind werd afgeschaft en Alessandro de' Medici werd tot erfelijk hertog uitgeroepen en besteeg op 1 mei feitelijk de troon. Florence veranderde zo van een onafhankelijke stadsrepubliek in een erfelijk hertogdom van de dynastie Medici.", "92da65c9"]},
"OLAYLAR_EK2:1534-01-01:0":{"b": ["Huwelijk van Süleyman de Wetgever en Hürrem Sultan", "abc05f26"], "d": ["Dat Süleyman officieel met Hürrem trouwde, veranderde de paleistraditie ingrijpend; de instelling 'Haseki Sultan' ontstond en de deur naar het tijdperk van vrouwen in de dynastieke politiek ging open.", "db1f832b"]},
"OLAYLAR_EK2:1536-02-18:0":{"b": ["Eerste uitgebreide capitulaties met Frankrijk", "e2264e48"], "d": ["Als onderdeel van het Franse bondgenootschap tegen de Habsburgse omsingeling werden handelsprivileges ondertekend tussen Jean de la Forest en Makbul İbrâhim Pasja; de capitulaties, die toen een diplomatiek instrument waren, zouden in de loop van de eeuwen de deur naar financiële afhankelijkheid worden.", "e7c6fd84"]},
"OLAYLAR_EK2:1538-06-13:0":{"b": ["Indische Oceaan-expeditie: beleg van Diu", "fcd1217a"], "d": ["De vloot die uit Suez vertrok, stak de Rode Zee over en belegerde Diu in Gujarat; hoewel de burcht niet werd ingenomen, reikte de Osmaanse macht voor het eerst tot in de Indische Oceaan en werd het Portugese monopolie aan het wankelen gebracht.", "ce118bf7"]},
"OLAYLAR_EK2:1553-12-07:0":{"b": ["Reis van Seydi Ali Reis naar India", "e5da3b2c"], "d": ["Seydi Ali Reis, die de opdracht had de vloot in Basra naar Egypte te brengen, werd door stormen naar India gedreven; zijn Mir'âtü'l-memâlik, waarin hij zijn terugreis vertelt, is een van de eerste Osmaanse reisverslagen.", "bb472cec"]},
"OLAYLAR_EK2:1554-01-01:0":{"b": ["Executie van Pîrî Reis", "63026444"], "d": ["De grote zeevaarder en cartograaf, die van de Hormuz-campagne terugkeerde nadat hij de vloot in Basra had achtergelaten, werd op 84-jarige leeftijd geëxecuteerd — een van de meest omstreden beslissingen uit onze wetenschapsgeschiedenis.", "e3d1ac3f"]},
"OLAYLAR_EK2:1557-10-16:0":{"b": ["Opening van het Süleymaniye-complex", "1c6458b2"], "d": ["Het complex dat architect Sinan 'mijn gezellenwerk' noemde; met zijn madrasa's, ziekenhuis en bibliotheek werd het het grootste onderwijs- en liefdadigheidscomplex van de klassieke periode.", "0c203c6b"]},
"OLAYLAR_EK2:1565-05-18:0":{"b": ["Beleg van Malta", "f57f6a85"], "d": ["Malta, het slot van de Middellandse Zee, werd vier maanden belegerd; Turgut Reis sneuvelde en het beleg werd opgeheven. Het was de eerste grote stap terug van de Osmaanse zeevaart onder Süleyman.", "860ee1bc"]},
"OLAYLAR_EK2:1575-03-01:0":{"b": ["Voltooiing van de Selimiye-moskee", "3b0484e1"], "d": ["De Selimiye, waarvan Sinan zei dat het zijn 'meesterwerk' was en waarin één koepel de ruimte beheerst, wordt beschouwd als het hoogtepunt van de klassieke Osmaanse architectuur (UNESCO-Werelderfgoed).", "9d7cd43c"]},
"OLAYLAR_EK2:1577-01-01:0":{"b": ["Oprichting van de Sterrenwacht van Constantinopel", "169bdf5d"], "d": ["De sterrenwacht van Takiyyüddin, een van de best uitgeruste observatoria van die tijd, werd in 1580 afgebroken na de discussies die ontstonden naar aanleiding van de komeet van 1577; de institutionele sterrenkunde liep drie eeuwen achter.", "7fb471aa"]},
"OLAYLAR_EK2:1578-08-09:0":{"b": ["Overwinning bij Çıldır — oostelijke oorlog begon", "13125a54"], "d": ["Met de nederlaag van het Safawidische leger bij Çıldır gingen de poorten van de Kaukasus open; Tbilisi werd ingenomen en Georgië kwam onder Osmaanse heerschappij.", "0bf34d05"]},
"OLAYLAR_EK2:1583-05-09:0":{"b": ["Slag van de Fakkels — Shirvan definitief Osmaans", "3bbc23bc"], "d": ["In de slag die zo wordt genoemd omdat zij ook 's nachts bij fakkellicht werd voortgezet, werden de Safawiden definitief verslagen; de Osmaanse heerschappij in Shirvan en Bakoe werd bezegeld.", "e2aa6d1e"]},
"OLAYLAR_EK2:1585-01-01:0":{"b": ["Grote muntverslechtering — akçe-crisis", "9205c3d4"], "d": ["Onder druk van de lange oorlogen en het Amerikaanse zilver werd het zilvergehalte van de akçe gehalveerd; de prijsrevolutie voedde het uiteenvallen van het sipahi-stelsel en de Celali-onrust.", "bd2a508f"]},
"OLAYLAR_EK2:1585-09-25:0":{"b": ["Verovering van Tabriz", "6506bdb9"], "d": ["Serdar Özdemiroğlu Osman Pasja trok Tabriz binnen; de oude hoofdstad van de Safawiden werd onder Osmaans bestuur gebracht. Osman Pasja stierf enkele weken later in het legerkamp.", "e54b35bd"]},
"OLAYLAR_EK2:1590-03-21:0":{"b": ["Verdrag van Ferhad Pasja — grootste grenzen in het oosten", "c429972f"], "d": ["Met het verdrag dat werd gesloten na de aankomst in Constantinopel van Sjah Abbas' gezant Haydar Mirza (18 januari 1590), onder voorwaarde dat de veroverde plaatsen Osmaans bleven, en dat de twaalf jaar durende oorlog beëindigde, bleven Tabriz, Karabach, Shirvan, Georgië en Luristan Osmaans; het rijk bereikte in het oosten de grootste grenzen uit zijn geschiedenis.", "41d8b058"]},
"OLAYLAR_EK2:1603-10-21:0":{"b": ["Osmaans-Safawidische oorlog (1603-1612) begon — tegenoffensief van Sjah Abbas, verlies van Tabriz", "abf27dd8"], "d": ["Sjah Abbas, die zijn leger had gereorganiseerd, ging gebruik makend van de Celali-onrust over tot het offensief; Tabriz viel en de winsten in de Kaukasus gingen binnen enkele jaren verloren. Plaatsen die in dezelfde veldtocht en daarna verloren gingen: Nakhitsjevan, Khoy, Marand, Salmas; ook de beys van Karacadağ (Ahar) en Mukri keerden terug naar de Safawidische kant.", "b1757da9"]},
"OLAYLAR_EK2:1611-03-25:0":{"b": ["Evliya Çelebi geboren", "2b6051ff"], "d": ["Evliya Çelebi, die zijn reizen van meer dan vijftig jaar bijeenbracht in de tiendelige Seyahatnâme, liet een unieke panorama van de 17e-eeuwse Osmaanse wereld na.", "bbd451a3"]},
"OLAYLAR_EK2:1612-11-20:0":{"b": ["Verdrag van Nasuh Pasja", "bb69e388"], "d": ["Met het verdrag dat de oorlog sinds 1603 beëindigde, werd afgezien van de winsten van 1590 en werd teruggekeerd naar de Amasya-grens van 1555; het evenwicht aan het oostfront was hersteld.", "f3ce47a7"]},
"OLAYLAR_EK2:1616-06-09:0":{"b": ["Opening van de Sultan Ahmed-moskee", "e39dfd43"], "d": ["Met haar zes minaretten en blauwe İznik-tegels is de 'Blauwe Moskee' het laatste grote sultanscomplex van de klassieke periode.", "c3e55fc5"]},
"OLAYLAR_EK2:1648-08-18:0":{"b": ["Moord op sultan İbrahim", "bc4eb452"], "d": ["Met als reden verkwisting en een bestuurscrisis zette een alliantie van korpsen en ulema İbrahim af; tien dagen later werd hij met een fatwa gewurgd. De zevenjarige Mehmed IV besteeg de troon; de macht kwam feitelijk in handen van de grote valide Kösem Sultan.", "b90693f4"]},
"OLAYLAR_EK2:1657-10-06:0":{"b": ["Overlijden van Kâtib Çelebi", "e167e89d"], "d": ["Hij is de topfiguur van de Osmaanse wetenschapsgeschiedenis met zijn bibliografie Keşfü'z-zunûn en zijn geografie Cihannümâ; hij staat bekend om zijn pioniersaanpak waarin hij Europese bronnen gebruikte.", "786ec8d5"]},
"OLAYLAR_EK2:1703-08-22:0":{"b": ["Edirne-incident — afzetting van Mustafa II", "0291c1cd"], "d": ["De woede over het feit dat de sultan in Edirne verbleef en over de invloed van Feyzullah Efendi ontaardde in een grote opstand van leger en handelaren; de sjeik-ul-islam werd gelyncht, de sultan afgezet en het paleis keerde terug naar Constantinopel.", "e8740499"]},
"OLAYLAR_EK2:1720-10-08:0":{"b": ["Ambassadeur naar Parijs: Yirmisekiz Mehmed Çelebi", "26312a3f"], "d": ["De grote ambassade die naar Frankrijk werd gezonden was de eerste systematische waarneming ter plaatse van het Westen; zijn Sefâretnâme inspireerde de vernieuwing in het Tulpentijdperk.", "aa11c96a"]},
"OLAYLAR_EK2:1727-07-05:0":{"b": ["Eerste Osmaanse drukkerij opgericht", "4943f7e5"], "d": ["Er werd toestemming gegeven om Turkse boeken te drukken; het eerste werk, het Vankulu-woordenboek, werd in 1729 gedrukt. De drukkerij is de meest blijvende erfenis van de vernieuwing in het Tulpentijdperk.", "a33e45d0"]},
"OLAYLAR_EK2:1740-05-30:0":{"b": ["Capitulaties permanent gemaakt", "d044a79e"], "d": ["De privileges die aan Frankrijk waren verleend, werden niet langer aan de persoon van de sultan gebonden maar aan een blijvend verdrag; het capitulatiestelsel, dat niet meer eenzijdig opgezegd kon worden, kon pas in Lausanne worden afgeschaft.", "d50899dc"]},
"OLAYLAR_EK2:1773-01-01:0":{"b": ["Mühendishâne-i Bahrî-i Hümâyun opgericht", "9bf3f439"], "d": ["De ingenieursschool, opgericht na de ramp bij Çeşme om moderne marineofficieren op te leiden, is de eerste blijvende instelling van technisch onderwijs naar westers model; de landingenieursschool volgde in 1795.", "b73b2ce6"]},
"OLAYLAR_EK2:1793-06-01:0":{"b": ["Eerste permanente ambassade in Londen", "6b5630eb"], "d": ["Als onderdeel van het Nizâm-ı Cedîd-programma werden permanente ambassades in de Europese hoofdsteden geopend; de Osmaanse diplomatie ging over op het beginsel van wederkerigheid.", "0321b899"]},
"OLAYLAR_EK2:1808-11-16:0":{"b": ["Overlijden van Alemdar Mustafa Pasja", "4426534e"], "d": ["In de janitsarenopstand die in de nacht van 15 november 1808 begon, stak de hervormingsgezinde grootvizier, die bij de Hoge Porte werd belegerd, toen de verwachte hulp uitbleef de volgende dag het munitiemagazijn in brand en stierf met honderden aanvallers; de orde van het Sened-i İttifak en de eerste hervormingspoging werden met hem begraven.", "04420a26"]},
"OLAYLAR_EK2:1831-11-01:0":{"b": ["Eerste officiële krant: Takvîm-i Vekāyi", "c637f623"], "d": ["Het officiële staatsblad begon te verschijnen; het is het begin van de traditie van moderne publieke opinie en officiële mededelingen.", "b4f1f627"]},
"OLAYLAR_EK2:1838-08-16:0":{"b": ["Handelsverdrag van Balta Limanı", "e790b383"], "d": ["Aan Engeland werd ook in de binnenlandse handel de meest bevoorrechte positie toegekend en het yed-i vahit-stelsel (monopolie) werd afgeschaft; terwijl de binnenlandse productie onbeschermd bleef, werd het verdrag het document van de volledige opening van de Osmaanse markt voor de vrijhandel.", "14089a77"]},
"OLAYLAR_EK2:1842-01-01:0":{"b": ["Einde van het Emiraat Libanon — afzetting van Bashir III Shihab", "f85ae454"], "d": ["Emir Bashir II (III), die de christelijk-Druzische twist en de interne evenwichten in de Shouf-regio niet kon beheersen, werd in januari 1842 afgezet; de lokale emiraatsorde die sinds 1516 (door de Ma'noğulları en daarna de Shihabs) bestond, kwam ten einde en de regio kwam rechtstreeks onder Osmaans bestuur en daarna onder het systeem van dubbele kaymakamlik.", "205abc18"]},
"OLAYLAR_EK2:1844-01-01:0":{"b": ["Tashîh-i sikke: het Mecidiye-stelsel", "c77be809"], "d": ["Met de muntherziening werden de verslechterde munten ingenomen; een stabiel bimetallisch stelsel op basis van de gouden lira (Mecidiye) werd gevestigd.", "e0642ec8"]},
"OLAYLAR_EK2:1850-01-01:0":{"b": ["Einde van de lokale heerschappij van de familie Harfush in Baalbek", "8438f4ae"], "d": ["De invloed van de familie Harfush, die sinds 1521 (na de opstand van Canbirdi Gazâlî) in Baalbek als kleine lokale dynastie regeerde, kwam met de nieuwe administratieve regeling van de Hoge Porte ten einde; de stad werd een gewoon kaza-centrum van de provincie Damascus.", "106eabb2"]},
"OLAYLAR_EK2:1851-01-01:0":{"b": ["Oprichting van de Şirket-i Hayriyye", "462830e7"], "d": ["De maatschappij, opgericht om stoomboten op de Bosporus te exploiteren, geldt als de eerste Osmaanse naamloze vennootschap; de stoomboot-aanlegsteigers drukten hun stempel op het stadsleven.", "b4203b61"]},
"OLAYLAR_EK2:1854-08-24:0":{"b": ["Eerste buitenlandse leningsovereenkomst", "9017c579"], "d": ["Voor de financiering van de Krimoorlog werd op de Londense markt de eerste buitenlandse lening aangegaan; het punt dat in 21 jaar met 15 leningen werd bereikt, was het moratorium van 1875 en de Düyûn-ı Umûmiyye.", "1c4f9949"]},
"OLAYLAR_EK2:1855-09-14:0":{"b": ["Telegraaflijn in Constantinopel", "d320f39f"], "d": ["De eerste telegraaflijn, aangelegd vanwege de behoeften van de Krimoorlog, werd in gebruik genomen; het rijk kreeg in enkele decennia een van de grootste telegraafnetwerken ter wereld.", "f59439a3"]},
"OLAYLAR_EK2:1858-06-06:0":{"b": ["Land-kanunname (Arazi Kanunnâmesi)", "6bae243a"], "d": ["De kanunname die het landrecht moderniseerde, bond het feitelijke gebruiksrecht op staatsland (mîrî) aan de tapu (eigendomsakte); zij is een van de basisdocumenten van de eigendomsorde van het huidige Midden-Oosten.", "395494dc"]},
"OLAYLAR_EK2:1863-01-13:0":{"b": ["Eerste lessen in de Dârülfünun", "08f74066"], "d": ["De Dârülfünun, die onderwijs op universitair niveau zou verzorgen, begon te werken met openbare lessen; de instelling, die met onderbrekingen voortbestond, werd in 1900 definitief geopend en werd de kern van de Universiteit van Istanbul.", "6218d070"]},
"OLAYLAR_EK2:1864-11-08:0":{"b": ["Vilayet-reglement (Vilâyet Nizamnâmesi)", "ad20853b"], "d": ["In plaats van het eyalet-stelsel werd een vilayet-organisatie naar Frans model gevestigd; naar het voorbeeld van de toepassing van Midhat Pasja in de Donau-vilayet werd zij over het hele land verspreid.", "665b97d3"]},
"OLAYLAR_EK2:1867-06-21:0":{"b": ["Europese reis van Abdülaziz", "9ff0fa1e"], "d": ["De eerste Europese reis van een Osmaanse sultan met vreedzame doeleinden; de wereldtentoonstelling van Parijs en de bezoeken aan Londen dienden zowel als diplomatie als als etalage van modernisering.", "bd58ae5d"]},
"OLAYLAR_EK2:1868-09-01:0":{"b": ["Opening van de Galatasaray Mekteb-i Sultânîsi", "f9688524"], "d": ["Het lyceum met Franstalig onderwijs werd met zijn leerlingenpopulatie zonder onderscheid van religie en gemeenschap het symbool van het ideaal van gelijkheid in het onderwijs van de Tanzimat.", "c9d5821d"]},
"OLAYLAR_EK2:1869-04-01:0":{"b": ["Eerste boek van de Mecelle in werking", "6475461c"], "d": ["De Mecelle, die het verbintenissen- en zakenrecht van het islamitische recht met moderne wetgevingstechniek codificeerde, wordt beschouwd als het eerste islamitische burgerlijk wetboek; de commissie onder leiding van Cevdet Pasja voltooide de 16 boeken in 1876.", "9669c96e"]},
"OLAYLAR_EK2:1876-05-30:0":{"b": ["Afzetting van Abdülaziz", "eb7397ea"], "d": ["Constitutionalistische staatslieden en militaire kopstukken zetten Abdülaziz met een stille staatsgreep af; zijn verdachte dood vijf dagen later en de daaropvolgende Çırağan-incidenten leidden tot afrekeningen die jarenlang zouden duren.", "9523e81b"]},
"OLAYLAR_EK2:1878-05-20:0":{"b": ["Overval op Çırağan (zaak Ali Suâvi)", "d2a9ac87"], "d": ["De journalist Ali Suâvi overviel Çırağan om Murad V weer op de troon te zetten; de overval werd bloedig neergeslagen en het regime van Abdülhamid verstrakte de veiligheidsring blijvend.", "8bd8ba3f"]},
"OLAYLAR_EK2:1884-01-01:0":{"b": ["Oprichting van de Régie (tabaksmonopolie)", "bad9b030"], "d": ["De tabaksinkomsten werden overgedragen aan de Régie-maatschappij met buitenlands kapitaal binnen de Düyûn-ı Umûmiyye; de conflicten rond de 'Régie-smokkel' tussen boeren en bewakers duurden tientallen jaren. Andere plaatsen die op dezelfde datum verloren gingen: Zeila.", "19e84e39"]},
"OLAYLAR_EK2:1898-10-18:0":{"b": ["Bezoek van keizer Wilhelm II aan Constantinopel en Jeruzalem", "2988cd06"], "d": ["Het tweede bezoek van de Duitse keizer bezegelde de Osmaans-Duitse toenadering; de weg werd geopend voor de concessie van de Bagdadspoorweg en in Damascus werd de toespraak 'vriend van driehonderd miljoen moslims' gehouden.", "2e385229"]},
"OLAYLAR_EK2:1908-09-01:0":{"b": ["Hidjaz-spoorlijn bereikt Medina", "95009b9c"], "d": ["De 1464 km lange lijn, gebouwd met uitsluitend moslimdonaties en lokale ingenieurskunst, bereikte Medina; de pelgrimsreis werd van weken tot dagen verkort. Het is het grootste infrastructuurwerk uit de tijd van Abdülhamid II.", "a1c98c4c"]},
"OLAYLAR_EK2:1909-04-13:0":{"b": ["Incident van 31 maart", "1d7c2bb2"], "d": ["Een grote anti-constitutionele opstand nam Constantinopel in; het Actieleger uit Thessaloniki sloeg de opstand neer en Abdülhamid II werd afgezet.", "4885dfd1"]},
"OLAYLAR_EK2:1912-10-26:0":{"b": ["Beleg van Edirne begon", "234d9b28"], "d": ["De vijf maanden durende verdediging van Şükrü Pasja werd een heldenverhaal van verzet te midden van de Balkanramp; de stad viel door hongersnood en werd in juli 1913 teruggenomen.", "3c3ca395"]},
"OLAYLAR_EK2:1913-01-23:0":{"b": ["Overval op de Hoge Porte (Bâb-ı Âli Baskını)", "b304d02d"], "d": ["De regering, die zich voorbereidde op de overgave van Edirne, werd door een gewapende overval van de Unionisten ten val gebracht; minister van Oorlog Nâzım Pasja werd gedood. De periode van volledige macht van het Comité voor Eenheid en Vooruitgang begon.", "a8a7af44"]},
"OLAYLAR_EK2:1915-07-11:0":{"b": ["Afschaffing van het Mutasarrifaat Libanonberg", "b5639051"], "d": ["De autonome mutasarrifaatsorde, die was gesticht met het Règlement Organique van 1861 en berustte op het in 1864 vernieuwde internationale protocol, werd tijdens de Eerste Wereldoorlog eenzijdig door de Osmaanse staat ontbonden; het ministerie van Binnenlandse Zaken begon rechtstreeks moslim-mutasarrıfs in de regio te benoemen. De autonomieperiode van 1861-1915, waarin acht mutasarrıfs dienden, werd zo gesloten.", "83ff35bc"]},
"OLAYLAR_EK3:1402-08-01:0":{"b": ["Verdeling van het land onder de prinsen", "82f26bfb"], "d": ["Na de nederlaag bij Ankara trok Süleyman Çelebi naar Rumelië en riep in Edirne het sultanaat uit; İsa Çelebi hield Bursa en Çelebi Mehmed het gebied Amasya-Tokat-Sivas in handen. Op de kaart worden deze drie delen in afzonderlijke kleuren weergegeven.", "08baaa0b"]},
"OLAYLAR_EK3:1403-02-01:0":{"b": ["Verdrag van Gallipoli: Zwarte Zeekust tot Mesembria aan Byzantium gelaten", "a4164eca"], "d": ["Emir Süleyman, die zich na de nederlaag bij Ankara in Rumelië wilde handhaven, sloot in Gallipoli een verdrag met de Byzantijnse keizer Manuel. Hij liet Kartal, Pendik en Gebze met enkele eilanden, in Rumelië Thessaloniki en Thessalië en aan de Zwarte Zee de kuststrook tot Mesembria aan Byzantium; ook de belasting die Byzantium aan de Osmanen betaalde, werd afgeschaft. Ahtapolu, İğneada en Rezve aan de Istranca-kust bleven zo eenentwintig jaar onder Byzantijns bestuur; Murad II nam de meeste van deze plaatsen met de vrede van 1424 terug.", "ad1af28a"]},
"OLAYLAR_EK3:1403-03-09:0":{"b": ["Dood van Yıldırım Bayezid in gevangenschap", "7e968d83"], "d": ["De sultan, die in handen van Timur gevangen zat, stierf in Akşehir; zijn lichaam werd naar Bursa gebracht en begraven. Zijn dood maakte de troonstrijd tussen de prinsen onomkeerbaar.", "af68bc4d"]},
"OLAYLAR_EK3:1403-06-15:0":{"b": ["Verdrag van Gallipoli — toegevingen aan Byzantium", "dfacbd00"], "d": ["Süleyman Çelebi, die zijn positie in Rumelië wilde veiligstellen, gaf Thessaloniki, de kusten van de Zee van Marmara en enkele eilanden terug door overeenkomsten met de Byzantijnse en Latijnse staten; hij stemde zelfs in met het betalen van schatting.", "0d91820c"]},
"OLAYLAR_EK3:1403-09-01:0":{"b": ["Treffen bij Ulubat — nederlaag van İsa Çelebi", "500c5d24"], "d": ["İsa Çelebi, die Bursa in handen hield, werd bij Ulubat door zijn broer Mehmed verslagen; ook enkele pogingen tot herstel bleven zonder resultaat.", "624072ce"]},
"OLAYLAR_EK3:1406-06-01:0":{"b": ["Verdwijnen van İsa Çelebi", "0effa11e"], "d": ["İsa Çelebi, die met steun van Süleyman Çelebi enkele malen naar Anatolië terugkeerde, verdween na zijn laatste nederlaag; zijn deel ging naar Çelebi Mehmed en op de kaart breidde het gebied van Mehmed zich naar het westen uit.", "d164b447"]},
"OLAYLAR_EK3:1406-06-18:0":{"b": ["Musa Çelebi trok naar Walachije", "8441267a"], "d": ["Çelebi Mehmed, die Bursa en Ankara aan Süleyman Çelebi had verloren en zich naar Tokat-Amasya had teruggetrokken, moedigde zijn broer Musa aan naar Rumelië te gaan. Musa aanvaardde de uitnodiging van de Walachijse woiwode Mircea en bereikte Walachije over zee; vanaf daar zou hij een strijd aangaan die Süleyman tussen twee fronten zou brengen.", "e7866931"]},
"OLAYLAR_EK3:1410-05-06:0":{"b": ["Çelebi Mehmed nam Bursa en Ankara opnieuw in — het Anatolische deel verliet Süleyman Çelebi", "bfb69f12"], "d": ["Na de successen van Mûsâ Çelebi in Rumelië (Yambol, 13 februari 1410) trok Emir Süleyman Çelebi, die zich in Anatolië bevond, naar Rumelië. Nadat Süleyman Anatolië had verlaten, nam Mehmed Çelebi het gebied rond Bursa, inclusief Ankara, opnieuw in en liet hij ten teken van zijn troonsbestijging munten van het jaar 813 slaan. Op de kaart gaat de Anatolische kant van de Zee van Marmara van het deel van Emir Süleyman over naar de kleur van Çelebi Mehmed.", "bc148b8e"]},
"OLAYLAR_EK3:1410-06-15:0":{"b": ["Slag bij Kosmidion", "0efc2caa"], "d": ["In de slag voor de muren van Constantinopel, gevoerd met Byzantijnse steun, versloeg Süleyman Çelebi zijn broer Musa; maar zijn steun in Rumelië begon snel weg te smelten.", "ece5fe6b"]},
"OLAYLAR_EK3:1411-01-01:0":{"b": ["Beleg van Constantinopel door Musa Çelebi", "4932f586"], "d": ["Musa Çelebi, die Byzantium wilde straffen voor zijn steun aan Süleyman, belegerde Constantinopel; dit beleg dreef Byzantium in een bondgenootschap met Çelebi Mehmed.", "b52f942c"]},
"OLAYLAR_EK3:1411-02-17:0":{"b": ["Dood van Emir Süleyman — Musa heerst over Rumelië", "325c1549"], "d": ["Süleyman Çelebi werd tijdens zijn vlucht uit Edirne gevangengenomen en gedood; heel Rumelië kwam in handen van Musa Çelebi. Op de kaart verandert Rumelië van blauw naar paars.", "48aa849a"]},
"OLAYLAR_EK3:1413-07-05:0":{"b": ["Slag bij Çamurlu — herstel van de eenheid", "0b23173e"], "d": ["Çelebi Mehmed, die de steun van Byzantium, het Servische despotaat en de beys van Rumelië had gekregen, bracht zijn broer Musa bij Çamurlu een beslissende nederlaag toe; Musa werd tijdens zijn vlucht gedood. Rumelië, dat in handen van Musa was, ging samen met Edirne naar Mehmed en Mehmed Çelebi riep zich in Edirne uit tot de enige heerser van de Osmaanse staat. Het elf jaar durende Interregnum eindigde, de delen van de prinsen op de kaart werden in één lichaam verenigd.", "649e53b7"]},
"OLAYLAR_EK3:1683-01-01:0":{"b": ["Besluit tot de veldtocht naar Wenen — vrede van Vasvár niet vernieuwd, doel verlegd van Győr naar Wenen", "1bf278f2"], "d": ["Keizer Leopold I wilde dat het Verdrag van Vasvár, waarvan de termijn nog niet verstreken was, werd vernieuwd, en ook Mehmed IV leek voor vrede. Grootvizier Merzifonlu Kara Mustafa Pasja liet de vrede echter niet vernieuwen met als reden de klachten van Imre Thököly, die hij tot koning van Midden-Hongarije had laten uitroepen; hij zette predikers met Vânî Mehmed Efendi voorop in beweging en overtuigde de sultan van de oorlog. In het overleg werd besloten dat de sultan in Belgrado zou blijven en de serdar-ı ekrem verder zou trekken om Győr (Yanıkkale) in te nemen; maar in het overleg in Székesfehérvár werd het doel, ondanks het bezwaar van de Krim-khan Murad Giray en de gouverneur van Boeda, Uzun İbrâhim Pasja, veranderd in het beleg van Wenen.", "7a572168"]},
"OLAYLAR_EK3:1683-07-14:0":{"b": ["Tweede Beleg van Wenen begon — leger voor Wenen", "bb542e49"], "d": ["Het Osmaanse leger onder bevel van grootvizier Kara Mustafa Pasja kwam op 14 juli 1683 voor Wenen aan. Keizer Leopold I liet de verdediging van de stad over aan Starhemberg en trok zich terug in het binnenland van Oostenrijk. Dit tweede beleg, dat in tegenstelling tot het eerste rechtstreeks op Wenen werd voorbereid, zou tot 12 september duren.", "ecea5576"]},
"OLAYLAR_EK3:1683-10-09:0":{"b": ["Nederlaag bij Párkány en verlies van Esztergom", "a7366740"], "d": ["Het leger dat zich uit Wenen terugtrok werd bij Párkány voor de tweede keer verslagen; daarna viel Esztergom, een van de sleutelburchten van Hongarije. De terugtocht begon in een ineenstorting over te gaan.", "13a860f4"]},
"OLAYLAR_EK3:1683-12-25:0":{"b": ["Executie van Merzifonlu Kara Mustafa Pasja", "ce8b10ac"], "d": ["De grootvizier, die verantwoordelijk werd gehouden voor de nederlaag bij Wenen, werd in Belgrado gewurgd; maar zijn executie herstelde noch het front noch het aangetaste prestige van de staat.", "23449e61"]},
"OLAYLAR_EK3:1684-03-05:0":{"b": ["Heilige Liga opgericht", "060280d0"], "d": ["Onder leiding van het pausdom werd tussen Oostenrijk, Polen en Venetië de Heilige Liga tegen de Osmanen gesloten; in 1686 trad ook Rusland toe. Het rijk raakte zo verwikkeld in een zestien jaar durende oorlog aan meerdere fronten.", "5f02a851"]},
"OLAYLAR_EK3:1684-07-14:0":{"b": ["Eerste verdediging van Boeda", "ccc43630"], "d": ["Het eerste beleg van Boeda door het leger van de Heilige Liga werd afgeslagen door de koppige verdediging van de burcht, die vier maanden duurde; maar de burchten in Hongarije bleven een voor een vallen.", "fb62dd75"]},
"OLAYLAR_EK3:1685-08-19:0":{"b": ["Verlies van Uyvar", "689ab78c"], "d": ["De burcht Uyvar, die tweeëntwintig jaar in Osmaanse handen was gebleven en in Europa een spreekwoord was geworden, viel; de Osmaanse aanwezigheid in Boven-Hongarije viel uiteen.", "559f5062"]},
"OLAYLAR_EK3:1685-10-15:0":{"b": ["Arrestatie van Thököly in Oradea — Koninkrijk Midden-Hongarije ontbonden, burchten van Boven-Hongarije gaven zich over", "1741aaaf"], "d": ["Na de nederlaag bij Wenen begonnen de Osmanen ook Thököly te zien als een van degenen die tot de oorlog en de nederlaag hadden geleid. Op 15 oktober 1685 liet de beylerbey van Varad, Ahmed Pasja, op bevel van serdar Melek İbrâhim Pasja Thököly, die kwam om te helpen, gevangennemen; men hoopte betere vredesvoorwaarden te verkrijgen door hem aan de Habsburgers over te leveren. Toen het nieuws van de arrestatie zich verspreidde, gaven alle burchten en steden van het Koninkrijk Midden-Hongarije zich over aan de Habsburgers, met uitzondering van Munkács, dat door zijn vrouw Ilona Zrínyi werd verdedigd; de meeste kurucen-soldaten liepen over naar het Habsburgse leger. Toen Thököly op 2 januari 1686 in Belgrado werd vrijgelaten, bestond het koninkrijk niet meer.", "1a00b9f3"]},
"OLAYLAR_EK3:1686-09-02:0":{"b": ["Verlies van Boeda — 145 jaar Hongaarse hoofdstad", "70800e2b"], "d": ["Na een beleg van achtenzeventig dagen viel Boeda; de laatste beylerbey Abdurrahman Abdi Pasja sneuvelde op de muren. Het verlies van de stad, die sinds 1541 onder Osmaans bestuur stond, geldt als het symbool van het verlies van Hongarije. Andere plaatsen die op dezelfde datum verloren gingen: Pest.", "e66f909f"]},
"OLAYLAR_EK3:1687-08-12:0":{"b": ["Tweede Mohács (Harsány) — verlies van Transsylvanië en Mohács", "a7922681"], "d": ["Op de vlakte waar in 1526 de grote overwinning was behaald, werd ditmaal een zware nederlaag geleden; het leger viel uiteen en de opstandige soldaten lieten de grootvizier afzetten. De nederlaag leidde ook tot het verlies van Transsylvanië.", "6b95b7d0"]},
"OLAYLAR_EK3:1687-09-26:0":{"b": ["Verlies van Athene en de Parthenon-explosie", "b6691730"], "d": ["Een bom van de Venetiaanse artillerie liet de Parthenon, die de Osmanen als munitiemagazijn gebruikten, de lucht in vliegen; de tweeduizend jaar oude tempel werd een ruïne. De stad kwam in Venetiaanse handen (zij zou in 1688 worden teruggenomen).", "e28ad137"]},
"OLAYLAR_EK3:1687-11-08:0":{"b": ["Afzetting van Mehmed IV en troonsbestijging van Süleyman II", "9f53037c"], "d": ["Na rampen aan het front en de opstand van het leger werd Mehmed IV na een regering van 39 jaar afgezet; in zijn plaats werd zijn broer Süleyman II, die veertig jaar in de kooi was gehouden, op de troon gezet.", "6a7bb845"]},
"OLAYLAR_EK3:1688-09-06:0":{"b": ["Eerste verlies van Belgrado — beleg door de Heilige Liga", "c6b9b19a"], "d": ["Belgrado, dat sinds 1521 in Osmaanse handen was, gaf zich over aan het leger van de Heilige Liga; de poorten van Servië gingen open voor de vijand en het gevaar naderde de lijn Niš–Sofia. Andere plaats die op dezelfde datum in de atlas van de Osmanen naar de Habsburgers ging: Hisarcık (Grocka) — volgt de abi-centrumketen van Belgrado (TDV belgrad; verklaarde benadering).", "ba09a1ad"]},
"OLAYLAR_EK3:1689-08-01:0":{"b": ["Baden stak de Morava over bij Pasarofça — Pasarofça viel aan Oostenrijk", "bcf3fc59"], "d": ["Markgraaf Ludwig von Baden stak in augustus 1689 de Morava over bij Pasarofça en rukte op in de richting van Niš; de stad bleef tot de zomer van 1690 in Oostenrijkse handen (TDV suleyman-ii zegt dat Pasarofça in 1690 werd teruggenomen). De datum en de lezing van Röder werden in deze sessie niet opnieuw bevestigd.", "28e54b6c"]},
"OLAYLAR_EK3:1689-09-24:0":{"b": ["Verlies van Niš — opmars van de Habsburgers (kroon van het Koninkrijk Hongarije), kritiekste jaar", "c5e27b3f"], "d": ["De opmars van de Habsburgers (kroon van het Koninkrijk Hongarije) nam ook Niš uit het Osmaanse bestuur; de strooptochten reikten tot Üsküp en Priština. Vidin viel hierna, in oktober 1689 (afzonderlijk item). In het donkerste jaar van de oorlog voelde de staat zelfs de hoofdstad bedreigd.", "77de2b1f"]},
"OLAYLAR_EK3:1689-10-25:0":{"b": ["Orsova en Fethülislâm kregen een Oostenrijks garnizoen", "ee8dd875"], "d": ["Na de overgave zonder strijd van Vidin (oktober 1689, TDV vidin) herstelde Baden op 25 oktober 1689 Orsova en Fethülislâm (Kladovo) en voorzag ze van een garnizoen; Orsova bleef tot de herfst van 1690 Oostenrijks. De datum berust op Bánlaky/Röder en werd in deze sessie niet opnieuw bevestigd.", "4c6ebd2c"]},
"OLAYLAR_EK3:1690-09-27:0":{"b": ["Niš opnieuw Osmaans", "0c4f44eb"], "d": ["Fâzıl Mustafa Pasja trok in juli 1690 ten strijde; nadat Şehirköy, Pasarofça en Güvercinlik waren ingenomen, kwam het belegerde Niš op 27 september 1690 in Osmaanse handen (TDV semendire). Tegelijkertijd was ook Vidin teruggenomen. Andere plaatsen die op dezelfde datum in de atlas van de Habsburgers naar de Osmanen terugkeerden: Jagodina en Prokuplje (Ürküp) — omdat geen plaatsniveaudag kon worden gevonden, is de dag van Niš genomen (TDV semendire; verklaarde benadering; Röder 1842 schrijft dat de vizier tussen 8 en 24 september door Jagodina trok, de tegenspraak is niet opgelost).", "ec6a2b00"]},
"OLAYLAR_EK3:1690-10-01:0":{"b": ["Oostenrijkse troepen in Smederevo gaven zich over", "90da20c4"], "d": ["Na de inname van Niš op 27 september 1690 gaven de Oostenrijkse troepen in Smederevo zich na een beleg van vier dagen over (TDV semendire). Bánlaky/Röder noemt 24 september; de bronnen spreken elkaar tegen, de TDV is als basis genomen.", "9034a37d"]},
"OLAYLAR_EK3:1690-10-08:0":{"b": ["Belgrado teruggenomen", "ab435838"], "d": ["Grootvizier Köprülüzâde Fâzıl Mustafa Pasja nam Belgrado op 8 oktober 1690 op Oostenrijk terug; de stad die in 1688 verloren was gegaan keerde zo terug naar de Osmanen (TDV suleyman-ii). Andere plaats die op dezelfde datum in de atlas van de Habsburgers naar de Osmanen terugkeerde: Hisarcık (Grocka) — volgt de abi-centrumketen van Belgrado (TDV suleyman-ii; verklaarde benadering).", "5b889cb0"]},
"OLAYLAR_EK3:1691-08-19:0":{"b": ["Nederlaag bij Slankamen — Fâzıl Mustafa Pasja sneuvelde", "10d626f1"], "d": ["In een van de bloedigste veldslagen van de eeuw sneuvelde de grootvizier, in het voorhoofd getroffen; het leger viel uiteen. Met deze slag doofde de hoop op herstel.", "36dfe6ea"]},
"OLAYLAR_EK3:1694-09-21:0":{"b": ["Verlies van het eiland Chios", "07c084f8"], "d": ["De Venetiaanse vloot bezette Chios; de Osmaanse heerschappij in de Egeïsche Zee kwam onder dreiging. Het eiland zou het jaar daarop worden teruggenomen.", "f5f59c77"]},
"OLAYLAR_EK3:1695-02-11:0":{"b": ["Besluit van Mustafa II om persoonlijk ten strijde te trekken", "61c3ba9c"], "d": ["De nieuwe sultan kondigde aan dat hij naar het voorbeeld van zijn voorouders aan het hoofd van het leger ten strijde zou trekken; dit besluit wekte moreel in het leger en leidde de periode van persoonlijke veldtochten in die twee jaar zou duren.", "2794ae0f"]},
"OLAYLAR_EK3:1695-02-22:0":{"b": ["Herovering van Chios", "6b496fca"], "d": ["Mezomorto Hüseyin Pasja, die in de zeeslagen bij de Koyun-eilanden de Venetiaanse vloot versloeg, nam Chios terug; een teken van een korte opleving van de Osmaanse zeevaart.", "7638e074"]},
"OLAYLAR_EK3:1695-09-22:0":{"b": ["Overwinning bij Lugoj — eerste Oostenrijkse veldtocht van Mustafa II", "d5ee9b34"], "d": ["In de eerste veldtocht waaraan de sultan persoonlijk deelnam werd Lipova teruggenomen en werden de Oostenrijkse strijdkrachten bij Lugoj verslagen; in de al jaren durende keten van nederlagen vond de eerste breuk plaats. De atlas beschouwt ook Caransebeș (Karánşebeş) in deze veldtocht als van de Habsburgers naar de Osmanen teruggekeerd; de bron geeft alleen september 1695 (TDV mustafa-ii), de atlasdag is overgenomen van de Lugoj-aantekening (verklaarde benadering).", "a6411d61"]},
"OLAYLAR_EK3:1696-07-19:0":{"b": ["Verlies van de burcht Azak", "2b78b5cd"], "d": ["Peter I, die ernaar streefde de Zwarte Zee te bereiken, nam Azak in tijdens zijn tweede beleg; Rusland vestigde zich voor het eerst blijvend in een Osmaanse burcht en zette zijn eerste stap op weg naar een zeemacht.", "b765c903"]},
"OLAYLAR_EK3:1696-08-27:0":{"b": ["Overwinning bij Ulaş (Olașin)", "02ac9ca8"], "d": ["De overwinning die tijdens de tweede veldtocht van de sultan aan de oever van de Donau werd behaald, doorkruiste het Oostenrijkse plan om Temesvár in te nemen; maar zij veranderde het algemene evenwicht van de oorlog niet.", "b6e2d27a"]},
"OLAYLAR_EK3:1697-09-11:0":{"b": ["Nederlaag bij Zenta — het lot van de oorlog bepaald", "475c4a7b"], "d": ["Het leger werd bij het oversteken van de Tisza overvallen door prins Eugenius; de strijdkrachten, verdeeld over beide oevers van de rivier, werden binnen enkele uren vernietigd, en duizenden soldaten en staatslieden, onder wie grootvizier Elmas Mehmed Pasja, kwamen om. Zenta, een van de zwaarste nederlagen uit de Osmaanse geschiedenis, maakte de vredestafel onvermijdelijk.", "ced10fdc"]},
"OLAYLAR_EK3:1698-11-13:0":{"b": ["Vredesonderhandelingen van Karlowitz begonnen", "1f395cf3"], "d": ["In de onderhandelingen die onder bemiddeling van Engeland en Nederland begonnen, moest de Osmaanse delegatie voor het eerst het beginsel van 'uti possidetis' (het behoud van het bezit) aanvaarden; de onderhandelingen, die tweeënzeventig zittingen duurden, worden beschouwd als de geboorte van de moderne Osmaanse diplomatie.", "1d41e9e8"]},
"OLAYLAR_EK4:1801-03-08:0":{"b": ["Mehmed Ali van Kavala ging in Egypte aan land", "514c943f"], "d": ["Onder het Osmaanse leger dat werd gestuurd om het door de Fransen bezette Egypte terug te nemen, bevond zich ook een uit Kavala bijeengebrachte vrijwilligerseenheid. Mehmed Ali, die in de dertig was, was de tweede commandant van deze eenheid; hij zette voet in Egypte niet als gouverneur maar als officier van een compagnie.", "b7e3bb36"]},
"OLAYLAR_EK4:1803-05-01:0":{"b": ["Albanese soldaten zetten de gouverneur van Egypte af", "c76a0ec2"], "d": ["De Albanese troepen, wier soldij niet werd betaald, kwamen in opstand en dwongen gouverneur Hüsrev Pasja de citadel te ontvluchten. In het vacuüm dat ontstond door het vertrek van de Fransen raakten de Mamelukkenbeys, het Albanese korps en de door de Hoge Porte benoemde gouverneurs verwikkeld in een driehoeksstrijd; Mehmed Ali kwam naar voren door in deze driehoek evenwichten te scheppen. Andere plaatsen die op dezelfde datum verloren gingen: Ta'if.", "669d61a0"]},
"OLAYLAR_EK4:1805-05:0":{"b": ["De ulema van Caïro riepen Mehmed Ali uit tot gouverneur", "a16752f2"], "d": ["De handelaren en ulema van Caïro, bezwijkend onder de belastingdruk, kwamen onder leiding van de naqib al-ashraf Omar Makram in opstand, verklaarden gouverneur Hurşid Pasja niet te erkennen en zetten Mehmed Ali op de gouverneurszetel. Dat een gouverneur door het volk werd gekozen, is in de Osmaanse geschiedenis een zeldzame gebeurtenis.", "1572b66f"]},
"OLAYLAR_EK4:1805-07-03:0":{"b": ["De Hoge Porte aanvaardde het voldongen feit: firman van het gouverneurschap van Egypte", "b86736a3"], "d": ["De Hoge Porte, die geen macht had om in Egypte haar eigen kandidaat te handhaven, zond Mehmed Ali een firman met de rang van vizier en het gouverneurschap van Egypte. Op de kaart gaat Egypte vanaf deze datum over naar de vazallaag (lichte tint): juridisch Osmaans grondgebied, feitelijk het land van de dynastie van Kavala. Andere plaatsen die op dezelfde datum naar de vazallaag gingen: Caïro, Alexandrië, Damietta, Asyut, Aswan, İbrim, Suez, Reşîd (Rosetta).", "e769c607"]},
"OLAYLAR_EK4:1807-03-17:0":{"b": ["De Britse expeditie van Fraser landde in Alexandrië", "4d6c31be"], "d": ["Als antwoord op de Osmaanse toenadering tot Frankrijk zond Engeland een landingsmacht naar Egypte. Mehmed Ali was op dat moment in Boven-Egypte bezig met de Mamelukken; hij keerde snel terug en organiseerde de verdediging.", "fd5f278f"]},
"OLAYLAR_EK4:1807-04-21:0":{"b": ["Nederlaag bij Rosetta (Reşid) — Britten teruggeslagen", "3636004c"], "d": ["De Britse colonne die de stad Rosetta binnentrok leed bij straatgevechten zware verliezen; in september ontruimden de troepen Egypte volledig. Deze overwinning versterkte het aanzien van Mehmed Ali zowel in Egypte als in Constantinopel.", "68a2ba26"]},
"OLAYLAR_EK4:1811-03-01:0":{"b": ["Bloedbad in de Citadel: liquidatie van de Mamelukkenbeys", "84030b97"], "d": ["De Mamelukkenbeys, uitgenodigd voor de ceremoniële stoet voor de Hidjaz-veldtocht, werden in de nauwe doorgang van de Citadel van Caïro in de val gelokt en uitgeschakeld. De vijfhonderd jaar durende Mamelukse invloed kwam zo ten einde en Mehmed Ali had in Egypte geen rivalen meer.", "1ca00e33"]},
"OLAYLAR_EK4:1811-09-03:0":{"b": ["Hidjaz-veldtocht begon — het leger trok vanuit Suez over zee en over land langs de pelgrimsroute naar Yanbu", "1c05c159"], "d": ["Het heroveren van de Haramain, die sinds 1803 onder Saoedi-wahhabitisch bestuur stonden, was de grootste legitimiteitskwestie van Mahmud II; toen de Hoge Porte daartoe de macht niet had, werd de taak aan de gouverneur van Egypte gegeven. Mehmed Ali stuurde zijn zestienjarige zoon Tusun aan het hoofd van het leger.", "5e614d69"]},
"OLAYLAR_EK4:1811-10-01:0":{"b": ["Yanbu overgenomen — eerste kustbasis van de Hidjaz-veldtocht", "179bc78d"], "d": ["Ongeveer tweeduizend Albanese infanteristen die met nieuw gebouwde schepen uit Suez vertrokken, gingen in oktober 1811 bij Yanbu aan land; het stadje gaf zich na twee dagen zwak verzet over. De cavalerie onder bevel van Tusun volgde de pelgrimsroute over land en bereikte via Aqaba en Wejh pas twee weken later Yanbu. Yanbu werd de eerste basis in de Hidjaz van het Egyptische leger dat naar Medina en Mekka zou optrekken.", "cfc2ed8a"]},
"OLAYLAR_EK4:1812-01-01:0":{"b": ["Eerste nederlaag in de pas van Safra-Jedida", "99ef804d"], "d": ["De Egyptische voorhoede, in de smalle bergpassen in een hinderlaag gelokt, werd uiteengeslagen. De nederlaag werd de tactische les van de veldtocht: het bleek onmogelijk in de Hidjaz op te trekken zonder de steun van de bedoeïenenstammen.", "765dd19d"]},
"OLAYLAR_EK4:1812-12-03:0":{"b": ["Medina teruggenomen", "6f6a5d55"], "d": ["Na een lang beleg gaf Medina zich over. De herovering van de stad van de Profeet werd in Constantinopel gevierd met kanonschoten; als beloning voor Mehmed Ali werd ook het gouverneurschap van Jeddah gegeven.", "45cc4c79"]},
"OLAYLAR_EK4:1813-01-23:0":{"b": ["Mekka teruggenomen — pelgrimsroute geopend", "3d6d66a0"], "d": ["De Egyptische strijdkrachten die Mekka binnentrokken, lieten bij de Ka'ba opnieuw de khutba lezen in naam van de Osmaanse sultan. De pelgrimskaravanen, die al tien jaar waren onderbroken, konden weer vertrekken. Op de kaart keert de Hidjaz terug naar de Osmaanse heerschappij, maar omdat het bestuur in Caïro zetelt, wordt het in vazalkleur weergegeven. Andere plaats die op dezelfde datum onder vazalbestuur kwam: Jeddah.", "f0970e28"]},
"OLAYLAR_EK4:1813-05-02:0":{"b": ["Herovering van Ta'if — voltooiing van de Hidjaz-veldtocht", "6315fb31"], "d": ["Na Medina (december 1812) en Mekka (januari 1813) nam het Egyptische leger onder bevel van Tusun Pasja ten slotte ook Ta'if op de wahhabieten terug. De tien jaar durende Saoedische heerschappij kwam ten einde en ook de drie heilige centra van de Hidjaz kwamen weer onder Osmaans-Egyptische controle.", "374bf563"]},
"OLAYLAR_EK4:1813-08-28:0":{"b": ["Mehmed Ali trok persoonlijk naar de Hidjaz", "fda0ea2d"], "d": ["De gouverneur, die zag dat de veldtocht traag verliep, nam het bestuur rechtstreeks in handen; hij probeerde het Saoedische front van binnenuit te laten ineenstorten door met de stamhoofden te onderhandelen. Ook het aandeel van Egypte in de Rode Zee-handel groeide door deze veldtocht.", "aeb051d1"]},
"OLAYLAR_EK4:1815-01-20:0":{"b": ["Slag bij Basal: Saoedische strijdkrachten verslagen", "9c9ab91f"], "d": ["De Saoedi's, die in de open veldslag een zware nederlaag leden, trokken zich terug in het binnenland. De gesloten wapenstilstand was niet blijvend; twee jaar later zou de campagne naar het hart van Nejd worden gebracht. De atlas beschouwt na deze overwinning Turaba en Khurma ten oosten van Ta'if als aan de Saoedi's ontnomen (bron van het feit: Lorimer, Gazetteer; plaatsspecifieke getuigenis en de dag 13 januari zijn verklaarde benadering).", "551e1880"]},
"OLAYLAR_EK4:1816-09-01:0":{"b": ["İbrâhim Pasja trok ten strijde naar Nejd", "d5ed80d1"], "d": ["İbrâhim Pasja, die na de dood van zijn broer Tusun het bevel overnam, begon aan een zware tocht door de woestijn die twee jaar duurde. Het leger, dat van put naar put oprukte, schakelde de stammen een voor een uit en bereikte de Saoedische hoofdstad.", "e84c2cef"]},
"OLAYLAR_EK4:1818-09-09:0":{"b": ["Dir'iyya viel — eerste Saoedische staat kwam ten einde", "aa96206d"], "d": ["Na een beleg van zes maanden gaf Dir'iyya zich over en werd verwoest. Emir Abdullah b. Saud werd naar Constantinopel gezonden en geëxecuteerd. De Osmaanse vlag bereikte voor het eerst zo diep het binnenland van Arabië; het garnizoen in Nejd bleef tot 1824. Andere plaatsen die op dezelfde datum werden toegevoegd: Dir'iyya (Nejd).", "4b161cf5"]},
"OLAYLAR_EK4:1820-07-20:0":{"b": ["Soedan-veldtocht begon", "b1fc6905"], "d": ["Het doel van Mehmed Ali was drieledig: soldaten voor zijn leger verzamelen, het goud van Sennar bereiken en de overblijfselen van de gevluchte Mamelukken vernietigen. De troepen onder bevel van zijn zoon İsmâil Pasja trokken langs de Nijl naar het zuiden.", "478563e9"]},
"OLAYLAR_EK4:1821-01-04:0":{"b": ["Dongola ingenomen — resten van de Mamelukken verspreid", "ba6bc24b"], "d": ["Het leger dat Dongola, in de grote bocht van de Nijl, binnentrok, liquideerde de laatste Mamelukkengroep die daar een toevlucht had gezocht. Op de kaart verschijnt Soedan vanaf deze datum in de vazallaag: Caïro is de veroveraar en Caïro zal het ook besturen.", "bca7d521"]},
"OLAYLAR_EK4:1821-06-14:0":{"b": ["Het sultanaat Sennar (Funj) gaf zich over", "3cac7dd2"], "d": ["De driehonderd jaar oude dynastie van de Funj gaf zich zonder strijd over. Het kamp dat in hetzelfde jaar werd opgericht op het punt waar de twee takken van de Nijl samenvloeien, veranderde snel in Khartoem, het bestuurscentrum van Soedan. Andere plaatsen die op dezelfde datum werden toegevoegd: Sennar.", "1ad105c1"]},
"OLAYLAR_EK4:1821-08-19:0":{"b": ["Kordofan veroverd", "06440602"], "d": ["De tweede colonne die naar het westen werd gestuurd, versloeg de strijdkrachten van Darfoer bij Bara en nam Kordofan in met de omgeving van Nuhud. De Egyptische heerschappij over Soedan breidde zich zo uit van de Nijlvallei tot de westelijke steppen.", "6bc3a4f6"]},
"OLAYLAR_EK4:1822-06-28:0":{"b": ["Egyptische strijdkrachten landden op Kreta", "835aee90"], "d": ["Toen de Griekse opstand oversloeg naar Kreta, vroeg de Hoge Porte dat een Egyptische troepenmacht naar het eiland zou worden gestuurd. Met deze interventie begon de invloed van Mehmed Ali op het eiland, die acht jaar later uitmondde in de toekenning van het gouverneurschap van Kreta aan hem.", "8d651366"]},
"OLAYLAR_EK4:1822-10-24:0":{"b": ["Moord op İsmâil Pasja in Shendi", "223860c9"], "d": ["De lokale emir Nimr, woedend over de zware belasting- en soldatenvorderingen, stak het huis waarin İsmâil Pasja verbleef in brand en verbrandde hem en zijn gevolg. De vergeldingscampagne veranderde de regio in een bloedbad; het bestuur van Soedan werd daarna op hardheid gebaseerd.", "722af711"]},
"OLAYLAR_EK4:1824-07-19:0":{"b": ["Mahmud II vroeg Mehmed Ali om hulp voor de Morea", "03594a42"], "d": ["Voor de Morea-opstand, die het janitsarenleger in drie jaar niet kon neerslaan, wendde de sultan zich tot het Egyptische leger dat naar Europees model was getraind. Als tegenprestatie werden het gouverneurschap van de Morea en Kreta beloofd. Dit verzoek was de eerste openlijke bekentenis dat het rijk afhankelijk was geworden van zijn eigen provincie.", "1b0ee342"]},
"OLAYLAR_EK4:1825-02-24:0":{"b": ["İbrâhim Pasja ging bij Modon aan land", "9c993dba"], "d": ["De landingsmacht, beschermd door de Egyptische vloot, zette voet aan de zuidwestpunt van de Morea. Dit leger, uitgerust met reguliere infanterie en veldartillerie, verkreeg snel de overhand op de opstandige benden.", "edf38fca"]},
"OLAYLAR_EK4:1825-06-22:0":{"b": ["Tripolitsa teruggenomen — centrum van de Morea viel", "8a478c11"], "d": ["Met de val van Tripolitsa, het bestuurscentrum van de opstand, kwam het grootste deel van de Morea weer onder controle. Op de kaart verschijnt het schiereiland in vazalkleur omdat het in handen was van de Egyptische strijdkrachten.", "e7d9b818"]},
"OLAYLAR_EK4:1826-04-22:0":{"b": ["Missolonghi (Mesolongi) viel", "07257f87"], "d": ["Na een beleg van een jaar werd de stad ingenomen. Maar de weerklank die de verdediging in de Europese pers kreeg, bracht de sympathie voor de Griekse zaak op een hoogtepunt en bereidde de grond voor de interventie van de grote mogendheden.", "9bf1efc2"]},
"OLAYLAR_EK4:1827-06-05:0":{"b": ["Akropolis van Athene overgenomen", "3b19f946"], "d": ["Met de val van de Akropolis was de Griekse opstand militair bijna ten einde. Op dat punt hield de kwestie op een interne opstand te zijn en werd zij een onderwerp van de Europese diplomatie.", "e096fc52"]},
"OLAYLAR_EK4:1827-07-06:0":{"b": ["Verdrag van Londen: drie mogendheden dwongen Griekse autonomie af", "7ce46fd8"], "d": ["Engeland, Frankrijk en Rusland besloten gezamenlijk op te treden om de Osmanen en de Grieken een wapenstilstand en autonomievoorwaarde te laten aanvaarden; er werd meegedeeld dat hun vloten zouden ingrijpen als dit werd geweigerd. De Hoge Porte verwierp het aanbod.", "8382f516"]},
"OLAYLAR_EK4:1828-08-06:0":{"b": ["Conventie van Alexandrië: Egypte besloot zich uit de Morea terug te trekken", "cc978f37"], "d": ["Mehmed Ali, die zijn vloot bij Navarino had verloren, kwam zonder Constantinopel te raadplegen rechtstreeks overeen met de Britse admiraal om zijn strijdkrachten uit de Morea terug te trekken. Dat een gouverneur zelfstandig verdragen sloot met de grote mogendheden, kondigde de toekomstige crisis aan.", "9430ea24"]},
"OLAYLAR_EK4:1828-10-05:0":{"b": ["Egyptische strijdkrachten ontruimden de Morea", "8fb742dd"], "d": ["De laatste troepen werden ingescheept; het schiereiland ging feitelijk verloren en werd met het Protocol van Londen van 1830 de kern van het onafhankelijke Griekenland. Mehmed Ali had het beloofde gouverneurschap van de Morea niet gekregen en daarvoor een grote vloot en een groot leger verloren. Andere plaatsen die op dezelfde datum verloren gingen: Modon, Koron.", "7bfbefe0"]},
"OLAYLAR_EK4:1830-11-01:0":{"b": ["Bestuur over Kreta aan Mehmed Ali gelaten", "7f76396d"], "d": ["Als compensatie voor het verlies van de Morea werd het gouverneurschap van Kreta aan Mehmed Ali gegeven. Het eiland werd tien jaar lang vanuit Caïro bestuurd; op de kaart verschijnt het in die tijd in vazalkleur. Andere plaatsen die op dezelfde datum werden toegevoegd: Kandiye (Kreta).", "5b000d2b"]},
"OLAYLAR_EK4:1831-10-31:0":{"b": ["İbrâhim Pasja trok Syrië binnen — eerste crisis begon", "1a5cc386"], "d": ["Het voorwendsel was de gouverneur van Akko, die de uit Egypte gevluchte fellahs niet uitleverde; de werkelijke reden was de behoefte van Mehmed Ali aan het hout, de havens en de mankracht van Syrië. Het leger stak de Sinaï over en nam snel de Palestijnse kust in.", "9d41b0f9"]},
"OLAYLAR_EK4:1831-11-26:0":{"b": ["Beleg van Akko begon", "b211d96d"], "d": ["De burcht, die Napoleon in 1799 had tegengehouden, hield zes maanden stand. Het beleg was de eerste grote proef voor de moderne artillerie van het Egyptische leger.", "97d9816b"]},
"OLAYLAR_EK4:1832-05-27:0":{"b": ["Akko viel", "0f47917b"], "d": ["Toen de batterijen die de muren beschoten een bres sloegen, werd de burcht ingenomen. De poort naar Syrië was geopend; de Hoge Porte verklaarde Mehmed Ali in diezelfde dagen tot rebel en schafte zijn gouverneurschap af.", "f92b4224"]},
"OLAYLAR_EK4:1832-06-16:0":{"b": ["Damascus gaf zich over", "48da3b62"], "d": ["De stad gaf zich zonder strijd over. İbrâhim Pasja probeerde de plaatselijke steun te winnen door de belastingorde en de gelijkheid voor niet-moslims af te kondigen; dezelfde politiek zou enkele jaren later ook de reden worden voor opstanden tegen hem. Andere plaatsen die in dezelfde dagen werden toegevoegd: Beiroet, Tripoli (Trablusşam), Sidon.", "c67bd97e"]},
"OLAYLAR_EK4:1832-07-08:0":{"b": ["Slag bij Homs", "867810ee"], "d": ["Het Osmaanse leger dat werd gestuurd om Syrië te bevrijden werd in open terrein verslagen. Het bleek dat het nieuwe leger, zes jaar na de afschaffing van het janitsarenkorps opgericht, nog niet gereed was.", "f429ba2e"]},
"OLAYLAR_EK4:1832-07-15:0":{"b": ["Aleppo ingenomen", "9c0ead76"], "d": ["Ook het handels- en bestuurscentrum van Noord-Syrië viel. Zo naderde het Egyptische leger de voet van de Taurus en richtte zich op de passen aan de poort van Anatolië.", "b8b4a1bd"]},
"OLAYLAR_EK4:1832-07-29:0":{"b": ["Nederlaag in de pas van Belen (Beylan) — Çukurova geopend", "4bae872b"], "d": ["De verdedigingslinie in de smalle pas in het Amanosgebergte werd doorbroken. Antiochië, Adana en Tarsus gingen naar de Egyptische strijdkrachten (de bezetting van Maraş is volgens de TDV in 1833, afzonderlijk item); op de kaart keert Çukurova terug naar de vazaltint. De weg naar het binnenland van Anatolië was nu onverdedigd.", "73cb1c5e"]},
"OLAYLAR_EK4:1832-09-13:0":{"b": ["Gülek-pas viel — kust van İçel (Mersin, Silifke) kwam onder Egyptische controle", "d9049b5b"], "d": ["De Gülek-pas, de Çukurova-poort van de Taurus, kwam in handen van het Egyptische leger. İbrâhim Pasja benoemde zijn eigen müteselllim in de sandjak İçel en alle aanlegplaatsen aan de kust kwamen onder Egyptische controle. Op de kaart worden Mersin en Silifke vanaf deze dag (ondergrens; de benoemingsdag staat niet in de bron) als aan Egypte gebonden weergegeven; omdat in het besluit van Kütahya alleen de muhassıllık van Adana werd overgedragen, eindigt deze controle met de ontruiming van Anatolië.", "fa650158"]},
"OLAYLAR_EK4:1832-09-13:1":{"b": ["Konya Ereğli onder Egyptische bezetting — Taurus-ingang van de weg Konya–Adana", "fb908900"], "d": ["Ereğli, gelegen op de weg naar Konya van het Egyptische leger dat de Gülek-pas had overschreden, kwam in 1832 onder bezetting van İbrâhim Pasja en werd, toen het met de regeling van Kütahya in 1833 werd ontruimd, opnieuw aan de provincie Karaman gebonden. Op de kaart is het het door bronnen gestaafde tussenpunt van de bezettingslijn tussen Adana en Konya; voor Ulukışla en Karapınar kon geen getuigenis op stadsniveau worden gevonden.", "c5c7c153"]},
"OLAYLAR_EK4:1832-11-21:0":{"b": ["Egyptisch leger trok Konya binnen", "13952a2d"], "d": ["Het leger dat de Taurus was overgestoken, bereikte Midden-Anatolië. Voor het eerst rukten de strijdkrachten van een Osmaanse gouverneur op in het kerngebied van het rijk. Andere plaatsen die op dezelfde datum werden toegevoegd: Karaman.", "569bd202"]},
"OLAYLAR_EK4:1832-12-21:0":{"b": ["Slag bij Konya: grootvizier gevangengenomen", "ec82cc9a"], "d": ["Het Osmaanse leger, dat uiteenviel in de mist, leed een zware nederlaag en grootvizier Reşid Mehmed Pasja werd gevangengenomen. Het centrale leger van de staat bestond niet meer; er was geen macht meer tussen Constantinopel en de Egyptische strijdkrachten.", "30e73138"]},
"OLAYLAR_EK4:1833-01-01:0":{"b": ["Maraş onderging Egyptische bezetting", "f558e383"], "d": ["Volgens de TDV werd Maraş in 1833 bezet door İbrâhim Pasja van Kavala en bleef het bijna negentien maanden onder zijn bestuur. Omdat Maraş buiten de provinciegrenzen van de regeling van Kütahya viel, is dit bestuur niet juridisch maar feitelijk.", "3d3c898a"]},
"OLAYLAR_EK4:1833-01-01:1":{"b": ["Karahisâr-ı Sâhib (Afyon) onderging Egyptische bezetting — route Konya–Kütahya", "ae0c2c78"], "d": ["Karahisâr-ı Sâhib, gelegen op de route van het Egyptische leger dat na de slag bij Konya naar Kütahya oprukte, bleef in 1833 enige tijd in handen van İbrâhim Pasja. Op de kaart is het het door bronnen gestaafde tussenpunt van de bezettingslijn tussen Konya en Kütahya; voor Akşehir, Ilgın en İshaklı kon geen getuigenis op stadsniveau worden gevonden, zij staan in Osmaanse kleur.", "bce0b466"]},
"OLAYLAR_EK4:1833-02-02:0":{"b": ["Egyptisch leger bereikte Kütahya", "214f8df6"], "d": ["İbrâhim Pasja bleef staan in Kütahya, op drie dagmarsen van Constantinopel. Dat hij niet verder ging was niet militair maar politiek: de Russische interventie en de reactie van Europa waren meegerekend.", "0f1c5f03"]},
"OLAYLAR_EK4:1833-02-20:0":{"b": ["Russische vloot voor Büyükdere", "6f836d61"], "d": ["Mahmud II, die geen hulp kreeg van Engeland en Frankrijk, wendde zich tot Rusland, de vijand van gisteren. Dit besluit van de sultan, dat bekendstaat om zijn uitspraak 'wie in zee valt, grijpt zich aan een slang vast', leidde ertoe dat Russische soldaten aan de Zeestraten verschenen en deed in Europa de alarmbellen luiden.", "3e402e00"]},
"OLAYLAR_EK4:1833-05-06:0":{"b": ["Akkoord van Kütahya (mondeling) — Syrië en Adana naar Mehmed Ali", "25fe9985"], "d": ["De Hoge Porte liet naast Egypte, Kreta en de Hidjaz ook de gouverneurschappen van Damascus, Aleppo, Tripoli en Sidon aan Mehmed Ali en de muhassıllık van Adana aan İbrâhim Pasja. Daartegenover trok het leger zich terug ten zuiden van de Taurus. Dit was geen verdrag maar had de vorm van firmans van de sultan aan een gouverneur — de kwestie was niet opgelost maar uitgesteld.", "4160e4f4"]},
"OLAYLAR_EK4:1833-06-15:0":{"b": ["Terugtrekking van het Egyptische leger uit Anatolië bij Gülek voltooid", "a53ac2a3"], "d": ["Na de regeling van Kütahya ontruimden de Egyptische strijdkrachten Anatolië; tegen midden juni was het hele leger via de Gülek-pas naar Çukurova overgestoken. De kust van İçel (Mersin, Silifke) keert terug onder Osmaans bestuur; de muhassıllık van Adana en Syrië blijven bij Egypte.", "c5e13625"]},
"OLAYLAR_EK4:1833-07-08:0":{"b": ["Verdrag van Hünkâr İskelesi", "da741d5c"], "d": ["Met Rusland werd een achtjarig wederzijds defensiebondgenootschap gesloten. Volgens de geheime clausule zou het Osmaanse Rijk de zeestraten voor oorlogsschepen sluiten als Rusland werd aangevallen. Dit werd een van de meest omstreden beslissingen van de Osmaanse diplomatie en maakte Engeland actief in de Egyptische kwestie.", "43dc2c96"]},
"OLAYLAR_EK4:1834-05-19:0":{"b": ["Opstand van Palestina-Nablus tegen het Egyptische bestuur", "4fe43e27"], "d": ["Dienstplicht, wapeninzameling en nieuwe belastingen leidden tot een brede opstand in Palestina. De opstand werd hard neergeslagen; de steun voor het Egyptische bestuur onder de lokale bevolking smolt snel weg.", "2a3301a2"]},
"OLAYLAR_EK4:1834-08-01:0":{"b": ["Einde van het Egyptische bestuur over Maraş (bij benadering)", "bb46ca42"], "d": ["Als de zinsnede van de TDV 'bijna negentien maanden' vanaf de bezetting van 1833 wordt geteld, eindigt het Egyptische bestuur omstreeks de zomer van 1834. Dat Mustafa Bey van de Küçükalioğulları zich in 1834 niet tegen het Egyptische leger kon verzetten en zich naar de kant van Maraş terugtrok, toont ook dat Maraş toen een toevluchtsoord buiten de Egyptische controle was.", "fbb6814a"]},
"OLAYLAR_EK4:1837-10-15:0":{"b": ["Opstand in de Druzenberg", "12e74626"], "d": ["Het verzet in het Druzische gebied duurde twee jaar. De in Syrië opgebouwde ontevredenheid zou in 1840, toen de geallieerde vloten aan de kust landden, de rug van het Egyptische leger blootleggen.", "75c50707"]},
"OLAYLAR_EK4:1838-05-25:0":{"b": ["Mehmed Ali maakte zijn onafhankelijkheidsplannen bekend", "48633bbd"], "d": ["De gouverneur verklaarde aan de consuls van de grote mogendheden dat hij overwoog de onafhankelijkheid van Egypte en Syrië uit te roepen. Engeland verzette zich daar resoluut tegen: het ontstaan van een sterke staat in de Middellandse Zee die dicht bij Frankrijk stond, zou de route naar India bedreigen.", "d6181bd9"]},
"OLAYLAR_EK4:1839-04-21:0":{"b": ["Osmaans leger stak de Eufraat over", "9af1ea69"], "d": ["Mahmud II dreef zijn leger naar de Syrische grens om terug te nemen wat hij bij Kütahya had verloren. De Pruisische officier Moltke, die als adviseur bij het leger was, maakte bezwaar tegen de keuze van de stellingen en tegen het vroege offensief; zijn bezwaren werden niet gehoord.", "85d5db1c"]},
"OLAYLAR_EK4:1839-06-24:0":{"b": ["Slag bij Nizip — Osmaans leger uiteengeslagen", "156b3cdf"], "d": ["Het slecht opgestelde Osmaanse leger werd binnen enkele uren verslagen. Voordat het nieuws van de nederlaag Constantinopel bereikte, stierf de sultan; de staat zou binnen enkele dagen zijn leger, zijn heerser en daarna zijn vloot verliezen.", "fb8af82d"]},
"OLAYLAR_EK4:1839-06-28:0":{"b": ["Dood van Mahmud II", "07eccfff"], "d": ["De sultan, die tijdens zijn regering van eenendertig jaar het janitsarenkorps had afgeschaft en het centrale bestuur had herbouwd, stierf zonder zijn grootste tegenstander te hebben verslagen. Zijn ziekte was niet juist gediagnosticeerd. Zijn dood werd tot 30 juni geheim gehouden totdat in de stad militaire maatregelen waren genomen uit vrees dat de janitsarenmentaliteit in beweging zou komen.", "3174d901"]},
"OLAYLAR_EK4:1839-07-01:0":{"b": ["Troonsbestijging van Abdülmecid en begrafenis van Mahmud II", "d0f3d2cc"], "d": ["Na de dood van zijn vader besteeg de zestienjarige Abdülmecid de troon. Op dezelfde dag werd het stoffelijk overschot van Mahmud II naar het Topkapı-paleis gebracht; de gevreesde onrust bleef uit en brede massa's moslims en niet-moslims sloten zich aan bij de begrafenisstoet.", "7b398ea4"]},
"OLAYLAR_EK4:1839-07-14:0":{"b": ["Overdracht van de vloot aan Alexandrië", "a53e6103"], "d": ["Kapudan pasja Ahmed Fevzi Pasja, die vermoedde dat grootvizier Koca Hüsrev Pasja de vloot aan Rusland zou geven, bracht de vloot naar Alexandrië en leverde haar aan Mehmed Ali over. Het Osmaanse Rijk bleef in dezelfde maand zonder leger, zonder sultan en zonder vloot.", "78a26255"]},
"OLAYLAR_EK4:1839-07-27:0":{"b": ["Gemeenschappelijke nota van de grote mogendheden", "2a3b8316"], "d": ["Vijf mogendheden overhandigden de Hoge Porte een nota met het verzoek in de Egyptische kwestie niet alleen een regeling te treffen. Een interne aangelegenheid werd zo formeel een 'Europese kwestie'; de Osmaanse staat verloor feitelijk de bevoegdheid om over zijn eigen provincie te beslissen.", "979e7f0a"]},
"OLAYLAR_EK4:1840-07-15:0":{"b": ["Verdrag van Londen: vier mogendheden aan de zijde van de Osmanen", "a517f775"], "d": ["Het verdrag, ondertekend met uitsluiting van Frankrijk, stelde Mehmed Ali een ultimatum: aanvaarding binnen tien dagen leverde het erfelijk gouverneurschap van Egypte en, voor het leven, Akko op; aanvaarding binnen twintig dagen alleen Egypte; weigering niets. De gouverneur weigerde.", "fc066f82"]},
"OLAYLAR_EK4:1840-09-10:0":{"b": ["Bombardement van Beiroet en geallieerde landing", "0905ce92"], "d": ["De Brits-Oostenrijkse vloot beschoot Beiroet; in het Libanongebergte werden wapens uitgedeeld aan de bevolking die in opstand kwam tegen het Egyptische bestuur. De controle van İbrâhim Pasja in Syrië stortte in tussen interne opstand en buitenlandse interventie.", "743ec7e2"]},
"OLAYLAR_EK4:1840-10-10:0":{"b": ["Beiroet en de kuststeden gingen verloren", "09bdaf23"], "d": ["Na de gevechten in de richting van Baalbek trokken de Egyptische strijdkrachten zich van de kust terug. Op de kaart verlaat de Libanese kust de vazaltint en keert terug naar rechtstreeks Osmaans bestuur.", "fe5e95aa"]},
"OLAYLAR_EK4:1840-11-03:0":{"b": ["Akko viel in twee uur", "5aec21f0"], "d": ["Bij het bombardement van de geallieerde vloot ontplofte het munitiemagazijn van de burcht en Akko gaf zich binnen enkele uren over. De burcht, die İbrâhim Pasja acht jaar eerder in zes maanden had kunnen innemen, toonde de superioriteit van de zeeartillerie.", "5cf01edf"]},
"OLAYLAR_EK4:1840-11-27:0":{"b": ["Conventie van Alexandrië", "85cb47b0"], "d": ["Mehmed Ali stemde ermee in Syrië, Adana, Kreta en de Hidjaz op te geven, de Osmaanse vloot terug te geven en de heerschappij van de sultan te erkennen; in ruil daarvoor werd het erfelijk gouverneurschap van Egypte gewaarborgd.", "63d90626"]},
"OLAYLAR_EK4:1841-02-25:0":{"b": ["Egyptisch leger ontruimde Syrië en Çukurova", "719a28dc"], "d": ["De negen jaar durende bezetting kwam ten einde; het leger van İbrâhim Pasja keerde via de Sinaï terug naar Egypte. Op de kaart gaat de brede gordel van Aleppo tot Gaza en van Adana tot Kreta opnieuw over naar rechtstreeks Osmaans bestuur. Andere plaatsen die op dezelfde datum verloren gingen: Urfa, Maraş, Tarsus, Antiochië, Kandiye (Kreta), Hama, Damascus, Jeruzalem, Jaffa, Nablus.", "a678b17a"]},
"OLAYLAR_EK4:1841-05-24:0":{"b": ["Firman: gouverneurschap van Egypte erfelijk aan de familie van Kavala gelaten", "87b89ff8"], "d": ["De firman van de sultan erkende het gouverneurschap als overgaand van vader op zoon binnen de dynastie; daartegenover werd de sterkte van het leger teruggebracht tot achttienduizend, werd de belasting aan Constantinopel gebonden en werd de bevoegdheid om munten te slaan en verdragen te sluiten afgeschaft. Egypte bleef een provincie maar was voortaan het land van een afzonderlijke dynastie. Het bestuur over de Hidjaz en de Haramain keerde terug naar de Hoge Porte. Andere plaatsen die op dezelfde datum uit de vazallaag naar de rechtstreekse laag terugkeerden: Mekka, Medina, Jeddah, Yanbu.", "48099454"]},
"OLAYLAR_EK4:1841-07-13:0":{"b": ["Conventie van Londen over de Zeestraten", "0e95a1ea"], "d": ["De conventie, die in de plaats kwam van Hünkâr İskelesi, bepaalde dat de zeestraten in vredestijd voor alle oorlogsschepen gesloten waren. Het voorrecht dat Rusland alleen had verworven, werd zo een gemeenschappelijke Europese garantie; de kwestie van de zeestraten kreeg een internationaal statuut.", "5bbbb459"]},
"OLAYLAR_EK4:1848-09-01:0":{"b": ["İbrâhim Pasja werd feitelijk gouverneur van Egypte", "9e14f5d9"], "d": ["In de plaats van Mehmed Ali, die oud werd en zijn geestelijke vermogens verloor, werd zijn zoon İbrâhim Pasja tot gouverneur benoemd. Enkele maanden later, in november 1848, stierf hij echter vóór zijn vader.", "338908f8"]},
"OLAYLAR_EK4:1849-08-02:0":{"b": ["Overlijden van Mehmed Ali Pasja van Kavala", "871310e0"], "d": ["De gouverneur, geboren in Kavala, die in Egypte een dynastie stichtte en het rijk twee keer aan de rand van de afgrond bracht, stierf op tachtigjarige leeftijd. De dynastie die hij stichtte regeerde in Egypte tot 1953; de staat zag dat hij de wond die hij had geslagen alleen met Europese interventie kon sluiten en vervolgde de weg van de Tanzimat.", "c0877894"]},
"OLAYLAR_EK5:1281-01-01:0":{"b": ["Dood van Ertuğrul Gazi en overgang van Osman Bey naar het beylik — erfenis van Söğüt en Domaniç", "395fb9fa"], "d": ["Volgens de TDV stierf Ertuğrul Gazi in 680 (1281-82); het lemma vermeldt dat ook de data 1288 en 1289 worden gegeven. Osman Bey erfde van zijn vader geen veroverde stad, maar de twee toewijzingen die de Seltsjoekse sultan aan Ertuğrul had gedaan toen hij hem op de meest vooruitgeschoven lijn van het grensgebied vestigde: een yurtluk (winterkwartier) in Söğüt en een yaylak (zomerweide) in Domaniç. Het beylik begon dus niet met een veroveringserfenis maar met twee weidetoewijzingen; op de kaart worden deze twee plaatsen niet als 'verovering' maar als 'erfenis' weergegeven.", "37fbc33c"]},
"OLAYLAR_EK5:1282-03-30:0":{"b": ["Siciliaanse Vespers — het huis Anjou verloor het eiland Sicilië", "547db635"], "d": ["De opstand die in Palermo op paasmaandagavond bij het vespergebed uitbrak tegen het bestuur van Karel I van Anjou, scheurde het eiland Sicilië van het huis Anjou af. Het Koninkrijk Sicilië werd in tweeën gesplitst: het eiland ging naar Aragon, terwijl het huis Anjou standhield in het vasteland-koninkrijk met Napels als centrum. De overzeese bezittingen van de dynastie aan de Adriatische Zee en de Middellandse Zee bleven ook aan dit koninkrijk gebonden: Korfoe, dat zij sinds 1267 in handen hadden, en Durrës, dat zij sinds de jaren 1270 hielden, bleven als deel van het Koninkrijk Napels bestaan; ook de burchten Vlorë (Avlonya), Kanina en Himara aan de Albanese kust bleven in het koninkrijk met Napels als centrum (de commandant van Vlorë, John of Taxis, bood in 1282 weerstand tegen de Byzantijnen; Durrës, Vlorë en Kanina gingen waarschijnlijk begin 1285 naar Byzantium). Malta kwam pas in 1284 in handen van de Aragonezen.", "7c8ea21d"]},
"OLAYLAR_EK5:1285-01-01:0":{"b": ["Overval op Kulacahisar — eerste militaire actie van Osman Bey", "79b00b14"], "d": ["TDV-lemma Osman I: 'Hij plunderde en verbrandde de kleine burcht Kulaca Hisar bij İnegöl (684/1285).' Dit is de eerste in de bronnen te dateren militaire actie van Osman Bey. Er werd geen blijvende nederzetting ingenomen, de burcht werd geplunderd en verbrand; het is dus meer een klassieke grensstrooptocht dan een verovering. Zij geldt als het beginpunt van de militaire activiteit van het beylik.", "15ee9a09"]},
"OLAYLAR_EK5:1288-01-01:0":{"b": ["Verovering van Karacahisar — eerste stadswinst en heerschappij over Eskişehir", "178ae619"], "d": ["TDV-lemma Osman I: Osman Bey 'veroverde in 687 (1288) Karacahisar en nam Eskişehir in bezit'. Dit is de eerste echte stadswinst van het beylik en volgens de overlevering steeg Osman Bey met dit succes op tot sandjakbey aan de grens; er wordt verteld dat de eerste vrijdagkhutba in zijn naam in Karacahisar werd gelezen en dat hier de eerste kadi werd benoemd. Het TDV-lemma Eskişehir vermeldt dat de Osmaanse traditie het jaar 1291 geeft, maar dat de juistheid daarvan twijfelachtig is.", "90949e22"]},
"OLAYLAR_EK5:1291-05-18:0":{"b": ["Val van Akko aan de Mamelukken — liquidatie van de kruisvaarders van de Syrische kust: Sidon en Beiroet", "3ca7a464"], "d": ["Akko, dat lange tijd het centrum van het Kruisvaardersrijk Jeruzalem was, werd veroverd door de Mamelukse sultan al-Malik al-Ashraf Khalil en de heerschappij van de kruisvaarders in Palestina kwam ten einde. De Tempeliers, die zich uit Akko terugtrokken, zochten hun toevlucht in Sidon; toen het Mamelukse leger naderde, verlieten zij de zeeburcht en vluchtten naar Cyprus en de stad ging in dezelfde zomer naar de Mamelukken. Ook Beiroet, dat sinds 1197 in handen van de kruisvaarders was, werd in 1291 ingenomen door de gouverneur van Damascus, Sanjar al-Shujai. Zo werd de twee eeuwen durende kruisvaarderaanwezigheid van de Syrisch-Palestijnse kust gewist.", "63b3c40c"]},
"OLAYLAR_EK5:1299-01-01:0":{"b": ["Verovering van Bilecik en Yarhisar bij een nachtelijke overval", "f461b0af"], "d": ["TDV-lemma Bilecik: 'Hoewel de andere tekfurs in de regio, onder wie de tekfur van Bilecik, een aanslag op Osman Gazi hadden voorbereid, namen de Osmaanse strijdkrachten bij het bekend worden van dit complot met een plotselinge overval Yarhisar en Bilecik in (1299).' Twee burchten werden in één campagne, in dezelfde nachtelijke overval, ingenomen. Deze datum is het keerpunt dat als het stichtingsjaar van de Osmaanse staat wordt aanvaard. Andere plaatsen die op dezelfde datum werden toegevoegd: İnegöl.", "ec452c9e"]},
"OLAYLAR_EK5:1302-07-27:0":{"b": ["Slag bij Koyunhisar (Bapheus) — eerste grote overwinning op het Byzantijnse leger", "584a9512"], "d": ["TDV-lemma Osman I: Osman Bey streed op 27 juli 1302 bij Bapheus (Koyunhisar) tegen het Byzantijnse leger en versloeg het. Deze overwinning is het keerpunt dat Osman Bey van een regionale grensbey verhief tot stichter van een dynastie. Na de slag kwam de vlakte van Bursa onder Osmaanse controle en begon de blokkade van İznik.", "b82fb787"]},
"OLAYLAR_EK5:1303-01-01:0":{"b": ["Overwinning bij Dimbos en daarna de inname van Kite en Ulubat", "e168ab64"], "d": ["TDV-lemma Osman I: in 702 (1303) werd het bondgenootschap van de tekfurs van Bursa, Kestel, Kite en Adranos in de Dimbos-pas verslagen; de vijand werd al vechtend tot in de nauwe pas teruggedrongen en de tekfur van Kestel stierf op het slagveld. Onmiddellijk na de overwinning werden de burchten Kite en Ulubat ingenomen, waarmee de landverbinding van Bursa werd afgesneden en haar blokkade werd aangescherpt. Ook de jonge Orhan nam aan deze slag deel.", "4afb53bf"]},
"OLAYLAR_EK5:1304-01-01:0":{"b": ["Veldtocht naar de Sakarya: inname van Leblebicihisar, Lefke, Mekece en Geyve", "a51ba4d3"], "d": ["TDV-lemma Osman I geeft de volgorde van de Sakarya-veldtocht van 704 (1304): 'Toen hij bij Leblebüci Hisarı kwam, onderwierp de tekfur zich... hij kwam in Lefke... hij bereikte Mekece... hij ging naar Geyve en nam de lege burcht in.' Lefke is de poort van de Sakaryavallei naar Bilecik. Deze ene veldtocht bracht de keten van burchten langs de vallei onder Osmaanse controle en sloot de oostflank van het bekken van İznik.", "ae2866c2"]},
"OLAYLAR_EK5:1305-01-01:0":{"b": ["Verovering van de burchten in de pas van Geyve: Karaçepüş, Karatigin en Absu", "76907c78"], "d": ["TDV-lemma Orhan: Orhan 'veroverde in de Sakarya-veldtocht van 705 (1305) de burchten Karaçepüş (Katoikia), Karatigin bij İznik en Absu (Hypsu: in de pas van Geyve)'. Deze drie burchten sloten de doorgang tussen de Sakaryavallei en het bekken van İznik af en sneden de hulp over land aan İznik volledig af. In Karaçepüş en Absu in de pas van Geyve werd Gazi Abdurrahman gevestigd; de stad kon nu alleen nog door uithongering ten val worden gebracht.", "d330595f"]},
"OLAYLAR_EK5:1323-09-01:0":{"b": ["Veldtocht naar Adranos (Orhaneli) — laatste veldtocht van Osman Bey", "4811546c"], "d": ["Het TDV-lemma Orhan noteert de veldtocht naar de burcht Adranos in de herfst van 1323 als de laatste veldtocht van Osman Bey. De tekfur van Adranos was lid van het bondgenootschap van tekfurs dat twintig jaar eerder bij Dimbos tegen de Osmanen was gevormd; deze veldtocht betekende het vereffenen van die rekening. De exacte veroveringsdag van de burcht is niet bekend; de campagne werd voortgezet door Orhan Bey.", "1e8ea25a"]},
"OLAYLAR_EK5:1324-01-01:0":{"b": ["Overlijden van Osman Gazi en overgang van Orhan Bey naar het beylik", "021487cd"], "d": ["Osman Gazi, die zijn naam aan het beylik gaf, stierf in 724 (1324), zoals blijkt uit de getuigenis van de vakfiyes van Asporça Hatun en Mekece. Zijn zoon Orhan, die sinds 1305 bij de veldtochten aan het hoofd van het leger stond, nam na de dood van zijn vader zonder enige troonstrijd het hoofd van het beylik over. Dat de stichtende generatie de vlag zonder schokken overdroeg, toont dat de dynastie op de weg van grensbeylik naar staat haar eerste grote proef kalm doorstond.", "6f95e64a"]},
"OLAYLAR_EK5:1329-06-01:0":{"b": ["Slag bij Pelekanon (Maltepe) en inname van heel Kocaeli", "389e7bd4"], "d": ["TDV-lemma Orhan: op de eerste dag van de slag stuurde Orhan Gazi een troepenmacht van driehonderd man om het Byzantijnse leger naar zich toe te trekken; op de tweede dag breidde de slag zich uit doordat de eenheden onder bevel van Pazarlu de vlakte op kwamen, en toen de keizer door een pijl gewond raakte, brak paniek uit in het Byzantijnse leger. De uitkomst is beslissend: 'Orhan nam heel Kocaeli in; na de overwinning hadden de mensen van İznik geen hoop meer.' De kuststadjes van Hereke tot Üsküdar kwamen onder Osmaans gezag, Gebze werd het centrum van de regio. Dit was het laatste keizerlijke Byzantijnse leger dat kwam om Constantinopel te redden.", "73fe4332"]},
"OLAYLAR_EK5:1331-03-03:0":{"b": ["Oprichting van de eerste Osmaanse madrasa in İznik", "c85fb625"], "d": ["Orhan Bey benoemde Çandarlı Kara Halil onmiddellijk na de inname van İznik tot kadi aldaar, veranderde een basiliek in een moskee en liet daarnaast een imaret en een madrasa bouwen, waarmee hij de wederopbouw van de stad begon. Volgens het TDV-lemma Dâvûd-i Kayserî werd de bouw van de madrasa in 1336 voltooid en haalde Orhan Gazi Dâvûd-i Kayserî met een dagelijks salaris van 30 akçe als müderris. Deze madrasa is de eerste institutionele stap in het Osmaanse wetenschappelijke leven; het beylik voegde aan zijn veroveringskracht ook een wetenschappelijke traditie toe. Dat een veroverde Byzantijnse hoofdstad het islamitische wetenschapscentrum werd, was het eerste concrete teken van de aanspraak van de Osmanen een gevestigde staat te zijn.", "4f11a077"]},
"OLAYLAR_EK5:1333-08-01:0":{"b": ["Byzantium schatplichtig gemaakt — beleg van İzmit en verdrag", "0c1ec8d3"], "d": ["TDV-lemma Orhan: Orhan belegerde in de zomer van 733 (1333) İzmit met een groot leger en mangonels en de keizer stemde in met een verdrag. In ruil voor het opgeven van het beleg aanvaardde Byzantium jaarlijks 12.000 gouden munten (hyperpers) aan Orhan te betalen; 'zo was Byzantium in de ogen van de Osmaanse emir een schatplichtig land geworden'. Daartegenover zou Orhan een vriend van de keizer zijn en de steden die aan Byzantium onderworpen waren niet aanvallen. Dat een grensbeylik Oost-Rome belastingplichtig maakte, was een afkondiging van hoezeer het machtsevenwicht was gekanteld.", "e2e3eeb4"]},
"OLAYLAR_EK5:1345-01-01:0":{"b": ["Annexatie van het Karesi-beylik: Balıkesir, Bergama, Biga, Edremit en Erdek", "c7cb0511"], "d": ["Het TDV-lemma Orhan (İnalcık) plaatst de annexatie op 735 (1334-35): na de dood van Demirhan Bey nodigden de gazi's van Karesi en Hacı İlbey Dursun Bey uit voor de troon en vroegen zij Orhan om hulp. Orhan trok eerst op Balıkesir; toen Dursun Bey, op weg naar de vredesbesprekingen, door een pijl uit de burcht van Bergama werd gedood, werd het beylik volledig bij het Osmaanse land gevoegd. In dezelfde campagne onderwierpen Kirmasti en Mihaliç zich, werd Gölyazı ingenomen en werd het eerder op genade overgelaten Ulubat definitief bezet. Orhan benoemde Süleyman Pasja tot sandjak van Karesi en maakte Biga tot grenscentrum — zo werd het maritieme kader voor de oversteek naar Rumelië gewonnen. Opmerking: het TDV-lemma Karesioğulları geeft voor dezelfde gebeurtenis 746 (1345); de encyclopedie spreekt zichzelf tegen. Andere plaatsen die op dezelfde datum werden toegevoegd: Çanakkale.", "f5ed82c2"]},
"OLAYLAR_EK5:1352-01-01:0":{"b": ["Eerste capitulatie van Orhan Gazi met de Genuezen", "e64cb196"], "d": ["Orhan Gazi, die tijdens de Venetiaans-Genuese oorlog een overeenkomst met de Genuezen had gesloten, zond na de zeeslag in de Bosporus van februari 1352 1000 boogschutters voor de verdediging van Pera en leverde 60.000 gouden munten voor troepenvervoer; in ruil daarvoor schonk hij de Genuezen de eerste capitulatie. De volledige tekst van het verdrag is niet bewaard gebleven. Dit is de eerste officiële overeenkomst van de Osmanen met een Europese zeemacht en zou vijfendertig jaar later, in 1387, worden vernieuwd.", "68c60677"]},
"OLAYLAR_EK5:1354-03-02:0":{"b": ["Inname van Gallipoli — blijvend bruggenhoofd in Rumelië", "ba51a160"], "d": ["Gallipoli, dat zij in de jaren 1349-1352 als bondgenoot van Kantakouzenos in de omgeving hadden leren kennen, werd in 1354 door de Osmanen ingenomen; de grote aardbeving die de muren van de stad had doen instorten, had de gelegenheid geschapen. Het smalle bruggenhoofd bij Çimpe veranderde zo in een echte basis aan de Rumeliaanse kant van de Bosporus en de poort naar Thracië werd wijd opengezet. Gallipoli zou in 1366 door de Savoyaardse kruistocht verloren gaan, maar met de tweede verovering in 1376 definitief onder Osmaanse heerschappij komen. Andere plaatsen die op dezelfde datum werden toegevoegd: Kilitbahir.", "cac0192e"]},
"OLAYLAR_EK5:1357-09-01:0":{"b": ["Overlijden van Süleyman Pasja, veroveraar van Rumelië", "2dc98228"], "d": ["Süleyman Pasja, de oudste zoon van Orhan Bey en de architect van de Rumeliaanse veroveringen, stierf in de herfst van 1357 — de datum die het meest wordt aanvaard van de in de bronnen genoemde 758 (1357), 759 en 760 (1359) — na een val van zijn paard tijdens de jacht. De dood van de prins, die met zijn oversteken in 1352-1354 de blijvende Osmaanse aanwezigheid in Rumelië vestigde, liet de opvolgingsrij over aan zijn broer Murad. Het mausoleum van Süleyman Pasja, begraven in Bolayır, bleef het oudste dynastieke monument van de Osmanen in Europa.", "1f780557"]},
"OLAYLAR_EK5:1361-01-01:0":{"b": ["Pençik-wet — leggen van de basis van het Janitsarenkorps", "e5877c2d"], "d": ["Na de Rumeliaanse veroveringen werd op advies van de geleerde Karamanlı Kara Rüstem het pençik-stelsel ingevoerd, dat voorzag in het afzonderen voor de staat van een vijfde van de krijgsgevangenen of de tegenwaarde daarvan in geld. Doordat degenen die uit deze gevangenen werden gekozen bij Turkse families werden opgevoed en als soldaat werden opgenomen, ontstond de kern van een permanente infanteriemacht die rechtstreeks aan de sultan was gebonden — het Janitsarenkorps. Met deze regeling begon de transformatie van een grensbeylik, dat steunde op stamruiterij, in een staat met een centraal leger.", "f28873dd"]},
"OLAYLAR_EK5:1363-01-01:0":{"b": ["Afdaling naar West-Thracië: verovering van Gümülcine", "9ef69221"], "d": ["Na de inname van Edirne trokken de grensstrijdkrachten naar het westen van de Maritsa en namen onder bevel van Gazi Evrenos Bey Gümülcine (Komotini), het centrum van West-Thracië, in. De stad werd het voorste hoofdkwartier van waaruit Evrenos Bey zijn strooptochten naar Macedonië zou voeren. Zo kwam het deel van Thracië dat zich uitstrekt tot de Egeïsche kust onder Osmaanse controle en ging de weg naar Thessaloniki open.", "0206d2bb"]},
"OLAYLAR_EK5:1369-01-01:0":{"b": ["Varna ging naar het Prinsdom Dobroedzja en werd hoofdstad", "2bfe73f9"], "d": ["Tijdens het uiteenvallen van het Bulgaarse tsarenrijk werd Varna aan de Zwarte Zeekust gevoegd bij het door Dobrotitsa gestichte Prinsdom Dobroedzja en werd het de hoofdstad van deze kleine staat.", "5115e7b2"]},
"OLAYLAR_EK5:1373-01-01:0":{"b": ["Ten westen van Filibe: aansluiting van Tatarpazarcığı en İhtiman", "1664d0e1"], "d": ["Na de inname van Filibe in 1372 werden Tatarpazarcığı aan het bovenste uiteinde van de Maritsavallei en İhtiman, dat de pas naar Sofia bewaakt, onder Osmaans bestuur gebracht. Deze lijn, die in handen was van de lokale beys die na de Slag bij Çirmen vazal waren geworden, werd onder rechtstreeks bestuur gebracht en de route Filibe–Sofia werd ononderbroken gemaakt. Deze opmars is de voorbereiding op de weg naar de verovering van Sofia twaalf jaar later.", "0e9acfa0"]},
"OLAYLAR_EK5:1373-05-15:0":{"b": ["Opstand van Savcı Bey — gezamenlijke opstand van een prins en de Byzantijnse kroonprins", "75198c33"], "d": ["Savcı Bey, de zoon van Murad I, en Andronikos Palaiologos, de zoon van de Byzantijnse keizer Johannes V, kwamen begin mei 1373 gelijktijdig in Bursa en Constantinopel in opstand tegen hun vaders. Dit bondgenootschap dat de kroonprinsen van twee dynastieën verenigde, werd snel onderdrukt; Savcı Bey werd gevangengenomen, kreeg een gloeiende naald in de ogen en werd geëxecuteerd. De datum 787 (1385) die de Osmaanse overlevering voor de opstand geeft, is onjuist; de gebeurtenis valt vlak na de jaren waarin Byzantium Osmaans vazal werd en toont hoe verweven de twee hoven waren.", "9776426c"]},
"OLAYLAR_EK5:1374-01-01:0":{"b": ["Struma- en Mestavallei: aansluiting van Köstendil, Petriç, Nevrokop en Drama", "8c0980c4"], "d": ["De Struma- en Mestavalleien, die in handen waren van de Servische en Bulgaarse lokale beys die na de overwinning bij Çirmen schatting aan de Osmanen begonnen te betalen, werden door de opmars van de grensbeys onder rechtstreeks Osmaans bestuur gebracht. Met de aansluiting van Köstendil, Petriç, Nevrokop en Drama werd de oostelijke helft van Macedonië geopend en kwamen Thessaloniki en Serres binnen de belegeringsring. De uitbreiding van Rumelië naar het zuidwesten op de kaart is het gevolg van deze campagne.", "a50a02ad"]},
"OLAYLAR_EK5:1381-04-01:0":{"b": ["Timur nam Herat in: einde van de Kert-dynastie en overgang van Khorasan naar de Timoeriden", "15f6019e"], "d": ["Khorasan was in 1380 versnipperd door de strijd tussen de Sarbadars, de Kerts en de Muzaffariden. Nadat Timur zijn zoon Mîrân Şah naar de regio had gezonden, trok hij zelf op naar Herat en nam hij, na enige tijd te hebben belegerd, de stad over van de Kert-melik Gıyâseddin Pîr Ali. De opstand die na zijn vertrek uitbrak werd door Mîrân Şah bloedig neergeslagen en de Kert-dynastie, die sinds 1255 in Herat regeerde, werd beëindigd. Heel Khorasan, van Mashhad tot Nishapur, kwam op deze datum onder Timoeridisch bestuur.", "6ae06d43"]},
"OLAYLAR_EK5:1381-10-01:0":{"b": ["Einde van het Eretna-beylik en stichting van de staat van Kadı Burhâneddin", "60dcaf57"], "d": ["De Eretnaoğulları, die in 1335 uit een Ilkhanidisch gouverneurschap waren ontstaan en zesenveertig jaar over Midden-Anatolië met Sivas en Kayseri als centra hadden geregeerd, vielen uiteen door twisten binnen het paleis. Kadı Burhâneddin, die in mei 1378 vizier werd, schakelde zijn rivalen Kılıçarslan en Hacı Şadgeldi uit, riep in de herfst van 1381 zijn sultanaat uit, maakte een einde aan het beylik en stichtte de staat die zijn naam draagt. Zo wisselde de oostelijke buur van de Osmanen van hand; de lijn Sivas–Kayseri zou hierna zeventien jaar in handen van Kadı Burhâneddin blijven.", "f5b2be0c"]},
"OLAYLAR_EK5:1385-01-01:0":{"b": ["Opmars in Macedonië: verovering van Manastır en Ohri", "63bb7838"], "d": ["Manastır (Bitola) aan de Via Egnatia en Ohri (Ohrid) aan de oever van het meer kwamen tijdens de strooptochten in de richting van Albanië onder Osmaans bestuur. Beide waren sleutelpunten van de weg naar de Adriatische Zee; Ohri was bovendien het oudste orthodoxe aartsbisdomcentrum van de Balkan. De TDV vermeldt dat er over de veroveringsdatum van Ohri geen zekere informatie is, dat 787 (1385) en 797 (1395), na de dood van Marko Kraljević, worden genoemd; hier is 1385 als basis genomen. Manastır zou in de volgende eeuwen een van de belangrijkste militaire centra van Rumelië worden.", "e5418654"]},
"OLAYLAR_EK5:1385-09-18:0":{"b": ["Slag bij Savra — opening van de poorten van Albanië", "dda6671b"], "d": ["Op de oproep tot hulp van de Albanese bey Karlo Topia, die klem zat tegen de dynastie Balša, versloegen Osmaanse strijdkrachten op de vlakte van Savra het leger van Balša II; Balša kwam op het slagveld om. Deze slag, die werd aangegaan op uitnodiging van een inheemse bey, bezorgde de Osmanen hun eerste blijvende invloed in de Albanese gebieden die zich uitstrekken tot de Adriatische kust. Deze politiek, die ervan uitging dat de beys in de regio met elkaar overhoop lagen, zou gedurende de volgende eeuw de onveranderlijke methode van de Balkanveroveringen worden.", "05382964"]},
"OLAYLAR_EK5:1386-01-01:0":{"b": ["Timurs 'driejarige veldtocht': inname van Azerbeidzjan en Noord-Iran", "2a98ec51"], "d": ["Timur, die tijdens de Khorasan-campagnes de versnipperde toestand van Iran van dichtbij had gezien, trok in 788 (1386) naar het westen. In de campagne van 1386-1388, die de 'driejarige veldtocht' wordt genoemd, trok hij via Mazandaran, Luristan en Georgië naar Azerbeidzjan en bereikte Karabach; Tabriz, Ardabil, Urmia en Nachitsjevan kwamen onder Timoeridisch bestuur. Zijn verovering van Noord-Iran en Azerbeidzjan was, net als vroeger tussen de Jochi-ulus en de Ilkhans, ook het begin van een langdurige strijd met de Gouden Horde.", "aaf3b558"]},
"OLAYLAR_EK5:1386-06-01:0":{"b": ["Slag bij Frenkyazısı en beleg van Konya — eerste Karaman-veldtocht", "af4e5d77"], "d": ["Murad I trok persoonlijk ten strijde tegen Karamanoğlu Alâeddin Ali Bey, die, hoewel zijn schoonzoon, zich stoorde aan de Osmaanse expansie in West-Anatolië; in de slag op de plek Frenk Yazısı versloeg het getrainde en ervaren Osmaanse leger de Karaman-strijdkrachten. Daarna werd de burcht van Konya belegerd, maar doordat Alâeddin Bey gratie kreeg, werd het beylik niet geheel opgeheven. Deze veldtocht is het openingsbedrijf van de lange afrekening tussen de Osmanen en Karaman die een eeuw zou duren en pas in 1468 met de definitieve annexatie zou eindigen.", "087a605a"]},
"OLAYLAR_EK5:1390-06-01:0":{"b": ["Oprichting van de scheepswerf van Gallipoli — geboorte van de Osmaanse vloot", "47546241"], "d": ["De eerste georganiseerde scheepswerf van de Osmaanse staat werd in 1390 door Yıldırım Bayezid in Gallipoli gesticht, op de plek van de scheepswerf die van Byzantium was overgebleven. De Osmanen, die de maritieme erfenis van de West-Anatolische beyliks overnamen, werden zo voor het eerst een zeemacht die haar eigen schepen bouwde. De scheepswerf, gelegen op het sleutelpunt van de Dardanellen, diende anderhalve eeuw lang, van het beleg van Constantinopel tot de Egeïsche veldtochten, als de hoofdbasis van de Osmaanse vloot.", "f214717c"]},
"OLAYLAR_EK5:1391-01-01:0":{"b": ["Het gebied Hamid kwam bij de Osmanen: Isparta, Burdur, Uluborlu, Eğirdir", "e3da7de5"], "d": ["Yıldırım Bayezid, die ten strijde trok na de aanval van Karamanoğlu Alâeddin Bey op het gebied Hamid en de klachten van de bevolking, nam het volledige resterende grondgebied van de Hamîdoğulları in en gaf het bestuur aan zijn zoon İsa Çelebi.", "8a997ead"]},
"OLAYLAR_EK5:1393-01-01:0":{"b": ["Einde van de Muzaffariden-dynastie: Sjah Mansur verslagen bij Shiraz", "5fd14eb8"], "d": ["Sjah Mansur, de laatste sterke heerser van de Muzaffariden, die sinds 1318 over Yazd, Fars, Isfahan en Kerman heersten, ondernam samen met zijn verwanten actie tegen Timur. In de slag bij Shiraz verloor hij het grootste deel van zijn strijdkrachten doordat een van zijn emirs overliep naar de andere kant; hij werd verslagen en gedood. Doordat Timur daarna ook alle leden van de dynastie liet doden, kwam er een einde aan de Muzaffaridische heerschappij en werden Fars en Kerman bij het Timoeridische bestuur gevoegd.", "8e89c2dc"]},
"OLAYLAR_EK5:1393-06-01:0":{"b": ["Aansluiting van Amasya bij het Osmaanse grondgebied", "fe2860cf"], "d": ["De emir van Amasya, die tijdens de Midden-Anatolische campagne van Yıldırım Bayezid werd belegerd, droeg de stad over aan de Osmanen en Bayezid trok in 1393 de stad binnen. De sultan liet het bestuur over aan zijn zoon Mehmed Çelebi; Amasya werd als prinsensandjak voortaan een van de belangrijkste opleidingshaarden van de Osmaanse dynastie. Deze keuze zou in het latere Interregnum doorslaggevend zijn: Çelebi Mehmed zou zijn strijd om de staat te herenigen vanuit deze Amasya-basis voeren.", "389ab68d"]},
"OLAYLAR_EK5:1393-08-29:0":{"b": ["Timur nam Bagdad in — de Jalayiriden vluchtten naar Anatolië", "4d5602b3"], "d": ["Timur nam na een lang beleg Bagdad in; de heerser van de stad, de Jalayiridische sultan Ahmed, vluchtte naar het westen en vond eerst onderdak bij de Mamelukken en daarna aan het Osmaanse hof. De expansie van Timur naar het westen kwam zo voor het eerst in rechtstreeks contact met de Osmaanse invloedssfeer. Hier begint de eerste schakel van de vijandschap tussen de twee heersers.", "2fac674f"]},
"OLAYLAR_EK5:1393-09-01:0":{"b": ["Inname van Varna aan de Zwarte Zeekust", "a84b2abf"], "d": ["Tijdens het opdringen in de gebieden van het Bulgaarse tsarenrijk tussen de Donau en de Zwarte Zee ging Varna, de grootste haven aan de kust, over naar Osmaans bestuur. De inname van de haven maakte de weg vrij voor de opmars naar Dobroedzja en gaf de Osmanen de eerste grote aanlegplaats aan de westkust van de Zwarte Zee. Varna zou eenenvijftig jaar later ook het toneel zijn van de overwinning van 1444 waarbij het kruisvaardersleger werd vernietigd.", "2e425501"]},
"OLAYLAR_EK5:1398-07-15:0":{"b": ["Val van de staat van Kadı Burhâneddin", "b13391e3"], "d": ["Kadı Burhâneddin, die in handen viel van de Akkoyunlu-heerser Karayülük Osman Bey, bood aan de overgave van Sivas in ruil voor zijn vrijlating, maar de bevolking van de stad bood weerstand en de sultan werd voor de muren geëxecuteerd. Hoewel de notabelen van Sivas zijn zoon Alâeddin Ali Çelebi op de troon zetten, vroegen zij tegenover de druk van de Akkoyunlu hulp aan Yıldırım Bayezid; de Osmaanse strijdkrachten onder bevel van Süleyman Çelebi versloegen Karayülük en kregen de stad in handen. Zo verdween de staat van Kadı Burhâneddin uit de geschiedenis en werden Sivas, Tokat, Niksar en Kayseri bij het Osmaanse grondgebied gevoegd. Andere plaatsen die op dezelfde datum werden toegevoegd: Kırşehir, Çorum.", "2a0c7f3a"]},
"OLAYLAR_EK5:1399-11-01:0":{"b": ["Timurs ultimatum: uitlevering van de voortvluchtigen geweigerd", "33790bc8"], "d": ["Onder druk van Timur zochten de Jalayiridische sultan Ahmed en de Kara Koyunlu-leider Kara Yûsuf onderdak op Osmaans grondgebied; Timur eiste de uitlevering van deze twee voortvluchtigen, Yıldırım Bayezid weigerde. Daarop begonnen tussen de twee heersers brieven te worden gewisseld die wederzijds zware beledigingen bevatten. De ideologische bodem van de oorlog werd met deze correspondentie gelegd voordat er één soldaat in beweging kwam.", "ac66be59"]},
"OLAYLAR_EK5:1400-01-01:0":{"b": ["Yıldırım-ziekenhuis in Bursa — eerste Osmaanse ziekenhuis", "5f0dc59a"], "d": ["In de jaren waarin Yıldırım Bayezid in Bursa de prachtige Ulucami liet bouwen, schonk hij de stad ook een dârüşşifa (ziekenhuis); het was de schakel van het brede liefdadigheidsprogramma, bestaande uit een imaret, madrasa, han en brug, die aan de geneeskunde was gewijd. Dit gebouw, het eerste ziekenhuis dat de staat stichtte, diende ook als medische school die artsen opleidde en bepaalde het model van de Osmaanse gezondheidsinstellingen. Het werk, dat slechts twee jaar vóór de ramp bij Ankara werd voltooid, is een van de laatste schakels in Yıldırıms visie om Bursa te veranderen in een keizerlijke hoofdstad.", "5765ebac"]},
"OLAYLAR_EK5:1400-08-01:0":{"b": ["Timur maakte Sivas met de grond gelijk", "f4d79de6"], "d": ["Timur, die onder leiding van Karayülük Osman Bey van de Akkoyunlu en de emir van Erzincan, Mutahharten, naar Sivas optrok, belegerde de stad achttien dagen en richtte, nadat hij haar had overgenomen met de belofte dat niemands bloed zou worden vergoten, een groot bloedbad aan; hij liet de verdedigers in greppels werpen en levend onder aarde bedekken. Belangrijke werken van de stad, voorop de muren, werden verwoest, Sivas stortte demografisch in. Dit is de eerste grote klap die Timur twee jaar vóór de Slag bij Ankara aan Osmaans grondgebied toebracht.", "8ddb3e3a"]},
"OLAYLAR_EK5:1401-02-01:0":{"b": ["Yıldırım Bayezid nam Erzincan en Kemah terug", "7047ca08"], "d": ["Yıldırım Bayezid, die van Timurs vertrek op zijn Syrische veldtocht gebruik maakte, nam Erzincan en Kemah af van de emir van Erzincan, Mutahharten, die aan Timur onderworpen was. Hoewel hij niet had ingegrepen bij de verwoesting van Sivas, betekende deze zet een rechtstreekse uitdaging van Timurs invloedssfeer in Oost-Anatolië. De verhouding tussen de twee heersers was hierna niet meer te herstellen.", "2160d645"]},
"OLAYLAR_EK5:1402-03-13:0":{"b": ["Ultimatum van Timur vanuit Tabriz — vier voorwaarden", "3e1ac50e"], "d": ["Timur liet via een gezant vanuit Tabriz vier voorwaarden meedelen: teruggave van Kemah aan Mutahharten, teruggave van de op de Anatolische beys afgenomen gebieden aan hun eigenaars, het zenden van een Osmaanse prins als gijzelaar en het aanvaarden van de muts en gordel als teken van onderworpenheid, en de uitlevering van Kara Yûsuf. Bayezid aanvaardde geen van deze; ondanks aandringen van staatslieden en de bemiddeling van Mutahharten stortten de besprekingen in. Timur was vastbesloten de Anatolische kwestie definitief af te sluiten voordat hij naar China trok.", "bd475bc3"]},
"OLAYLAR_EK5:1402-08-17:0":{"b": ["Saruhanoğulları opnieuw gesticht — Manisa verliet de Osmanen", "ac747b05"], "d": ["Drie weken na de nederlaag bij Ankara nam Orhan Bey met steun van Timur het hoofd van het beylik over en werd het gebied Saruhan opnieuw onafhankelijk. De regio met als centrum Manisa verdween twaalf jaar na de Osmaanse annexatie van 1390 van de kaart. Dit is een van de toepassingen met een met zekerheid bekende datum van Timurs politiek om de beyliks te laten herrijzen.", "9fe5744d"]},
"OLAYLAR_EK5:1402-08-20:0":{"b": ["Emir Süleyman vluchtte met de staatsschatkist naar Rumelië", "0a2b7363"], "d": ["Emir Süleyman nam de staatsschatkist, de archieven, zijn familie en zijn broers uit Bursa mee, stak vanuit Gemlik per schip over naar Güzelcehisar (Anadoluhisarı), bereikte vandaar Gallipoli en riep in Edirne zijn heerschappij uit. De verhuizing van het staatsarchief en de schatkist naar Rumelië is het begin van de verschuiving van het Osmaanse zwaartepunt naar de Balkan voor een generatie. Op de kaart wordt Rumelië vanaf deze datum in de eigen kleur van Emir Süleyman getekend.", "393aa053"]},
"OLAYLAR_EK5:1402-09-15:0":{"b": ["Timur herstelde de Anatolische beyliks — Turkse eenheid viel uiteen", "15187774"], "d": ["Na de overwinning bij Ankara gaf Timur de beys die bij hem waren hun oude gebieden terug. Aan de beys Karamanoğlu Mehmed en Ali werden het gebied Karaman en Kayseri, Kırşehir, Sivrihisar en Beyşehir, aan Germiyanoğlu Yâkub Bey II Kütahya en het gebied Germiyan, en aan Candaroğlu İsfendiyar Bey bovenop de lijn Kastamonu–Sinop ook Çankırı en Kalecik gegeven. Ook de gebieden Aydın, Menteşe en Teke keerden terug naar hun oude dynastieën. De Anatolisch-Turkse eenheid die Yıldırım Bayezid in tien jaar had opgebouwd, viel in één zomer uiteen; op de kaart verschijnen deze beyliks opnieuw in hun eigen kleuren.", "3a86d489"]},
"OLAYLAR_EK5:1402-12-14:0":{"b": ["Timur nam Smyrna van de Sint-Jansridders", "66dd1dd4"], "d": ["Timur, die via Kütahya, Denizli, Aydın, Ayasuluk en Tire naar het westen afdaalde, belegerde en nam Smyrna aan de kust, dat sinds 1344 in christelijke handen was. Timur, die in korte tijd de burcht innam die Yıldırım Bayezid jarenlang niet had kunnen veroveren, nam ook de omliggende burchten in, liet het gebied Aydın aan zijn oude bezitters en keerde terug naar het oosten. De stad kwam hierna onder het bestuur van Aydınoğlu Cüneyd Bey.", "b6c372a5"]},
"OLAYLAR_EK5:1402-12-20:0":{"b": ["Îsâ Çelebi nam Bursa in — het Anatolische deel ontstond", "955128c1"], "d": ["Îsâ Çelebi, die zich na de nederlaag bij Ankara naar de omgeving van Karesi had teruggetrokken, nam Bursa in terwijl Timur in Smyrna was. In de oude hoofdstad, die door Timurs soldaten was geplunderd en in brand gestoken, riep hij zijn heerschappij uit en liet munten slaan in zijn naam; in januari 1403 werd hij in Anatolië erkend als 'heerser van de Turken'. Op de kaart verschijnt dit deel, dat zich langs de Aziatische kust van de Zee van Marmara uitstrekt, in de eigen kleur van Îsâ Çelebi.", "fdd5eed3"]},
"OLAYLAR_EK5:1403-03-15:0":{"b": ["Terugtrekking van Timur uit Anatolië", "93a98839"], "d": ["Timur, die het bericht ontving dat Yıldırım Bayezid in Akşehir was gestorven, beschouwde zijn werk in Anatolië als afgerond en wendde zich naar het oosten. Hij liet de beyliks die hem trouw hadden verklaard en de onderling verdeelde Osmaanse prinsen achter; sommige steden zoals Sivas werden overgelaten aan emirs zoals Mezid Bey die aan Timur onderworpen waren. Timur keerde nooit meer naar Anatolië terug, maar de versnipperde orde die hij vestigde duurde tien jaar.", "646cb1bc"]},
"OLAYLAR_EK5:1404-03-01:0":{"b": ["Emir Süleyman stak over naar Anatolië: Bursa kwam in zijn handen", "9b27aa5f"], "d": ["Emir Süleyman, die van de nederlaag van Îsâ Çelebi hoorde, stak samen met Çandarlı Ali Pasja met een sterk leger over naar Anatolië en nam Bursa in; de registers van maart 1404 tonen dat ook Karadeniz Ereğli onder zijn bestuur stond. Çelebi Mehmed kon geen weerstand bieden tegen Süleyman, die al snel zowel Rumelië als het grootste deel van Anatolië beheerste. Op de kaart verschijnen vanaf deze datum tot de herovering van Bursa door Çelebi Mehmed (1410) beide oevers in één kleur, in het deel van Emir Süleyman.", "bca67f28"]},
"OLAYLAR_EK5:1405-01-01:0":{"b": ["Slag in de vlakte van Yenişehir — Çelebi Mehmed trok zich terug naar Amasya", "f1568288"], "d": ["Çelebi Mehmed, die Bursa en Ankara had verloren, werd in de vlakte van Yenişehir door Emir Süleyman verslagen, verloor al zijn winsten in West-Anatolië en trok zich terug op de basis Tokat-Amasya. Na deze nederlaag vermeed hij een rechtstreeks treffen en richtte hij zich op het versterken van zijn gezag in het binnenland van Anatolië. Zo begon de langste stille fase van het Interregnum.", "8c8a3c8c"]},
"OLAYLAR_EK5:1406-01-01:0":{"b": ["Emir Süleyman nam Ankara van Çelebi Mehmed", "d6a2acd6"], "d": ["Na de terugtrekking van Timur uit Anatolië belegerde Emir Süleyman in 1406 Ankara, dat nog in handen van Çelebi Mehmed was. De burchtcommandant Yâkub Bey hield enige tijd stand, maar droeg de burcht door een list van grootvizier Çandarlı Ali Pasja aan Süleyman over. Daarop kwam Çelebi Mehmed na een overeenkomst met Karamanoğlu Mehmed Bey in actie tegen Süleyman.", "f2a18bf9"]},
"OLAYLAR_EK5:1408-06-01:0":{"b": ["Çelebi Mehmed nam Sivas terug van de Timoeride Mezid Bey", "90079b0c"], "d": ["Na de invasie van Timur was het bestuur over Sivas overgelaten aan Mezid Bey, die aan Timur onderworpen was. Çelebi Mehmed in Amasya zond zijn commandant Bayezid Pasja om de stad in te nemen en na hevig verzet kwam Sivas voor de tweede keer in handen van de Osmaanse dynastie. Zo bereikte het deel van Mehmed zes jaar na de Slag bij Ankara in het oosten opnieuw zijn oude grens.", "22c266b9"]},
"OLAYLAR_EK5:1409-01-01:0":{"b": ["Einde van de Artukiden-dynastie: overgave van Mardin aan de Kara Koyunlu", "15b06f33"], "d": ["De Artukiden, die sinds 1106 in Mardin regeerden en de langstlevende tak van de dynastie vormden, konden de druk van de Akkoyunlu niet weerstaan. Melik Ahmed, die begreep dat hij de stad niet kon verdedigen, kwam met de Kara Koyunlu-heerser Kara Yûsuf overeen en droeg Mardin aan hem over. De meer dan drie eeuwen durende Artukidische heerschappij kwam zo ten einde; Mardin en omgeving waren het toneel van de strijd tussen Kara Koyunlu en Akkoyunlu tot zij een eeuw later naar de Osmanen overgingen.", "52e31654"]},
"OLAYLAR_EK5:1410-02-13:0":{"b": ["Slag bij Yambol — Mûsâ Çelebi trok Edirne binnen", "8f978408"], "d": ["Mûsâ Çelebi, die via Walachije naar Rumelië was overgestoken, bracht met Walachijse en Servische steun de strijdkrachten van Emir Süleyman bij Yambol een nederlaag toe en trok Edirne binnen. Tijdens het Interregnum ging Rumelië zo voor het eerst uit handen van Emir Süleyman. Zijn heerschappij was echter niet blijvend; vier maanden later zou hij bij Kosmidion worden verslagen en zich terugtrekken in het binnenland van de Balkan.", "e80e7126"]},
"OLAYLAR_EK5:1412-10-01:0":{"b": ["Slag bij İnceğiz — eerste nederlaag van Çelebi Mehmed in Rumelië", "3c35cd43"], "d": ["Çelebi Mehmed, die met Byzantijnse schepen naar Rumelië was overgestoken, ging bij İnceğiz de strijd aan met Mûsâ Çelebi; Mûsâ versloeg Mehmed met de zevenduizend janitsaren onder zijn bevel en Mehmed moest terugkeren naar Anatolië. Deze nederlaag bracht Mehmed tot een strategie om, in plaats van rechtstreeks te vechten, de grensbeys van Rumelië en het Servische despotaat naar zijn kant te trekken. Met deze diplomatie werd de bodem voor de overwinning bij Çamurlu, negen maanden later, bereid.", "dd443a98"]},
"OLAYLAR_EK5:1415-03-01:0":{"b": ["Beleg van Konya en verdrag met de Karamanoğulları — Hamid-gebied, Said-gebied, Beyşehir, Seydişehir en Akşehir teruggenomen", "0996257e"], "d": ["Çelebi Mehmed organiseerde een grote veldtocht tegen de Karamanoğulları, die tijdens het Interregnum Osmaans grondgebied hadden aangevallen en Bursa hadden belegerd en in brand gestoken, en belegerde in Muharrem 818 Konya. Karamanoğlu Mehmed II Bey moest om vrede vragen; krachtens het verdrag werden het gebied Hamid (de streek Isparta) en het gebied Said opnieuw bij het Osmaanse grondgebied gevoegd, werden Beyşehir, Seydişehir en Akşehir teruggegeven en keerde ook Sivrihisar, dat Timur in 1402 aan de Karamanoğulları had gegeven, terug naar de Osmanen. Deze veldtocht, waarmee de door de Slag bij Ankara uiteengevallen Anatolische eenheid weer in elkaar begon te worden gezet, is een van de concrete redenen waarom Çelebi Mehmed als 'tweede stichter' wordt beschouwd.", "952c9f73"]},
"OLAYLAR_EK5:1415-06-01:0":{"b": ["Inname van Smyrna op Aydınoğlu Cüneyd Bey", "2377ca51"], "d": ["Smyrna, het centrum van Aydınoğlu Cüneyd Bey, die tijdens het Interregnum voortdurend van kant wisselde tussen de prinsen, werd na een beleg van tien dagen door Çelebi Mehmed ingenomen; Cüneyd werd gratie verleend en hij werd naar het sandjakbeylik van Nikopol gestuurd. De stad, die Timur in 1402 aan de Aydınoğulları had teruggegeven, keerde zo dertien jaar later terug naar de Osmanen. Cüneyd zou de stad in 1422 opnieuw innemen; de kwestie werd pas in 1424-1426 door Murad II afgesloten.", "41fefe61"]},
"OLAYLAR_EK5:1416-01-01:0":{"b": ["Executie van Torlak Kemal — Saruhan definitief Osmaans", "8a09dbf1"], "d": ["Torlak Kemal, die de West-Anatolische tak van de beweging van sjeik Bedreddin leidde, werd in de omgeving van Manisa verslagen en geëxecuteerd. Vanaf deze datum kwam het gebied Saruhan definitief onder Osmaanse controle en het beylik dat Timur in 1402 had doen herrijzen, verdween uit de geschiedenis. De laatste politieke overblijfselen van het Interregnum in West-Anatolië werden zo opgeruimd.", "43bec619"]},
"OLAYLAR_EK5:1417-01-01:0":{"b": ["Verovering van Vlorë, Berat en Kanina", "1e1949b8"], "d": ["De Osmanen namen in 1417 Vlorë aan de Adriatische kust samen met de stad Berat in het binnenland en de burcht Kanina onder hun heerschappij. Een jaar later mislukte een Venetiaanse poging om de stad terug te nemen en werd hier een sandjakorganisatie gevestigd, waarmee het Osmaanse gezag blijvend werd. De inname van Vlorë maakte de Osmanen voor het eerst rechtstreeks eigenaar van een haven aan de Adriatische Zee en gaf hen een overzees springplank tegenover Italië.", "508b9927"]},
"OLAYLAR_EK5:1419-01-01:0":{"b": ["Herovering van Midden-Anatolië: Kayseri en Kırşehir", "204eacb3"], "d": ["De steden van Midden-Anatolië die tijdens het Interregnum in handen waren gekomen van de Karamanoğulları, keerden tijdens de campagnes van Çelebi Mehmed om de staat te herstellen terug onder Osmaans bestuur. Met de aansluiting van Kayseri en Kırşehir werd het bekken van de Kızılırmak, dat in de Slag bij Ankara verloren was gegaan, grotendeels teruggenomen. Deze opmars is het vervolg van de oostwaartse politiek die vier jaar eerder met het beleg van Konya begon.", "c663fc08"]},
"OLAYLAR_EK5:1419-01-28:0":{"b": ["De Mamelukken gaven Kayseri aan Dulkadırlı Nâsırüddin Muhammed", "aad4b00c"], "d": ["Het Mamelukse leger dat ten strijde trok tegen Karamanoğlu Mehmed Bey bezette Kayseri; de Mamelukse commandant liet de stad en omgeving aan Dulkadırlı Nâsırüddin Muhammed en keerde terug naar zijn land.", "8cd84dc4"]},
"OLAYLAR_EK5:1423-01-01:0":{"b": ["Definitieve liquidatie van de Tekeoğulları: inname van Antalya", "e65565b2"], "d": ["Het Tekeoğulları-beylik, dat na de Slag bij Ankara door Timurs toedoen opnieuw was gesticht, kwam ten einde met het beleg van Antalya door de Osmaanse strijdkrachten onder bevel van Hamza Bey; de laatste belangrijke man van het beylik, Osman Çelebi, werd uit de weg geruimd. Zo werd het gebied Teke aan de Middellandse Zeekust na een afscheiding van eenentwintig jaar definitief bij de Osmanen gevoegd. Het beylik regeerde sinds 1321 als afsplitsing van de Hamîdoğulları in Antalya.", "6b81398d"]},
"OLAYLAR_EK5:1423-05-01:0":{"b": ["Veldtocht van Turahan Bey naar de Morea en verwoesting van de Hexamilion-muur", "c6c2706d"], "d": ["Toen Byzantium de rivaliserende troonpretendent Mustafa Çelebi steunde, stuurde Murad II Turahan Bey naar de Morea. Turahan Bey brak de Hexamilion-muur, die de Landengte van Korinthe van kant tot kant afsloot, af, drong het schiereiland binnen en richtte grote verwoestingen aan. De vrede kwam tot stand onder de voorwaarde dat de muur nooit meer zou worden gebouwd en jaarlijks belasting zou worden betaald; het despotaat Morea werd zo militair weerloos gemaakt en de bodem voor de definitieve verovering van 1460 werd zevenendertig jaar van tevoren bereid.", "3482eb23"]},
"OLAYLAR_EK5:1424-01-01:0":{"b": ["De Athos-kloosters kwamen onder Osmaanse bescherming", "562de5ea"], "d": ["In de jaren dat Thessaloniki werd belegerd, wendde de kloosterrepubliek Athos op de oostelijke vinger van Chalcidice zich tot Murad II om bescherming te vragen en aanvaardde de Osmaanse heerschappij. De eigendoms- en eredienstrechten van de monniken werden gewaarborgd; de kloosters werden in ruil voor belasting vrij gelaten in hun interne aangelegenheden. Deze orde werd het langstlevende voorbeeld van de beschermingsrelatie die de Osmanen met orthodoxe instellingen aangingen en duurde vijf eeuwen.", "6be1a9f2"]},
"OLAYLAR_EK5:1427-01-01:0":{"b": ["Annexatie van het Tâceddinoğulları-beylik: Niksar", "370ffd47"], "d": ["Onder druk van Yörgüç Pasja, de beylerbey van Amasya, droeg Tâceddinoğlu Hüsâmeddin Hasan Bey in 830 (1427) de sleutels van zijn land met als centrum Niksar over; hem werd een sandjak in Rumelië gegeven. Zo kwam een einde aan het beylik dat in de tweede helft van de 14e eeuw was gesticht en waarvan de grenzen soms reikten tot Kelkit, Amasya, Samsun, Ordu en Giresun. In hetzelfde jaar werden ook de gebieden van de Hacıemiroğulları opgenomen in het kadaster en aan de sandjak Canik gebonden; het tijdperk van de beyliks in de Midden-Zwarte Zeeregio was gesloten.", "06fa8222"]},
"OLAYLAR_EK5:1427-01-01:1":{"b": ["Belgrado aan Hongarije gelaten — Verdrag van Tata", "62481183"], "d": ["Na de dood van de Servische despoot Stefan Lazarević werd, krachtens het Verdrag van Tata tussen de Hongaarse koning Sigismund en zijn erfgenaam Đurađ Branković, de burcht Belgrado aan Hongarije overgedragen. De burcht aan het samenvloeiingspunt van Donau en Sava was tot dan toe in handen van het Servische despotaat en voor de Osmanen het slot van de poort naar Midden-Europa. Deze overdracht maakte Belgrado honderd jaar lang tot de hardste hindernis voor de Osmaanse opmars: de belegeringen van 1440 en 1456 zouden mislukken en de burcht zou pas in 1521 vallen.", "ee1ad2d8"]},
"OLAYLAR_EK5:1432-01-01:0":{"b": ["Mardin ging van de Kara Koyunlu-wacht naar Karayülük Osman Bey van de Akkoyunlu", "d82bc97f"], "d": ["De Kara Koyunlu bestuurden Mardin, dat Kara Yûsuf in 1409 had ingenomen, door gouverneurs; Emir Nâsır, die als wacht was achtergelaten, droeg de stad in 835 (1432) over aan Karayülük Osman Bey van de Akkoyunlu. Het Akkoyunlu-bestuur duurde tot het begin van de 16e eeuw.", "407382cb"]},
"OLAYLAR_EK5:1435-01-01:0":{"b": ["De Karamanoğulları namen Kayseri van de Dulkadırlı's", "2b09e8e8"], "d": ["De Karaman-bey voegde met een overwinning op de Dulkadırlı's Kayseri, Ürgüp, Develi Karahisarı en Uçhisar bij zijn land.", "39a543cc"]},
"OLAYLAR_EK5:1446-05-05:0":{"b": ["Gebeurtenis van Buçuktepe — eerste janitsarenopstand en terugkeer van Murad II op de troon", "6388dda1"], "d": ["De Gebeurtenis van Buçuktepe, de eerste janitsarenopstand die de geschiedenis kent en die in Edirne uitbrak, begon met de eis om hun soldij met een halve akçe te verhogen en eindigde met de afzetting van de jonge Mehmed II. Murad II vertrok haastig uit Manisa op 8 Safer 850 en begon zijn tweede regering. De gebeurtenis was het eerste teken dat het kapıkulu-korps een macht was geworden die een stem had over de troon, en bepaalde de levenslange behoedzaamheid van de Veroveraar tegenover de janitsaren.", "c03ef4f8"]},
"OLAYLAR_EK5:1449-01-01:0":{"b": ["Aansluiting van de kust van Epirus: Arta en Preveza", "796f7ecf"], "d": ["Negentien jaar nadat Ioannina zich in 1430 had overgegeven, kwamen ook Arta en Preveza in het kustgedeelte van het despotaat Epirus onder Osmaans bestuur. Zo kwam de Ambracische Golf, die uitkomt op de Ionische Zee, onder controle en was de zeeverbinding van Ioannina voltooid. Preveza is het sleutelpunt van de baai die negentig jaar later zijn naam zou geven aan de overwinning van Barbarossa die de geschiedenis inging.", "b5e95ae5"]},
"OLAYLAR_EK5:1451-02-18:0":{"b": ["Overlijden van Murad II en tweede troonsbestijging van Mehmed II", "8f8256ad"], "d": ["Murad II, die na de bruiloft van zijn zoon ziek werd, stierf op 1 Muharrem 855 (3 februari 1451) in Edirne. De negentienjarige Mehmed II besteeg op 16 Muharrem 855 (18 februari 1451) voor de tweede keer de Osmaanse troon — ditmaal blijvend. De terugkeer van de jonge heerser, die vijf jaar eerder bij Buçuktepe van zijn troon was gezet, is het begin van een regering die twee jaar later met de verovering van Constantinopel zou worden bekroond en het Osmaanse beylik in een wereldrijk zou veranderen.", "5363b0f7"]},
"OLAYLAR_EK5:1454-07-14:0":{"b": ["Eerste beleg van Kaffa door de gezamenlijke Osmaans-Krim strijdkrachten", "e346d163"], "d": ["De Krim-khan Hacı Giray, die in juni 1454 een overeenkomst met Mehmed de Veroveraar sloot, belegerde Kaffa over land met 7000 ruiters; ook een Osmaanse vloot van vijftig à zestig galeien nam positie op zee. Het Genuese Kaffa liet het beleg opheffen door schatting te betalen en de definitieve verovering werd uitgesteld tot eenentwintig jaar later, 1475. Deze eerste gezamenlijke operatie was het eerste voorbeeld van de Osmaans-Krim militaire samenwerking die later bij de definitieve verovering van Kaffa zou worden herhaald.", "bf590b3e"]},
"OLAYLAR_EK5:1455-01-01:0":{"b": ["Inname van de noordelijke Egeïsche eilanden: Tenedos, Imbros en Thasos", "76575895"], "d": ["Onmiddellijk na de verovering van Constantinopel richtte Mehmed de Veroveraar zich, om de zeeweg van de nieuwe hoofdstad veilig te stellen, op de eilanden aan de Egeïsche ingang van de Dardanellen; Tenedos en Imbros werden van Byzantium ingenomen, Thasos van de familie Gattilusio van Genuese afkomst. Deze eilanden, die beide oevers van de zeestraat afsloten, werden voortaan de eerste schakel van de bevoorradings- en verdedigingslijn van Constantinopel. De heerschappij wisselde door de interventies van de pauselijke en Venetiaanse vloten enige tijd heen en weer en werd pas in 1459 definitief.", "9a34e8f0"]},
"OLAYLAR_EK5:1455-06-01:0":{"b": ["Verovering van Kosovo: inname van Priština en Novi Pazar", "d7ed2345"], "d": ["Het Osmaanse leger dat tegen het Servische despotaat optrok, nam Priština op de vlakte van Kosovo en Yenipazar (Novi Pazar), het centrum van de regio Raška, in; in dezelfde campagne werd ook Novo Brdo, beroemd om zijn zilvermijnen, ingenomen. Zo werd de zuidelijke helft van Servië rechtstreeks aan het Osmaanse bestuur gebonden en werd het despotaat in Smederevo van zijn kerngebied afgesneden. Deze verovering was de beslissende stap op weg naar de volledige annexatie van Servië vier jaar later.", "b2c7fcce"]},
"OLAYLAR_EK5:1456-01-01:0":{"b": ["Peć (İpek) kwam onder Osmaans bestuur — een van de centra van de sandjak Dukakin", "19511588"], "d": ["In 1455, onmiddellijk na de Servische veldtocht van Mehmed de Veroveraar, ging Peć, het centrum van het Servische patriarchaat, over naar Osmaans bestuur; in de Osmaanse bronnen bestaat geen vermelding van deze overgang. Het stadje werd na verloop van tijd een kleine moslimstad en was een van de verblijfplaatsen van de sandjakbey in de sandjak Dukakin.", "4d7160f6"]},
"OLAYLAR_EK5:1456-01-24:0":{"b": ["Verovering van Enez en Samothrake — voltooiing van de kust van West-Thracië", "106e723b"], "d": ["Enez, op de plek waar de Maritsa in zee uitmondt, werd ingenomen van de familie Gattilusio van Genuese afkomst, die het tachtig jaar in handen had gehad; het eiland Samothrake, dat ervan afhing, werd in dezelfde campagne ingenomen. Met de val van Enez werd de kuststrook van West-Thracië van Thessaloniki tot Gallipoli ononderbroken Osmaans grondgebied. In handen van de familie Gattilusio bleef alleen Lesbos over; dat zou zes jaar later worden ingenomen.", "327297a0"]},
"OLAYLAR_EK5:1456-07-22:0":{"b": ["Mislukking van het beleg van Belgrado", "3d53a604"], "d": ["Mehmed de Veroveraar belegerde na de verovering van Constantinopel Belgrado, dat gold als het slot van Midden-Europa; maar de versterkingen die János Hunyadi over de Donau bracht en de vrijwilligers die de kruisvaarderspredikant Capistrano verzamelde, voorkwamen de val van de burcht. De sultan werd ondanks zijn persoonlijke heldhaftigheid voor het beleg gewond en moest zich terugtrekken. Deze mislukking zou de Hongaarse grens vijfenzestig jaar lang voor de Osmaanse opmars afsluiten; Belgrado zou pas in 1521 door Süleyman kunnen worden ingenomen.", "036836cb"]},
"OLAYLAR_EK5:1458-05-01:0":{"b": ["Verovering van Noord-Morea: Patras (Balyabadra)", "c08a8509"], "d": ["Mehmed de Veroveraar, die zich in dezelfde jaren als de annexatie van Servië tot het despotaat Morea wendde, nam met zijn strijdkrachten Patras (Balyabadra) in het noordwesten van het schiereiland in. Deze haven, die de ingang van de Golf van Korinthe bewaakt, is het slot van de toegang tot de Morea over land; de inname bereidde de bodem voor de definitieve verovering twee jaar later. De stad was de laatste grote aanlegplaats waar de Byzantijnse despoten contact hadden met de Latijnse wereld.", "4490cc14"]},
"OLAYLAR_EK5:1459-06-20:0":{"b": ["Inname van de westelijke Zwarte Zeekust: Amasra", "f43608fc"], "d": ["Amasra, de versterkte kolonie van Genua aan de westelijke Zwarte Zee, gaf zich zonder verzet over onder de gezamenlijke druk van de vloot en de landstrijdkrachten van Mehmed de Veroveraar. Deze haven aan de kust van Bartın–Zonguldak stond als Latijnse enclave tussen de Candaroğulları en het Osmaanse grondgebied; met de inname werd de kust één geheel. De val van Amasra is de eerste stap van de grote Zwarte Zee-veldtocht die twee jaar later (1461) tegen Sinop en Trebizonde zou worden gevoerd.", "b8b9f4f0"]},
"OLAYLAR_EK5:1462-09-17:0":{"b": ["Verovering van het eiland Lesbos", "fe17aeba"], "d": ["Het Osmaanse leger onder bevel van Mehmed de Veroveraar nam in Dhu'l-Hijja 866 Lesbos na een korte maar hevige belegering af van de familie Gattilusio van Genuese afkomst en annexeerde het. De val van het grootste eiland van de noordelijke Egeïsche Zee liquideerde ook de laatste belangrijke basis van de Genuezen in de regio. Het eiland zou dankzij zijn nabijheid van de Anatolische kust voortaan dienen als voorpost van de Osmaanse vloot en tevens de geschiedenis van de zeevaart ingaan als de plaats waar de gebroeders Barbarossa opgroeiden.", "453088e2"]},
"OLAYLAR_EK5:1463-07-28:0":{"b": ["Begin van de zestien jaar durende Osmaans-Venetiaanse oorlog", "563ddb68"], "d": ["De Venetianen begonnen in 1463 de oorlog door een bondgenootschap te sluiten met Karaman en de Akkoyunlu-heersers om de Osmaanse opmars in de Morea en de Egeïsche Zee te stoppen. Deze omsingelingsstrategie, gevormd door Uzun Hasan in het oosten, Venetië in het westen en Karaman daartussen, dwong de Veroveraar tegelijkertijd aan meerdere fronten te vechten. De zestien jaar durende strijd zou alle grote campagnes van die tijd omvatten, van Otlukbeli tot de Albanese veldtochten, en pas met het Verdrag van Constantinopel in 1479 eindigen.", "e70079e9"]},
"OLAYLAR_EK5:1466-01-01:0":{"b": ["Verovering van het grootste deel van Herzegovina: Trebinje en Mostar", "f54c0100"], "d": ["De gebieden van de Herzegovinaanse hertog Stjepan Vukčić Kosača, die een afzonderlijk bestuur had gevormd naast Bosnië, gingen drie jaar na de val van het Koninkrijk Bosnië grotendeels over naar Osmaans bestuur: in het zuiden werd Trebinje in 1466 'samen met vrijwel de hele regio Herzegovina' ingenomen. Mostar, gevormd rond de twee kleine burchten van de brug over de Neretva, moet kort vóór de verovering van Blagaj, het centrum van Herzegovina, in 1466-1468 zijn ingenomen; in het Bosnische icmal-kadaster van 1468-1469 staat het geregistreerd onder de naam 'Köprülü Hisar'. De verovering van Herzegovina werd in 1483 voltooid met de resterende burchten van het hertogdom.", "a7f22be7"]},
"OLAYLAR_EK5:1466-06-01:0":{"b": ["Tweede Albanese veldtocht — persoonlijke opmars van de Veroveraar tegen Skanderbeg", "9cdd2bfa"], "d": ["Om het meer dan een kwart eeuw durende verzet van Skanderbeg te breken, organiseerde Mehmed de Veroveraar in 1466-1467 grote veldtochten waarvan hij persoonlijk het bevel voerde. Het Osmaanse leger belegerde Krujë en bouwde de burcht van İlbasan (Elbasan) om de regio onder controle te brengen. Hoewel de veldtocht het Albanese verzet de rug brak, lukte het niet de burcht te laten vallen; de volledige onderwerping van de regio zou tot tien jaar na de dood van Skanderbeg duren.", "00e75aca"]},
"OLAYLAR_EK5:1467-11-10:0":{"b": ["Ineenstorting van de staat Kara Koyunlu: Jahan Shah gedood", "30bc6358"], "d": ["De Kara Koyunlu-heerser Jahan Shah, die tijdens de terugtocht van zijn veldtocht tegen Uzun Hasan wegens het invallen van de winter werd overvallen, werd gedood tijdens zijn vlucht tussen Bingöl en Kiğı. Na deze klap kon de staat zich niet meer herstellen; de laatste heerser Hasan Ali werd in 1469 gevangengenomen en gedood door Uğurlu Mehmed, de zoon van Uzun Hasan. De bijna een eeuw durende Kara Koyunlu-heerschappij in Oost-Anatolië, Azerbeidzjan en Irak ging zo over op de Akkoyunlu.", "5a5288e7"]},
"OLAYLAR_EK5:1468-01-17:0":{"b": ["Dood van Skanderbeg — uitdoven van het Albanese verzet", "9158c35f"], "d": ["Skanderbeg, die aan het Osmaanse hof was opgegroeid en in 1444 na de nederlaag bij Zlatitsa in opstand kwam en meer dan een kwart eeuw in Albanië weerstand bood, stierf in Lezhë, waar hij zijn toevlucht had gezocht. Dit verzet, dat de Osmaanse legers onder Murad II en de Veroveraar herhaaldelijk bezighield, verloor met zijn dood zijn centrale leiding. Met de ineenstorting van het Albanese front, gevoed door het pausdom en Venetië, namen de Osmanen binnen tien jaar Krujë en Shkodër in en voegden de regio definitief bij hun grondgebied.", "5c7cffad"]},
"OLAYLAR_EK5:1475-01-10:0":{"b": ["Nederlaag bij Racova (Vaslui) in Moldavië", "a1a74bf7"], "d": ["De Moldavische woiwode Stefan cel Mare lokte de Osmaanse strijdkrachten onder bevel van de beylerbey van Rumelië Hadım Süleyman Pasja naar moerassig terrein en bracht hun een zware nederlaag toe. Deze nederlaag, een van de zwaarste landnederlagen uit de tijd van de Veroveraar, wekte in Europa grote weerklank en bezorgde Stefan faam in de kruisvaarderswereld. De sultan zou het jaar daarop persoonlijk ten strijde trekken voor vergelding.", "3247c9fe"]},
"OLAYLAR_EK5:1476-07-26:0":{"b": ["Overwinning bij Valea Albă (Akdere) — Moldavische veldtocht", "45a66791"], "d": ["Mehmed de Veroveraar, die persoonlijk ten strijde trok om de nederlaag bij Racova van een jaar eerder te wreken, bracht het Osmaanse leger en de Moldavische troepen bij Valea Albă (Akdere) een grote nederlaag toe en trok Suceava, het centrum van het beylik, binnen. De burchten konden echter niet worden ingenomen; door voedseltekort, de pest onder de janitsaren en Hongaarse voorbereidingen moest het leger zich terugtrekken. De definitieve gehoorzaamheid van Moldavië zou pas in de volgende jaren, met de inname van Kilia en Akkerman in 1484, kunnen worden verzekerd.", "27b9dd1c"]},
"OLAYLAR_EK5:1478-06-15:0":{"b": ["Verovering van Krujë (Akçahisar) en voltooiing van Albanië", "559a79b4"], "d": ["Tien jaar na de dood van Skanderbeg werd in 1478 met de inname van Krujë, Drivast, Lezhë en Jabljak de verovering van Albanië grotendeels voltooid. De val van de burcht Krujë, die jarenlang de Osmaanse legers weerstond en het symbool was van het verzet van Skanderbeg, betekende het einde van het Venetiaans-Albanese bondgenootschap in de regio. Shkodër, dat overbleef, zou het jaar daarop met het Verdrag van Constantinopel aan de Osmanen worden gelaten.", "4f6059e8"]},
"OLAYLAR_EK5:1479-01-01:0":{"b": ["Aansluiting van het schiereiland Taman", "4ef917b8"], "d": ["Na de inname van Kaffa en Kerch in 1475 nam de vloot die Mehmed de Veroveraar naar de Kaukasische kusten zond, samen met Anapa en Kopa, het Genuese Matrega (Tamatarhan) op het schiereiland Taman in. Zo kwamen beide oevers van de zeestraat onder controle en kon de toegang tot de Zee van Azov volledig worden gecontroleerd. Taman werd als poort naar de Noord-Kaukasus aan de sandjak Kaffa gebonden.", "74a0de9f"]},
"OLAYLAR_EK5:1480-07-28:0":{"b": ["Mislukking van het beleg van Rhodos", "35a85c28"], "d": ["Op bevel van Mehmed de Veroveraar belegerde de vloot van 160 schepen onder bevel van Mesih Pasja in het voorjaar van 885 (1480) Rhodos en het eiland bleef drie maanden geblokkeerd. De Sint-Jansridders onder leiding van grootmeester Pierre d'Aubusson boden ondanks zware verliezen fel weerstand; nadat ook de laatste grote bestorming op 20 Jumada al-awwal 885 werd afgeslagen, trok de vloot zich op 3 augustus terug. Na deze mislukking werden de muren van de stad van de grond af vernieuwd en veranderde zij in de sterkste vesting van Europa; het eiland kon pas in 1522 door Süleyman worden ingenomen.", "23334bd0"]},
"OLAYLAR_EK5:1481-06-22:0":{"b": ["Slag bij Yenişehir — nederlaag van Cem Sultan", "c35abee2"], "d": ["De twee broers die na de dood van de Veroveraar in actie kwamen om de troon, stonden tegenover elkaar op de vlakte van Yenişehir en Cem Sultan leed een beslissende nederlaag. De prins, die achttien dagen in Bursa regeerde en de khutba in zijn naam liet lezen, moest zich na de nederlaag eerst naar Konya en daarna naar Mamelukse gebieden terugtrekken. Yenişehir begon de langst durende dynastieke crisis uit de Osmaanse geschiedenis: de kwestie-Cem zou veertien jaar lang het Osmaanse buitenlands beleid tegenover Europa verlammen.", "9d30204e"]},
"OLAYLAR_EK5:1482-01-01:0":{"b": ["Annexatie van Herzegovina", "bf247891"], "d": ["Na de verovering van Bosnië in 1463 gingen de gebieden van het overgebleven Hertogdom Herzegovina stapsgewijs over naar Osmaans bestuur: Trebinje en Mostar werden in 1466 ingenomen, de sandjak Herzegovina werd in 1470 gevormd en de laatste gebieden van het hertogdom aan de Adriatische kust werden samen met Herceg Novi begin 1482 veroverd en bij de sandjak gevoegd. Zo werd het bergachtige gebied achter de Adriatische Zee volledig Osmaans en werden Bosnië en Herzegovina één bestuurlijke geografie. De zoon van de laatste hertog, die het Osmaanse paleis binnentrad, is Hersekzâde Ahmed Pasja, die later zou opklimmen tot grootvizier.", "0522e47f"]},
"OLAYLAR_EK5:1482-01-01:1":{"b": ["Zakynthos (Zaklise) tegen jaarlijkse schatting aan Venetië gelaten", "268a691a"], "d": ["Zakynthos, een van de Ionische eilanden die aan het einde van de tijd van de Veroveraar van de familie Tocco waren afgenomen, werd aan Venetië gelaten toen de nieuwe sultan, die bezig was met de kwestie-Cem, rust in het Westen zocht. Het eiland werd overgedragen aan een Venetiaans bestuur dat de Osmaanse soevereiniteit erkende en jaarlijks vijfhonderd dukaten schatting betaalde. Zo bleef het rechtstreekse Osmaanse bestuur in de Ionische Zee beperkt tot Lefkada.", "0773761c"]},
"OLAYLAR_EK5:1482-07-29:0":{"b": ["Cem Sultan zocht zijn toevlucht op Rhodos", "2228d6da"], "d": ["Cem Sultan, wiens poging om Konya te belegeren ook zonder resultaat bleef, vluchtte met een dertigtal mannen uit Anatolië, bereikte Rhodos en werd door de Sint-Jansridders plechtig ontvangen. Het gastschap veranderde echter snel in gevangenschap; de prins werd eerst aan Frankrijk en daarna aan het pausdom overgedragen en werd een troef in handen van de Europese politiek. Bayezid II moest voor het vasthouden van zijn broer jaarlijks betalen en de militaire stappen van de Osmanen naar het Westen werden tot de dood van Cem opgeschort.", "05ca0dd6"]},
"OLAYLAR_EK5:1485-01-01:0":{"b": ["Begin van de Osmaans-Mamelukse oorlog (front van Çukurova)", "3fe3f0c7"], "d": ["De strijd om invloed over de Dulkadırlı's en de vijandschap die de toevlucht van Cem Sultan in Mamelukse gebieden naliet, begonnen in 1485 een zes jaar durende oorlog tussen twee grote soennitische mogendheden. In de gevechten in Çukurova rond Adana en Tarsus kon geen van beide partijen de overhand krijgen; de Osmaanse legers ontvingen enkele zware klappen. Deze oorlog is de eerste fase van de breuk in de Osmaans-Mamelukse betrekkingen en de opening van het proces dat dertig jaar later met de veldtochten van Yavuz naar Marj Dabiq en Ridaniya zou eindigen.", "08141630"]},
"OLAYLAR_EK5:1491-05-01:0":{"b": ["Osmaans-Mamelukse vrede — bemiddeling van Tunis", "60dd6719"], "d": ["In de in 1485 begonnen Osmaans-Mamelukse oorlog kon geen van beide partijen een beslissende overwinning behalen; door bemiddeling van de Tunesische heerser Osman Hafsî werd in 1491 een akkoord bereikt. Het verdrag bracht de grenzen grotendeels terug naar de toestand van vóór de oorlog en de afrekening tussen de twee islamitische staten werd een generatie lang uitgesteld. De zes jaar durende uitputtende strijd is een van de voornaamste redenen voor de voorzichtige buitenlandse politiek van Bayezid II en zijn nadruk op interne regelingen in plaats van een oriëntatie naar het oosten.", "406d3b78"]},
"OLAYLAR_EK5:1492-08-01:0":{"b": ["Opname van de uit Spanje verdreven Sefardische Joden in het Osmaanse Rijk", "5c2b5c24"], "d": ["Na de val van Granada vonden sommige Joden die voor de vervolging door de inquisitie in Spanje vluchtten, onderdak in Osmaans grondgebied en werden in verschillende steden gevestigd. Onder het Osmaanse bestuur verwierven deze Sefardische gemeenschappen een tot dan toe niet gekende vrijheid om zich te vestigen waar zij wilden, hun geloof te belijden, onderwijsinstellingen te openen en nieuwe synagogen te bouwen. Deze migratie, die met de drukkunst, geneeskunde en financiële kennis die zij meebrachten het economisch leven van Thessaloniki en Constantinopel veranderde, werd het meest besproken voorbeeld in Europa van de Osmaanse tolerantieorde.", "b5b4a53b"]},
"OLAYLAR_EK5:1495-02-25:0":{"b": ["Dood van Cem Sultan — einde van veertien jaar gijzelaarschap", "f6588b70"], "d": ["Cem Sultan, die door het pausdom aan koning Karel VIII van Frankrijk was overgedragen, stierf op 27 januari 1495 na zijn vertrek uit Rome op een plek genaamd Castel Capuana; de bronnen vermelden dat hij mogelijk door pauselijke kringen was vergiftigd. De dood van de prins, die veertien jaar lang door de Europese staten als dreigkaart tegen de Osmanen was vastgehouden, maakte eindelijk de handen van Bayezid II vrij. De sultan zou hierna ook Venetië de oorlog verklaren en zijn vloot naar zijn eerste grote overwinning leiden.", "8f2579d5"]},
"OLAYLAR_EK5:1499-08-28:0":{"b": ["Zeeslag bij Sapienza (Zonchio) — eerste grote vlootsucces in de Middellandse Zee", "9754aaef"], "d": ["Bayezid II, die na het einde van de kwestie-Cem de handen vrij had, verklaarde in 1499 Venetië de oorlog; de Osmaanse vloot versloeg de Venetiaanse vloot voor Sapienza (Zonchio) en behaalde de eerste grote zeeoverwinning in de Middellandse Zee. Met deze overwinning maakte de vloot bekend dat zij Venetië nu ook op zee kon tegemoet treden.", "5fa6989c"]},
"OLAYLAR_EK5:1500-12-24:0":{"b": ["Verlies van Kefalonia en Ithaca", "60f0f687"], "d": ["Venetië, dat door de inname van Modon en Koron was geschokt, ging in een bondgenootschap met Spanje over tot een tegenoffensief en belegerde Kefalonia, dat sinds 1479 in Osmaanse handen was. Na een verzet van zevenenveertig dagen viel de burcht, het eiland ging samen met Ithaca naar Venetië en keerde driehonderd jaar lang niet terug naar Osmaans bestuur. Dit verlies schiep een evenwicht waarin wat in de Morea was gewonnen in de Ionische Zee werd teruggegeven.", "a61731e0"]},
"OLAYLAR_EK5:1502-03-01:0":{"b": ["Ondergang van het Khanaat van de Gouden Horde en opkomst van de Krim", "0d1dc515"], "d": ["De laatste heerser, Sjeik Ahmed Khan (1481-1502), kon zijn land niet redden uit de crisis waarin het was gestort en het Khanaat van de Gouden Horde verdween in 1502 uit de geschiedenis door de slag van Krim-khan Mengli Giray. Als gevolg van troonstrijd en versplintering kwamen op het grondgebied van de oude Gouden Horde de khanaten Krim, Kazan, Nogai, Astrachan en Sibir op. Terwijl deze overwinning van de Krim onder Osmaanse bescherming de Osmaanse invloed ten noorden van de Zwarte Zee onbetwistbaar maakte, zou het vacuüm dat in de regio ontstond in de loop van de volgende eeuw door Moskou worden opgevuld.", "9314f239"]},
"OLAYLAR_EK5:1502-12-14:0":{"b": ["Einde van de Osmaans-Venetiaanse oorlog en vrede", "125b1526"], "d": ["De oorlog die in 1499 begon en Venetië schokte met Sapienza, Lepanto en het verlies van Modon en Koron, eindigde in 1502 met vrede. Venetië verloor zijn belangrijkste basissen in de Morea en moest de Osmaanse suprematie erkennen in ruil voor het behoud van zijn handelsprivileges in de oostelijke Middellandse Zee. De voorzichtig geachte regering van Bayezid II had de Osmanen met deze oorlog voor het eerst tot een serieuze zeemacht in de Middellandse Zee verheven.", "3d102f53"]},
"OLAYLAR_EK5:1511-07-02:0":{"b": ["Opstand van Şahkulu — Kızılbaş-opstand van de streek Teke tot Sivas", "3beadca7"], "d": ["Şahkulu Baba Tekeli, die in 1510 onder invloed van de Safawidische propaganda in Anatolië zijn opstand openbaarde, had in maart 1511 de bazaar van Antalya bezet en in april bij Kütahya en omgeving de Osmaanse strijdkrachten verslagen. In de laatste botsing met grootvizier Hadım Ali Pasja bij Sivas leden beide partijen zware verliezen; zowel de grootvizier als de leider van de opstand kwamen om. Deze opstand, die het gezag van de staat in Anatolië aan het wankelen bracht, toonde het machtsvacuüm in de laatste jaren van Bayezid II en werd de sterkste reden voor de opmars van prins Selim naar de troon.", "846180f5"]},
"OLAYLAR_EK5:1512-04-24:0":{"b": ["Troonsafstand van Bayezid II en troonsbestijging van Yavuz Sultan Selim", "c4cfab69"], "d": ["Onder druk van prins Selim, die in de troonstrijd met zijn broers de steun van de janitsaren achter zich had, deed Bayezid II op 24 april 1512 afstand van de troon en besteeg Selim I op dezelfde dag als negende Osmaanse heerser de troon. De oude sultan stierf onderweg naar Dimetoka, zijn geboorteplaats, in het dorp Abalar bij Çorlu op 25 Rabi' al-awwal 918 (10 juni 1512). De regering van eenendertig jaar, voorzichtig en naar binnen gericht, werd opgevolgd door het tijdperk van Yavuz, dat de grenzen van het rijk in acht jaar zou verdubbelen.", "7194b8c2"]},
"OLAYLAR_EK5:1513-01-01:0":{"b": ["Verovering van de burcht Sinj", "83271ea5"], "d": ["De Osmaanse ruiterstrijdkrachten aan de Bosnische grens namen de burcht Sinj, die zich uitstrekt tot in het binnenland van Dalmatië, in op het Hongaarse Koninkrijk. Dit was een vroege schakel van de Dalmatische grenslijn die negen jaar later zou worden uitgebreid door de verovering van Knin en omgeving door Gazi Hüsrev Bey; de burcht zou in 1686 aan Venetië verloren gaan.", "28c20426"]},
"OLAYLAR_EK5:1513-04-01:0":{"b": ["Slag bij Yenişehir en het uitschakelen van prins Ahmed", "e2ed15dd"], "d": ["Yavuz Sultan Selim versloeg zijn oudere broer prins Ahmed, de sterkste rivaal voor de troon, op de vlakte van Yenişehir bij Bursa en liet hem gevangennemen en uit de weg ruimen. Zo werd de broederstrijd die sinds 1511 duurde afgesloten en kwam een einde aan de interne verdeeldheid in Anatolië. Selim won de vrijheid om, nu zijn rug gedekt was, zich op de Safawidische kwestie te richten.", "ed5f5ec0"]},
"OLAYLAR_EK5:1514-09-06:0":{"b": ["Intocht van Yavuz Sultan Selim in Tabriz", "dad2e227"], "d": ["Na de overwinning bij Çaldıran trok het Osmaanse leger Tabriz, de Safawidische hoofdstad, binnen en de khutba werd in de stad in naam van de sultan gelezen. Selim bleef er een week en liet een deel van de kunstenaars en ulema van Tabriz naar Constantinopel overbrengen; deze overbrenging zou de Osmaanse hofkunst diepgaand beïnvloeden. Hoewel de stad werd verlaten toen de winter naderde en de janitsaren ontevreden waren, was de Safawidische superioriteit in het oosten gebroken. Op de kaart zijn de plaatsen die op deze dag Osmaans werden niet aaneengesloten en dat klopt: Tabriz is een negen dagen durende legerbezetting; de vlakte van Erzincan had zich tijdens de veldtocht zonder strijd overgegeven, terwijl de burcht Kemah in het midden ervan tot 19 mei 1515 Safawidisch bleef weerstaan; Siirt werd door Halil Bey, de melik van Hasankeyf, die in Tabriz uit de gevangenis van Sjah Ismail was bevrijd, door zich aan de Osmanen te onderwerpen op de Safawiden teruggenomen — het omliggende Diyarbakır bleef tot 1515 en Hasankeyf tot 1517 Safawidisch.", "3f65211e"]},
"OLAYLAR_EK5:1515-05-19:0":{"b": ["Verovering van de burcht Kemah op de Safawiden", "73fd8671"], "d": ["Yavuz Sultan Selim, die na Çaldıran de winter in Amasya doorbracht, droeg Bıyıklı Mehmed Pasja op de versterkte burcht Kemah, die het doorwaadbare punt van de Eufraat bewaakt, te veroveren. Na een beleg waaraan de sultan persoonlijk deelnam, werd de burcht aan de Safawiden ontnomen en ging de poort naar Oost-Anatolië open. Deze verovering is de eerste concrete stap die de overwinning bij Çaldıran in blijvende gebiedswinst omzette.", "9e896ebe"]},
"OLAYLAR_EK5:1515-06-13:0":{"b": ["Overwinning bij Turnadağ — het Dulkadir-beylik werd vazal van de Osmanen", "fd879145"], "d": ["De Osmaanse strijdkrachten versloegen de Dulkadir-bey Alâüddevle Bozkurt, die tijdens de Çaldıran-veldtocht een dubbelzinnige houding had aangenomen, op de plek Ördekli tussen Göksun en Andırın; Alâüddevle werd in deze slag gedood. Het beylik werd op deze datum niet geannexeerd: na Alâüddevle werd Şehsuvaroğlu Ali Bey door Yavuz Sultan Selim aan het hoofd van het Dulkadıroğulları-beylik geplaatst en het land met Maraş-Elbistan als centrum bleef bestaan als een aan de Osmanen onderworpen beylik. De buffer aan de Mamelukse grens kwam zo onder Osmaanse controle en de weg naar de Egyptische veldtocht twee jaar later lag open; de annexatie zou plaatsvinden na de executie van Ali Bey.", "cf9c7460"]},
"OLAYLAR_EK5:1515-09-19:0":{"b": ["Verovering van Âmid (Diyarbakır) en stichting van het beylerbeylik Diyarbakır", "a6867d5b"], "d": ["Nadat İdrîs-i Bitlisî de soennitische Koerdische beys in de regio voor de Osmanen had gewonnen, hielden de Safawidische strijdkrachten een lang beleg niet vol en werden de sleutels van Âmid aan Bıyıklı Mehmed Pasja overgedragen. De stad werd het centrum van het nieuw gestichte beylerbeylik Diyarbakır. Zo kwam de bestuurlijke kern van Boven-Mesopotamië in Osmaanse handen.", "70169bcc"]},
"OLAYLAR_EK5:1516-03-26:0":{"b": ["Verovering van Harput — opening van de weg naar Diyarbakır", "564eb269"], "d": ["Hüsrev Pasja, de beylerbey van Karaman, die op weg ging om het na Çaldıran ingenomen Diyarbakır te redden van het Safawidische beleg, nam na een beleg van drie dagen de burcht Harput in, waarvan de omgeving eerder door Çerkez Hüseyin Bey was ingenomen. De weg ten oosten van de Eufraat naar Diyarbakır was zo veiliggesteld.", "eb738178"]},
"OLAYLAR_EK5:1516-05-01:0":{"b": ["Slag bij Koçhisar (Kızıltepe) — nederlaag van Kara Khan", "9ea9e843"], "d": ["Het Osmaanse leger onder bevel van Bıyıklı Mehmed Pasja versloeg de Safawidische gouverneur Kara Khan bij Koçhisar, op de plek Koruk in de vlakte van Dede Garkın, in een dag durende veldslag; het afgehakte hoofd van Kara Khan werd naar het legerkamp van de sultan gezonden. Daarna trokken de Osmaanse strijdkrachten de stad Mardin binnen, maar zij bleven enkele dagen en vertrokken; de burcht van Mardin, bezet door Safawidische bewakers, kon pas een jaar later worden overgenomen. Deze overwinning stelde Yavuz in staat zijn zuidgrens veilig te stellen en zich op de Egyptische veldtocht te richten. Andere plaatsen die op dezelfde datum werden toegevoegd: Palu, Çemişgezek, Siverek.", "6bc19ce1"]},
"OLAYLAR_EK5:1516-06-05:0":{"b": ["Vertrek van Yavuz Sultan Selim uit Constantinopel voor de Egyptische veldtocht", "ac258b4b"], "d": ["Yavuz Sultan Selim vertrok uit Constantinopel schijnbaar om een nieuwe oostelijke veldtocht tegen de Safawiden voor te bereiden en trok via Akşehir naar het zuiden. Dat de Mamelukse sultan Qansuh al-Ghawri contact legde met Sjah Ismail en de oostflank van de Osmanen bedreigde, zou het doel snel doen veranderen. De veldtocht is het begin van de grote campagne die twee jaar zou duren en de Osmanen in een Midden-Oosters rijk zou veranderen.", "6b27f782"]},
"OLAYLAR_EK5:1516-06-20:0":{"b": ["Inname van Zabid: eerste intocht van Osmaanse zeelieden in de Rode Zee", "38740e0c"], "d": ["Tegenover de Portugese druk in de Indische Oceaan namen de zeelieden van Osmaanse afkomst Hüseyin Bey en Selman Reis, die op verzoek van de Mamelukse sultan Qansuh al-Ghawri naar de Rode Zee waren gestuurd, met hun vloot Zabid in. Deze operatie, die nog in Mamelukse dienst werd uitgevoerd, is de eerste feitelijke aanwezigheid van de Osmaanse marine op de lijn Rode Zee–India. Toen Egypte een jaar later aan de Osmanen overging, zou dezelfde vloot rechtstreeks aan Constantinopel worden gebonden.", "f715b0aa"]},
"OLAYLAR_EK5:1516-07-30:0":{"b": ["Officiële afkondiging van de Mamelukken en Aleppo als doel van de veldtocht", "689e310d"], "d": ["Yavuz Sultan Selim kondigde, nadat Qansuh al-Ghawri een overeenkomst met de Safawiden had gesloten en zijn leger naar Aleppo had gedreven, openlijk de Mamelukse sultan en Aleppo als doel van de veldtocht af. Zo veranderde de al jaren durende verborgen rivaliteit tussen twee soennitische staten in openlijke oorlog. Deze afkondiging was het begin van de vier weken durende aftelling naar Marj Dabiq.", "f2a137f3"]},
"OLAYLAR_EK5:1516-08-02:0":{"b": ["Mislukking van het beleg van Aden: eerste Rode Zee-poging tegen Portugal", "8ffd46f2"], "d": ["Selman Reis en Hüseyin Bey voerden een acht dagen durend beleg om Aden, de poort van de Rode Zee naar de Indische Oceaan, in te nemen, maar moesten zich tegenover de sterke versterkingen van de stad terugtrekken. Dat Aden niet kon worden ingenomen zal de zuidelijke strategie tegen Portugal jarenlang hinderen. Deze poging is de eerste proef in de oceaanpolitiek van de Osmanen.", "8b584b76"]},
"OLAYLAR_EK5:1516-08-24:0":{"b": ["Aansluiting van het Ramazanoğulları-beylik bij de Osmanen", "cfaa3754"], "d": ["Bij de toewijzingen na de overwinning bij Marj Dabiq werd het Ramazanoğulları-beylik met als centrum Adana aan Mahmud Bey gegeven en onder Osmaanse heerschappij gebracht. Het beylik, dat de Mamelukse onderworpenheid verliet, werd in plaats van afgeschaft in de status van 'ocaklık' aan de familie gelaten; de Ramazanoğulları bleven Çukurova besturen als Osmaanse sandjakbeys. Deze bevoorrechte orde duurde tot 1608, toen Pîr Mansûr het beylik verliet. Andere plaatsen die op dezelfde datum werden toegevoegd: Malatya, Tarsus, Mosul, Antep.", "af7c4758"]},
"OLAYLAR_EK5:1516-08-28:0":{"b": ["Aleppo, Raqqa en Deir ez-Zor kwamen onder Osmaanse heerschappij", "2088eb6a"], "d": ["Vier dagen na Marj Dabiq trok Yavuz Sultan Selim zonder verzet Aleppo binnen en in de moskeeën van de stad werd de khutba in zijn naam gelezen. Dat Aleppo, dat gold als de handels- en bestuurlijke hoofdstad van Syrië, zo snel viel, toont dat het Mamelukse gezag in de regio was ingestort. De inname van de stad opende in één klap de weg naar Damascus en vandaar naar Egypte. Andere plaatsen die op dezelfde datum werden toegevoegd: Antiochië, Raqqa, Deir ez-Zor.", "6055ffc7"]},
"OLAYLAR_EK5:1516-08-29:0":{"b": ["Ontmoeting met de Abbasidische kalief Mutawakkil III op de Gökmeydan van Aleppo", "22979f42"], "d": ["Mutawakkil III, de Abbasidische kalief van Caïro die bij Marj Dabiq samen met het Mamelukse leger gevangen was genomen, werd op de Gökmeydan in Aleppo voor de sultan gebracht en Yavuz Sultan Selim betoonde hem groot respect. Het kalifaat van Caïro, dat sinds 1261 een symbolisch ambt in de schaduw van de Mamelukse sultans was, kwam met deze ontmoeting feitelijk onder Osmaanse bescherming. De kalief zou later samen met de sultan naar Constantinopel worden gebracht.", "b1490892"]},
"OLAYLAR_EK5:1516-09-26:0":{"b": ["Tripoli (Trablusşam) en Hama kwamen onder Osmaans bestuur", "a1e19a79"], "d": ["Na Aleppo en Hama ging ook Tripoli aan de Syrische kust zonder verzet over naar Osmaans bestuur. De stad, een van de drukste havens van de oostelijke Middellandse Zee, was de poort van Damascus naar de zee en het centrum van de handel in zijde en suiker. Met de inname wisselde de kuststrook van Bilâdüşşâm volledig van hand.", "57168655"]},
"OLAYLAR_EK5:1516-09-27:0":{"b": ["Damascus kwam onder Osmaanse heerschappij", "2b844d91"], "d": ["Nadat de overgave van Hama en Homs hem de weg had geopend, bereikte Yavuz Sultan Selim op 27 september na Aleppo de stad Damascus; hij trok niet meteen de stad in maar sloeg buiten, op de plek Mastaba, zijn tent op en trok op de twaalfde dag na zijn aankomst met een grote ceremonie binnen. Hij verbleef lang in Damascus en vestigde de bestuurlijke orde van Syrië en liet het graf van Muhyiddin Ibn al-Arabi bouwen. Zo kwam heel Bilâdüşşâm uit het Mamelukse bestuur. Andere plaatsen die op dezelfde datum werden toegevoegd: Beiroet.", "7cd1cd2b"]},
"OLAYLAR_EK5:1516-10-10:0":{"b": ["Tumanbay uitgeroepen tot Mamelukse sultan in Caïro", "6020d90d"], "d": ["Na de dood van Qansuh al-Ghawri bij Marj Dabiq zetten de Mamelukse emirs Tumanbay, de laatste sultan van de staat, op de troon. De nieuwe sultan van Circassische afkomst nam een staat over die Syrië had verloren, wiens schatkist was uitgeput en die geen vuurwapens had. Toch zou hij door een verdedigingslinie voor Caïro op te zetten een laatste verzet tegen de Osmaanse opmars organiseren.", "c55b45e9"]},
"OLAYLAR_EK5:1516-12-21:0":{"b": ["Slag bij Gaza (Khan Yunis): nederlaag van Janbirdi al-Ghazali", "9f1eb8cb"], "d": ["Yavuz Sultan Selim zond grootvizier Hadım Sinan Pasja met een voorhoede van vierduizend man naar Gaza. Janbirdi al-Ghazali, door Tumanbay benoemd tot gouverneur van Damascus, probeerde de Osmaanse voorhoede op de lijn Gaza–Khan Yunis tegen te houden maar leed een zware nederlaag en vluchtte naar Egypte. Met het uiteenvallen van de laatste Mamelukse bufferstrijdmacht in Palestina lag de weg naar de Sinaïwoestijn volledig open.", "042a934e"]},
"OLAYLAR_EK5:1516-12-28:0":{"b": ["Ten oosten van de Jordaan: Amman kwam onder Osmaans bestuur", "9db62667"], "d": ["Terwijl de Osmaanse strijdkrachten, die zich na de slag bij Gaza op de Egyptische veldtocht voorbereidden, naar het zuiden trokken, kwam ook Amman ten oosten van de Jordaan onder Osmaans bestuur. De kust- en binnensteden van Palestina (Jaffa, Nablus, Sidon, Akko, Jeruzalem) waren in de herfst van 1516 na Marj Dabiq al van hand gewisseld. Deze steden werden vier eeuwen lang als sandjaks van de provincie Damascus bestuurd.", "fac75355"]},
"OLAYLAR_EK5:1516-12-29:0":{"b": ["Komst van Yavuz Sultan Selim naar Jeruzalem", "66d7bfad"], "d": ["De sultan kwam na de slag bij Gaza met de notabelen van de staat en de soldaten naar Jeruzalem, dat na Marj Dabiq zonder verzet onder Osmaans bestuur was gekomen. De sultan bezocht de Rotskoepel en de Al-Aqsa-moskee en bevestigde de heilige status van de stad. Jeruzalem zou vanaf deze datum tot december 1917 vier eeuwen onder Osmaans bestuur blijven.", "42cf2ec1"]},
"OLAYLAR_EK5:1517-01-02:0":{"b": ["Intocht van Yavuz Sultan Selim in Gaza en oriëntatie op de Sinaïwoestijn", "2106bfc7"], "d": ["Na de nederlaag van Janbirdi al-Ghazali bij Khan Yunis (21 december 1516) was Gaza in handen van de voorhoede. De sultan trok op 2 januari 1517 Gaza binnen, waar hij Sinan Pasja, de aanvoerder van de voorhoede, ontmoette en het leger de laatste voorbereidingen trof voor de oversteek naar Egypte. In de waterloze Katya-woestijn (Sinaï) die zich uitstrekt van Gaza tot Salihiya zou acht dagmarsen worden gelopen en water met kamelen worden vervoerd. Deze oversteek is de meest riskante en logistiek moeilijkste fase van de veldtocht.", "5c3d7bc1"]},
"OLAYLAR_EK5:1517-01-24:0":{"b": ["Inname van Suez — poort naar de Rode Zee", "05f3324e"], "d": ["Na de overwinning bij Ridaniya, toen de Osmaanse troepen Caïro binnentrokken, kwam ook Suez aan het noordelijke uiteinde van de Rode Zee onder Osmaans bestuur. Deze scheepswerf-haven, vanwaar de Mamelukken vloten naar de Indische Oceaan stuurden, werd de basis van de zuidelijke politiek die tegen Portugal zou worden gevoerd. Suez is de noordelijke monding van de lijn waar drie eeuwen later het kanaal zou worden geopend.", "501facb1"]},
"OLAYLAR_EK5:1517-01-24:1":{"b": ["Eerste intocht van Osmaanse troepen in Caïro", "0a3f4f4d"], "d": ["Op de dag na de overwinning bij Ridaniya mochten de Osmaanse legers Caïro binnentrekken en op 24 januari vestigden de troepen zich in de stad. Deze intocht betekende echter niet de volledige controle over de stad; Tumanbay had zich teruggetrokken in Boven-Egypte en het Mamelukse verzet was nog niet gebroken. De verovering van Caïro zou niet in één dag, maar in een bloedig proces van weken worden voltooid.", "32d9401c"]},
"OLAYLAR_EK5:1517-01-27:0":{"b": ["Overval van Tumanbay op Caïro en drie dagen durende straatgevechten", "b83b6ce6"], "d": ["Tumanbay, die zich had teruggetrokken in Boven-Egypte, trok in de nacht van 27-28 januari met ongeveer zevenduizend man plotseling Caïro binnen en begon verzet in de stad, waardoor de Osmaanse troepen in een uiterst moeilijke positie kwamen. In de drie dagen durende hevige straatgevechten hielden de Mamelukken tijdelijk het grootste deel van de stad in handen. Het verzet kon pas worden gebroken doordat de Osmaanse artillerie en versterkingen ingrepen.", "98838d21"]},
"OLAYLAR_EK5:1517-02-08:0":{"b": ["Janbirdi al-Ghazali trad in Osmaanse dienst", "a94ea459"], "d": ["Janbirdi al-Ghazali, de voormalige Mamelukse emir die zich na Ridaniya had teruggetrokken in Salihiya, wendde zich tot de sultan en vroeg om genade. Yavuz Sultan Selim nam hem in zijn dienst, omdat hij dacht dat hij nuttig zou zijn bij het vestigen van de openbare orde in Egypte en Syrië. Deze keuze is het eerste grote voorbeeld van de Osmaanse politiek om Mamelukse kaders in het stelsel op te nemen in plaats van ze te liquideren.", "847c1e81"]},
"OLAYLAR_EK5:1517-02-15:0":{"b": ["Plechtige intocht van Yavuz Sultan Selim in Caïro en het lezen van de khutba", "6d98080c"], "d": ["Na het neerslaan van de straatgevechten trok de sultan op 15 februari 1517 in een zeer luisterrijke ceremonie Caïro binnen en in de moskeeën werd de khutba in zijn naam gelezen. Het lezen van de khutba in Caïro in naam van de Osmaanse sultan is de afkondiging dat de sinds 1250 durende Mamelukse heerschappij juridisch was beëindigd. Deze datum geldt als het symbolische moment van voltooiing van de feitelijke verovering van Egypte.", "3f8589a3"]},
"OLAYLAR_EK5:1517-03-30:0":{"b": ["Gevangenneming van de laatste Mamelukse sultan Tumanbay in Terrûce", "7058e6ad"], "d": ["Tumanbay, die zich na het verlaten van Caïro in de Nijldelta had verborgen, werd door de bedoeïenen die hem onderdak boden verraden en gevangengenomen in de streek Terrûce. Zijn gevangenneming nam het georganiseerde centrum van het Mamelukse verzet weg. De laatste sultan zou hierna veertien dagen in Osmaanse handen worden gehouden.", "5fc98f13"]},
"OLAYLAR_EK5:1517-04-13:0":{"b": ["Executie van Tumanbay bij Bab Zuweila en einde van de Mamelukkenstaat", "ad9820be"], "d": ["Veertien dagen na zijn gevangenneming werd Tumanbay opgehangen bij Bab Zuweila, de beroemde poort van Caïro; zijn lichaam werd later begraven in de madrasa die zijn oom had laten bouwen. Zo verdween de Mamelukkenstaat, die sinds 1250 over Egypte en Syrië heerste, formeel uit de geschiedenis. Met het breken van het verzet werden ook steden in Boven-Egypte (Sa'id) zoals Asyut en Aswan aan het Osmaanse bestuur gebonden.", "96555946"]},
"OLAYLAR_EK5:1517-04-18:0":{"b": ["Aanval van de Portugese vloot op Jeddah en verdediging door Selman Reis", "52322cf5"], "d": ["De Portugese vloot, bestaande uit een dertigtal galeien en galjoenen, viel Jeddah aan; Selman Reis leidde de verdediging van de stad, verhinderde dat de vijand aan land ging en liet enkele Portugese schepen zinken. Deze verdediging voorkwam dat de haven van Mekka en daarmee de pelgrimsroute in handen van een christelijke staat viel. Jeddah zou enkele maanden later met de bay'a van de Hidjaz formeel bij het Osmaanse bestuur worden gevoegd.", "a480f1f5"]},
"OLAYLAR_EK5:1517-05-19:0":{"b": ["Alexandrië overgenomen met de vloot — voltooiing van de verovering van Egypte", "386878fe"], "d": ["Precies vier maanden na Ridaniya en zesendertig dagen na de executie van Tumanbay ging Alexandrië over naar Osmaans bestuur met de komst van de Osmaanse vloot onder bevel van Câfer Bey in de haven; ook de deltahavens Rosetta en Damietta werden in hetzelfde proces gebonden. Dat deze grote haven van Egypte aan de Middellandse Zee maanden na de val van Caïro en niet over land maar over zee werd overgenomen, toont duidelijk dat de verovering niet met één slag maar regio na regio werd voltooid. Alexandrië zou hierna de vitale haven worden die Constantinopel en Caïro verbond. Andere plaatsen die op dezelfde datum werden toegevoegd: Reşîd (Rosetta).", "52187c14"]},
"OLAYLAR_EK5:1517-07-06:0":{"b": ["Aansluiting van de Hidjaz zonder strijd: bay'a van Abû Numayy, zoon van de sjerief van Mekka", "c13b98c7"], "d": ["Yavuz Sultan Selim had eerst overwogen troepen te sturen voor de inname van Mekka en omgeving, maar had daarvan afgezien toen de emir van Mekka, sjerief Barakat, zijn gehoorzaamheid meedeelde. Barakats twaalfjarige zoon Abû Numayy kwam met de geschenken van zijn vader en de sleutels van Mekka naar Caïro en werd door de sultan ontvangen. Zo werd de Hidjaz niet als automatisch gevolg van Ridaniya, maar vijfenhalve maand later en zonder dat er één schot werd gelost, vreedzaam en door middel van bay'a bij de Osmanen gevoegd. Andere plaatsen die op dezelfde datum werden toegevoegd: Ta'if.", "636183e3"]},
"OLAYLAR_EK5:1517-07-12:0":{"b": ["Aanvaarding van de titel Hâdimü'l-Haremeyn en khutba in Medina", "63b32b59"], "d": ["Na de tweede ontvangst van de delegatie uit Mekka nam Yavuz Sultan Selim formeel de bescherming van de Haramain op zich en begon hij de titel 'hâdimü'l-Haremeyni'ş-şerîfeyn' (dienaar van de twee heilige steden) te gebruiken. Sjerief Barakat trok de hem gezonden eregewaad aan en liet de khutba in naam van de sultan lezen; toen ook de delegatie uit Medina naar Constantinopel ging, werd het emiraat van Barakat bij berat bevestigd. De sultan zond tweehonderdduizend gouden munten en veel proviand naar de bevolking van de Haramain en startte zo de traditie van de surre, die elk jaar zou worden herhaald. Andere plaatsen die op dezelfde datum werden toegevoegd: Yanbu, Tabuk.", "3b3bfd8f"]},
"OLAYLAR_EK5:1517-08-28:0":{"b": ["Selman Reis trad in Osmaanse dienst en overdracht van de Rode Zee-politiek", "771da99a"], "d": ["Selman Reis, die Jeddah tegen de Portugezen had verdedigd, kwam naar Caïro en verscheen voor Yavuz Sultan Selim; hoewel hij enige tijd werd vastgehouden, werd hij in 1519 naar Constantinopel geroepen en beloofde dertig galeien en enkele galjoenen gereed te maken tegen de Portugese dreiging. Deze ontmoeting is het begin van het overnemen van de Rode Zee- en Indische Oceaan-politiek uit de Mamelukse erfenis en het rechtstreeks aan Constantinopel binden ervan. De Osmanen waren nu naast een Middellandse Zeestaat ook een macht met een oceaanpolitiek.", "c87580bd"]},
"OLAYLAR_EK5:1517-09-10:0":{"b": ["Vertrek van Yavuz Sultan Selim uit Caïro en beylerbeylik van Hayır Bey", "8cd4fb23"], "d": ["Yavuz Sultan Selim, die ongeveer acht maanden in Egypte bleef en er de bestuurlijke, financiële en militaire orde vestigde, verliet Caïro; Hayır Bey, de voormalige naib van Aleppo die bij Marj Dabiq de linkerflank terugtrok en zo de Mamelukse ondergang versnelde, begon als eerste Osmaanse beylerbey van Egypte te besturen vanuit de Citadel. De keuze van een gouverneur van Mamelukse afkomst was een bewust overgangsbeleid om ervoor te zorgen dat het nieuwe bestuur de lokale bevolking niet vreemd zou voorkomen. De sultan nam op de terugweg de laatste Abbasidische kalief Mutawakkil III en de uitgelezen kunstenaars en geleerden van Egypte mee naar Constantinopel.", "c2b3bc7e"]},
"OLAYLAR_EK5:1517-09-11:0":{"b": ["Einde van het Abbasidische kalifaat van Caïro — verhaal van de 'overdrachtsceremonie'", "1d357640"], "d": ["Toen Yavuz Sultan Selim Egypte innam, bracht hij de laatste kalief Mutawakkil III al-Allah, die bij Marj Dabiq was gevangengenomen, mee naar Constantinopel; zo kwam een einde aan het Abbasidische kalifaat van Caïro, dat sinds 1261 zonder gezag in de schaduw van de Mamelukse sultans had voortbestaan. Het beroemde verhaal dat het kalifaat in de Hagia Sophia in een officiële ceremonie aan Yavuz werd overgedragen, komt echter voor het eerst voor aan het einde van de 18e eeuw in het werk van d'Ohsson en staat in geen enkele bron uit de tijd van Yavuz. De TDV İslâm Ansiklopedisi beschouwt het verhaal als verzonnen omdat er geen oorspronkelijke bron is die de ceremonie documenteert; maar zij vermeldt ook dat voor de overgang van het kalifaat naar de sharia geen dergelijke overdrachtsceremonie nodig was.", "86efdf28"]},
"OLAYLAR_EK5:1518-01-01:0":{"b": ["Erzurum bij het Osmaanse bestuur gevoegd — Safawidische invloed in Oost-Anatolië gebroken", "78d1be02"], "d": ["Hoewel de Osmaanse invloed in de regio na de overwinning bij Çaldıran (1514) toenam, werd de volledige inname van Erzurum uitgesteld tot de Iraanse invloed was gebroken; de stad werd pas na de Egyptische veldtocht in 1518-19 bij het Osmaanse bestuur gevoegd. Erzurum was in 1502, toen Sjah Ismail een einde maakte aan het Akkoyunlu-beylik, onder Safawidische heerschappij gekomen; deze periode van zestien jaar was zo gesloten. In 1534 zou tijdens de Irakeyn-veldtocht het beylerbeylik van Erzurum worden gesticht. In 1518-1519 werd samen met de regio Erzurum ook Aşkale bij het Osmaanse bestuur gevoegd (dag niet bevestigd).", "41e2822f"]},
"OLAYLAR_EK5:1519-03-01:0":{"b": ["Begin van de Celali-opstanden: opstand van Bozoklu Sjeik Celal", "99bd8a99"], "d": ["In de streek Bozok kondigde een man genaamd Sjeik Celal zijn mahdi-schap af en kwam in opstand rond Tokat; hoewel de opstand werd neergeslagen, werd zijn naam een eeuw lang de naam van alle bandietenbewegingen en opstanden in Anatolië. Het Celalisme veranderde, gecombineerd met het uiteenvallen van het timar-stelsel en de bevolkingsdruk aan het einde van de 16e eeuw, in het langstdurende interne veiligheidsprobleem van het rijk. De opstanden leidden in Anatolië tot massale migraties die 'de grote vlucht' (büyük kaçgunluk) werden genoemd.", "ec33f73b"]},
"OLAYLAR_EK5:1519-09-01:0":{"b": ["Aansluiting van Algiers bij de Osmaanse staat", "b8eba4c1"], "d": ["Hayreddin Reis, die in Noord-Afrika tegen de Spaanse druk weerstand bood, wendde zich om stand te kunnen houden tot Constantinopel en bood Algiers aan de sultan aan; de khutba werd in naam van Yavuz Sultan Selim gelezen. Zo werd Algiers formeel bij het Osmaanse grondgebied gevoegd en werden aan Hayreddin soldaten en kanonnen gezonden met de titel van beylerbey. Deze aansluiting legde de basis van de eeuwenlange Osmaanse zeeheerschappij in de westelijke Middellandse Zee. Andere plaatsen die op dezelfde datum werden toegevoegd: Constantine, Cherchell (Şerşel), Médéa (Titteri), Sétif.", "42dac5d2"]},
"OLAYLAR_EK5:1520-09-21:0":{"b": ["Overlijden van Yavuz Sultan Selim in Çorlu", "9fe83744"], "d": ["Selim I, die het grondgebied van de staat in acht jaar meer dan verdubbelde, vertrok op 18 juli 1520 uit Constantinopel voor een nieuwe veldtocht; door een grote gezwel op zijn rug kon hij niet verder dan Çorlu. Ondanks ingrijpen van de artsen verergerde zijn ziekte en na een hopeloze behandeling van twee maanden stierf hij hier op 8-9 Shawwal 926 (21-22 september 1520). Met Çaldıran, Marj Dabiq en Ridaniya had hij Iran tegengehouden en de Mamelukkenstaat opgeheven en het kalifaat en het beschermheerschap over de Haramain naar de Osmanen gebracht. Hij liet één zoon na: Süleyman.", "39cccc63"]},
"OLAYLAR_EK5:1521-01-01:0":{"b": ["Het eiland Ikaria (Nikarya) kwam onder Osmaans bestuur", "6afa972b"], "d": ["Ikaria tussen Samos en Chios stond van 1481 tot 1521 onder het bestuur van de Sint-Jansridders van Rhodos; de eerste Osmaanse periode op het eiland begon in 1522 en duurde tot 1822. In deze periode was de kaymakam verantwoordelijk voor het innen en betalen van belastingen; zoals op de andere Egeïsche eilanden bleef ook de lokale raad van ouderen (demogerontia) bestaan en kwam soms in botsing met het Osmaanse bestuur.", "7c6cc486"]},
"OLAYLAR_EK5:1522-01-01:0":{"b": ["Annexatie van het land Dulkadir — provincie Dulkadir met Maraş als centrum", "595c3c30"], "d": ["Het land Dulkadir, dat na de nederlaag bij Turnadağ in 1515 als aan de Osmanen onderworpen beylik was blijven bestaan, werd na de moord op Şehsuvaroğlu Ali Bey met zijn kinderen in Artukova rechtstreeks bij het Osmaanse grondgebied gevoegd en omgevormd tot een provincie met Maraş als centrum. De regio Bozok van het beylik werd als afzonderlijke sandjak aan het Osmaanse bestuur gebonden. Zo werd de ongeveer tweehonderd jaar durende Dulkadır-periode van Maraş, Elbistan, Göksun, Gürün, Zamantı en Darende gesloten; het bufferbeylik aan de Mamelukse grens verdween volledig.", "9b819db9"]},
"OLAYLAR_EK5:1522-05-29:0":{"b": ["Verovering van Knin", "a46d3117"], "d": ["Met de strooptochten van Bosnië-sandjakbey Gazi Hüsrev Bey in de jaren 927-928 (1521-1522) kwamen een reeks Venetiaanse burchten, met name Knin, Skradin en Ostrovica, onder Osmaans bestuur; de grens werd voorbij de tweede bergketen geduwd. Deze keten van veroveringen legde de basis van de sandjak Dalmatië, die vijftien jaar later met de inname van Klis zou worden voltooid.", "21f9fbd5"]},
"OLAYLAR_EK5:1523-01-05:0":{"b": ["Terugtrekking van de ridders: overdracht van Bodrum, Kos en de Dodekanesos", "ea01666e"], "d": ["Krachtens de overgavevoorwaarden van Rhodos ontruimden de Sint-Jansridders niet alleen het centrum van het eiland maar alle posities die zij twee eeuwen lang in handen hadden gehad. De burcht Bodrum (Saint Pierre) aan de Anatolische kust en de eilanden Kos, Kalymnos en Leros gingen zo zonder gevecht over naar Osmaans bestuur. Met deze overdracht, die twee weken na de val van Rhodos werd voltooid, kwam aan de zuidoostelijke hoek van de Egeïsche Zee de Latijnse aanwezigheid volledig ten einde.", "bcbe8fa8"]},
"OLAYLAR_EK5:1524-01-01:0":{"b": ["Opstand van Hain Ahmed Pasja in Egypte", "b18bb805"], "d": ["Ahmed Pasja, die in afwachting van het grootvizierschap naar het gouverneurschap van Egypte was gestuurd, riep zich in Caïro uit tot 'al-Malik al-Mansur Sultan Ahmed' en maakte zijn onafhankelijkheid bekend. De opstand werd snel neergeslagen en de pasja gedood, maar het voorval toonde de kwetsbaarheid van de centrale controle in de rijkste provincie van het rijk. Daarop ging İbrahim Pasja naar Egypte en liet de beroemde Egyptische Kanunname opstellen, die het bestuur van de provincie opnieuw regelde.", "35eb542c"]},
"OLAYLAR_EK5:1528-01-01:0":{"b": ["Annexatie van Noord-Bosnië: Jajce en Banja Luka", "8ec86cfa"], "d": ["Toen de Hongaarse verdedigingslinie na Mohács instortte, trok de sandjakbey van Bosnië, Gazi Hüsrev Bey, de Vrbasvallei in en nam de laatste Bosnische burchten in die het Hongaarse koninkrijk nog in handen had. Met de val van Jajce en Banja Luka reikte de provincie Bosnië in het noorden tot de rivier de Sava en ontstond het Kroatische front. Banja Luka werd al snel het tweede centrum van de provincie.", "1f634005"]},
"OLAYLAR_EK5:1529-09-08:0":{"b": ["Inname van Boeda en overdracht aan Szapolyai", "fba4f89b"], "d": ["Op weg naar de veldtocht naar Wenen belegerde het Osmaanse leger Boeda, dat in handen van Ferdinand was gekomen, nam het terug en droeg de stad over aan János Szapolyai, de Hongaarse koning onder Osmaanse bescherming. Zo werd over Hongarije het model van een vazalkoninkrijk als buffer in de Habsburgs-Osmaanse rivaliteit gevestigd. Deze orde zou tot 1541 duren; na de dood van Szapolyai zou Boeda rechtstreeks een Osmaanse provincie worden.", "6777eb1d"]},
"OLAYLAR_EK5:1532-04-25:0":{"b": ["Süleyman trok ten strijde naar Duitsland — uitdaging aan Karel V", "7c3d7055"], "d": ["Nadat het beleg van Wenen zonder resultaat was gebleven en Ferdinand Boeda opnieuw had belegerd, vertrok de sultan ditmaal uit Constantinopel om keizer Karel V rechtstreeks tot een veldslag te dwingen. Het leger zou in augustus worden opgehouden door het verzet van de kleine burcht Güns en omdat de keizer niet ten strijde trok, zou de veldtocht beperkt blijven tot strooptochten. De veldtocht bereidde de bodem voor de eerste vrede met de Habsburgers een jaar later.", "c3e6e378"]},
"OLAYLAR_EK5:1532-08-05:0":{"b": ["Duitse veldtocht en beleg van Güns (Kőszeg)", "8aec937a"], "d": ["Süleyman trok met zijn leger tegen Oostenrijk op om Karel V tot een veldslag te dwingen; de kleine burcht Güns bood vijfentwintig dagen weerstand en vertraagde de opmars van het leger. Toen de keizer niet ten strijde trok, sloegen de ruiters toe rond Wenen en werd, door het voortschrijden van het seizoen, teruggekeerd. De veldtocht leverde geen gebiedswinst op, maar bracht de Habsburgers aan de onderhandelingstafel en bereidde de bodem voor de vrede van het jaar daarop.", "792fc40e"]},
"OLAYLAR_EK5:1533-01-01:0":{"b": ["Verdrag van Constantinopel — eerste vrede met de Habsburgers", "b085767a"], "d": ["De sultan, die Ferdinands gezant Cornelius ontving, stemde in met een wapenstilstand en zo ontstond de eerste officiële vredestekst tussen de Osmanen en Oostenrijk. Met het verdrag aanvaardde Ferdinand voor de Hongaarse gebieden die hij in handen had jaarlijks belasting te betalen en de Oostenrijkse aartshertog werd in het protocol als gelijke van de grootvizier beschouwd. Deze ongelijke status was de duidelijke uitdrukking van de Osmaanse aanspraak op superioriteit in de 16e eeuw.", "e51c434d"]},
"OLAYLAR_EK5:1534-06-01:0":{"b": ["Inname van Kars en opening van de noordoostelijke grens", "742e3101"], "d": ["Terwijl de voorhoede van de Irakeyn-veldtocht vanuit Erzurum naar het oosten trok, werd de burcht Kars, die in handen van het Georgische atabegaat was en sinds Timur in puin lag, zonder verzet overgenomen. Omdat de stad de pas tussen de boog van de Aras en Çıldır bewaakte, gold zij als de sleutel van de noordelijke poort naar Iran. Deze winst werd de eerste schakel van het beylerbeylik Kars en de Kaukasuslijn die dertig jaar later zou worden gesticht.", "b3a27cc8"]},
"OLAYLAR_EK5:1534-07-13:0":{"b": ["Eerste intocht in Tabriz — opening van de Irakeyn-veldtocht", "cf7ed4e3"], "d": ["İbrahim Pasja, die als serdar-ı ekrem vooruit trok, trok Tabriz, de Safawidische hoofdstad, zonder verzet binnen toen sjah Tahmasp een veldslag vermeed en zich terugtrok in het binnenland. Süleyman bereikte de stad in september; maar door het invallen van de winter en de te lange bevoorradingslijn trok het leger in de richting van Bagdad en kon Tabriz lange tijd niet worden gehouden. De stad, die na Çaldıran voor de tweede keer werd ingenomen, werd de plaats waar de Osmanen leerden dat in het oosten veroveren gemakkelijk, maar behouden moeilijk was.", "a303a9e4"]},
"OLAYLAR_EK5:1534-09-22:0":{"b": ["Verovering van Tunis door Barbarossa", "d8754216"], "d": ["Kapudan pasja Barbaros Hayreddin Pasja trok, na met zijn vloot de kust van Italië te hebben geraakt, naar Tunis, joeg de Hafsidische heerser Mulay Hasan op de vlucht en trok de stad binnen. De inname van Tunis keerde met zijn positie, die de Straat van Sicilië controleerde, het machtsevenwicht in de westelijke Middellandse Zee in één klap in het voordeel van de Osmanen. Deze heerschappij zou echter niet lang duren en Karel V zou het jaar daarop met een grote vloot antwoorden.", "b0aeb30e"]},
"OLAYLAR_EK5:1535-07-21:0":{"b": ["Verlies van Tunis aan Karel V", "a691f0f8"], "d": ["Karel V nam, na met een grote veldtocht gesteund door de Genuese en pauselijke vloten La Goulette te hebben laten vallen, Tunis in en herstelde Mulay Hasan onder Spaanse bescherming op de troon. Met het vestigen van een Spaans garnizoen in de stad werd de Osmaanse opmars in de centrale Middellandse Zee tijdelijk gestopt. De definitieve verovering van Tunis zou pas veertig jaar later, in 1574, mogelijk zijn.", "cbb995cd"]},
"OLAYLAR_EK5:1536-01-01:0":{"b": ["Campagne van Gazi Hüsrev Bey langs de Sava: Bosanski Brod en Jasenovac", "3740ec83"], "d": ["Na de inname van Jajce en Banja Luka in 1528 bleven de burchten langs de rivier de Sava nog enige tijd in de Kroatisch-Slavonische grens die aan de Habsburgse kroon was gebonden. Gazi Hüsrev Bey, die in 1536 voor de derde keer sandjakbey van Bosnië werd, nam in hetzelfde jaar Požega en omgeving in en voegde ook de burchten Brod en Jasenovac aan de Sava bij het Osmaanse bestuur. Zo reikte de noordgrens van Bosnië tot de Sava; de regio werd twee jaar later voltooid met de inname van Dubica.", "415f0592"]},
"OLAYLAR_EK5:1536-03-15:0":{"b": ["Executie van Makbul İbrahim Pasja", "348aa7b8"], "d": ["İbrahim Pasja, die dertien jaar grootvizier was, de beste vriend van Süleyman en feitelijk de tweede man van de staat, werd in het paleis waar hij voor het iftar was uitgenodigd, zonder enige reden te noemen gewurgd en geëxecuteerd. Zijn houding in de Irakeyn-veldtocht, het gebruik van de titel 'serasker sultan' en de evenwichten binnen het paleis worden als factoren in zijn dood beschouwd. De executie is een keerpunt dat toont dat de grootviziers in het Osmaanse centrale bestuur geen absolute veiligheid hadden.", "a780f3de"]},
"OLAYLAR_EK5:1537-03-12:0":{"b": ["Verovering van de burcht Klis en stichting van de sandjak Dalmatië", "6ffd4ebf"], "d": ["Murad Bey, de kethüda van Gazi Hüsrev Bey, een bekeerling van Kroatische afkomst, nam de strategische burcht Klis, vlak ten noorden van Split, van Venetië in. Onmiddellijk na de verovering werd Klis het centrum van een nieuwe sandjak en kaza die zijn omgeving omvatte; de grenzen van deze sandjak trokken grotendeels het kader van Osmaans Kroatië. Deze verovering, die vijftien jaar na Knin kwam, voltooide het bestuurlijke skelet van het binnenland van Dalmatië.", "8338f8aa"]},
"OLAYLAR_EK5:1537-08-25:0":{"b": ["Beleg van Korfoe en oorlog met Venetië", "11af95bd"], "d": ["Na de Apulische veldtocht landde het Osmaanse leger op Korfoe en belegerde de sterke Venetiaanse burcht van het eiland. Door de steile structuur van de burcht, zware verliezen en de seizoensomstandigheden werd de blokkade op 6 september opgeheven en trok men zich terug. Hoewel het beleg zonder resultaat bleef, resulteerde de oorlog die met Venetië werd geopend in de aansluiting van talrijke eilanden in de Egeïsche en Adriatische Zee bij de Osmanen en de overwinning bij Preveza het jaar daarop.", "f023c2b9"]},
"OLAYLAR_EK5:1537-10-01:0":{"b": ["Egeïsche veldtocht van Barbarossa: inname van de rechtstreeks door Venetië bestuurde eilanden", "1b32ed96"], "d": ["De vloot, die terugkeerde van het beleg van Korfoe, nam gebruik makend van het feit dat Venetië de oorlog was verklaard in de Egeïsche Zee de eilanden die niet aan het hertogdom maar rechtstreeks aan Venetië waren gebonden een voor een over. Aegina werd na hevig verzet ingenomen, Astypalaia, dat in handen van de familie Querini was, Karpathos en Kasos gaven zich over, ook Patmos, dat onder kloosterbestuur stond, aanvaardde de Osmaanse bescherming. Het Hertogdom Naxos werd daarentegen schatplichtig gemaakt en op zijn plaats gelaten; de annexatie ervan zou tot 1566 moeten wachten.", "632f4747"]},
"OLAYLAR_EK5:1538-08-01:0":{"b": ["Noord-Egeïsche veldtocht van Barbarossa: inname van Skyros en de Noordelijke Sporaden", "20ab688e"], "d": ["Op weg naar Preveza nam de vloot de Noord-Egeïsche eilanden, die sinds de verovering van Constantinopel bij Venetië onderdak hadden gezocht, een voor een over. Skyros ten noorden van Euboea en Skiathos, Skopelos en Alonissos, die de ingang van de Golf van Thessaloniki bewaken, kwamen zo onder Osmaans bestuur. Deze eilanden sloten het laatste Noord-Egeïsche gat dat, hoewel Negroponte in 1470 was ingenomen, nog achtenzestig jaar in Venetiaanse handen was gebleven.", "2a9ea08f"]},
"OLAYLAR_EK5:1538-08-03:0":{"b": ["Inname van Aden en annexatie van de Jemenitische kust", "e7d46d8f"], "d": ["De vloot die voor de Indische veldtocht uit Suez vertrok, richtte zich eerst op de Jemenitische kust, omdat men zonder veiligstelling van de Rode Zee de oceaan niet op kon. Hadım Süleyman Pasja voer op 3 augustus 1538 de haven van Aden binnen; de Tahiridische heerser Amir b. Dawud, die naar de Portugezen neigde, werd bij de kapudan gebracht en geëxecuteerd en in de stad werd een bezetting van 500 man achtergelaten. Tijdens dezelfde veldtocht werden ook Mocha en de eilanden Kamaran en Farasan, die de zeestraat beheersen, overgenomen en de basis gelegd voor het beylerbeylik van Jemen. Zo bezat de Osmaanse staat voor het eerst de gehele noordkust van de Bab-el-Mandeb; Sanaa en het binnenland moesten nog negen jaar wachten.", "495e1991"]},
"OLAYLAR_EK5:1538-09-01:0":{"b": ["Moldavische veldtocht en annexatie van het gebied Bucak (Bender)", "90a88a56"], "d": ["In de veldtocht tegen de Moldavische woiwode Petru Rareş, die zijn Osmaanse verplichtingen niet nakwam, werd Suceava ingenomen en werd de stad Iași door de Krim-khan Sâhib Giray geplunderd. De sultan benoemde Stefan Lăcustă tot woiwode en voegde samen met Bender het gebied Bucak (Zuid-Bessarabië) rechtstreeks bij het Osmaanse grondgebied. Deze annexatie werd een van de schakels die de noordwestelijke kusten van de Zwarte Zee in een Osmaanse binnenzee veranderden. Moldavië was al een aan de Osmanen onderworpen woiwodschap; deze veldtocht nam geen grondgebied af van een buitenlandse staat, maar nam alleen het interne bestuur van Bender en Bucak van de woiwode af en bond het rechtstreeks aan de sultan; de rest van het woiwodschap behield zijn vazalstatus. Dezelfde structuur zou in 1484 in Kilia en Akkerman en in 1713 in Hotin worden herhaald: grensburchten rechtstreeks, binnenlanden vazal.", "96376de1"]},
"OLAYLAR_EK5:1540-11-01:0":{"b": ["Overname van Nauplion bij verdrag", "104d0937"], "d": ["De drie jaar durende Venetiaanse oorlog na Preveza eindigde toen de republiek instemde met het afstaan van haar laatste twee burchten in de Morea. Nauplion en Monemvasia (Benefşe), die niet door beleg konden worden ingenomen, werden naast een oorlogsvergoeding van driehonderdduizend dukaten aan de onderhandelingstafel aan de Osmanen overgedragen. Het schiereiland Morea werd zo zodanig verenigd dat er geen enkele Venetiaanse voetafdruk overbleef.", "4a26ee03"]},
"OLAYLAR_EK5:1543-01-01:0":{"b": ["Szeged kwam onder Osmaans bestuur en vorming van de livâ Szeged", "019aa000"], "d": ["Nadat in 1541 het Osmaanse bestuur in Boeda volledig was gevestigd, aanvaardden de notabelen van Szeged de heerschappij van Ferdinand I en maakten zich op voor gewapende verdediging. De beylerbey van Boeda, Küçük Bâlî Pasja, liet begin 1543 de bestuurders van de stad bij zich roepen en wegens verraad executeren; daarna zond hij een eenheid om de stad in te nemen. Daarbij werd de livâ Szeged gevormd en werd Derviş Bey, de zoon van Bâlî Pasja, tot eerste sandjakbey benoemd; de livâ strekte zich aanvankelijk uit tussen de Donau en de Tisza.", "8293a839"]},
"OLAYLAR_EK5:1543-07-21:0":{"b": ["Verovering van Valpo, Šiklós en Pécs", "2ca030a3"], "d": ["Het eerste doel van de Hongaarse veldtocht, twee jaar na de annexatie van Boeda, was de zuidflank van de nieuwe provincie tussen de Drava en de Donau veilig te stellen. Nadat de burchten Valpo en Šiklós waren ingenomen, gaf Pécs, het centrum van Baranya, zich over. De stad zou het drukst bevolkte en best opgebouwde centrum van Osmaans Hongarije worden en de historicus İbrahim Peçuylu ontleende er zijn naam aan.", "aacf43d3"]},
"OLAYLAR_EK5:1543-08-10:0":{"b": ["Verovering van Esztergom en Székesfehérvár", "efca9e05"], "d": ["In de Hongaarse veldtocht die Süleyman persoonlijk leidde, kwam na een beleg van tweeënhalve week Esztergom, het religieuze centrum en aartsbisschopsstad van het Hongaarse koninkrijk, onder Osmaans bestuur. Daarna werd ook Székesfehérvár (İstolni Belgrad), de kroningsstad van de Hongaarse koningen, ingenomen en de verdedigingsgordel van de provincie Boeda voltooid. Esztergom zou tot 1595 als sleutelburcht van de Donaulijn in Osmaanse handen blijven.", "93577806"]},
"OLAYLAR_EK5:1544-09-01:0":{"b": ["Noordelijke en westelijke verdedigingsgordel van Boeda: Vác, Hatvan en Simontornya", "733ee5ce"], "d": ["Nadat Esztergom en Székesfehérvár waren ingenomen, trad de beylerbey van Boeda, zonder veldtocht van de sultan, in actie om de burchtenring rond de hoofdstad te voltooien. Vác aan de Donauknie, Hatvan, de poort van de Alföld, en Simontornya aan de lijn van de Sió werden een voor een overgenomen. De winsten van dit stille jaar veranderden Boeda van een grensstad in een provinciehoofdstad die honderdveertig jaar zou standhouden.", "0ca98fa3"]},
"OLAYLAR_EK5:1545-12-26:0":{"b": ["Annexatie van Basra en toegang tot de Perzische Golf", "02f87c11"], "d": ["Tijdens de verovering van Bagdad (1534) had Râşid b. Meğamis, de heerser van Basra, zijn gehoorzaamheid aan Süleyman betuigd en in 1538 de sleutels van de stad gezonden. Toen zijn opvolger sjeik Yahyâ zich tegen de Osmanen keerde, trok de beylerbey van Bagdad, Ayas Pasja, over land en de sandjakbey van Mosul met 120 schepen langs de Eufraat; Ayas Pasja trok op 26 december 1545 Basra binnen en de stad werd een beylerbeylik-centrum. Deze haven aan de monding van de Shatt al-Arab was de poort waarmee de Osmanen de Golf, die Portugal vanuit Hormuz controleerde, openden; met het Verdrag van Amasya in 1555 erkende ook Iran deze situatie.", "8905782c"]},
"OLAYLAR_EK5:1547-01-01:0":{"b": ["Verovering van Sanaa en het binnenland van Jemen", "d31ded85"], "d": ["Na Taiz werd ook Sanaa ingenomen en werd het hele land aan het beylerbeylik gebonden. Maar door de steile geografie en het verschil in geloofsrichting was deze heerschappij nooit gemakkelijk; Jemen werd voor de Osmanen een front dat voortdurend soldaten verslond.", "66968d6d"]},
"OLAYLAR_EK5:1547-02-01:0":{"b": ["Verovering van Taiz", "d4509df9"], "d": ["In Jemen, waar men negen jaar eerder tevreden was geweest met de kuststrook, trokken de strijdkrachten van Özdemir Pasja, omdat de Zaidi-imams in het bergachtige binnenland steeds sterker werden, naar de hooglanden en namen Taiz in.", "46b811eb"]},
"OLAYLAR_EK5:1547-06-19:0":{"b": ["Verdrag van Constantinopel — vijfjarige vrede met de Habsburgers", "41f81773"], "d": ["Tussen de Osmanen en de Habsburgers werd een vrede van vijf jaar ondertekend; Ferdinand aanvaardde voor de Hongaarse gebieden die hij in handen had jaarlijks 30.000 dukaten te betalen. Het verdrag bevestigde juridisch de feitelijke driedeling van Hongarije. Dat het westelijk front zo veiliggesteld was, gaf Süleyman de mogelijkheid nieuwe veldtochten tegen Iran te organiseren.", "36cfadaa"]},
"OLAYLAR_EK5:1548-07-27:0":{"b": ["Tweede Iraanse veldtocht en herovering van Tabriz", "e82365df"], "d": ["In de veldtocht die werd ondernomen op aanmoediging van Elqas Mirza, de broer van sjah Tahmasp, die tegen hem in opstand was gekomen en onderdak had gezocht in Constantinopel, trok het leger voor de tweede keer Tabriz binnen. Omdat de Safawiden opnieuw geen veldslag aangingen en zich terugtrokken onder het platbranden van het land, kon men slechts enkele weken in de stad blijven. De veldtocht maakte het zeker dat Tabriz niet gehouden kon worden en richtte de Osmaanse strategie op het vestigen van een blijvende grenslijn, namelijk het versterken van Van.", "bb2a7ceb"]},
"OLAYLAR_EK5:1548-08-24:0":{"b": ["Verovering van Van en vastlegging van de oostgrens", "fc8f930b"], "d": ["De burcht Van, die op de terugweg uit Tabriz werd belegerd, was met zijn ligging op de rots aan de oostkust van het meer onbetwist het slot van de regio en gaf zich na een kort beleg over. De stad werd onmiddellijk beylerbeylik-centrum; de sandjaks Erciş, Adilcevaz en Hakkâri werden eraan gebonden. In tegenstelling tot Tabriz werd Van behouden en bleef vier eeuwen lang de verste blijvende Osmaanse stelling in het oosten.", "3ca861b4"]},
"OLAYLAR_EK5:1550-01-01:0":{"b": ["Annexatie van Al-Hasa en Qatif — de Arabische kust van de Golf", "f6701e60"], "d": ["Na de inname van Basra werd Qatif, dat een voorpost van Portugal aan de westkust van de Golf was geworden, ingenomen en samen met de oases van Al-Hasa in het binnenland werd een nieuw beylerbeylik gesticht. Dit was het uitgangspunt van de campagnes naar Bahrein en Hormuz. De Osmaanse staat had zo tegelijkertijd zeggenschap aan zowel de Rode Zee- als de Perzische Golfkust van het Arabische schiereiland.", "240c0b43"]},
"OLAYLAR_EK5:1550-01-01:1":{"b": ["Verlies van Şehrizor — Ardalan-bey Sührâb neigde naar de Safawiden", "5600efc9"], "d": ["De streek Şehrizor, die tijdens de Irakeyn-veldtocht (1535) het Osmaanse bestuur had erkend, stond onder het bestuur van emir Bige Bey van Ardalan, die in de burcht Zalm zetelde. Na de dood van Bige Bey in 1550 nam zijn broer Sührâb de burcht Zalm in en nam de macht over het beylik over; hij wendde zich tot de Safawiden en brak met de gehoorzaamheid aan de Osmanen; zo kwam de streek Şehrizor buiten de Osmaanse invloed. De regio werd pas tijdens de Nachitsjevan-veldtocht in 1554 teruggewonnen met het belegeren en innemen van de burcht Zalm.", "62ddad8a"]},
"OLAYLAR_EK5:1551-01-01:0":{"b": ["Inname van Ardahan en het bekken van Çıldır", "14c9eb76"], "d": ["De beylerbey van Erzurum richtte zich tijdens de oorlog tegen de Safawiden op de gebieden van de Georgische atabegs aan de Kura-boog en bond Ardahan en de omgeving van Çıldır aan het Osmaanse bestuur. De lijn Kars–Ardahan werd zo aaneengesloten en de hooglanden die toegang geven tot Georgië in het noordoosten kwamen onder controle. De definitieve administratieve orde van de regio zou zevenentwintig jaar later worden voltooid met de provincie Çıldır.", "2f8d92cc"]},
"OLAYLAR_EK5:1551-09-07:0":{"b": ["Sokollu Mehmed Pasja stak de Donau over — begin van de Transsylvanische oorlog", "38fde931"], "d": ["Na de verwarring die werd veroorzaakt door de voogd van de Transsylvaanse koning János Zsigmond, de monnik Martinuzzi, en het afstaan door Transsylvanië van de burchten in het Banaat aan Ferdinand, werd een nieuwe veldtocht noodzakelijk geacht; het bevel werd gegeven aan de beylerbey van Rumelië, Sokollu Mehmed Pasja. Het leger stak ondanks de pogingen van Martinuzzi om tijd te rekken de Donau over en nam Becse, Becskerek, Csanád en Lippa in; maar het beleg van Temesvár werd op 16 november wegens de kou opgeheven. Zo was in Hongarije een nieuwe Osmaans-Habsburgse oorlog geopend.", "85071c5e"]},
"OLAYLAR_EK5:1552-07-27:0":{"b": ["Strijdkrachten uit Temesvár namen de palanka's van Zuid-Banaat in — Versec, Haram, Keve", "edca0921"], "d": ["Nadat Temesvár zich aan het Osmaanse leger had overgegeven, richtten de uit het beleggingsleger afgesplitste troepen zich op de kleine palanka's van het Banaat; volgens het verhaal van Bánlaky werden de palanka's Versec, Facset, Mehádia, Csákóvár, Haramvár en Keve door deze strijdkrachten ingenomen. Zo kwam ook Haram aan de Donau in Osmaanse handen.", "a5906d21"]},
"OLAYLAR_EK5:1552-09-04:0":{"b": ["Verovering van Szolnok en mislukking van het beleg van Eger", "a7156e8f"], "d": ["Na de inname van Temesvár namen de twee verenigde Osmaanse legers Szolnok aan de Tisza bijna zonder gevecht in doordat de huursoldaten de burcht verlieten. Daarna kon de burcht Eger, die vervolgens werd belegerd, niet worden ingenomen tegenover het achtendertig dagen durende verzet van het garnizoen van tweeduizend man onder bevel van István Dobó en trok het leger zich terug toen de winter inviel. Dat in dezelfde veldtocht de ene burcht gemakkelijk viel en de andere standhield, was het eerste duidelijke teken dat de grens in Hongarije niet meer vanzelf in het voordeel van de Osmanen opschoof.", "354ed31f"]},
"OLAYLAR_EK5:1553-02-01:0":{"b": ["Osmaans-Frans bondgenootschap — de Franse vloot onder Osmaans bevel", "a8e01b22"], "d": ["Met het verdrag van 1 februari 1553 werd de Franse vloot onder bevel van de Osmaanse vloot gesteld; gezamenlijk optreden tegen Spanje in de westelijke Middellandse Zee werd voorzien. Na het verdrag vertrok Turgut Reis op 15 juni 1553 met vijfenveertig galeien om Frankrijk te steunen. Dit was het eerste officiële bondgenootschapsverdrag dat de commerciële bodem van de capitulaties van 1536 naar militaire samenwerking bracht.", "bfa2fc2d"]},
"OLAYLAR_EK5:1553-10-05:0":{"b": ["Executie van prins Mustafa in Konya Ereğli", "dec36858"], "d": ["Prins Mustafa, die de tent van zijn vader binnenging om zich bij het voor de Nachitsjevan-veldtocht bijeengebrachte leger te voegen, kwam op het moment dat hij voor de sultan zou verschijnen de beulen tegen en werd gewurgd en gedood. De moord op de kroonprinskandidaat, die in het leger zeer geliefd was, wekte diepe woede onder de janitsaren en Rüstem Pasja werd uit het grootvizierschap gezet. Het voorval ging als een van de meest omstreden breuklijnen van de Osmaanse prinsenpolitiek de literatuur en het volksgeheugen in.", "ce2742ae"]},
"OLAYLAR_EK5:1555-01-01:0":{"b": ["Verschuiving van de grens van İbrim en Nubië naar het zuiden", "c57d5d77"], "d": ["De zuidgrens van het beylerbeylik van Egypte werd tot voorbij de tweede cataract verlegd doordat de op een rotsachtige kaap aan de Nijl gelegen burcht İbrim door Özdemir Bey werd versterkt en Neder-Nubië volledig bij Osmaans Egypte werd gevoegd. (In İbrim was de Osmaanse administratieve organisatie na de verovering van Egypte gevestigd; op de kaart wordt İbrim vanaf 1517 als Osmaans weergegeven. Dit jaar is bij benadering, de bron geeft geen jaar.) De burcht was een dam tegen de aanvallen uit Nubië en tevens het controlepunt van de route van goud en slaven naar Sennar. De hier gestationeerde Bosnische bewakingseenheid werd zo blijvend dat haar nakomelingen er driehonderd jaar later nog steeds waren. De bronnen geven twee verschillende verhalen over het moment waarop İbrim onder Osmaans bestuur kwam: het TDV-lemma Sudan koppelt de aansluiting van Neder-Nubië bij Osmaans Egypte aan de campagne van Özdemir Pasja halverwege de 16e eeuw, terwijl het lemma Nubië schrijft dat de regio tot aan de Halfa-vallei en de administratieve organisatie in İbrim onmiddellijk na de verovering van 1517 werd gevestigd. De sandjak İbrim werd op 26 juli 1573 aan de provincie Habesh gebonden.", "cd2c7ae9"]},
"OLAYLAR_EK5:1555-09-27:0":{"b": ["Inname van Bejaïa (Bougie) op de Spanjaarden", "49691cda"], "d": ["Bejaïa, dat drieënveertig jaar in Spaanse handen was en de kust tussen Algiers en Constantine in tweeën deelde, gaf zich over na belegering over land en zee. Met de val van de burcht werd de kust van het ocak van Algiers ononderbroken tot aan Oran. In Spanje wekte dit verlies zo'n grote verontwaardiging dat de commandant die de burcht overgaf, Alonso de Peralta, in zijn vaderland werd geëxecuteerd.", "a030d882"]},
"OLAYLAR_EK5:1559-01-01:0":{"b": ["Aansluiting van Zeila bij de provincie Habesh", "7bbf369a"], "d": ["De haven van Zeila aan de Afrikaanse kust van de Golf van Aden, aan het zuidelijke uiteinde van de provincie Habesh, werd aan het Osmaanse bestuur gebonden. Deze stad, de poort naar de zee van het Sultanaat Adal, was het laatste bevoorradingspunt voor schepen die buiten de Bab-el-Mandeb voeren. Met de aansluiting van Zeila bereikte de Osmaanse grens in Afrika zijn zuidelijkste punt.", "fe4597b7"]},
"OLAYLAR_EK5:1559-05-30:0":{"b": ["Slag van de prinsen bij Konya", "1c8de387"], "d": ["Prins Bayezid, die zich in de troonstrijd mengde, kwam met een leger van ongeveer 30.000 man voor Konya en werd in een twee dagen durende strijd verslagen door zijn broer prins Selim. De verslagen Bayezid zocht via Amasya zijn toevlucht in Iran bij sjah Tahmasp. De slag veranderde de opvolgingscrisis van de laatste jaren van Süleyman in een kwestie van buitenlands beleid.", "d466cfc5"]},
"OLAYLAR_EK5:1560-05-14:0":{"b": ["Zeeoverwinning bij Djerba", "c7b905c1"], "d": ["De Osmaanse vloot onder bevel van Piyâle Pasja verspreidde de Spaans-Genuees-Maltese geallieerde vloot, die was samengekomen om Tripoli terug te nemen, voor Djerba door een manoeuvre van splitsing in tweeën. De geallieerden verloren het grootste deel van hun vloot en ook de burcht op het eiland viel snel. Djerba wordt na Preveza beschouwd als de tweede grote zeeoverwinning die de Osmaanse suprematie in de Middellandse Zee bezegelde.", "e987b794"]},
"OLAYLAR_EK5:1562-07-23:0":{"b": ["Executie van prins Bayezid in Qazvin", "a759de14"], "d": ["Prins Bayezid, die zijn toevlucht in Iran had gezocht, werd na lange onderhandelingen door sjah Tahmasp aan een Osmaanse delegatie overgeleverd en werd samen met zijn vier zonen gewurgd en gedood. In ruil voor de overlevering verkregen de Safawiden belangrijke materiële concessies en grensgaranties. Met deze executie verdween de laatste hindernis voor de troonsbestijging van Selim II en bleef de vredesorde van Amasya behouden.", "cf625eb3"]},
"OLAYLAR_EK5:1566-04-14:0":{"b": ["Inname van Chios op de Genuezen", "a4559b96"], "d": ["Chios, dat tweehonderd jaar als handelskolonie werd bestuurd door de Genuese familie Giustiniani en schatting aan de Osmanen betaalde, werd door Piyâle Pasja zonder één schot overgenomen op grond van het uitblijven van betaling van de schatting en het verlenen van haven aan vijandelijke schepen. Samen met Psara werd ook de laatste Genuese aanwezigheid aan de oostkust van de Egeïsche Zee geliquideerd. Met behoud van de mastiekproductie en de privileges van de Chiotes werd het eiland gebonden aan de provincie Cezâyir-i Bahr-i Sefîd.", "a5ec4417"]},
"OLAYLAR_EK5:1566-04-15:0":{"b": ["Annexatie van het Hertogdom Naxos — alle Cycladen", "68f0ec0b"], "d": ["Het Latijnse Hertogdom Naxos, dat sinds 1207 bestond en sinds 1537 schatting aan de Osmanen betaalde, werd opgeheven onder verwijzing naar de klachten die binnenkwamen doordat de laatste hertog Giacomo Crispo zijn volk onderdrukte. Naxos, Paros, Antiparos, Andros, Syros, Mykonos, Ios, Santorini en alle Cycladeneilanden in hun omgeving werden met één besluit rechtstreeks onder Osmaans bestuur gebracht. Süleyman gaf het bestuur van de eilanden enige tijd aan Yasef Nasi; zo kwam midden in de Egeïsche Zee een einde aan een Latijnse heerschappij van drieënhalve eeuw.", "d4d7a143"]},
"OLAYLAR_EK5:1567-04-01:0":{"b": ["Opstand in Jemen en de Jemen-veldtocht van Koca Sinan Pasja", "c8218d8e"], "d": ["De Zaidi-imam Mutahhar kwam in opstand met als reden dat belasting met geweld werd geïnd en verdreef het Osmaanse bestuur uit het grootste deel van Jemen. Koca Sinan Pasja, die uit Constantinopel werd gestuurd, nam in de campagne van 1568-1570 na een lang beleg Kawkaban in en vestigde zo opnieuw de Osmaanse heerschappij in de regio. De veldtocht was van vitaal belang voor het behoud van de controle over de zuidelijke poort van de Rode Zee en de handelsroute van de Indische Oceaan.", "d4771f85"]},
"OLAYLAR_EK5:1567-10-01:0":{"b": ["Defensiebondgenootschap met het Sultanaat Atjeh en hulp in de Indische Oceaan", "8e835f24"], "d": ["De Atjehse gezanten, die tegenover Portugese aanvallen hulp vroegen aan Süleyman, boden na het overlijden van de sultan bij Szigetvár hun trouw aan Selim II aan en met hem werd een defensieverdrag getekend. De sultan beval dat kanonnen, geweren, munitie en vaklieden uit Alexandrië zouden worden gezonden; zeventien oorlogsschepen werden klaargemaakt om naar de wateren van India te worden gestuurd. De groei van de Jemenitische opstand verhinderde het vertrek van de vloot, maar de Osmaanse artilleristen en vaklieden die Atjeh bereikten, lieten blijvende sporen in de regio na.", "65c41562"]},
"OLAYLAR_EK5:1570-07-02:0":{"b": ["Landing op Cyprus: inname van Limassol", "9074ccc9"], "d": ["Het Osmaanse leger dat op het eiland landde, nam zonder veel verzet Limassol in en richtte zich de volgende dag op Larnaca. Doordat de lokale bevolking ontevreden was over het Venetiaanse bestuur en de Osmaanse strijdkrachten hielp, werd ook in Larnaca geen serieus verzet ontmoet; de aanlegsteiger van Tuzla werd gemaakt tot basis voor het aan land zetten van soldaten en uitrusting. Venetië had zijn verdediging geconcentreerd in Nicosia en Famagusta; de gouverneur van Paphos betuigde pas nadat Nicosia was gevallen zijn gehoorzaamheid aan de serdar.", "6bbd2fee"]},
"OLAYLAR_EK5:1570-09-09:0":{"b": ["Verovering van Nicosia", "413d866b"], "d": ["Na een beleg dat op 25 juli 1570 begon en vijfenveertig dagen duurde, gaf Nicosia, de hoofdstad van Cyprus onder Venetiaans bestuur, zich over aan het Osmaanse leger. De val van het centrum van het eiland drong het Venetiaanse verzet terug in de burcht van Famagusta. De verovering wekte in het Westen grote weerklank en versnelde het proces dat leidde tot de vorming van de vloot van de Heilige Liga onder leiding van de paus.", "1ef832d4"]},
"OLAYLAR_EK5:1570-09-17:0":{"b": ["Overgave van Kyrenia — de noordkust van Cyprus", "39fdeea5"], "d": ["De val van Nicosia op 9 september, waarbij de stad over de kling werd gejaagd, brak het verzet in het noorden van Cyprus. De burcht Kyrenia achter het Beşparmak-gebergte, die het lot van de hoofdstad vernam, gaf zich acht dagen later onder voorwaarden over en het garnizoen werd met toestemming om het eiland te verlaten weggezonden. Op het eiland bleef de Venetiaanse vlag alleen nog in Famagusta wapperen; die zou nog elf maanden standhouden.", "ecf762c9"]},
"OLAYLAR_EK5:1572-06-01:0":{"b": ["Wederopbouw van de vloot na Lepanto", "db51fe44"], "d": ["Na de ramp bij Lepanto was het eerste werk van Kılıç Ali Pasja, die tot kapudan pasja werd benoemd, de zwaar geteisterde vloot te herbouwen; de scheepswerven werkten in de winter van 1571-1572 onafgebroken. In juni 1572 voer een nieuwe vloot van ongeveer 250 galeien en 300 galeien van vrijwillige reis naar de Middellandse Zee. Dit snelle herstel toonde dat Lepanto de Osmaanse zeemacht niet blijvend had gebroken.", "324f2d99"]},
"OLAYLAR_EK5:1573-03-07:0":{"b": ["Verdrag van Constantinopel met Venetië — erkenning van Cyprus", "4d08ef50"], "d": ["Venetië, dat na het uiteenvallen van de Heilige Liga alleen kwam te staan, sloot een afzonderlijke vrede met de Osmanen, erkende formeel dat Cyprus aan de Osmanen toebehoorde en aanvaardde oorlogsschade te betalen. Het verdrag toonde duidelijk dat de overwinning bij Lepanto de christelijke wereld geen politieke winst had opgeleverd. Venetië zou zich hierna zeventig jaar lang onthouden van rechtstreekse oorlog met de Osmanen.", "de6151ba"]},
"OLAYLAR_EK5:1574-12-13:0":{"b": ["Overlijden van Selim II", "c289f5ee"], "d": ["Selim II kon na een val ongeveer twee maanden niet naar de divan komen en stierf. Zijn dood werd twaalf dagen geheim gehouden in het paleis totdat zijn oudste zoon Murad uit Manisa naar Constantinopel kwam. Over de dag van overlijden lopen de bronnen uiteen: Selânikî noemt 15 december; Gerlach, Mehmed b. Mehmed en Cenâbî noemen 13 december.", "e9e279ab"]},
"OLAYLAR_EK5:1574-12-22:0":{"b": ["Aankondiging van de dood van Selim II en troonsbestijging van Murad III", "84334d70"], "d": ["De dood van Selim II en de troonsbestijging van Murad III, die uit Manisa was gehaald, werd op 22 december 1574 officieel aangekondigd. De nieuwe sultan zou eenentwintig jaar op de troon blijven; zijn regering stond bekend om de lange Iraanse oorlogen in het oosten, de vooravond van de Lange Oorlog in het westen en de muntverslechtering binnenlands. Tot de dood van Sokollu Mehmed Pasja in 1579 duurde de oude orde in het staatsbestuur voort.", "3e1ec091"]},
"OLAYLAR_EK5:1578-08-04:0":{"b": ["Slag bij Alcácer Quibir (Wadi al-Makhazin) — Abd al-Malik met Osmaanse steun vernietigde het Portugese leger", "21280dac"], "d": ["Abd al-Malik, die met Osmaanse steun de Marokkaanse troon besteeg, vernietigde het grote leger van de Portugese koning Sebastiaan bij Wadi al-Makhazin; omdat drie heersers tegelijk in de slag omkwamen, wordt zij in westerse bronnen 'Slag van de Drie Koningen' genoemd. De militaire macht van Portugal stortte in en het land kwam kort daarna in Spaanse handen. Abd al-Malik kwam ook om in de slag; zijn broer Ahmad al-Mansur, die hem opvolgde, maakte de overwinning met een delegatie aan Constantinopel bekend. De verhouding tussen de twee staten bleef op het niveau van uitwisseling van gezanten en geschenken, niet van schatting of onderwerping, en werd kort daarna gespannen door de kwestie van de geschenken.", "0ddf3962"]},
"OLAYLAR_EK5:1578-10-05:0":{"b": ["Trouwbetuiging van de bevolking van Derbent aan Lala Mustafa Pasja — Demirkapı onder Osmaans bestuur", "9c55aeff"], "d": ["Tijdens de Shirvan-veldtocht ging een delegatie van zeven personen uit Derbent naar serdar Lala Mustafa Pasja in Ereş en betuigde haar trouw. Derbent (Demirkapı), dat de nauwe doorgang tussen de Kaukasusmuur en de Kaspische Zee afsluit, speelde als noodzakelijke doorgang van de landwegen uit het noorden een sleutelrol bij het behoud van Shirvan. De Osmaanse heerschappij duurde hier tot 1607.", "9776382c"]},
"OLAYLAR_EK5:1578-11-01:0":{"b": ["Verovering van Shirvan: inname van Shamakhi", "9afae4c1"], "d": ["Het leger dat na de overwinning bij Çıldır naar de Kaukasus uitwaaierde, trok Shirvan, de rijkste provincie van de Safawiden aan de Kaspische kust, binnen en nam de centrale stad Shamakhi in. Özdemiroğlu Osman Pasja werd hier tot beylerbey benoemd en de noordelijke tak van de Zijderoute kwam onder Osmaanse controle. Shirvan zou het front van de twaalf jaar durende oostelijke oorlog worden dat het vaakst van hand wisselde en het duurst uitkwam.", "9955f6f2"]},
"OLAYLAR_EK5:1583-08-01:0":{"b": ["Inname van Bakoe — toegang tot de Kaspische kust", "eb5adab8"], "d": ["Als laatste schakel van de Shirvan-campagne werd de haven van Bakoe aan de westkust van de Kaspische Zee ingenomen. De oliebronnen rond de stad waren ook toen al een bekende inkomstenbron en de haven was het uitvoerpunt van de Iraanse zijde die over de Kaspische Zee kwam. De Osmaanse staat werd zo voor het eerst en enige keer in haar geschiedenis kusteigenaar aan de Kaspische Zee.", "ffafa858"]},
"OLAYLAR_EK5:1583-09-13:0":{"b": ["Verovering van Revan (Jerevan) en bouw van de burcht", "7f623b7b"], "d": ["Ferhad Pasja, die in Kars het bevel kreeg naar Revan te gaan en daar een burcht te bouwen, trok op Revan en de stad werd begin Ramadan 991 (midden september 1583) onder Osmaanse controle gebracht. In Revan, dat de noordelijke poort van de Arasvallei bewaakt, werd een nieuwe en grote burcht gebouwd en de stad werd beylerbeylik-centrum. Revan, dat in het midden van de legerroute tussen Kars en Tabriz lag, was de logistieke ruggengraat van het oostfront. De burcht werd zo stevig gebouwd dat zij gedurende de volgende tweehonderd jaar het onveranderlijke doel van de Osmaans-Iraanse oorlogen was.", "f6b3bd6e"]},
"OLAYLAR_EK5:1588-09-01:0":{"b": ["Annexatie van Karabach en Ganja", "29abaead"], "d": ["Als laatste winst van de tien jaar durende oostelijke oorlog trok Ferhad Pasja in 1588 naar Ganja en trok op 1 september de stad binnen; de regio Karabach tussen Kura en Aras en haar centrum Ganja werden onder Osmaans bestuur gebracht. Zo vormden Shirvan, Revan en Karabach samen een ononderbroken Osmaanse lijn in de Kaukasus. Het in 1590 ondertekende Verdrag van Ferhad Pasja zou deze grens bevestigen, maar de winst kon slechts twintig jaar worden behouden.", "67f1d89d"]},
"OLAYLAR_EK5:1592-06-19:0":{"b": ["Verovering van Bihać", "651a7275"], "d": ["Telli Hasan Pasja, de beylerbey van Bosnië, nam in november 1591 Ripač, de voorburcht van Bihać, in en veroverde in 1592 ook de stad en de burcht zelf; na een beleg van tien dagen gaf commandant Lamberg zich over. Deze verovering duwde de Bosnische grens naar voren langs de rivier de Una en werd de laatste grote Osmaanse winst aan de vooravond van de Lange Oorlog, die een jaar later zou uitbreken met de dood van Telli Hasan Pasja als martelaar bij Kulpa.", "b6814991"]},
"OLAYLAR_EK5:1593-07-01:0":{"b": ["Begin van de Osmaans-Oostenrijkse 'Lange Oorlog'", "bd22c392"], "d": ["Nadat de beylerbey van Bosnië, Telli Hasan Pasja, bij Kulpa (Sisak) werd verslagen en sneuvelde, verklaarde de Osmaanse staat Oostenrijk de oorlog en begon de dertien jaar durende Lange Oorlog. Deze oorlog, waarin infanterie met vuurwapens doorslaggevend was, versnelde de inzet van sekban en soldaten met geweren in de Osmaanse legerorde en verdiepte het verval van de timar-sipahi. De oorlog zou in 1606 eindigen met het Verdrag van Zsitvatorok.", "f309a27f"]},
"OLAYLAR_EK5:1593-07-19:0":{"b": ["Koca Sinan Pasja trok ten strijde naar Oostenrijk — eerste veldtocht van de Lange Oorlog", "d4a2f46d"], "d": ["Nadat de beylerbey van Bosnië Hasan Pasja bij Sisak werd verslagen en sneuvelde, overtuigde grootvizier Koca Sinan Pasja de sultan met schitterende woorden en beloften van de oorlog en vertrok met 12.000 janitsaren en andere eenheden. Zo werd de eerste veldtocht van de dertien jaar durende Osmaans-Oostenrijkse oorlog geopend.", "0f217276"]},
"OLAYLAR_EK5:1594-09-27:0":{"b": ["Verovering van Győr (Yanıkkale)", "14b75207"], "d": ["Grootvizier Koca Sinan Pasja nam na een beleg van meer dan een maand Győr (Yanıkkale) over, dat gold als het slot van de weg naar Wenen. De val van de burcht leidde in Europa tot grote paniek en was de schitterendste winst van de Osmanen in de Lange Oorlog. Maar de burcht zou slechts vier jaar kunnen worden gehouden.", "a634af40"]},
"OLAYLAR_EK5:1595-01-17:0":{"b": ["Overlijden van Murad III", "1b62e886"], "d": ["Na een regering van eenentwintig jaar stierf Murad III in de dagen waarin het Walachijse leger İbrâil in brand stak en doorstootte naar Silistra, en werd hij begraven in de hazire van de Hagia Sophia. Zijn zoon Mehmed III, die uit Manisa werd geroepen, bereikte tien dagen later Constantinopel en besteeg de troon (27 januari 1595).", "1deabc61"]},
"OLAYLAR_EK5:1595-09-02:0":{"b": ["Verlies van Esztergom aan Oostenrijk", "f420d333"], "d": ["De bewakers van Esztergom, die bij het beleg onder leiding van Karl von Mansfeld onvoldoende hulp kregen, droegen de burcht over aan aartshertog Matthias. Met het einde van een tweeënvijftig jaar durende Osmaanse heerschappij werd de verdedigingsketen aan de Donaulijn doorbroken en kwam Boeda rechtstreeks onder dreiging. De burcht zou pas tien jaar later, in 1605, kunnen worden teruggenomen.", "7617d6f2"]},
"OLAYLAR_EK5:1596-10-12:0":{"b": ["Verovering van de burcht Eger", "3e511629"], "d": ["Na een strijd van drie weken viel de sterke burcht Eger, die de Osmanen eerder nooit hadden kunnen innemen, doordat de bewakers zich overgaven. Deze verovering, waarbij de sultan persoonlijk aanwezig was, herstelde tot op zekere hoogte het door het verlies van Esztergom geschade moreel en de provincie Eger werd gesticht. Samen met de twee weken later behaalde overwinning bij Mezőkeresztes werd 1596 het meest succesvolle Osmaanse jaar van de Lange Oorlog.", "5dc53fa9"]},
"OLAYLAR_EK5:1598-03-29:0":{"b": ["Verlies van Győr (Yanıkkale)", "b4ccc679"], "d": ["De troepen onder bevel van Miklós Pálffy en Adolf von Schwarzenberg namen Győr terug door de burchtpoorten bij een overval op te blazen. Het verlies van de burcht, die Koca Sinan Pasja vier jaar eerder met grote inspanning had verkregen, deed de voorste linie van de Osmanen in Hongarije instorten. Hoewel de vijandelijke strijdkrachten die Boeda in hetzelfde jaar belegerden werden teruggeslagen, ontaardde het evenwicht van de oorlog geleidelijk in een uitputtingsoorlog.", "80bf88e0"]},
"OLAYLAR_EK5:1599-01-01:0":{"b": ["Opstand van Karayazıcı Abdülhalim", "30493b0d"], "d": ["Karayazıcı Abdülhalim, die de uit het leger gevluchte sekban en levend in de Lange Oorlog verzamelde, nam in Midden-Anatolië een groot gebied onder zijn controle, nam de burcht Urfa in (november 1599) en riep zich onder de titel 'Halim Shah' uit tot sultan en zond firmans met zijn eigen tughra. Karayazıcı, die wordt beschouwd als de eerste leider van de grote Celali-golf, stierf in 1602 en zijn beweging werd voortgezet door zijn broer Deli Hasan. De opstand is het begin van de periode van 'de grote vlucht' waarin de Anatolische boeren massaal hun land verlieten.", "ceda9161"]},
"OLAYLAR_EK5:1601-09-10:0":{"b": ["Verdediging van Kanije door Tiryaki Hasan Pasja", "d56a5e6a"], "d": ["Aartshertog Ferdinand en zijn bondgenoten, die Kanije, dat een jaar eerder was veroverd, wilden terugnemen, belegerden de burcht meer dan twee maanden; Tiryaki Hasan Pasja bood met zijn strijdmacht van 9000 man weerstand. Hoewel hij geen hulp van buiten kreeg, sloeg hij de algemene aanvallen af en dwong de vijand met uitvallen om zich met zware verliezen terug te trekken. De verdediging werd legendarisch in de Osmaanse geschiedschrijving en 'Het beleg van Kanije' werd een literair genre op zich.", "edc6d7b6"]},
"OLAYLAR_EK5:1603-12-20:0":{"b": ["Overlijden van Mehmed III en troonsbestijging van Ahmed I", "da735fde"], "d": ["Na de dood van Mehmed III op 20 december besteeg zijn veertienjarige zoon Ahmed I de troon. Dat hij de eerste sultan was die op kinderleeftijd en zonder naar een sandjak te zijn gestuurd de troon besteeg, toont dat de gewoonte om prinsen in de provincie op te leiden feitelijk ten einde was. Onder de regering van Ahmed I zou de broedermoord worden opgegeven en zou worden overgegaan op het beginsel van 'ekberiyet' (de oudste mannelijke telg bestijgt de troon).", "a5f7151a"]},
"OLAYLAR_EK5:1605-10-03:0":{"b": ["Herovering van Esztergom", "7330f273"], "d": ["Grootvizier Lala Mehmed Pasja belegerde Esztergom, dat tien jaar eerder verloren was gegaan, en voegde het opnieuw bij het Osmaanse bestuur. In dezelfde veldtocht werden ook Pest en Vác bevrijd en herstelden de Osmanen hun lijn in Hongarije. Dit succes zorgde ervoor dat men het jaar daarop relatief sterk aan tafel kwam te zitten in Zsitvatorok; Esztergom zou tot 1683 in Osmaanse handen blijven.", "242d3547"]},
"OLAYLAR_EK5:1607-10-24:0":{"b": ["Overwinning in de vlakte van Oruç en neerslaging van de opstand van Canbolatoğlu", "30f93532"], "d": ["Canbolatoğlu Ali Pasja, die in Aleppo een onafhankelijk beylik had gevormd en een bondgenootschap met Toscane zocht, werd door grootvizier Kuyucu Murad Pasja in de vlakte van Oruç zwaar verslagen. Met het herstel van het centrale gezag in Syrië werd de gevaarlijkste tak van de Celali-golf gebroken. De twee jaar durende meedogenloze zuivering van Kuyucu Murad Pasja bracht in Anatolië, zij het tijdelijk, de openbare orde terug.", "6e620c57"]},
"OLAYLAR_EK5:1608-08-09:0":{"b": ["Overwinning bij Alaçayır en neerslaging van de opstand van Kalenderoğlu", "55db0485"], "d": ["De Celali-leider Kalenderoğlu, die de streken Manisa en Bursa schatplichtig maakte, werd door Kuyucu Murad Pasja bij Alaçayır verslagen en moest naar Iran vluchten. Met deze overwinning werd het laatste van de grote Celali-legers in Anatolië verspreid. De harde zuivering van Kuyucu Murad Pasja, van wie wordt verteld dat hij de rebellen die hij liet doden in door hem gegraven putten liet gooien, bracht op korte termijn orde, maar kon het verlies aan bevolking en productie van Anatolië niet goedmaken.", "dc332b4b"]},
"OLAYLAR_EK5:1612-07-06:0":{"b": ["Eerste ahidname aan Nederland verleend", "5d9d117e"], "d": ["De gezant van de Verenigde Nederlandse Republiek, Cornelis Haga, wist van Ahmed I een ahidname te verkrijgen die dezelfde omvang had als die aan Frankrijk en Engeland. Nederland kreeg zo het recht een ambassade in Constantinopel, consulaten in Osmaanse havens te openen en onder eigen vlag handel te drijven. Deze ahidname symboliseert de toetreding tot de Osmaanse markt van de noordelijke zeemachten die in de Middellandse Zeehandel de plaats van Venetië innamen.", "7991027b"]},
"OLAYLAR_EK5:1617-11-22:0":{"b": ["Overlijden van Ahmed I en troonsbestijging van Mustafa I — ekberiyet-stelsel", "9901c09e"], "d": ["Na een maagziekte van eenenvijftig dagen stierf de achtentwintigjarige Ahmed I en in plaats van zijn zoon werd zijn broer Mustafa I op de troon gezet. Zo werd het opvolgingsstelsel van vader op zoon verlaten en feitelijk overgegaan op het 'ekberiyet'-stelsel waarbij het oudste mannelijke lid van de dynastie de troon bestijgt. Deze eerste regering, die zesennegentig dagen duurde, is ook het begin van het tijdperk waarin prinsen in de 'kafes' (kooi) werden opgevoed.", "1f866a67"]},
"OLAYLAR_EK5:1618-02-26:0":{"b": ["Afzetting van Mustafa I en troonsbestijging van Jonge Osman (Osman II)", "e0f552f2"], "d": ["Mustafa I werd na zesennegentig dagen afgezet met als reden dat zijn geestelijke gezondheid niet in orde was en de veertienjarige zoon van Ahmed I, Osman II, werd sultan. Volgens de overlevering op gezag van Hasanbeyzâde was de Kızlar Ağası Mustafa Ağa invloedrijk bij dit afzettingsbesluit. Jonge Osman wordt, met zijn plan om het janitsarenkorps af te schaffen en een nieuw leger te vormen, beschouwd als de eerste radicale naam in de Osmaanse hervormingsdiscussies. Dit plan zou vier jaar later zijn leven kosten.", "4d655aca"]},
"OLAYLAR_EK5:1618-09-26:0":{"b": ["Verdrag van Serav — vernieuwing van de vrede met Iran", "e778aca8"], "d": ["Het Verdrag van Serav, bereikt met Iran na de nederlaag bij Pul-i Shikaste, bevestigde grotendeels de voorwaarden van het Verdrag van Nasuh Pasja van 1612; de hoeveelheid zijde die de Safawiden jaarlijks zouden sturen werd teruggebracht van tweehonderd naar honderd ladingen. Zo werd de tweede fase van de oostelijke oorlogen die sinds 1603 duurden afgesloten. De vrede zou niet lang duren; met het verlies van Bagdad in 1623 zou de oorlog opnieuw oplaaien.", "f14d72aa"]},
"OLAYLAR_EK5:1621-10-09:0":{"b": ["Veldtocht van Chocim en Verdrag van Chocim", "bc4c823c"], "d": ["Het versterkte kamp dat Chodkiewicz voor Chocim had opgezet kon niet worden doorbroken door het grote leger waarvan Osman II zelf het bevel voerde en na maandenlange aanvallen werd geen resultaat behaald. Met het verdrag dat op 9 oktober werd ondertekend, werd de Dnjestr als grens aanvaard en verbonden de Polen zich ertoe de Kozakkenaanvallen te verhinderen. De veldtocht, die ondanks het feit dat hij als overwinning werd gepresenteerd geen resultaat opleverde, versterkte het wantrouwen van de jonge sultan jegens de janitsaren en zijn voornemen het korps te zuiveren.", "7d812c58"]},
"OLAYLAR_EK5:1623-09-10:0":{"b": ["Tweede afzetting van Mustafa I en troonsbestijging van Murad IV", "1b3a9e74"], "d": ["Mustafa I, die na de moord op Osman II voor de tweede keer op de troon was gezet, werd na een jaar en drie maanden opnieuw afgezet en de elfjarige Murad IV werd tot sultan uitgeroepen. De eerste negen jaar werd de staat feitelijk bestuurd door zijn moeder Kösem Sultan en de paleisnotabelen. Murad IV zou vanaf 1632 het bestuur persoonlijk in handen nemen en een periode van harde centralisatie inluiden.", "6dea0fec"]},
"OLAYLAR_EK5:1623-11-28:0":{"b": ["Verlies van Bagdad aan de Safawiden", "db81be0c"], "d": ["Na de onderhandelingen die Bekir Subaşı, die in Bagdad in opstand was gekomen, met de Safawiden voerde, droeg zijn zoon Derviş Mehmed, die de binnenburcht verdedigde, de stad over aan de strijdkrachten van Sjah Abbas. Het verlies van een van de symboolsteden van de kalifaatserfenis en van het grootste deel van Irak wekte in Constantinopel grote verontwaardiging. Het heroveren van Bagdad zou vijftien jaar lang het enige doel van het Osmaanse oostelijke beleid zijn.", "ef09360d"]},
"OLAYLAR_EK5:1628-09-22:0":{"b": ["Neerslaging van de opstand van Abaza Mehmed Pasja met Erzurum als centrum", "e6da2729"], "d": ["Abaza Mehmed Pasja, de beylerbey van Erzurum, die in opstand kwam tegen de janitsaren onder het voorwendsel de moord op Osman II te wreken, hield Oost-Anatolië jarenlang onder zijn controle en bood weerstand aan het centrum. Hij moest zich overgeven na het beleg van Erzurum door grootvizier Hüsrev Pasja, kreeg gratie en werd benoemd in Bosnië. Het einde van de opstand was een voorwaarde voor Murad IV om een veldtocht tegen Iran te kunnen ondernemen.", "68311e29"]},
"OLAYLAR_EK5:1634-01-08:0":{"b": ["Eerste executie van een sjeik-ul-islam: Ahîzâde Hüseyin Efendi", "a60a58c5"], "d": ["Sjeik-ul-islam Ahîzâde Hüseyin Efendi werd bij Büyükçekmece geëxecuteerd met als reden dat hij had bemiddeld in de militaire onrust en de sultan een schriftelijke waarschuwing over de rechtsgang had gestuurd. Dat hij de eerste geëxecuteerde Osmaanse sjeik-ul-islam was, doorbrak de diepgewortelde traditie dat de zwaarste straf voor leden van de ilmiye ballingschap was. Het voorval geldt als symbool van het verhardende gezag van Murad IV en van de verstoring van het evenwicht tussen staat en ulema.", "2822f303"]},
"OLAYLAR_EK5:1635-08-08:0":{"b": ["Verovering van Revan door Murad IV", "b65a9b73"], "d": ["Murad IV, die op 28 maart 1635 uit Constantinopel vertrok, belegerde Revan op 28-29 juli en nam de burcht op 8 augustus over; daarna trok hij het ontruimde Tabriz binnen en liet de stad verwoesten. De sultan liet ter herinnering aan de overwinning het Revan-paviljoen in het Topkapı-paleis bouwen. Deze veldtocht was de eerste grote oostelijke campagne na een onderbreking van dertig jaar waarbij de sultan persoonlijk het bevel over het leger voerde.", "2da4da04"]},
"OLAYLAR_EK5:1636-04-01:0":{"b": ["Verlies van Revan aan de Safawiden", "fbb8dd25"], "d": ["Na de terugtrekking van het Osmaanse leger belegerden de strijdkrachten van sjah Safi Revan en namen het binnen acht maanden terug. Dat de burcht zo snel verloren ging, toonde hoe moeilijk blijvende heerschappij in de Kaukasus logistiek was. Revan zou ook met het Verdrag van Qasr-i Shirin in 1639 aan Iran worden gelaten en de Osmanen zouden hun aanspraak op Azerbeidzjan opgeven.", "f90cb004"]},
"OLAYLAR_EK5:1638-12-24:0":{"b": ["Herovering van Bagdad", "4d2f27f3"], "d": ["Murad IV, die op 8 mei 1638 uit Constantinopel vertrok, nam na een hevig beleg van veertig dagen Bagdad, dat vijftien jaar in Safawidische handen was, terug; tijdens het beleg sneuvelde vizier Tayyar Mehmed Pasja. Met de verovering van de stad werd het Osmaanse bestuur in Irak hersteld en nam de sultan de titel 'Veroveraar van Bagdad' aan. De verovering werd het jaar daarop met het Verdrag van Qasr-i Shirin bestendigd en legde de basis voor de huidige grens tussen Turkije en Iran.", "bb99d1fb"]},
"OLAYLAR_EK5:1640-02-09:0":{"b": ["Overlijden van Murad IV en troonsbestijging van sultan İbrahim", "e2ca1ca0"], "d": ["Na de dood van Murad IV op zevenentwintigjarige leeftijd (achtentwintig volgens de hijri-telling) besteeg zijn broer İbrahim, het enige overlevende mannelijke lid van de dynastie, de troon. Tijdens de regering van de nieuwe sultan, die jarenlang in de kooi had geleefd, schokten de paleisuitgaven en de machtsstrijd binnen het paleis de staatsorde. Met zijn afzetting en moord acht jaar later zou de tweede sultansmoord uit de Osmaanse geschiedenis plaatsvinden.", "9ad0a971"]},
"OLAYLAR_EK5:1642-02-26:0":{"b": ["Herovering van de burcht Azak op de Kozakken", "e5fcf160"], "d": ["De burcht Azak, die de Donkozakken in 1637 hadden ingenomen, werd ontruimd tegenover de gezamenlijke operatie van Sultanzâde Mehmed Pasja en de Krim-khan Mehmed Giray IV; de Kozakken staken de burcht in brand en trokken zich terug. De herovering van de noordelijke poort van de Zwarte Zee sloot de gevaarlijke periode waarin Kozakkenaanvallen tot de Bosporus van Constantinopel reikten. De burcht zou in 1696 ditmaal aan de Russische tsaar Peter I worden verloren.", "39448f1f"]},
"OLAYLAR_EK5:1645-08-22:0":{"b": ["Begin van de Kretenzische veldtocht en verovering van Chania", "a1b0c77f"], "d": ["Onder het voorwendsel dat Maltese piraten een Osmaans pelgrimsschip hadden aangevallen en op Kreta onderdak hadden gevonden, werd Venetië de oorlog verklaard en de vloot onder bevel van Yûsuf Pasja zette soldaten aan land op het eiland. Na een beleg van vierenvijftig dagen werd de burcht Chania ingenomen en werd op Kreta de eerste blijvende Osmaanse basis gevestigd. Zo begon de langstdurende oorlog uit de Osmaanse geschiedenis; het eiland zou pas vierentwintig jaar later, in 1669, volledig kunnen worden veroverd.", "2809708a"]},
"OLAYLAR_EK5:1646-11-13:0":{"b": ["Verovering van Rethymno — verdeling van Kreta in tweeën", "8f2c4353"], "d": ["Een jaar na de inname van Chania viel ook de burcht Rethymno in het midden van het eiland en kwam de westelijke helft van Kreta volledig onder Osmaans bestuur. Venetië hield alleen de hoofdstad Candia en de oostpunt in handen; het eiland leefde drieëntwintig jaar in tweeën gedeeld. De inname van Rethymno was de stap die het beleg van Candia startte — hier begon het langste beleg uit de geschiedenis.", "88ec9840"]},
"OLAYLAR_EK5:1648-03-31:0":{"b": ["Verlies van Klis aan Venetië", "5473c22c"], "d": ["Aan het Dalmatische front van de Kretenzische (Candia-)oorlog omvatte het tegenoffensief van de Venetiaanse commandant Leonardo Foscolo ook Klis, dat sinds 1537 centrum van de sandjak was; de burcht ging naar Venetië. Dat de Osmanen zich met al hun kracht op Kreta concentreerden, maakte het onmogelijk dit verlies aan de Dalmatische grens terug te nemen — Klis zou nooit meer onder Osmaans bestuur terugkeren; het sandjakcentrum werd verplaatst naar Livno.", "d0ec59d4"]},
"OLAYLAR_EK5:1648-05-01:0":{"b": ["Begin van het beleg van Candia", "13016b10"], "d": ["Na de inname van Chania en Rethymno omsingelde het Osmaanse leger Candia, het laatste grote steunpunt van Venetië op het eiland. Deze blokkade, die eenentwintig jaar zou duren, ging de geschiedenis in als een van de langste belegeringen uit de wereldkrijgsgeschiedenis. Tijdens het beleg zouden de pogingen van de Venetiaanse vloot om de Dardanellen te blokkeren de oorlog naar het hart van de Egeïsche Zee brengen.", "8a35e8f9"]},
"OLAYLAR_EK5:1651-09-02:0":{"b": ["Moord op grote valide Kösem Sultan", "9d763f79"], "d": ["De ongeveer tweeënzestigjarige Kösem Sultan werd door Başlala Uzun Süleyman Ağa en zijn mannen, die handelden op bevel van Turhan Sultan, de moeder van Mehmed IV, in een kamer in de harem gevonden en gedood. De dood van deze machtige dynastieke vrouw, die onder drie sultans de staatspolitiek stuurde, wordt beschouwd als het feitelijke einde van het tijdperk dat het 'Sultanaat van de Vrouwen' wordt genoemd. Het vrijgekomen gezag baande vijf jaar later de weg naar de benoeming van Köprülü Mehmed Pasja tot grootvizier met buitengewone bevoegdheden.", "d1ff09cb"]},
"OLAYLAR_EK5:1656-07-13:0":{"b": ["Nederlaag bij de Dardanellen en verlies van Tenedos en Lemnos", "e01a1f7e"], "d": ["De grote zeeoverwinning die de Venetiaanse admiraal Mocenigo in juni 1656 voor de Dardanellen behaalde, vernietigde de Osmaanse vloot nagenoeg volledig; daarna werden Tenedos, Lemnos en Samothrake bezet. Met de blokkade van de zeestraat door Venetië schoten de voedselprijzen in Constantinopel omhoog en verspreidde zich angst voor een aanval op de hoofdstad. Deze ramp was de directe reden voor de benoeming van Köprülü Mehmed Pasja in september 1656 tot grootvizier onder voorwaarden en met buitengewone bevoegdheden.", "31f7a914"]},
"OLAYLAR_EK5:1657-08-25:0":{"b": ["Overwinning bij de Dardanellen en herovering van Tenedos", "603da863"], "d": ["De vloot die Köprülü Mehmed Pasja mobiliseerde, versloeg op 19 juli 1657 voor de zeestraat de Venetiaanse vloot; daarna nam de troepenmacht onder bevel van Kurd Pasja op 25 augustus Tenedos terug en op 30 augustus ontruimden de Venetianen het eiland volledig. In november werd ook Lemnos bevrijd, werd de blokkade van de Dardanellen doorbroken en werd de bevoorradingsroute van Constantinopel heropend. Köprülü stak persoonlijk over naar het eiland en liet de versterkingen herstellen; dit succes is de eerste grote militaire winst van het Köprülü-tijdperk.", "af4d7bfd"]},
"OLAYLAR_EK5:1658-08-27:0":{"b": ["Verovering van Ineu (Yanova) en Transsylvanische veldtocht", "d1089616"], "d": ["Köprülü Mehmed Pasja, die ten strijde trok om György II Rákóczi, prins van Transsylvanië, te straffen omdat hij zonder toestemming een Poolse veldtocht had ondernomen en de Osmaanse bescherming had geschonden, trok via Belgrado op en nam de strategische burcht Ineu (Yanova) in. Door een nieuwe prins in Transsylvanië te benoemen werd de vazalband hard in herinnering gebracht. Deze veldtocht was de eerste schakel van de poging van de Osmanen om hun gezag in Midden-Europa te herstellen. Transsylvanië was al een aan de Osmanen onderworpen prinsdom; de inname van Ineu was geen verovering van een buitenlandse staat, maar het onttrekken van deze burcht aan het prinselijk bestuur van het onderworpen Transsylvanië en het rechtstreeks binden ervan aan een Osmaanse sandjak; de rest van het prinsdom bleef in vazalstatus.", "4e24d834"]},
"OLAYLAR_EK5:1659-02-16:0":{"b": ["Neerslaging van de opstand van Abaza Hasan Pasja", "4ba74321"], "d": ["Abaza Hasan Pasja, die tegen de harde zuiveringen van Köprülü Mehmed Pasja de beylerbeys van Anatolië en de sekban-agha's achter zich schaarde, begon een grote opstand met de eis dat de grootvizier werd afgezet. De opstand werd in Aleppo neergeslagen en de leiders werden uitgeschakeld; dit was het laatste gezamenlijke verzet van de provinciale pasja's tegen het centrum. Zo werd het gezag van Köprülü onbetwist en steeg het grootvizierschap weer tot het werkelijke uitvoerende centrum van de staat.", "900e66b5"]},
"OLAYLAR_EK5:1660-08-27:0":{"b": ["Verovering van Oradea (Varad)", "0e6ad300"], "d": ["In het kader van de veldtocht tegen György II Rákóczi, de prins van Transsylvanië die de Osmanen de oorlog had verklaard, werden de burcht en de stad Oradea (Varad) ingenomen. Met de val van een van de sleutelburchten van Transsylvanië werd in de regio een nieuwe Osmaanse provincie (de provincie Varad) gesticht. De verovering bracht de Habsburgers in paniek en werd een van de directe oorzaken van de Osmaans-Oostenrijkse oorlog die drie jaar later zou beginnen. Andere plaatsen die op dezelfde datum werden toegevoegd: Varat. Ook hier werd het grondgebied niet van een buitenlandse staat genomen: Transsylvanië was al een onderworpen Osmaans prinsdom; dat Varad een provincie werd, onttrok alleen het bestuur van deze stad aan het onderworpen prinsdom en bond het rechtstreeks aan de sultan, net als twee jaar eerder bij Ineu.", "991162de"]},
"OLAYLAR_EK5:1664-08-01:0":{"b": ["Slag bij Szentgotthárd (St. Gotthard)", "61ebc1f2"], "d": ["De Osmaanse strijdkrachten die de Raab overstaken, werden door het geallieerde Europese leger onder bevel van Montecuccoli tegengehouden en leden zware verliezen. De slag geldt als keerpunt in de militaire geschiedenis doordat het voor het eerst duidelijk de superioriteit van het gedisciplineerde geweervuur van de infanterie tegenover de Osmaanse cavalerieaanval toonde. Ondanks de nederlaag wisten de Osmanen negen dagen later in het getekende Verdrag van Vasvár gunstige voorwaarden te verkrijgen.", "4ab743fc"]},
"OLAYLAR_EK5:1664-08-09:0":{"b": ["Verdrag van Vasvár", "089c978c"], "d": ["Het verdrag dat ondanks de nederlaag bij Szentgotthárd werd ondertekend, bepaalde dat Uyvar en Varad Osmaans bleven, dat Transsylvanië onder Osmaanse bescherming neutraal werd gelaten en dat Oostenrijk een 'geschenk' van 200.000 kuruş zou betalen. Deze twintig jaar durende vrede is een van de zeldzame voorbeelden van een partij die de oorlog verloor maar aan tafel won. De ontevredenheid die het verdrag in de Habsburgse publieke opinie wekte, zou de beweging van Midden-Hongarije en indirect de Wenen-veldtocht van 1683 voeden.", "61ca5d47"]},
"OLAYLAR_EK5:1671-01-01:0":{"b": ["Begin van het dey-bestuur in Algiers", "e99faa51"], "d": ["Het korps van Algiers en de taife-i reîs (piratenkapiteins) zetten de laatste agha af en kozen Hacı Mehmed voor het leven tot dey. Vanaf deze datum werd Algiers niet meer bestuurd door een door Constantinopel benoemde beylerbey, maar door de dey die het plaatselijke korps uit eigen gelederen koos; de Osmaanse band bleef beperkt tot het lezen van de naam van de sultan in de khutba, de vlag en de verplichting tot militaire dienst. Algiers veranderde zo van een provincie in een ocak — dezelfde transformatie maakten Tunis in 1705 met de Husseiniden en Tripolitanië in 1711 met de Karamanlis door.", "b8decd95"]},
"OLAYLAR_EK5:1672-06-04:0":{"b": ["Poolse veldtocht begon — Mehmed IV en Fâzıl Ahmed Pasja aan het hoofd van het leger", "75e15a39"], "d": ["Toen de Poolse aanvallen op de Oekraïense hetman Petro Doroshenko, die onder Osmaanse bescherming was gekomen, voortduurden, vroeg Constantinopel de Poolse koning van de aanvallen af te zien; toen er geen positief antwoord kwam, werd besloten tot een veldtocht tegen Polen. Grootvizier Fâzıl Ahmed Pasja vertrok op 4 juni 1672 met het leger, waarbij ook de sultan aanwezig was, naar Polen. De veldtocht zou eindigen met de verovering van Kamjanets-Podilsky en het Verdrag van Buczacz.", "7340721a"]},
"OLAYLAR_EK5:1672-08-27:0":{"b": ["Verovering van Kamjanets-Podilsky en stichting van de provincie Podolië", "c3f4f6d0"], "d": ["Na een beleg van negen dagen werd Kamjanets-Podilsky, dat gold als de sterkste burcht van Polen in het oosten, overgenomen; Mehmed IV verrichtte op 2 september het eerste vrijdaggebed in de moskee die uit de kathedraal was omgevormd. De burcht werd het centrum van de nieuw gestichte provincie Podolië en de Osmaanse vlag bereikte op het grondgebied van het huidige Oekraïne het verst naar het noorden. Kamjanets zou tot het Verdrag van Karlowitz in 1699 de noordwestelijke punt van het rijk blijven.", "d89c513a"]},
"OLAYLAR_EK5:1674-08-03:0":{"b": ["Kara Mustafa Pasja nam Uman over van Polen", "0d3543a0"], "d": ["Kara Mustafa Pasja, die tegen Polen werd gestuurd, nam Uman, een van de burchten in Poolse handen, over; de stad bleef tot Karlowitz onder Osmaans bestuur.", "bdb8e553"]},
"OLAYLAR_EK5:1678-08-21:0":{"b": ["Verovering van de burcht Chyhyryn", "a17cedd0"], "d": ["Na de campagne van Melek İbrahim Pasja een jaar eerder die geen resultaat had gehad, belegerde grootvizier Merzifonlu Kara Mustafa Pasja onder persoonlijk bevel de versterkte burcht Chyhyryn (19/21 juli) en nam hem op 21 augustus in. De val van de burcht, het symbool van de Osmaans-Russische rivaliteit om het Kozakken-hetmanaat in Oekraïne, dwong Rusland tot vrede. Dit succes was een van de bronnen van het zelfvertrouwen waarmee Merzifonlu zich op Wenen zou richten.", "aee53ec4"]},
"OLAYLAR_EK5:1681-02-13:0":{"b": ["Verdrag van Bachtsjisaraj — eerste officiële vrede met Rusland", "df82bc0b"], "d": ["Na de onderhandelingen die na de Chyhyryn-veldtochten door bemiddeling van de Krim-khan werden gevoerd, werd een twintigjarige vrede tussen de Osmaanse staat en Rusland ondertekend, waarbij de Dnjepr (Özü) als grens werd aanvaard. Als eerste omvattende verdrag tussen de twee staten wordt het beschouwd als het beginnende document van de Osmaans-Russische betrekkingen. Dankzij de vrede werd het oostelijk front veiliggesteld en kon het leger naar Midden-Europa worden gestuurd.", "56f57388"]},
"OLAYLAR_EK5:1682-09-16:0":{"b": ["Verlening van het berat van het koninkrijk Midden-Hongarije aan Imre Thököly", "3cd8d51d"], "d": ["Imre Thököly, de protestantse Hongaarse edelman die tegen de Habsburgse druk in opstand kwam, werd vanaf april 1682 beschouwd als 'gekozen koning van Midden-Hongarije' en op 16 september bood de beylerbey van Boeda, İbrahim Pasja, hem de prinselijke insignes aan. Zo werd onder Osmaanse bescherming een nieuwe vazal-Hongaarse staat gevestigd. Deze interventie maakte de oorlog met Oostenrijk onvermijdelijk en startte de keten die leidde naar het Tweede Beleg van Wenen in het jaar daarop.", "6f7f5236"]},
"OLAYLAR_EK5:1684-08-06:0":{"b": ["Verlies van Lefkada (Santa Maura) aan Venetië", "e6905fee"], "d": ["De vloot van Venetië, dat zich bij de Heilige Liga had aangesloten, bezette na het beschieten van de stad het eiland Santa Maura (Lefkada) in de Ionische Zee. Doordat in hetzelfde jaar ook Preveza viel, werd de Osmaanse controle aan de monding van de Adriatische Zee gebroken. Deze verliezen waren de beginstappen van de campagne waarin Morosini binnen drie jaar de hele Morea zou veroveren.", "8fe34c55"]},
"OLAYLAR_EK5:1685-08-11:0":{"b": ["Verlies van Koroni aan Venetië", "2ed762bc"], "d": ["De Venetiaanse strijdkrachten onder bevel van Morosini namen de burcht Koroni aan de zuidwestpunt van het schiereiland Morea in; de stad zou hierna dertig jaar onder Venetiaans bestuur blijven. De val van Koroni was de eerste grote winst van de Venetiaanse campagne gericht op de verovering van de Morea. De burcht kon pas in 1715 door het Osmaanse leger onder bevel van Silâhdar Ali Pasja worden teruggenomen.", "506cf83e"]},
"OLAYLAR_EK5:1688-04-08:0":{"b": ["Herovering van Athene — terugtrekking van Venetië", "03393b46"], "d": ["Morosini, die in september 1687 de Akropolis bombardeerde en de Parthenon de lucht in liet vliegen, begreep nadat hij de winter in Athene had doorgebracht dat hij zich in de stad niet kon handhaven. Door een pestepidemie, bevoorradingsproblemen en het herstel van de Osmaanse strijdkrachten ontruimde het Venetiaanse garnizoen de stad en trok zich terug in de Morea. Athene keerde zo zonder strijd terug naar Osmaans bestuur, maar de verwoesting die de Parthenon had geleden kon niet worden hersteld.", "79c8586a"]},
"OLAYLAR_EK5:1688-10-20:0":{"b": ["Afslaan van het Venetiaanse beleg van Negroponte (Euboea)", "aae7e6a0"], "d": ["Morosini, die zich na de verovering van de Morea op de Egeïsche Zee richtte, probeerde Negroponte met een beleg van meer dan drie maanden in te nemen; maar tegenover de in de winter van 1687-1688 versterkte vestingwerken en het verzet van het garnizoen moest hij zich met zware verliezen terugtrekken. Deze mislukking stopte de Venetiaanse opmars in de Egeïsche Zee en schaadde Morosini's militaire aanzien. Negroponte zou ook bij Karlowitz in Osmaanse handen blijven.", "ea8430a3"]},
"OLAYLAR_EK5:1690-04-23:0":{"b": ["Verlies van de burcht Kanije aan Oostenrijk", "553b45f3"], "d": ["Kanije, dat sinds januari 1690 in de strakke blokkade van een Habsburgs leger van 60.000 man werd gehouden, ging na maandenlang zonder hulp weerstand te hebben geboden verloren door de overgaveovereenkomst die de laatste bewaker Mustafa Pasja ondertekende. Zo kwam een einde aan een negentig jaar durende Osmaanse heerschappij in de burcht die bekend stond om de legendarische verdediging van Tiryaki Hasan Pasja. Het verlies van Kanije was de ineenstorting van het laatste grote steunpunt van de Osmanen in het westen van Hongarije.", "dc630d57"]},
"OLAYLAR_EK5:1691-06-23:0":{"b": ["Troonsbestijging van Ahmed II", "52947b14"], "d": ["Na de dood van Süleyman II besteeg zijn negenenveertigjarige broer Ahmed II in Edirne de troon. Zijn regering viel samen met de zwaarste jaren van de oorlogen van de Heilige Liga; twee maanden na zijn troonsbestijging sneuvelde bij Slankamen grootvizier Fâzıl Mustafa Pasja. Daartegenover werd het in zijn tijd ingevoerde mâlikâne-stelsel een van de belangrijkste regelingen die de langetermijnstructuur van de Osmaanse financiën veranderde.", "d3441b14"]},
"OLAYLAR_EK5:1696-01-01:0":{"b": ["Inname van Basra door de Iraniërs", "a9cdf3a3"], "d": ["Terwijl de Osmaanse staat in het westen bezig was met de oorlogen van de Heilige Liga, werd Basra na de pestepidemie van 1690 geplunderd, eerst door sjeik Mani van de Muntafiq en daarna door Faraj Allah, de khan van Huwayza. Gebruik makend van deze verwarring namen de Iraniërs in 1696 de stad in en lieten in Basra een bewaker achter.", "2db76d27"]},
"OLAYLAR_EK5:1700-07-14:0":{"b": ["Verdrag van Constantinopel — Azak aan Rusland gelaten", "79db4724"], "d": ["In Karlowitz kon met Rusland slechts een wapenstilstand van twee jaar worden gesloten; de blijvende vrede werd in Constantinopel getekend na anderhalf jaar moeizame onderhandelingen. De Osmaanse staat liet de in 1696 verloren burcht Azak en de omliggende gebieden formeel aan Rusland, de Krim-khan gaf de jaarlijkse belasting op die hij van Moskou ontving. Daartegenover verkreeg Rusland het recht een permanente gezant in Constantinopel te hebben; zo werd de Russische aanwezigheid aan de noordkust van de Zwarte Zee juridisch bevestigd.", "a3a5a803"]},
"OLAYLAR_EK5:1701-01-01:0":{"b": ["Daltaban Mustafa Pasja nam Qurna en Basra terug", "7adb777d"], "d": ["Daltaban Mustafa Pasja, die na Karlowitz tot gouverneur van Bagdad en seraskier van Basra werd benoemd, trok met strijdkrachten uit Aleppo, Raqqa, Sivas en Karaman en een rivierenvloot die uit Birecik afdaalde naar het zuiden. De stamhoofden in de omgeving onderwierpen zich een voor een, de Iraanse bewaker van Basra, Dâvud Han, verliet de stad en Qurna en Basra kwamen opnieuw onder Osmaans bestuur.", "60abbe06"]},
"OLAYLAR_EK5:1704-01-01:0":{"b": ["Begin van het Kölemen (Mamelukken)-bestuur in Bagdad", "abe52618"], "d": ["Met de benoeming van Hasan Pasja van Georgische afkomst tot gouverneur van Bagdad begon in Irak een periode waarin in plaats van door het centrum benoemde gouverneurs een bestuurderselite die uit eigen slaven was gevormd, de overhand had. Met het gouverneurschap van Süleyman Pasja in 1749 vestigde het stelsel zich definitief en de Hoge Porte moest niet langer wie zij wilde, maar een van de kölemen die de invloed in handen hadden benoemen. Hoewel deze halfautonome structuur van nut was bij de verdediging van de Iraanse grens, verzwakte zij anderhalve eeuw lang de controle van het centrale gezag over Irak.", "7cf655d4"]},
"OLAYLAR_EK5:1705-07-12:0":{"b": ["Stichting van de Husseiniden-dynastie in Tunis", "cb1a98f9"], "d": ["In het gezagsvacuüm dat ontstond door de invasie van Tunis door Algerijnse strijdkrachten nam de sipahi-agha van Turkse afkomst Hüseyin b. Ali het beylik in handen en verkreeg legitimiteit door zijn trouw aan de Osmaanse sultan te betuigen. De dynastie die hij stichtte regeerde Tunis in de jaren 1705-1735 en 1756-1957; in de plaats van het ocak-bestuur kwam een beylikorde die van vader op zoon overging. Zo ontstond het eerste voorbeeld van dynastieke structuren in de Maghreb-ocaks die aan het centrum gebonden maar feitelijk autonoom waren.", "941c7858"]},
"OLAYLAR_EK5:1708-04-04:0":{"b": ["Inname van Oran en Mers el-Kébir op de Spanjaarden", "b67ce06a"], "d": ["De strijdkrachten van de beylerbey van het ocak van Algiers namen na een lang beleg Oran, dat twee eeuwen in handen van een Spaans garnizoen was, en de haven Mers el-Kébir in. Het was het grootste succes van de Maghreb-ocaks onder Osmaanse bescherming tegen Spanje in de westelijke Middellandse Zee en verzekerde de westelijke flank van Algiers. De stad zou in 1732 opnieuw door Spanje worden bezet, maar in 1792 definitief worden teruggenomen.", "33d9da74"]},
"OLAYLAR_EK5:1711-07-21:0":{"b": ["Verdrag van de Proet — herovering van Azak en Taganrog", "bac5d2a1"], "d": ["Het zevenartikelige verdrag dat werd ondertekend toen het aan de Proet omsingelde Russische leger zich overgaf, bepaalde de teruggave van de burcht Azak met zijn grond en munitie aan de Osmanen. De vestingen Taganrog, Kamenka en Yenikale zouden worden afgebroken en de partijen zouden in deze gebieden geen nieuwe burchten bouwen. De vloot- en basisorde die Peter I zestien jaar lang in Voronezj en Azak had opgebouwd, stortte in; Ruslands afdaling naar de Zwarte Zee werd ongeveer vijftig jaar uitgesteld.", "657d45ff"]},
"OLAYLAR_EK5:1711-07-29:0":{"b": ["Stichting van de Karamanli-dynastie in Tripolitanië", "e1105d4a"], "d": ["In Tripolitanië, uitgeput door de twisten van de ocak-agha's, nam de cavalerieofficier Ahmed Karamanlı het bestuur over en maakte zijn positie officieel met het beylerbeylik-berat dat hij van Constantinopel kreeg. Door toedoen van Ahmed Pasja, zijn zoon Mehmed Pasja en zijn kleinzoon Yûsuf Pasja ontstond een dynastie die van 1711 tot 1835 duurde; er ontstond een halfonafhankelijke structuur die haar eigen vloot bouwde en rechtstreeks verdragen met Europese staten sloot. Deze periode zou pas in 1835 eindigen met het rechtstreeks aan het centrum binden van de provincie.", "b1c3dd0a"]},
"OLAYLAR_EK5:1713-06-24:0":{"b": ["Verdrag van Edirne met Rusland", "14901a70"], "d": ["Nadat de beloften van de Proet niet werden nagekomen, werd nog twee keer oorlog verklaard, en uiteindelijk werd in Edirne een blijvende vrede ondertekend toen de Russen de verplichtingen aanvaardden. Het verdrag bevestigde de voorwaarden van de Proet; Rusland zou zich niet met Poolse zaken bemoeien, zich uit de Kozakkengebieden terugtrekken en de terugkeer van de Zweedse koning Karel 'Demirbaş' naar zijn land niet verhinderen. Het sluiten van het noordelijk front maakte het mogelijk dat de Osmaanse staat zich richtte op het Morea- en Venetiaanse front. Andere plaatsen die op dezelfde datum werden toegevoegd: Hotin.", "34010e06"]},
"OLAYLAR_EK5:1714-12-08:0":{"b": ["Oorlogsverklaring aan Venetië — voorbereiding van de Morea-veldtocht", "d970b122"], "d": ["In de Divan werd het oorlogsbesluit genomen met als redenen dat Venetië de Montenegrijnse rebellen steunde, Osmaanse koopvaardijschepen in beslag nam en de in Karlowitz verkregen Morea met zware belastingen drukte. De veldtocht die grootvizier Silâhdar Damad Ali Pasja voorbereidde, zou het jaar daarop in minder dan honderd dagen uitmonden in de herovering van het hele schiereiland Morea. Maar dit succes zou Oostenrijk in beweging brengen en in 1716 de deur openen naar een veel zwaardere oorlog.", "ef2edb5f"]},
"OLAYLAR_EK5:1715-06-05:0":{"b": ["İstendil (Tinos): overgave van het laatste Venetiaanse eiland in de Egeïsche Zee", "4abec891"], "d": ["De vloot die op weg was naar de Morea-veldtocht, ging voor anker voor İstendil (Tinos), het enige eiland dat Venetië nog in de Egeïsche Zee had. Het eiland, dat dankzij zijn Latijnse bevolking nog honderdvijftig jaar de Venetiaanse vlag voerde hoewel het Hertogdom Naxos in 1566 was gevallen, gaf zich na een kort beleg zonder bloedvergieten over. Zo werd de laatste Venetiaanse voetafdruk in de Egeïsche Zee gewist en werd de zee volledig een Osmaanse binnenzee.", "7b191aca"]},
"OLAYLAR_EK5:1715-07-20:0":{"b": ["Verovering van Nauplion — sleutelburcht van de Morea", "62a5808a"], "d": ["Nauplion, de Venetiaanse hoofdstad en sterkste vesting in de Morea, viel na het innemen van het bastion Palamidi na een negen dagen durend bombardement. Dat de burcht zo snel werd ingenomen, brak het verzet in de rest van het schiereiland. De herovering van de in Karlowitz verloren Morea werd hier feitelijk voltooid. Andere plaats die op dezelfde datum in de atlas van Venetië naar de Osmanen ging: Argos — volgt de abi-centrumketen van Nauplion (TDV anabolu; verklaarde benadering).", "8467e05c"]},
"OLAYLAR_EK5:1715-08-01:0":{"b": ["Overgave van Modon", "43faa909"], "d": ["Na de val van Nauplion werd de burcht Modon aan de zuidwestpunt van de Morea over land door het leger en over zee door de vloot belegerd en gaf zich snel over. Deze haven, die Venetië tweehonderd jaar lang in zijn campagnes in de oostelijke Middellandse Zee gebruikte, was het onvermijdelijke aanloppunt waar schepen water en proviand innamen. Het verlies maakte een einde aan de bewegingsvrijheid van de Venetiaanse vloot in de Egeïsche Zee.", "0d2c6d1a"]},
"OLAYLAR_EK5:1716-04-13:0":{"b": ["Oostenrijk en Venetië sloten een bondgenootschap — poort naar de Osmaans-Oostenrijkse oorlog van 1716-1718", "99511ca2"], "d": ["Nadat de Osmanen de Morea van Venetië hadden teruggenomen, sloot Oostenrijk, met de bewering dat het Verdrag van Karlowitz was geschonden, een bondgenootschap met Venetië; prins Eugenius vroeg in een brief aan de grootvizier om teruggave van de plaatsen die van Venetië waren genomen. In het overleg in het kamp van Davutpaşa werd op aandringen van grootvizier Ali Pasja Oostenrijk de oorlog verklaard en daartoe een fatwa van de sjeik-ul-islam verkregen.", "4a2089d7"]},
"OLAYLAR_EK5:1716-04-24:0":{"b": ["Grootvizier Ali Pasja trok ten strijde naar Oostenrijk", "2fbdce42"], "d": ["Na de oorlogsverklaring aan Oostenrijk trok de serdar-ı ekrem Ali Pasja met een leger van meer dan 100.000 man op naar Oostenrijk; de vloot koerste dezelfde zomer naar Korfoe. Het leger zou van Belgrado naar Varadin optrekken en bij de nederlaag begin augustus zou de grootvizier sneuvelen.", "02a5590b"]},
"OLAYLAR_EK5:1716-08-05:0":{"b": ["Nederlaag bij Petrovaradin (Varadin) — martelaarschap van Damad Ali Pasja", "265c1d81"], "d": ["Het Osmaanse leger dat via Belgrado de Donau overstak, ontmoette voor Petrovaradin de Oostenrijkse strijdkrachten onder bevel van prins Eugenius; hoewel de janitsarenaanval in de eerste golf de vijandelijke loopgraven forceerde, werden de gelederen verspreid met de ineenstorting van de cavalerievleugel. Grootvizier Silâhdar Damad Ali Pasja sneuvelde, in het voorhoofd getroffen, en het kamp en het artilleriepark vielen volledig in vijandelijke handen. Deze nederlaag, door de Osmaanse vekâyi'nâme's 'het jaar van Varadin' genoemd, was de eerste schakel in de keten die leidde tot het verlies van Temesvár en het jaar daarop van Belgrado.", "ad21a2c3"]},
"OLAYLAR_EK5:1716-08-20:0":{"b": ["Mislukking van het beleg van Korfoe", "b2aa7011"], "d": ["De seraskier van de Morea, Kara Mustafa Pasja, viel Korfoe over land aan en kapudan pasja Canım Hoca Mehmed Pasja met de vloot over zee; het eiland was de sleutelbasis van Venetië in de Adriatische Zee. Maar de uiterst sterke versterkingen van de burcht, de door de Venetiaanse vloot gebrachte versterkingen en het nieuws over de nederlaag aan het Donaufront leidden tot opheffing van het beleg. Dat Korfoe niet kon worden ingenomen doofde de stemming die was gerezen door de herovering van de Morea en verlegde het zwaartepunt van de oorlog naar Hongarije.", "4589579c"]},
"OLAYLAR_EK5:1716-10-13:0":{"b": ["Verlies van Temesvár (Timișoara) aan Oostenrijk", "27fe1365"], "d": ["Na de nederlaag bij Petrovaradin trok prins Eugenius rechtstreeks op Temesvár en de burcht werd na een beleg van meer dan veertig dagen bij verdrag overgegeven. De stad, die in 1552 onder Süleyman was veroverd en 164 jaar als beylerbeylik-centrum de oostelijke pijler van de Hongaarse verdediging was, ging zo verloren. Met de val van Temesvár ging het hele Banaat naar Oostenrijk en werd de Osmaanse grens naar het zuiden van de Donau geduwd. Andere plaatsen die op dezelfde datum in de atlas van de Osmanen naar de Habsburgers gingen: Csákóvár, Facset en Caransebeș (Karánşebeş) — met de overdracht van de provincie Temesvár (TDV timisvar; een plaatsniveaudag staat niet in de bron, abi-centrumketen, verklaarde benadering).", "a1408ad1"]},
"OLAYLAR_EK5:1716-11-16:0":{"b": ["Overgave van de burcht Haram (Nieuwe Palanka) aan Oostenrijk — de Donauoever van het Banaat ging verloren", "38ee4c6d"], "d": ["Mercy, de Oostenrijkse cavaleriegeneraal die na de val van Temesvár de opdracht kreeg de rest van het Banaat in te nemen, trok op 14 november naar Haram (Nieuwe Palanka) aan de Donau; toen hij op 16 november bij de burcht aankwam, gaf het Osmaanse garnizoen van 200 man zich over onder de voorwaarde dat het met de witte vlag vrij mocht vertrekken. Zo ging ook de Donaulijn van Zuid-Banaat, die sinds 1552 in Osmaanse handen was, naar Oostenrijk. Andere plaats die op dezelfde datum in de atlas van de Osmanen naar de Habsburgers ging: Versec — volgt de abi-centrumketen van Haram (Bánlaky 0019/1703; verklaarde benadering).", "5b54ecb0"]},
"OLAYLAR_EK5:1723-06-15:0":{"b": ["Oostelijke veldtocht: inname van Tbilisi en begin van de Iraanse oorlog", "78343dc2"], "d": ["Toen de Safawidische staat door de Afghaanse invasie instortte en Rusland afdaalde naar de Kaspische kusten, stuurde de Osmaanse staat een leger naar het oosten opdat het vacuüm niet geheel aan de Russische invloed zou toevallen. Tbilisi werd ingenomen en Georgië kwam onder Osmaans bestuur; daarna ging de opmars in de richting van Ganja, Revan en Nachitsjevan door. Deze veldtocht, gevoerd achter het vreedzame uiterlijk van het Tulpentijdperk, was het begin van een lang oostelijk avontuur dat dertien jaar zou duren en uiteindelijk zou eindigen met de teruggave van alles wat was gewonnen.", "5c412d91"]},
"OLAYLAR_EK5:1724-06-24:0":{"b": ["Verdrag van Constantinopel (Mukāsemenâme) — verdeling van Iran met Rusland", "fce8eec2"], "d": ["Om te voorkomen dat de Osmanen en Rusland tegenover elkaar kwamen te staan op het uiteenvallende Safawidische land, werd door bemiddeling van de Franse gezant een verdelingsverdrag ondertekend. De westelijke en zuidelijke kusten van de Kaspische Zee werden aan Rusland gelaten, de steden van Georgië, Shirvan, Azerbeidzjan en West-Iran aan de Osmaanse staat. Deze verdeling, die op papier een grote winst leek, zou kort daarna door de opkomst van Nadir Sjah feitelijk ongeldig worden. Volgens het verdrag werden de vruchtbare gebieden van Shirvan, zoals Shabran en Mushkur, aan de Russische kant gelaten (Çaycıoğlu, DergiPark).", "7b0b411b"]},
"OLAYLAR_EK5:1725-07-28:0":{"b": ["Inname van Tabriz — verovering van Azerbeidzjan", "e502a4f7"], "d": ["Tabriz, dat na de mislukte poging van een jaar eerder opnieuw werd belegerd, gaf zich na een straat voor straat gevoerde hevige strijd over aan het Osmaanse leger. Ook Marand, Maragheh en Sovukbulak (Mahabad), die aan de provincie Tabriz toebehoorden, kwamen onder Osmaans bestuur. In hetzelfde jaar werden ook Lori, Ganja, Ardabil en Khorramabad ingenomen en werden de gebieden die op grond van het Verdrag van Constantinopel aan de Osmanen toekwamen feitelijk bezet. Deze in het oosten bereikte uitgestrektheid was de verste grens sinds het tijdperk van het Verdrag van Ferhad Pasja; maar het behouden ervan legde een zware last op leger en schatkist.", "e0953563"]},
"OLAYLAR_EK5:1727-10-04:0":{"b": ["Verdrag van Hamadan — West-Iran bij de Osmanen gevoegd", "94a29dc3"], "d": ["Met het verdrag dat werd ondertekend met de Afghaanse heerser Ashraf Shah kwam een einde aan de vier jaar durende oorlog en werden de door de Osmaanse staat bezette gebieden van West-Iran juridisch erkend. Ashraf Shah aanvaardde in ruil daarvoor het kalifaat van de Osmaanse sultan en nam op zich dat in Iran de khutba in naam van de sultan zou worden gelezen. Deze diplomatieke overwinning was van korte duur; het tegenoffensief dat Nadir Sjah in 1730 begon, zou de winsten van het verdrag binnen enkele jaren wegvagen.", "fd0174b9"]},
"OLAYLAR_EK5:1732-01-08:0":{"b": ["Verdrag van Ahmed Pasja — teruggave van het grootste deel van West-Iran", "590d839f"], "d": ["Na de overwinning van Nadir Sjah bij Malayer en de opeenvolgende Iraanse offensieven ondertekende de gouverneur van Bagdad, Ahmed Pasja, zonder het centrum te raadplegen een vredestekst. Volgens het verdrag werd de Aras als grens aanvaard; de steden van West-Iran zoals Hamadan, Kermanshah, Ardalan, Ardabil en Tabriz werden aan Iran teruggegeven, Ganja en Tbilisi bleven Osmaans. Deze tekst, die in Constantinopel met verontwaardiging werd ontvangen, werd ook door Nadir Sjah onvoldoende bevonden en nog voordat het jaar 1732 voorbij was, laaide de oorlog weer op. De atlas beschouwt ook Kotur, dat de keten van Khoy volgt, op deze dag als van de Osmanen naar de Safawiden gegaan (TDV hoy; een voor Kotur specifieke dag staat niet in de bron — verklaarde benadering).", "fdaa1e6f"]},
"OLAYLAR_EK5:1732-07-01:0":{"b": ["Opnieuw verlies van Oran aan Spanje", "20485027"], "d": ["De grote landingsvloot die de Spaanse koning Filips V stuurde, kwam onder bevel van graaf Montemar voor Oran en nam de stad terug door de strijdkrachten van het ocak van Algiers te verslaan. De haven, die vierentwintig jaar eerder was veroverd, zou zestig jaar lang opnieuw in handen van een Spaans garnizoen blijven. Dit verlies, dat de grenzen van de macht van de Maghreb-ocaks in de westelijke Middellandse Zee toonde, kon pas in 1792 met de definitieve verovering van Oran worden goedgemaakt.", "b255a8da"]},
"OLAYLAR_EK5:1733-05-01:0":{"b": ["Hervorming van het Humbaracı-korps naar Europees model en stichting van de Humbarahâne", "d980cf2a"], "d": ["Humbaracı Ahmed Pasja, van Franse afkomst, die in Osmaanse dienst was getreden, maakte met de steun van grootvizier Hekimoğlu Ali Pasja het humbaracı-korps tot een betaalde, naar Europese wijze georganiseerde eenheid. Aan driehonderd uit Bosnië gerekruteerde soldaten werd regelmatig onderwijs gegeven op basis van rekenkunde en meetkunde; voor organisatie, uitrusting en pensioen werden nieuwe reglementen opgesteld en met moderne techniek werden honderd bommenwerpers en vijftigduizend bommen vervaardigd. De Humbarahâne, waar meetkunde werd onderwezen, geldt als de eerste kern van modern militair ingenieursonderwijs bij de Osmanen.", "181b7161"]},
"OLAYLAR_EK5:1736-09-01:0":{"b": ["Verdrag van Constantinopel — Zuid-Kaukasus aan Iran gelaten", "8c205aab"], "d": ["De vier jaar durende tweede Iraanse oorlog eindigde met het verdrag dat werd ondertekend na de nederlaag bij Arpaçay en het verlies van Ganja en Tbilisi. De Osmaanse staat trok zich terug uit alle sinds 1723 veroverde gebieden in Zuid-Kaukasus en West-Iran en de grens keerde terug naar de lijn van Qasr-i Shirin van 1639. Van de dertien jaar durende oostelijke veldtochten bleef een zware financiële last en een lege schatkist over; daartegenover was het sluiten van het oostelijk front van vitaal belang voor de nieuwe oorlog die met Rusland begon.", "bcb0cbe8"]},
"OLAYLAR_EK5:1737-07-11:0":{"b": ["Val van de burcht Özi (Očakov) aan de Russen", "f93e61f3"], "d": ["Het Russische leger onder bevel van maarschalk Münnich belegerde de burcht Özi aan de Dnjepr-monding; toen het munitiemagazijn ontplofte, stortte de verdediging in en de burcht viel met groot verlies aan mensenlevens. Het verlies van Özi, dat gold als het slot van de noordwestelijke kust van de Zwarte Zee, opende de weg naar de Krim voor de Russen en veroorzaakte grote paniek in Constantinopel. De burcht zou het jaar daarop door epidemie en bevoorradingsproblemen door de Russen worden ontruimd en weer aan de Osmanen komen.", "479e0090"]},
"OLAYLAR_EK5:1737-08-04:0":{"b": ["Overwinning bij Banja Luka — bevrijding van Bosnië", "f603865a"], "d": ["Toen Oostenrijkse strijdkrachten Bosnië binnentrokken en Banja Luka belegerden, snelde de gouverneur van Bosnië, Hekimoğlu Ali Pasja, met strijdkrachten die hij uit de lokale bevolking had verzameld te hulp en bracht de numeriek superieure vijand een zware nederlaag toe. Deze overwinning liet het Oostenrijkse plan om Bosnië te bezetten al bij de eerste zet instorten en het noorden van de provincie werd volledig teruggenomen. Banja Luka werd een van de keerpunten die het moreel herstelden van het Osmaanse leger, dat na 1683 tegenover Oostenrijk voortdurend moest terugtrekken.", "81c1850e"]},
"OLAYLAR_EK5:1739-07-22:0":{"b": ["Overwinning bij Hisarcık (Grocka) — opening van de weg naar Belgrado", "2101cdff"], "d": ["Het Oostenrijkse leger, dat optrok om Belgrado te beschermen, werd in een nauwe pas aan de Donau in een hinderlaag gelokt en leed in de gevechten die de hele dag duurden zware verliezen. Terwijl de strijdkrachten van maarschalk Wallis in wanorde naar Belgrado terugtrokken, bereikte het Osmaanse leger de voet van de burcht en begon het beleg. Hisarcık was de meest beslissende veldoverwinning tegen Oostenrijk sinds Karlowitz en leidde rechtstreeks tot de herovering van Belgrado.", "5811893a"]},
"OLAYLAR_EK5:1739-10-03:0":{"b": ["Verdrag van Niš — vrede met Rusland, neutralisering van Azak en stoppen van de Krim-aanvallen", "674f974e"], "d": ["Rusland, dat alleen kwam te staan toen Oostenrijk in Belgrado in vrede toestemde, moest door bemiddeling van de Franse gezant Villeneuve de oorlog beëindigen. De vestingwerken van de burcht Azak werden afgebroken en het gebied werd tot neutraal terrein tussen de twee staten verklaard; Rusland aanvaardde de voorwaarde geen oorlogs- en koopvaardijschepen op de Zwarte Zee te hebben. Zo werd het streven van Rusland naar de zee nog een generatie uitgesteld en stond de Osmaanse staat in de 18e eeuw voor de laatste keer winstgevend van de tafel op.", "7ca0d614"]},
"OLAYLAR_EK5:1739-12-12:0":{"b": ["Özi keerde terug uit Russische bezetting: na afbraak overgegeven met de vrede van 1739", "7ecc2bef"], "d": ["De Russen hadden Özi op 11 juli 1737 ingenomen. Krachtens de vrede met Rusland van 1739 werd de burcht, nadat de vestingwerken waren afgebroken, opnieuw aan de Osmanen overgedragen; de Osmanen hielden Özi tot 1788, vóór het Verdrag van Iași.", "39ee6708"]},
"OLAYLAR_EK5:1743-10-23:0":{"b": ["Verdediging van Mosul — Nadir Sjah teruggeslagen", "c03ffbc1"], "d": ["Nadir Sjah, die Kirkuk en Erbil had ingenomen en voor Mosul was gekomen, beschoot de stad veertig dagen lang en voerde opeenvolgende algemene aanvallen uit. De verdediging die gouverneur Hüseyin Pasja al-Jalili voerde door ook de bevolking van de stad te bewapenen, dwong het Iraanse leger met zware verliezen het beleg op te heffen. Dat Mosul standhield voorkwam het verlies van heel Irak en versterkte de invloed van de familie Jalili in de stad een eeuw lang.", "b9f67e29"]},
"OLAYLAR_EK5:1744-01-01:0":{"b": ["Bondgenootschap van Dir'iyya — stichting van het eerste Saoedische emiraat in Nejd", "188751bf"], "d": ["Emir Muhammad b. Saud, die de uit Uyayna verdreven geleerde Muhammad b. Abd al-Wahhab in Dir'iyya onder zijn bescherming nam, sloot met hem een bondgenootschap waarbij de politieke autoriteit in dienst van de religieuze oproep werd gesteld. Dit akkoord begon een nieuwe geschiedenis voor de familie Saud en bracht de verspreide oase-emiraten van Nejd samen rond één beweging. Deze macht, die in een halve eeuw tot Kerbela, Mekka en Medina zou reiken, zou de Osmaanse staat dwingen zijn heerschappij in de Hidjaz te verdedigen.", "6843c874"]},
"OLAYLAR_EK5:1746-09-04:0":{"b": ["Verdrag van Kerden — einde van de Osmaans-Iraanse oorlogen", "1d3a919e"], "d": ["Met het verdrag dat werd ondertekend na de vier jaar durende laatste oorlog werd de grens van Qasr-i Shirin van 1639 ongewijzigd vernieuwd; geen van beide partijen behaalde gebiedswinst. Nadir Sjah's dringende eis tot erkenning van het Ja'farisme als vijfde rechtsschool bleef zonder tegenprestatie; daartegenover werd besloten dat Iraanse pelgrims vrij de hadj mochten verrichten en tot wederzijdse uitwisseling van gezanten. De meer dan twee eeuwen durende Osmaans-Iraanse oorlogen kwamen zo feitelijk ten einde; deze grens is tot op heden grotendeels behouden gebleven.", "2a089331"]},
"OLAYLAR_EK5:1754-12-13:0":{"b": ["Overlijden van Mahmud I en troonsbestijging van Osman III", "30203700"], "d": ["Mahmud I, die tijdens zijn regering van vierentwintig jaar de met het Verdrag van Belgrado verloren gebieden terugkreeg en de hervorming van het Humbaracı-korps steunde, stierf terwijl hij terugkeerde van het vrijdagse selamlık. Zijn broer Osman III, die tot zijn achtenvijftigste in de kooi had geleefd, volgde hem op. Een korte en onrustige regering begon; onder Osman III, die in drie jaar zes grootviziers verving, heerste een duidelijke stilstand in de staatszaken.", "8bdf7c4e"]},
"OLAYLAR_EK5:1757-10-30:0":{"b": ["Overlijden van Osman III en troonsbestijging van Mustafa III", "3ac10f85"], "d": ["Na een regering van drie jaar besteeg met het overlijden van Osman III Mustafa III de troon, die openstond voor hervormingsideeën en grote belangstelling toonde voor staatszaken. De nieuwe sultan probeerde, steunend op de ervaring van grootvizier Koca Râgıb Pasja, de financiën te herstellen en het leger te vernieuwen; in deze tijd werd het snelle artilleriekorps van baron de Tott gesticht. Maar de Russische oorlog van 1768 zou alle winsten van de regering van zeventien jaar overschaduwen.", "2d13aff2"]},
"OLAYLAR_EK5:1768-10-08:0":{"b": ["Oorlogsverklaring aan Rusland — incident bij Balta en begin van de oorlog van 1768-1774", "9c6aabe0"], "d": ["Nadat Russische en Kozakkeneenheden die de Confederatie van Bar in Polen achtervolgden het stadje Balta aan de Osmaanse grens overvielen en in brand staken, nam de Divan het oorlogsbesluit en werd de Russische gezant in Yedikule opgesloten. De oorlog, die zonder serieuze militaire voorbereiding en zes maanden van tevoren werd aangekondigd, verliep al vanaf het begin slecht. Deze zes jaar durende strijd zou met de overval bij Çeşme, de nederlaag bij Kagul en de bezetting van de Krim veranderen in een van de zwaarste reeksen nederlagen uit de Osmaanse geschiedenis.", "18bfa4d5"]},
"OLAYLAR_EK5:1769-09-20:0":{"b": ["Verlies van de burcht Chocim aan de Russen", "66d43ea4"], "d": ["Nadat twee pogingen van het Russische leger onder prins Galitzine werden afgeslagen, trok het leger zich terug na de nederlaag van de grootvizier tussen Kamjanets en Chocim en ontruimden de bewakers de burcht. Dat de sterkste Osmaanse vesting ten noorden van de Donau zonder verzet verloren ging, opende de poorten van Walachije en Moldavië voor de Russen. De twee vorstendommen werden in hetzelfde jaar bezet; Chocim kon pas in 1774 met het Verdrag van Küçük Kaynarca worden teruggenomen.", "1d0b219f"]},
"OLAYLAR_EK5:1770-08-01:0":{"b": ["Nederlaag in de vlakte van Kagul (Kartal)", "6f408eaf"], "d": ["Drie weken na het verbranden van de vloot bij Çeşme werd het belangrijkste Osmaanse leger aan de Donau in de vlakte van Kagul uiteengeslagen tegenover de veel kleinere maar gedisciplineerde troepen van maarschalk Rumjantsev. Het kamp, de bagage en honderden kanonnen vielen in vijandelijke handen; de vluchtende eenheden leden bij het oversteken van de Donau zware verliezen. De vernietiging in dezelfde zomer van zowel de vloot als het landleger leidde tot de opeenvolgende val van Kilia, Akkerman, İsmail en Bender en tot de bezetting van de Krim.", "0fd97052"]},
"OLAYLAR_EK5:1771-07-01:0":{"b": ["Russische bezetting van het Krim-schiereiland", "217837b0"], "d": ["De Russische legers, die een jaar eerder Bucak hadden ingenomen, trokken onder bevel van prins Dolgoroekov door de Or-poort en vielen het hele Krim-schiereiland binnen. De khan werd van de troon gezet en de pro-Russische Sâhib Giray werd aan het hoofd geplaatst, waarmee de eerste stap werd gezet om het khanaat van de Osmanen los te scheuren. Het verlies van de Krim, die drie eeuwen het noordelijke schild van de Osmanen was geweest, was het begin van het proces van onafhankelijkheid in 1774 en van rechtstreekse annexatie in 1783.", "952270d8"]},
"OLAYLAR_EK5:1774-01-21:0":{"b": ["Overlijden van Mustafa III en troonsbestijging van Abdülhamid I", "42cba8e2"], "d": ["In plaats van Mustafa III, die op het meest kritieke moment van de Russische oorlog stierf, besteeg zijn negenenveertigjarige broer Abdülhamid I, die drieënveertig jaar in de kooi van het paleis had doorgebracht, de troon. De nieuwe sultan, die een van de moeilijkste periodes van de staat overnam, moest in hetzelfde jaar het hoofd bieden aan de zware voorwaarden van het te ondertekenen Verdrag van Küçük Kaynarca. Zijn vijftien jaar durende regering zou worden doorgebracht met het verlies van de Krim en een nieuwe Russische oorlog en eindigen met de beroerte die hij in 1789 kreeg toen hij het nieuws van de val van Özi las.", "05963836"]},
"OLAYLAR_EK5:1774-06-25:0":{"b": ["Nederlaag bij Kozludzha — nederlaag die leidde naar Küçük Kaynarca", "8e0542f9"], "d": ["De Osmaanse strijdkrachten die zich voor Şumnu verzamelden, werden bij Kozludzha verslagen door de gecombineerde colonnes van Soevorov en Kamenski en het grootste deel van het leger viel uiteen. Met deze nederlaag was er op de Balkan geen macht meer die weerstand kon bieden; de Russische voorhoede belegerde Şumnu en het hoofdkwartier van de grootvizier kwam onder dreiging. Dat er binnen een maand aan tafel werd gezeten in Küçük Kaynarca en buitengewoon zware voorwaarden werden aanvaard, is rechtstreeks het gevolg van deze nederlaag.", "6721d6e3"]},
"OLAYLAR_EK5:1775-05-07:0":{"b": ["Overdracht van Boekovina (Noord-Moldavië) aan Oostenrijk", "190f9caa"], "d": ["Oostenrijk, dat gebruik maakte van de zwakte die Küçük Kaynarca had veroorzaakt, eiste Boekovina, de regio die Moldavië met Transsylvanië verbindt, en verkreeg dit gebied zonder oorlog door dreiging en omkoping. Het verlies van deze vruchtbare en strategische regio ten zuidwesten van Chocim splitste het woiwodschap Moldavië feitelijk in tweeën. Deze overdracht, waarbij geen schot werd gelost, werd beschouwd als een van de duidelijkste tekenen dat de Osmaanse staat zijn afschrikkende kracht had verloren. Met de overdracht van Boekovina in 1775 gingen Suceava en Czernowitz naar Oostenrijk (dag niet bevestigd).", "93bbc1f7"]},
"OLAYLAR_EK5:1776-04-16:0":{"b": ["Bezetting van Basra door Iran", "0161e709"], "d": ["Sadık Khan, broer van de Zand-heerser Karim Khan, nam Basra in na een beleg van een jaar en de Osmaanse staat verloor zijn belangrijkste haven in de Perzische Golf. De bezetting trof rechtstreeks de Indische handelsroute, de inkomsten uit dadels en parels en de zuidelijke verdediging van Irak. De stad kon pas in 1779, tijdens de troonstrijd in Iran na de dood van Karim Khan, worden teruggenomen.", "838306ba"]},
"OLAYLAR_EK5:1779-03-21:0":{"b": ["Tenkihname van Aynalıkavak — tijdelijke overeenkomst over de Krim", "9b3b0468"], "d": ["De twee staten, die door de kwestie wie aan het hoofd van het Krim-khanaat zou komen aan de rand van oorlog waren gekomen, ondertekenden door bemiddeling van Frankrijk in het Aynalıkavak-paviljoen een verklaringstekst. Rusland aanvaardde zijn soldaten uit de Krim terug te trekken en de Osmaanse staat het khanaat van de pro-Russische Şâhin Giray te erkennen; het religieuze kalifaatsrecht van de sultan over de Krim werd bevestigd. Dit kwetsbare evenwicht, dat vier jaar zou duren, zou in 1783 volledig instorten toen Rusland het schiereiland rechtstreeks annexeerde.", "8a428802"]},
"OLAYLAR_EK5:1787-08-16:0":{"b": ["Oorlogsverklaring aan Rusland — Osmaans-Russische oorlog van 1787-1792 begon", "3bfb870c"], "d": ["Na de pronkerige reis van Catharina II naar de Krim en haar bescherming van Georgië nam de Divan het oorlogsbesluit met het doel de annexatie ongedaan te maken en werd de Russische gezant opnieuw in Yedikule opgesloten. Maar het leger was niet gereed, de schatkist was leeg en de zoektocht naar bondgenoten had niets opgeleverd. De oorlog, die vijf jaar zou duren, zou eindigen met de val van Özi met een bloedbad, het verlies van İsmail en de zware voorwaarden van het Verdrag van Iași.", "80a26d8f"]},
"OLAYLAR_EK5:1788-02-09:0":{"b": ["Toetreding van Oostenrijk tot de oorlog — strijd aan twee fronten", "ae912290"], "d": ["Krachtens het geheime bondgenootschap dat het in 1781 met Rusland had gesloten, verklaarde de Oostenrijkse keizer Jozef II de oorlog aan de Osmaanse staat en trok in de richting van Belgrado en Bosnië. Het Osmaanse leger moest plotseling aan twee fronten tegelijk vechten: Rusland in het noorden en Oostenrijk in het westen. Ondanks overwinningen op de Oostenrijkers bij Lazarethane, Mehadia en Şebeş zou met het verlies van Belgrado in 1789 ook het westelijk front instorten.", "402d5acd"]},
"OLAYLAR_EK5:1790-01-31:0":{"b": ["Osmaans-Pruisisch bondgenootschap", "03b88e51"], "d": ["Selim III, die zodra hij op de troon kwam bondgenoten in Europa zocht, ondertekende met Pruisen een bondgenootschapsverdrag dat wederzijdse hulp voorzag; Pruisen verbond zich ertoe Rusland en Oostenrijk de oorlog te verklaren en de Osmaanse staat om geen vrede te sluiten voordat de Krim was teruggenomen. Dit was de eerste echte wederzijdse bondgenootschapstekst die in de Osmaanse geschiedenis met een Europese staat werd ondertekend en toonde dat het klassieke begrip 'geen bondgenootschap met de ongelovigen' was verlaten. Pruisen trad niet in de oorlog, maar baande door Oostenrijk tot vrede te dwingen de weg voor het Verdrag van Sistova.", "de29f327"]},
"OLAYLAR_EK5:1790-12-22:0":{"b": ["Val en bloedbad van de burcht İsmail", "6a296b0c"], "d": ["De burcht İsmail, die gold als de sterkste vesting van de Donaudelta, werd in één dag ingenomen met een bloedige algemene aanval van generaal Soevorov; de bezetting en de bevolking van de stad werden grotendeels over de kling gejaagd. Dit bloedbad, dat in Europa grote weerklank vond, veroorzaakte een diepe schok in de Osmaanse publieke opinie en brak de ruggengraat van de Donau-verdedigingslinie. De burcht zou een jaar later met het Verdrag van Iași worden teruggenomen, maar het lot van de oorlog was dan al bepaald.", "225351fb"]},
"OLAYLAR_EK5:1791-08-04:0":{"b": ["Verdrag van Sistova — afsluiting van het Oostenrijkse front", "58741f1d"], "d": ["Dankzij de druk van Pruisen en het feit dat de Franse Revolutie Oostenrijk in het westen bezighield, kwamen de twee staten tot vrede op basis van de grenzen van vóór de oorlog. Oostenrijk gaf alle bezette plaatsen, ook Belgrado, terug; de Osmaanse staat aanvaardde alleen kleine correcties aan de Kroatische grens. Dat het westelijk front onder deze voorwaarden werd gesloten, stelde de Osmaanse staat in staat al zijn kracht tegen Rusland te verzamelen en beperkte het verlies bij het Verdrag van Iași. Met deze correcties aan de Kroatische grens gingen Cetin (Cetingrad) en Drežnik Grad van de Osmanen naar de Habsburgers (TDV zistovi-antlasmasi; Korić 2016, n. 118, artikel 4). Orsova (Oud-Orsova) is de enige plaats die niet werd teruggegeven (Bánlaky 0019/1796); de atlas schrijft de juridische overdracht op deze dag (feitelijke bezetting 16 april 1790).", "83845e51"]},
"OLAYLAR_EK5:1792-01-10:0":{"b": ["Verdrag van Iași — definitief verlies van de Krim en grens aan de Dnjestr", "a56fd194"], "d": ["Met het verdrag dat aan het einde van de vijf jaar durende oorlog werd ondertekend, werd de Dnjestr (Turla) als grens aanvaard; de linkeroever van de rivier ging naar Rusland, de rechteroever bleef Osmaans, en Özi met omgeving ging definitief verloren. De Osmaanse staat gaf de hoop op herovering van de Krim volledig op en erkende de annexatie van 1783 juridisch; Walachije en Moldavië werden teruggegeven met een belastingvrijstelling van twee jaar. Met de aanvaarding ook van de verplichting tot een oorlogsvergoeding van twaalf miljoen kuruş werd het noorden van de Zwarte Zee blijvend aan Rusland gelaten. Andere plaatsen die op dezelfde datum werden toegevoegd: İsmail.", "277ee99d"]},
"OLAYLAR_EK5:1795-03-01:0":{"b": ["Feitelijke heerschappij van Pazvandoğlu Osman in Vidin", "0ce70361"], "d": ["Pazvandoğlu Osman, die in opstand kwam tegen de ordeningen van de Nizâm-ı Cedîd, liet de gouverneur van Vidin vluchten, nam de stad in en versterkte die met diepe grachten langs de Donau. In 1797, op het hoogtepunt van zijn macht, verzamelde hij een strijdmacht van bijna tachtigduizend man en bracht Nikopol, Sistova, Rusçuk, Sofia en Niš onder zijn controle; hij presenteerde zich niet als rebel maar als hervormer. Het maandenlange beleg van de Hoge Porte in 1798-1799 bleef zonder resultaat en hij regeerde tot zijn dood in 1807 halfonafhankelijk in Noord-Bulgarije.", "b0acf80b"]},
"OLAYLAR_EK5:1795-09-01:0":{"b": ["Opening van de Mühendishâne-i Berrî-i Hümâyun", "e9a3a34b"], "d": ["Om artillerie-, genie- en cartografische officieren voor het Nizâm-ı Cedîd-leger op te leiden werd in Hasköy de landingenieursschool geopend; zij was het equivalent bij het landleger van de in 1773 gestichte Marine-ingenieursschool. Op het programma stonden algebra, meetkunde, mechanica, vestingbouw en ballistiek, en wiskunde- en artilleriewerken werden uit Europese talen vertaald. Deze school, die als de wortel van het moderne ingenieursonderwijs in Turkije wordt beschouwd, geldt als het begin van de huidige Technische Universiteit van Istanbul.", "ff1a8344"]},
"OLAYLAR_EK5:1798-09-09:0":{"b": ["Oorlogsverklaring aan Frankrijk en bondgenootschap met Rusland en Engeland", "80e95bd7"], "d": ["Na de bezetting van Egypte door Napoleon verklaarde de Osmaanse staat Frankrijk de oorlog en verbrak daarmee de traditionele Franse vriendschap van twee en een halve eeuw. In hetzelfde proces sloot zij voor het eerst in haar geschiedenis een bondgenootschap met Rusland en liet de Russische vloot door de Zeestraten naar de Middellandse Zee varen; daarna werd ook een bondgenootschap met Engeland ondertekend. Dankzij deze bondgenootschappen werden de Ionische eilanden op de Fransen veroverd, maar het openstellen van de Zeestraten voor een buitenlandse vloot vormde een precedent dat later een zware prijs zou hebben.", "7d8a9e45"]},
"OLAYLAR_EK5:1799-05-20:0":{"b": ["Verdediging van Akko — Napoleon teruggeslagen", "56b5c45b"], "d": ["Napoleon, die van Egypte naar Syrië oprukte, belegerde Akko en voerde twee maanden lang opeenvolgende aanvallen uit; de stad werd verdedigd door Cezzâr Ahmed Pasja met steun van de Britse vloot en de uit Constantinopel gezonden Nizâm-ı Cedîd-troepen. Napoleon, die het beleg moest opheffen en zich naar Egypte moest terugtrekken, begroef zijn droom van uitbreiding naar het oosten voor deze muren. Het nieuws werd in Constantinopel met grote vreugde ontvangen en gold als bewijs dat het pas gevormde getrainde leger zijn eerste serieuze proef had doorstaan.", "78b85f0c"]},
"OLAYLAR_EK5:1801-04-01:0":{"b": ["Aanval van de wahhabieten op Kerbela", "522341ed"], "d": ["De wahhabitische strijdkrachten die uit Nejd vertrokken, trokken Kerbela binnen, plunderden de stad, verwoestten het mausoleum van Imam Hoessein en doodden meer dan drieduizend mensen. De kölemen-gouverneurs van de Osmaanse staat in Irak konden de aanval niet voorkomen; het voorval wekte zowel in Iran als in Constantinopel grote reacties. Deze aanval was de aankondiging dat de Saoedische beweging niet langer een oase-emiraat was maar een regionale macht die de heilige steden van de Osmanen bedreigde.", "f571ab30"]},
"OLAYLAR_EK5:1801-10-09:0":{"b": ["Ontruiming van Egypte door de Fransen", "00cfdc8c"], "d": ["Als gevolg van de gezamenlijke operatie van Osmaanse en Britse strijdkrachten over land en over zee werden eerst Caïro en daarna Alexandrië overgenomen en de Franse strijdkrachten per schip naar hun land gezonden. Terwijl de drie jaar durende bezetting eindigde, keerde Egypte op papier terug naar Osmaans bestuur, maar de strijd om de heerschappij tussen de Mamelukkenbeys en de Albanese troepen dreef het land in chaos. Dit vacuüm zou binnen enkele jaren de bodem bereiden voor de opkomst van Mehmed Ali van Kavala.", "acaf7e40"]},
"OLAYLAR_EK5:1802-06-25:0":{"b": ["Verdrag van Parijs — herstel van de vrede met Frankrijk", "1b76991f"], "d": ["Met het verdrag dat na de ontruiming van Egypte werd ondertekend, eindigde de oorlogstoestand tussen de Osmaanse staat en Frankrijk formeel en werden de oude capitulaties vernieuwd. Franse koopvaardijschepen mochten de Zwarte Zee binnenvaren; daartegenover erkende Frankrijk de Osmaanse territoriale integriteit. Het herstel van de vrede gaf het buitenlands beleid van Selim III, dat tussen Rusland en Engeland klem zat, opnieuw bewegingsruimte.", "367c616e"]},
"OLAYLAR_EK5:1803-02-01:0":{"b": ["Inname van Ta'if door de wahhabieten", "7b791359"], "d": ["De wahhabitische strijdkrachten onder bevel van Saud b. Abd al-Aziz belegerden en plunderden bij de eerste zet tegen de Hidjaz Ta'if; de stad viel als eerste poort naar het heilige land. Voor de Osmaanse sultan, die de titel van beschermheer van de Haramain droeg, was dit een slag die de legitimiteit van het sultanaat rechtstreeks aan het wankelen bracht. Twee en een halve maand later zou hetzelfde leger tegen Mekka optrekken.", "289d52ef"]},
"OLAYLAR_EK5:1803-04-30:0":{"b": ["Eerste inname van Mekka door de wahhabieten", "21157c05"], "d": ["Twee en een halve maand na de val van Ta'if trokken de wahhabitische strijdkrachten Mekka binnen, verwoestten de mausoleums en vestigden een orde volgens hun opvatting; sjerief Ghalib moest zich terugtrekken naar Jeddah. Het afsluiten van de pelgrimsroutes weerklonk in de hele islamitische wereld en dwong Constantinopel militaire hulp te vragen aan de gouverneur van Egypte, Mehmed Ali. Deze eerste heerschappij zou slechts drie maanden duren.", "7194e460"]},
"OLAYLAR_EK5:1803-08-06:0":{"b": ["Sjerief Ghalib nam Mekka terug", "83d08dff"], "d": ["Sjerief Ghalib, die zich naar Jeddah had teruggetrokken, belegerde Mekka met de strijdkrachten die hij had verzameld en nam na een beleg van vijfentwintig dagen de stad terug op de wahhabieten; de khutba werd opnieuw in naam van de Osmanen gelezen. Ook deze tweede heerschappij zou niet blijvend zijn: de Saoedische strijdkrachten zouden de stad in 1806 opnieuw innemen.", "8c15c19e"]},
"OLAYLAR_EK5:1804-02-14:0":{"b": ["Begin van de Eerste Servische Opstand", "0f6e8767"], "d": ["Nadat de opstandige janitsaren-deys die in Belgrado de macht hadden gegrepen de Servische notabelen in groten getale hadden vermoord, begon onder leiding van Karađorđe een gewapend verzet. De beweging, die aanvankelijk loyaal aan de sultan bleef en alleen tegen de deys gericht was, veranderde snel in een nationale opstand die autonomie en onafhankelijkheid eiste. De Servische strijdkrachten namen in 1806 Belgrado in; deze opstand werd de eerste schakel van de nationalistische onafhankelijkheidsbewegingen op de Balkan.", "07d5d6c6"]},
"OLAYLAR_EK5:1805-06-01:0":{"b": ["Bezetting van Medina door de wahhabieten", "84e310d7"], "d": ["Na Mekka kwam ook Medina in handen van de wahhabitische strijdkrachten; de schat van de Rawda-i Mutahhara werd verdeeld en de gekoepelde mausoleums in de stad werden verwoest. Zo ontsnapten beide heilige steden tegelijk aan Osmaanse controle en konden de pelgrimskaravanen uit Damascus en Egypte jarenlang niet vertrekken. Medina kon pas zeven jaar later, in 1812, worden teruggenomen door het Egyptische leger onder bevel van Tusun Pasja, zoon van Mehmed Ali Pasja.", "b8d034e6"]},
"OLAYLAR_EK5:1806-12-22:0":{"b": ["Begin van de oorlog met Rusland (Osmaans-Russische oorlog van 1806-1812) en sluiting van de Zeestraten", "ea170804"], "d": ["Nadat Selim III, die zich na de overwinning van Napoleon bij Austerlitz tot Frankrijk had genaderd, de woiwoden van Walachije en Moldavië ondanks de Russische druk afzette, bezetten de Russische legers de twee vorstendommen en begon de oorlog. De Osmaanse staat sloot de Zeestraten voor de Russische vloot; als antwoord stelde Engeland zich aan de zijde van Rusland en zond een vloot naar Constantinopel. Deze zes jaar durende oorlog zou, verweven met de Kabakçı-opstand en de afzetting van Selim III, in het Verdrag van Boekarest van 1812 eindigen met het verlies van Bessarabië.", "901537a4"]},
"OLAYLAR_EK5:1807-02-20:0":{"b": ["Komst van de Britse vloot voor Constantinopel (operatie-Duckworth)", "195bb58f"], "d": ["Engeland, dat de Osmaanse staat wilde dwingen de band met Frankrijk te verbreken, liet de vloot onder bevel van admiraal Duckworth door de Dardanellen varen en voor Constantinopel voor anker gaan. Mede onder leiding van de Franse gezant Sébastiani kwam de bevolking van Constantinopel in actie, de kustbatterijen werden binnen enkele dagen versterkt en de vloot moest zich terugtrekken zonder de stad te kunnen beschieten; op de terugweg leed zij bij de Dardanellen zware verliezen. Dat de hoofdstad voor het eerst zo van dichtbij door een buitenlandse vloot werd bedreigd, plaatste de kwestie van de Zeestraten in het middelpunt van de Europese diplomatie.", "bf71116c"]},
"OLAYLAR_EK5:1809-01-05:0":{"b": ["Verdrag van Kale-i Sultaniye (Dardanellen) — vrede met Engeland en regel van de Zeestraten", "fe282117"], "d": ["Met het verdrag dat na de mislukking van de operatie-Duckworth met Engeland werd ondertekend, eindigde de oorlog tussen de twee staten en werden de oude privileges van de Engelse kooplieden teruggegeven. De bepaling in de tekst, de 'oude regel' (kadîm kaide) genoemd, legde vast dat in vredestijd geen enkel buitenlands oorlogsschip door de Zeestraten mocht varen. Dit beginsel werd in de 19e eeuw de juridische grondslag van alle internationale regelingen die het regime van de Zeestraten vormgaven.", "7ef33a02"]},
"OLAYLAR_EK5:1811-10-14:0":{"b": ["Nederlaag bij Slobozia — omsingeling van het Donauleger", "54b60fd1"], "d": ["Het grootste deel van het Osmaanse leger dat voor Rusçuk de Donau overstak, werd door het omsingelingsmanoeuvre van Koetoezov vanaf de overkant van de rivier bij Slobozia ingesloten en aan honger overgelaten. Duizenden soldaten moesten zich overgeven; de strijdkracht van de grootvizier smolt feitelijk weg en de Hoge Porte moest een maand later om een wapenstilstand vragen. Deze nederlaag is de directe reden dat in het Verdrag van Boekarest van 1812 werd ingestemd met het afstaan van Bessarabië.", "d9da91c7"]},
"OLAYLAR_EK5:1813-10-05:0":{"b": ["Herovering van Belgrado en neerslaging van de Eerste Servische Opstand", "06f56f52"], "d": ["De Servische rebellen, die door het Verdrag van Boekarest van Russische steun verstoken waren, konden de gezamenlijke operatie van strijdkrachten uit Bosnië en Rumelië niet weerstaan; Hurşid Ahmed Pasja trok Belgrado binnen en de negen jaar durende opstand werd volledig neergeslagen. Karađorđe vluchtte naar Oostenrijk, de sandjak Smederevo werd opnieuw rechtstreeks aan het Osmaanse bestuur gebonden. De toegepaste harde maatregelen zouden echter twee jaar later een tweede en blijvende opstand onder leiding van Miloš Obrenović ontketenen.", "1f0a751b"]},
"OLAYLAR_EK5:1815-04-23:0":{"b": ["Tweede Servische Opstand en het oppervorstschap van Miloš Obrenović", "e6e82ad2"], "d": ["Tegen de zware maatregelen die na de neerslaging van de eerste opstand werden toegepast, brak onder leiding van Miloš Obrenović een nieuwe opstand uit; dit keer koos de Hoge Porte voor verzoening in plaats van geweld. Met de gesloten overeenkomst werd Miloš erkend als 'oppervorst' (başknez) en werd de bevoegdheid tot het innen van belasting en het voeren van binnenlandse zaken aan de Servische knezen gelaten. Deze eerste kern van feitelijke autonomie werd het beginpunt van het proces dat leidde naar het edict van 1830 en de onafhankelijkheid van 1878.", "bf6041bb"]},
"OLAYLAR_EK5:1821-02-22:0":{"b": ["Opstand in Walachije — Ypsilanti stak de Proet over en opstand van Vladimirescu", "67d46a98"], "d": ["Alexander Ypsilantis, die generaal in het Russische leger was, probeerde namens de Filiki Eteria door de Proet over te steken en in Walachije en Moldavië een algemene Griekse opstand te beginnen; in dezelfde dagen bracht ook Tudor Vladimirescu de inheemse boeren in beweging. De twee bewegingen konden zich niet verenigen: Vladimirescu antwoordde op Ypsilantis' oproep om samen tegen de Turken te vechten met 'Ik ben niet tegen de Turken maar tegen de Grieken in opstand gekomen' en werd kort daarna gedood door Ypsilantis' mannen. De opstand werd in mei door Osmaanse strijdkrachten neergeslagen, maar de orde van Phanariotische woiwoden kwam ten einde en het vuur van de opstand sloeg over naar de Morea.", "64b96ac8"]},
"OLAYLAR_EK5:1824-06-01:0":{"b": ["Stichting van de Tweede Saoedische Staat in Riyad", "34dad3bd"], "d": ["Zes jaar na de val van Dir'iyya in 1818 en de ondergang van de eerste Saoedische staat zette Turki b. Abdullah de Egyptische garnizoenen uit Nejd en stichtte een nieuw Saoedisch emiraat met Riyad als centrum. De nieuwe structuur vermeed het zich uit te strekken tot de Hidjaz, verkoos in Nejd te blijven en hield zich verre van rechtstreekse botsingen met de Osmaans-Egyptische strijdkrachten. Deze tweede staat zou tot het einde van de eeuw duren en vormt de tweede schakel in de keten die leidt naar de stichting van het huidige Saoedi-Arabië. Andere plaatsen die op dezelfde datum verloren gingen: Dir'iyya (Nejd).", "72b5fd29"]},
"OLAYLAR_EK5:1826-10-07:0":{"b": ["Verdrag van Akkerman — toegevingen aan Servië en de vorstendommen", "c75f15d0"], "d": ["De Osmaanse staat, die onmiddellijk na de afschaffing van het Janitsarenkorps zonder leger zat, moest tegenover het ultimatum van Rusland een verdrag met zware voorwaarden aanvaarden. De aan Servië beloofde autonomie werd bevestigd, er werd aanvaard dat de woiwoden van Walachije en Moldavië niet zonder Russische instemming konden worden afgezet en aan Russische koopvaardijschepen werd volledige vrijheid in de Zeestraten verleend. Toen de Hoge Porte twee jaar later vanwege de Griekse kwestie verklaarde het verdrag niet te erkennen, zou Rusland dit als reden voor oorlog beschouwen.", "a7de6cda"]},
"OLAYLAR_EK5:1827-02-01:0":{"b": ["Liquidatie van het timar-stelsel", "84d5d1d6"], "d": ["Een jaar na de afschaffing van het Janitsarenkorps werden de ongeveer 5.200 timar-sipahi's in drieënvijftig sandjaks in Rumelië en Anatolië samen met hun timarinkomsten omgevormd tot cavalerie van de Asâkir-i Mansûre. Zo kwam feitelijk een einde aan het timar-regime, de vierhonderd jaar oude ruggengraat van de Osmaanse land-, belasting- en legerorde. De vrijgekomen timars werden aan de schatkist overgedragen en de weg werd vrijgemaakt voor de overgang naar een centraal bezoldigd leger en een belastingstelsel in geld.", "077ea4ea"]},
"OLAYLAR_EK5:1827-03-14:0":{"b": ["Oprichting van de Tıphâne-i Âmire — begin van modern geneeskundeonderwijs", "ac3e57c0"], "d": ["Om artsen en chirurgen op te leiden voor het nieuw gevormde leger van de Asâkir-i Mansûre werd op voorstel van lijfarts Mustafa Behçet Efendi in Şehzadebaşı de Tıphâne-i Âmire geopend. De lessen werden ingericht volgens het Europese curriculum en het onderwijs werd aanvankelijk in het Frans gegeven; enkele jaren later werd ook de Cerrahhâne-i Âmire opgericht en werden de twee instellingen samengevoegd. Deze school, die geldt als het begin van het moderne geneeskundeonderwijs in Turkije, wordt beschouwd als de oorsprong van de huidige Geneeskundefaculteit van Istanbul.", "54a2ed54"]},
"OLAYLAR_EK5:1828-04-26:0":{"b": ["Begin van de Osmaans-Russische oorlog van 1828-1829", "9dff4e05"], "d": ["Na de verbranding van de vloot bij Navarino en de verklaring van de Hoge Porte dat zij het Verdrag van Akkerman niet erkende, begon Rusland de oorlog aan twee fronten tegelijk. Omdat het Janitsarenkorps pas was afgeschaft en het nieuwe leger zich nog in de opbouwfase bevond, was de Osmaanse verdediging van meet af aan zwak; terwijl de Russen de Donau overstaken, namen zij in het oosten Kars en Ahıska in. Het Russische leger, dat binnen een jaar tot Edirne oprukte, zou de zware voorwaarden van het Verdrag van Edirne van 1829 en de onafhankelijkheid van Griekenland afdwingen.", "9491c932"]},
"OLAYLAR_EK5:1830-05-07:0":{"b": ["Eerste verdrag met de Verenigde Staten", "d737516f"], "d": ["Met het handels- en scheepvaartverdrag dat na jarenlange contacten werd ondertekend, verkregen de VS in het Osmaanse land de status van meest begunstigde natie en het recht van commerciële doorvaart door de Zeestraten. Een afzonderlijke geheime clausule voorzag dat de Osmanen desgewenst schepen op Amerikaanse werven konden laten bouwen en kant-en-klare schepen en hout konden kopen; de Amerikaanse Senaat bekrachtigde het verdrag maar verwierp deze geheime clausule met 27 tegen 18 stemmen. De scheepsroute werd toch niet gesloten: Henry Eckford verkocht in 1831 het schip dat hij had meegebracht aan de Osmanen en Amerikaanse vaklieden die in Aynalıkavak werkten, verschaften de vloot nieuwe typen schepen. Dit verdrag werd het document van de eerste omvattende betrekking die de Osmaanse staat aanging met een staat buiten Europa.", "c87615ca"]},
"OLAYLAR_EK5:1831-09-14:0":{"b": ["Einde van het Kölemen-bestuur in Bagdad", "7e1d38a3"], "d": ["Mahmud II, die een centralisatiebeleid voerde, verklaarde Dâvud Pasja, de gouverneur van Bagdad, die het gevraagde geld niet zond en de van het centrum afkomstige ambtenaar liet doden, tot rebel. De troepenmacht onder bevel van Ali Rızâ Pasja nam na een beleg van negentig dagen de stad in en bijna alle kölemen werden geliquideerd. Zo kwam een einde aan het sinds 1704 durende halfonafhankelijke Kölemen-bestuur en werd Irak weer rechtstreeks aan het centrum gebonden.", "676f3744"]},
"OLAYLAR_EK5:1834-07-01:0":{"b": ["Oprichting van de Mekteb-i Harbiye in de Maçka-kazerne", "bf31c7d9"], "d": ["Om de Asâkir-i Mansûre-i Muhammediyye van naar Europees model opgeleide officieren te voorzien werd in de Maçka-kazerne de Mekteb-i Fünûn-ı Harbiyye geopend. De studenten kregen les in wiskunde, kaartlezen, vestingbouw en vreemde talen; kort daarna werden studenten naar Wenen en Parijs gestuurd om de staf te versterken. Deze school werd de plaats waar in het Osmaanse leger de traditie van op school opgeleide officieren en daarmee de nieuwe generatie soldaat-intellectuelen is geboren, die aan het einde van de 19e eeuw zou ontstaan.", "1d64a30c"]},
"OLAYLAR_EK5:1835-05-26:0":{"b": ["Rechtstreekse binding van Tripolitanië aan het centrum — einde van de Karamanli-dynastie", "faabcb96"], "d": ["Na de troonstrijd binnen de familie Karamanlı en de toegenomen Europese druk nadat Frankrijk in 1830 Algiers had bezet, greep de Hoge Porte rechtstreeks in Tripolitanië in. De vloot die uit Constantinopel werd gestuurd, trok de stad binnen, de laatste Karamanlı-bey werd afgezet en naar Constantinopel gebracht en de provincie werd overgedragen aan een door het centrum benoemde gouverneur. Met het einde van de dynastieperiode van 124 jaar werd het laatste stuk grondgebied dat de Osmaanse staat in Noord-Afrika rechtstreeks bestuurde, geconsolideerd.", "71104846"]},
"OLAYLAR_EK5:1838-02-28:0":{"b": ["Afschaffing van het defterdarschap en stichting van het Ministerie van Financiën", "89f8125e"], "d": ["Het defterdarschap, het hoofd van de klassieke Osmaanse financiële orde, werd afgeschaft en het Ministerie van Financiën (Maliye Nezâreti), een ministerie naar Europees voorbeeld, werd opgericht; de verspreide schatkisten werden in één hand verzameld. In hetzelfde jaar werden ook de overige eenheden van de Hoge Porte onder de naam nezâret herordend en werd overgegaan op een moderne ministerraadsstructuur. Deze regeling was een van de belangrijkste stappen die de administratieve infrastructuur voorbereidden voor het Edict van Tanzimat dat een jaar later zou worden afgekondigd.", "46962eda"]},
"OLAYLAR_EK5:1839-01-19:0":{"b": ["Vestiging van de Britten in Aden", "ddbd556b"], "d": ["Engeland zette, steunend op het handels- en vriendschapsverdrag dat het in 1802 met de sultan van Lahij, Ahmed b. Abdülkerîm, had gesloten, soldaten aan land in de haven van Aden en nam de stad onder zijn controle. Deze haven, die de ingang van de Rode Zee bewaakt, werd als steenkoolbevoorradingsbasis van de route naar India het sleutelpunt van de Britse imperiale strategie. Hoewel de aanspraak van de Osmaanse staat op Jemen op papier bleef bestaan, keerde de feitelijke heerschappij aan de zuidkust na deze datum nooit meer terug.", "731b896d"]},
"OLAYLAR_EK5:1849-01-01:0":{"b": ["Terugkeer naar de kust van Tihama: inname van Hudaydah, Zabid en Mocha", "353982d2"], "d": ["Naar de Jemenitische kust, die na de terugtrekking van het Egyptische leger in 1840 zonder bezitter was gebleven, trokken onder toezicht van de sjerief van Mekka strijdkrachten onder bevel van Tevfik Pasja en bonden de havens Hudaydah, Zabid en Mocha aan het Osmaanse bestuur. Hoewel men tot Sanaa wilde oprukken, werd wegens het verzet van de bevolking teruggekeerd naar Hudaydah; zo bleven de hooglanden bij de Zaidi-imams en bleef de Osmaanse heerschappij drie en twintig jaar lang beperkt tot de Tihama-strook. Het binnenland van Jemen zou pas in 1872 met de veldtocht van Ahmed Muhtar Pasja worden teruggenomen.", "7a30c1f9"]},
"OLAYLAR_EK5:1849-05-01:0":{"b": ["Conventie van Baltalimanı: gezamenlijke Osmaans-Russische bescherming in Walachije en Moldavië", "d3bb22e9"], "d": ["Nadat de revoluties van 1848 naar Walachije en Moldavië waren overgeslagen, hadden Osmaanse en Russische strijdkrachten de vorstendommen gezamenlijk bezet. Met de in Baltalimanı ondertekende conventie werd besloten dat de woiwoden niet door verkiezing maar door de sultan voor zeven jaar werden benoemd en dat de twee staten gezamenlijke controle in de regio vestigden. De overeenkomst behield de soevereiniteit van de Osmanen op papier maar verleende Rusland een feitelijk recht van deelgenootschap en versnelde de loskoppeling van de Donauvorstendommen van de Osmanen.", "b343f446"]},
"OLAYLAR_EK5:1849-08-16:0":{"b": ["Kwestie van de Hongaarse vluchtelingen: toevlucht van Kossuth en zijn kameraden in het Osmaanse Rijk", "1c7d7ef4"], "d": ["Nadat de Hongaarse revolutie van 1848-1849 door Russisch-Oostenrijkse interventie werd neergeslagen, zochten Lajos Kossuth en duizenden Hongaars-Poolse vluchtelingen hun toevlucht in Osmaans grondgebied. Oostenrijk en Rusland eisten de uitlevering van de vluchtelingen krachtig; de Hoge Porte weigerde met steun van Engeland en Frankrijk de uitlevering en vestigde de groep in Kütahya. De entourage van Kossuth verbleef hier ongeveer achttien maanden, honderden vluchtelingen werden moslim en traden in Osmaanse dienst. Het voorval werd beschouwd als een van de zeldzame diplomatieke overwinningen die het aanzien van het Tanzimat-Osmaanse Rijk in de Europese publieke opinie deden stijgen.", "07b6d020"]},
"OLAYLAR_EK5:1851-02-11:0":{"b": ["Oprichting van de Encümen-i Dâniş: eerste Osmaanse academie in Constantinopel", "6fda1365"], "d": ["De Encümen-i Dâniş, opgericht bij besluit van de Meclis-i Maârif-i Umûmiyye, is de eerste Osmaanse wetenschappelijke academie, opgericht om Turkse wetenschappelijke en studieboeken voor te bereiden. Zij werd op 18 juli 1851 in het gebouw van de Dârülmaârif met een ceremonie geopend; onder haar binnen- en buitenlandse leden bevond zich ook Ahmed Cevdet Pasja. Hoewel van korte duur, waren werken zoals Cevdet Pasja's Târih en Kavâid-i Osmâniyye producten van deze instelling en zij wordt beschouwd als een hoeksteen in het worden van het Turks tot wetenschapstaal.", "7eebb193"]},
"OLAYLAR_EK5:1853-11-11:0":{"b": ["Overwinning bij Oltenița: eerste Osmaanse succes aan het Donaufront", "a660ad2f"], "d": ["In de openingsfase van de Krimoorlog stak serdar-ı ekrem Ömer Lütfi Pasja de Donau over en sloeg bij Oltenița de Russische strijdkrachten met zware verliezen terug. De overwinning, die direct bij het begin van de oorlog de Russische opmars stopte, toonde Europa de kracht die het Osmaanse leger na de Tanzimat door opleiding had verworven. Dit succes bereidde de psychologische bodem voor die het besluit van Engeland en Frankrijk om aan Osmaanse zijde in de oorlog te treden vergemakkelijkte.", "a0e5e8fb"]},
"OLAYLAR_EK5:1854-03-12:0":{"b": ["Bondgenootschapsverdrag met Engeland en Frankrijk in Constantinopel", "04809278"], "d": ["Het bondgenootschapsverdrag dat in de Krimoorlog tussen de Osmaanse staat en Engeland en Frankrijk tegen Rusland werd ondertekend, bepaalde dat de drie staten gezamenlijk zouden optreden en dat de bondgenoten niet vóór het einde van de oorlog afzonderlijk vrede zouden sluiten. Zo ging de Osmaanse staat voor het eerst in zijn geschiedenis als gelijkwaardige partij een militair bondgenootschap aan met grote Europese mogendheden. Dit verdrag vormde twee jaar later in Parijs ook de juridische grond voor de formele toelating van de Osmanen tot het Europese staatsstelsel.", "1899331b"]},
"OLAYLAR_EK5:1855-08-16:0":{"b": ["Oprichting van de Şehremaneti van Constantinopel: eerste moderne gemeentelijke organisatie", "be4af27f"], "d": ["De infrastructuurcrisis die ontstond door de in Constantinopel samengestroomde geallieerde soldaten tijdens de Krimoorlog en de toegenomen bevolking toonde de ontoereikendheid van het klassieke stadsbestuur dat rond de kadi draaide. Met de naar Europees voorbeeld gestichte Şehremaneti werden reiniging, prijsregulering, bazaarcontrole en bouwzaken in één hand verzameld; het jaar daarop werd in Beyoğlu-Galata de Zesde Gemeentelijke Kring als proefgebied opgericht. Deze stap wordt beschouwd als het begin van het moderne gemeentebestuur bij de Osmanen.", "23959c70"]},
"OLAYLAR_EK5:1856-03-30:0":{"b": ["Verdrag van Parijs: einde van de Krimoorlog en toelating van de Osmanen tot het Europese staatsstelsel", "4aee0e2a"], "d": ["Met het Verdrag van Parijs, dat de Krimoorlog beëindigde, werd de Osmaanse staat tot gelijkwaardig lid van het Europese volkenrecht uitgeroepen en kwam zijn territoriale integriteit onder de gezamenlijke garantie van de grote mogendheden. De Zwarte Zee werd geneutraliseerd, de aanspraak van Rusland op bescherming van de orthodoxe onderdanen, die het sinds Küçük Kaynarca had verkregen, werd ongeldig verklaard, en het zuiden van Bessarabië (de kazas Kilia, Cahul, İsmail en Bolgrad) werd aan Moldavië gegeven. Maar hetzelfde verdrag maakte het Hervormingsedict tot een internationale verplichting en opende zo ook de deur voor inmenging in binnenlandse zaken.", "42c5d63d"]},
"OLAYLAR_EK5:1856-06-07:0":{"b": ["Opening van het Dolmabahçe-paleis: verhuizing van het bestuurscentrum van Topkapı", "71ad26d0"], "d": ["Het paleis dat Abdülmecid in 1842 bij de familie Balyan had besteld, werd na een bouw van veertien jaar geopend en het bestuurscentrum van de staat verhuisde van het vierhonderd jaar oude Topkapı naar de oever van de Bosporus. Met zijn Europese stijl, kristallen trap en Ceremoniezaal werd het paleis de stenen uitdrukking van de westerse ambitie van de Tanzimat. De enorme kosten ervan werden een van de meest bekritiseerde posten van de jaren waarin de Osmaanse financiën in de spiraal van buitenlandse schulden raakten.", "bb3cd1c8"]},
"OLAYLAR_EK5:1859-02-05:0":{"b": ["Eenwording van Walachije en Moldavië onder Cuza: geboorte van Roemenië", "baef4da5"], "d": ["Bij de na het Verdrag van Parijs gehouden verkiezingen kozen beide vorstendommen kolonel Alexandru Ioan Cuza tot woiwode en realiseerden zo de feitelijke eenwording. Hoewel de Hoge Porte en Oostenrijk zich daartegen verzetten, moest het door Frankrijk gesteunde voldongen feit worden aanvaard. Deze unie, die op papier aan de Osmanen gebonden bleef, zou in 1862 de naam Roemenië aannemen en in 1877 eenzijdig haar onafhankelijkheid uitroepen; het is een keerpunt in het uiteenvallen van de Osmaanse heerschappij langs de Donau.", "83e52b52"]},
"OLAYLAR_EK5:1859-09-14:0":{"b": ["Kuleli-incident: eerste staatsgreeppoging tegen Abdülmecid in Constantinopel", "e3653b21"], "d": ["Een geheim genootschap van militairen en burgers, dat zich verzette tegen de Tanzimat-politiek en de gelijkheid die het Hervormingsedict aan niet-moslims verleende, werd bij een bijeenkomst in de Kılıç Ali Pasja-moskee opgerold terwijl het plande de sultan af te zetten. Het voorval wordt met deze naam genoemd omdat de beklaagden in de Kuleli-kazerne werden berecht; de doodstraffen werden omgezet in verbanning. Het wordt beschouwd als de eerste paleisstaatsgreeppoging in de Osmaanse geschiedenis door een om ideologische redenen opgerichte organisatie.", "4e9e2296"]},
"OLAYLAR_EK5:1860-05-30:0":{"b": ["Druzisch-Maronitische burgeroorlog in de Libanonberg en de gebeurtenissen in Damascus", "5595fdd6"], "d": ["De botsingen die in mei 1860 uitbraken na de moord op twee Druzen bij Sidon groeiden uit tot de bloedigste Druzisch-Maronitische burgeroorlog in de bergen en sloegen in juli over naar Damascus, waar duizenden christenen omkwamen. Na de Franse troepenlanding zond de Hoge Porte Fuad Pasja met buitengewone bevoegdheid naar de regio; een harde strafexpeditie werd gevoerd. De gebeurtenissen vormden de reden voor Europese interventie en waren de directe oorzaak dat Libanon een bijzondere status kreeg.", "511709b3"]},
"OLAYLAR_EK5:1860-10-22:0":{"b": ["Begin van de publicatie van Tercümân-ı Ahvâl: eerste particuliere Turkse krant in Constantinopel", "24792957"], "d": ["De door Agâh Efendi uitgegeven Tercümân-ı Ahvâl, waarvan Şinâsi de redactie op zich nam, is de eerste Turkse krant die zonder staatssteun verscheen. In de inleiding van het eerste nummer werd het recht van het volk om over zijn eigen zaken te spreken verdedigd; de krant opende met het feuilleton van Şinâsi's Şair Evlenmesi ook de deur naar de moderne Turkse literatuur. De geboorte van het begrip publieke opinie en van de oppositiepers bij de Osmanen wordt op deze datum gesteld.", "cc4ba4a5"]},
"OLAYLAR_EK5:1861-06-09:0":{"b": ["Libanonberg-reglement: privilegestatus van mutasarrifaat voor Libanon", "bf375603"], "d": ["Het reglement, dat na de bloedbaden van 1860 onder druk van de grote mogendheden werd opgesteld, maakte van de Libanonberg een privilegiaal mutasarrifaat dat rechtstreeks aan de Hoge Porte was gebonden en werd bestuurd door een bestuursraad die volgens het evenwicht tussen de geloofsgemeenschappen werd samengesteld. Er werd bepaald dat de mutasarrıf een onderdaan van de Osmanen en katholieke christen moest zijn en dat zijn benoeming ter goedkeuring aan de grote mogendheden werd voorgelegd; de eerste mutasarrıf was Dâvud Pasja. Deze orde zou tot 1915 duren en de kern vormen van de moderne Libanese staat.", "1b56a9d5"]},
"OLAYLAR_EK5:1861-06-25:0":{"b": ["Overlijden van Abdülmecid en troonsbestijging van sultan Abdülaziz", "27204d7c"], "d": ["Na het overlijden van Abdülmecid, die tijdens zijn regering van tweeëntwintig jaar het Tanzimat- en het Hervormingsedict had ondertekend en aan tuberculose bezweek, besteeg zijn broer Abdülaziz de troon. De nieuwe sultan wekte de eerste jaren hoop met besparingsmaatregelen en een sobere levenswijze; hij maakte de vloot tot een van de weinige grote machten ter wereld. Maar aan het einde van zijn regering zouden de zware buitenlandse schuld, het faillissement van 1875 en de Balkanopstanden zich ophopen en de bodem bereiden voor de afzettingsbeweging van 1876.", "1c2db3f9"]},
"OLAYLAR_EK5:1862-02-21:0":{"b": ["De verenigde vorstendommen namen de naam Roemenië aan", "d960e3fc"], "d": ["Walachije en Moldavië, die in 1859 met de dubbele verkiezing van Cuza feitelijk waren verenigd, brachten in 1862 hun parlementen en regeringen in Boekarest onder één dak samen en namen formeel de naam Roemenië aan. Hoewel de Osmaanse staat juridisch zijn status van suzerein en de jaarlijkse belasting behield, verloor zij feitelijk de controle over het vorstendom. Het einde van de vierhonderd jaar durende Osmaanse invloed ten noorden van de Donau wordt met deze datum gesymboliseerd.", "1693f20f"]},
"OLAYLAR_EK5:1865-01-01:0":{"b": ["Aansluiting van Suakin, Massawa en Dahlak bij Egypte", "a0924860"], "d": ["Massawa, dat in 1846 door sultan Abdülmecid samen met Suakin als sâlyâne (inkomenstoewijzing) aan de Egyptische khedive Mehmed Ali Pasja was gegeven, werd onder khedive İsmâil Pasja samen met Dahlak en Suakin bij het Egyptische bezit gevoegd en georganiseerd in de status van kaymakamlik. Zo gingen deze drie havens aan de Afrikaanse kust van de Rode Zee, hoewel zij juridisch Osmaans grondgebied bleven, bestuurlijk rechtstreeks van de Hoge Porte over naar Caïro — zij kwamen in dezelfde vazallaag als hun buur Egypte en Soedan.", "782199b7"]},
"OLAYLAR_EK5:1866-08-21:0":{"b": ["Begin van de Kretenzische opstand (1866-1869)", "3679b861"], "d": ["De omvangrijke opstand die met de openlijke steun van Griekenland op het eiland uitbrak, maakte de eis van de Kretenzische Grieken voor enosis (aansluiting bij Griekenland) voor het eerst tot een internationale kwestie. De drie jaar durende hevige bergoorlog bracht het Osmaanse leger zware verliezen toe en wekte grote weerklank in de Europese publieke opinie. De opstand kon pas in 1868 worden bedwongen toen Âlî Pasja naar het eiland ging en het reglement dat brede privileges verleende in werking stelde.", "eba163ff"]},
"OLAYLAR_EK5:1867-04-18:0":{"b": ["Terugtrekking van de laatste Osmaanse garnizoenen uit de burchten van Belgrado en Servië", "b34217db"], "d": ["Onder druk van de grote mogendheden en op aandringen van prins Mihailo stemde de Hoge Porte ermee in de laatste militaire basissen die nog in Servië in haar bezit waren te ontruimen; op 18 april 1867 werd de Osmaanse vlag in de vesting van Belgrado neergehaald en werden de sleutels aan de prins overgedragen. Zo kwam een einde aan de sinds 1521 durende feitelijke Osmaanse militaire aanwezigheid en verdween de laatste grote hindernis op Servië's weg naar onafhankelijkheid. De suzereiniteit van de sultan werd teruggebracht tot slechts een symbolische vlag en een kwestie van belasting.", "875dbecb"]},
"OLAYLAR_EK5:1867-06-08:0":{"b": ["Verlening van de titel khedive aan de gouverneurs van Egypte", "09e10c12"], "d": ["Als gevolg van de intensieve lobby van İsmâil Pasja, uit de derde generatie van de dynastie van Kavala, en het geld dat hij naar Constantinopel liet stromen, kreeg de gouverneur van Egypte de titel khedive, die zijn superioriteit tegenover de andere gouverneurs benadrukt. In dezelfde jaren werd ook de opvolgingsregeling gewijzigd zodat de titel van vader op zoon overging, en werden aan Egypte bevoegdheden met een soevereiniteitskarakter verleend, zoals buitenlandse leningen aangaan, onderscheidingen verlenen en consulaten hebben. Deze stappen zijn de eerste schakel van de keten die de juridische losmaking van Egypte van de Osmanen versnelde.", "38a9a00f"]},
"OLAYLAR_EK5:1868-01-04:0":{"b": ["Reglement van Kreta: brede administratieve privileges voor het eiland", "12052262"], "d": ["Om de drie jaar durende opstand te beëindigen ging grootvizier Âlî Pasja persoonlijk naar het eiland en met het reglement dat met goedkeuring van de sultan werd uitgevaardigd, kregen de Kretenzers gemengde bestuursraden, lokale rechtbanken, het gebruik van het Grieks in officiële handelingen en belastingverlichting. Deze regeling hield de Osmaanse heerschappij op het eiland nog dertig jaar overeind. Maar de privileges die aan de christelijke bevolking werden verleend verzwakten de positie van de moslimse Kretenzers en zaaiden de kiem van de crisis van 1896-1898.", "9cce04af"]},
"OLAYLAR_EK5:1868-05-10:0":{"b": ["Opening van de Şûrâ-yı Devlet: stichting van de Osmaanse Raad van State", "70b16497"], "d": ["Met het irade van 5 maart 1868 werd de Meclis-i Ahkâm-ı Adliyye in tweeën gesplitst, waarbij de administratief-wetgevende zaken aan de Şûrâ-yı Devlet en de rechterlijke zaken aan de Dîvân-ı Ahkâm-ı Adliyye werden overgelaten; de instelling werd met een ceremonie bij de Hoge Porte geopend en Midhat Pasja werd haar eerste voorzitter. Zij kreeg de taak wetsontwerpen voor te bereiden, administratieve geschillen te beslechten en ambtenarenprocessen te voeren. Met haar gemengde samenstelling van moslim- en niet-moslimleden geldt zij als de eerste institutionele toepassing van het idee van scheiding der machten bij de Osmanen.", "c85741e0"]},
"OLAYLAR_EK5:1869-11-17:0":{"b": ["Opening van het Suezkanaal: verkorting van de route naar India via Egypte", "377ccd04"], "d": ["De bouw, begonnen in 1859, duurde tien jaar en het 163 kilometer lange kanaal dat de Middellandse Zee met de Rode Zee verbindt, werd in een luisterrijke ceremonie in gebruik genomen. Doordat de route die Europa met India verbindt duizenden mijlen korter werd, werd Egypte in één klap een sleutelpunt van de wereldhandel. Deze geostrategische waarde zou de voornaamste reden worden waarom Engeland dertien jaar na de opening van het kanaal Egypte bezette; de schuld die het kanaal op Egypte legde, zou het khedivaat tot faillissement drijven.", "ccff3d4b"]},
"OLAYLAR_EK5:1870-03-11:0":{"b": ["Stichting van het Bulgaarse Exarchaat: afscheiding van de Bulgaarse kerk van de Phanar", "33a8272c"], "d": ["Bij sultansfirman werd een zelfstandige Bulgaarse kerk (exarchaat) gesticht, gescheiden van het Griekse Patriarchaat, en werd aan een volksstemming overgelaten welke kazas aan het exarchaat zouden worden gebonden. Hoewel de Hoge Porte deze stap zette om de Griekse invloed te breken, pakte het resultaat averechts uit: de kerk veranderde in het georganiseerde centrum van de Bulgaarse nationale identiteit en van de Bulgaarse aanspraak op Macedonië. Zo werd de institutionele bodem gelegd voor de Bulgaars-Grieks-Servische rivaliteit op de Balkan en voor de opstanden van 1876.", "ce8f108b"]},
"OLAYLAR_EK5:1871-04-20:0":{"b": ["Veldtocht van Midhat Pasja naar Nejd: herstel van de Osmaanse heerschappij in Al-Hasa", "7db51461"], "d": ["Midhat Pasja, de gouverneur van Bagdad, die gebruik maakte van de troonstrijd binnen de familie Saud, zond soldaten naar de westkust van de Perzische Golf en bond het gebied Al-Hasa onder de naam sandjak Nejd aan de provincie Basra. Abdullah b. Faisal werd tot mutasarrıf benoemd en zo werd de Osmaanse heerschappij op papier gevestigd. De veldtocht had als doel de verspreiding van de Britse invloed in de Golf te stoppen en leidde in hetzelfde jaar ertoe dat ook Qatar onder Osmaanse controle kwam.", "fbc6819e"]},
"OLAYLAR_EK5:1871-09-07:0":{"b": ["Overlijden van grootvizier Âlî Pasja: einde van de Tanzimat-staf", "1cf0141c"], "d": ["Met het overlijden van Âlî Pasja, die na de dood van Fuad Pasja in 1869 de Tanzimat-politiek alleen droeg, was de generatie van meesterdiplomaten die dertig jaar het buitenlands beleid van de staat had geleid, uitgeput. Het pro-Russische en willekeurige bestuur van Mahmud Nedim Pasja, die hem opvolgde, versterkte het persoonlijke bewind van Abdülaziz. In de vijf jaar na de dood van Âlî Pasja ging de schatkist failliet, kwam de Balkan in opstand en werd een verandering van sultan onvermijdelijk.", "c4954cff"]},
"OLAYLAR_EK5:1871-09-20:0":{"b": ["Vestiging van Osmaanse controle in Qatar", "3b453165"], "d": ["Op uitnodiging van sjeik Qasim b. Thani, die onder Britse druk stond, landden Osmaanse strijdkrachten op het schiereiland Qatar en in de herfst van 1871 werd in de regio Osmaanse controle verkregen. Qatar werd georganiseerd als een kaza van de sandjak Nejd en de sjeik werd tot kaymakam benoemd. Deze zet werd de meest concrete winst van de vooruitgeschoven politiek die Midhat Pasja in de Golf tegen Engeland voerde; de Osmaanse vlag wapperde tot 1913 op het schiereiland.", "823711c3"]},
"OLAYLAR_EK5:1872-04-01:0":{"b": ["Inname van Sanaa: herstel van het Osmaanse gezag in Jemen", "978e20a0"], "d": ["Toen de strategische waarde van de Rode Zee steeg door de opening van het Suezkanaal, zond de Hoge Porte onder bevel van Ahmed Muhtar Pasja het reserveleger (fırka-i ihtiyâtiyye) naar Jemen. Met de inname van Sanaa werd het staatsgezag hersteld in het binnenland van Jemen, dat twee eeuwen feitelijk verloren was geweest, en werd de regio een vilayet. Maar de strijd met de Zaidi-imams eindigde nooit; de opstanden van 1891, 1898 en 1904 vormden het duurste en langstdurende interne front van de Osmanen. Andere plaatsen die op dezelfde datum werden toegevoegd: Sanaa, Taiz.", "2173d1a2"]},
"OLAYLAR_EK5:1875-06-19:0":{"b": ["Begin van de opstand in Herzegovina: opnieuw oplaaien van de Oosterse kwestie", "571b18ec"], "d": ["Door zware belastingen en de druk van de ayans sloeg de opstand van de christelijke boeren rond Nevesinje snel over naar heel Herzegovina en werd gevoed door vrijwilligers uit Servië en Montenegro. De opstand, die leidde tot hervormingsdwang van Oostenrijk en Rusland, ontketende het jaar daarop de Bulgaarse opstanden en de Servisch-Montenegrijnse oorlogsverklaringen. Zo brak de eerste schakel van de grote keten die leidde naar de Oorlog van '93 en het verlies van de Balkan met het Verdrag van Berlijn.", "b697eb06"]},
"OLAYLAR_EK5:1875-10-06:0":{"b": ["Faillissement van de Osmaanse financiën: schuldbetalingen gehalveerd", "2cac2fa5"], "d": ["De sinds 1854 opeenvolgend aangegane leningen, de kosten van de Krimoorlog, de paleisbouwwerken en de hongersnood in Anatolië van 1873-74 veranderden het begrotingstekort in een afgrond van meer dan vijf miljoen lira. De regering van Mahmud Nedim Pasja verklaarde feitelijk een moratorium door aan te kondigen dat de rente- en aflossingsbetalingen van de schuld vijf jaar lang zouden worden gehalveerd. Dit besluit, dat op de Europese beurzen grote reacties wekte, startte het proces dat zes jaar later zou uitmonden in het Muharrem-decreet en de stichting van de Düyûn-ı Umûmiyye-administratie.", "a6706632"]},
"OLAYLAR_EK5:1876-08-31:0":{"b": ["Afzetting van Murad V en troonsbestijging van Abdülhamid II", "cffb2271"], "d": ["Murad V, die na de afzetting van Abdülaziz de troon besteeg, raakte door de dood van zijn oom en de schok van het incident-Çerkes Hasan in zijn geestelijke gezondheid niet meer in staat zijn taak uit te oefenen; slechts zeven dagen van zijn drieënnegentig dagen durende regering was zijn oordeelsvermogen in orde. Hij werd met een fatwa van de sjeik-ul-islam afgezet en zijn broer Abdülhamid II werd in zijn plaats gezet. De nieuwe sultan besteeg de troon met de belofte aan Midhat Pasja dat hij de constitutie zou afkondigen; een tijdperk van drieëndertig jaar begon.", "9904ab70"]},
"OLAYLAR_EK5:1876-12-23:0":{"b": ["Conferentie van de Scheepswerf: Balkanhervormingen opgelegd door de grote mogendheden", "b5006a2c"], "d": ["De conferentie die de grote mogendheden in Constantinopel bijeenriepen om de Balkancrisis op te lossen, eiste de verdeling van Bulgarije in twee autonome vilayets en hervormingen onder internationale controle in Bosnië-Herzegovina. De Hoge Porte kondigde op de dag van de opening van de conferentie met kanonschoten de afkondiging van de Kanûn-ı Esâsî aan en probeerde de opgelegde eisen met een constitutionele hervorming te beantwoorden. De afgevaardigden beschouwden dit als tijdrekken en gingen op 20 januari 1877 uiteen; vier maanden later verklaarde Rusland de oorlog.", "8149c00f"]},
"OLAYLAR_EK5:1877-03-19:0":{"b": ["Opening van de eerste Meclis-i Meb'ûsan in Dolmabahçe", "429bb279"], "d": ["De 115 volksvertegenwoordigers die overeenkomstig de Kanûn-ı Esâsî waren gekozen, kwamen op 19 maart 1877 voor het eerst bijeen in een ceremonie in de Ceremoniezaal van het Dolmabahçe-paleis; zo begon in de Osmaanse geschiedenis het tijdperk van de representatieve vergadering. De moslimse en niet-moslimse afgevaardigden ondervroegen de regering fel en bespraken het bestuur van de oorlog en de verantwoordelijkheid van de ministers. Deze moedige oppositie zou de belangrijkste reden worden voor de verkorting van het leven van het parlement.", "df95fa07"]},
"OLAYLAR_EK5:1877-07-19:0":{"b": ["Begin van de verdediging van Plevna: verzet van Gazi Osman Pasja", "0e04a878"], "d": ["Osman Pasja, die in de Oorlog van '93 van Vidin naar Plevna oprukte om de weg naar Constantinopel van het Russische leger dat de Donau had overgestoken af te snijden, versterkte het stadje met bastions en loopgraven en begon een vijf maanden durende legendarische verdediging. Drie opeenvolgende grote Russisch-Roemeense aanvallen werden met zware verliezen afgeslagen en het leger, dat persoonlijk door tsaar Alexander II werd geleid, werd gedwongen tot een beleg. Plevna ging de geschiedenis in als het schitterendste verdedigingssucces van het Osmaanse leger in de 19e eeuw.", "5a86466f"]},
"OLAYLAR_EK5:1877-12-10:0":{"b": ["Val van Plevna: ineenstorting van het Donaufront", "185e7602"], "d": ["Osman Pasja, wiens voorraden in het vijf maanden durende beleg uitgeput raakten, begon een uitval over de rivier de Vit; toen hij gewond raakte en gevangen werd genomen, gaf de stad zich over. De Russische bevelhebbers groetten de gevangengenomen pasja door zijn sabel terug te geven, en Osman Pasja kreeg de titel 'Gazi'. Met de val van Plevna lag de weg voor het Russische leger open; binnen twee maanden vielen Sofia, Filibe en Edirne en bereikte de Russische voorhoede Yeşilköy.", "fc075756"]},
"OLAYLAR_EK5:1878-01-04:0":{"b": ["Bezetting van Sofia door Russische strijdkrachten", "ef369d22"], "d": ["Het Russische leger, dat na de val van Plevna de Balkan overstak, trok het onverdedigde Sofia binnen. De stad zou nooit meer onder Osmaans bestuur terugkeren; eind 1878 zou zij de hoofdstad worden van het autonome Prinsdom Bulgarije en in 1879 feitelijk. Op de kaart verlaat Sofia vanaf deze datum het rechtstreekse Osmaanse bestuur en gaat over naar tijdelijke Russische bezetting en daarna naar autonoom Bulgaars bestuur.", "66b1da91"]},
"OLAYLAR_EK5:1878-01-31:0":{"b": ["Wapenstilstand van Edirne: zwijgen van de wapens in de Oorlog van '93", "1f899180"], "d": ["Toen Sofia, Filibe en Edirne achtereenvolgens vielen en het Russische leger de kusten van de Zee van Marmara naderde, moest de Hoge Porte om een wapenstilstand vragen. De in Edirne ondertekende wapenstilstand liet de Osmanen de voorlopige vredesvoorwaarden aanvaarden, zoals autonomie voor Bulgarije, onafhankelijkheid van Montenegro, Servië en Roemenië en een zware oorlogsvergoeding. Deze voorwaarden zouden een maand later in San Stefano tot een verdragstekst worden.", "49d61081"]},
"OLAYLAR_EK5:1878-02-13:0":{"b": ["Onbepaalde schorsing van de Meclis-i Meb'ûsan door Abdülhamid II", "e770b540"], "d": ["Op de felle kritiek van de afgevaardigden, die de regering en het paleis verantwoordelijk hielden voor de rampzalige afloop van de oorlog, schorste Abdülhamid II het parlement voor onbepaalde tijd, steunend op de bevoegdheid die de Kanûn-ı Esâsî hem verleende. Zo werd het eerste Osmaanse parlement, dat ongeveer elf maanden had gewerkt, gesloten en begon een tijdperk van despotisme dat dertig jaar zou duren. Het parlement zou pas na de revolutie van 1908 weer kunnen bijeenkomen.", "dd2e6d60"]},
"OLAYLAR_EK5:1878-03-03:0":{"b": ["Verdrag van San Stefano: plan voor Groot-Bulgarije", "2c7cc611"], "d": ["Het Verdrag van San Stefano, dat de Oorlog van '93 beëindigde, vestigde een gigantisch autonoom Bulgarije dat zich uitstrekte tot de Egeïsche Zee en Macedonië omvatte; het erkende de onafhankelijkheid van Servië, Montenegro en Roemenië; liet Kars, Ardahan, Batoem en Doğubayazıt aan Rusland en legde bovendien een onbetaalbare oorlogsvergoeding op. Deze tekst, die Rusland naar de Middellandse Zee bracht, wekte de hevige reactie van Engeland en Oostenrijk. Zonder te zijn uitgevoerd werd hij binnen vier maanden met het Congres van Berlijn herzien; toch bleef hij het document dat het einde van het Osmaanse Rumelië afkondigde.", "dfd3e7f4"]},
"OLAYLAR_EK5:1878-07-29:0":{"b": ["Bezetting van Bosnië-Herzegovina en Novi Pazar door Oostenrijk-Hongarije", "e5f901df"], "d": ["Steunend op de bevoegdheid die het Verdrag van Berlijn gaf, trokken de legers van Oostenrijk-Hongarije Bosnië binnen; hoewel de Osmaanse regering instemde met niet-verzet, grepen de lokale moslimse en orthodoxe bevolking in Sarajevo en Mostar naar de wapens en boden drie maanden lang hevig weerstand. De bezetting kon pas op 20 oktober 1878 worden voltooid. De juridische soevereiniteit van de sultan duurde op papier tot 1908, maar het vierhonderd jaar oude Osmaanse Bosnië ging feitelijk verloren en een grote golf van moslimmigratie begon. Andere plaatsen die op dezelfde datum verloren gingen: Banja Luka.", "9d6a9e57"]},
"OLAYLAR_EK5:1881-12-20:0":{"b": ["Muharrem-decreet en stichting van de Düyûn-ı Umûmiyye-administratie", "02b7cc03"], "d": ["De onderhandelingen die na het faillissement van 1875 met de vertegenwoordigers van de schuldeisende staten werden gevoerd, mondden uit in het decreet van 28 Muharrem 1299 (20 december 1881): de hoofdsom van de schuld werd met meer dan de helft verlaagd, daartegenover werden de meest productieve inkomstenposten zoals zout, tabak, zijde, zegel- en visrechten overgedragen aan de Düyûn-ı Umûmiyye-administratie, die rechtstreeks door de schuldeisers werd beheerd. Deze administratie, die duizenden ambtenaren in dienst had, veranderde in een afzonderlijke financiële organisatie binnen de staat. Zij wordt beschouwd als de datum waarop de Osmaanse financiële onafhankelijkheid feitelijk eindigde.", "3cb26eeb"]},
"OLAYLAR_EK5:1884-02-01:0":{"b": ["Suakin — de enige haven die niet aan de Mahdi viel", "5a37b198"], "d": ["Terwijl vanaf februari 1884 alle gebieden van Oost-Soedan behalve Suakin onder de heerschappij van Muhammad Ahmad al-Mahdi kwamen, bleef de haven overeind onder de militaire bescherming van een Brits detachement van drie bataljons onder bevel van generaal Graham. Dit was het begin van een periode waarin feitelijke en juridische situatie uiteenliepen: hoewel de kust feitelijk onder Britse militaire controle stond, zou de administratieve band in 1885 aan Egypte worden ontnomen en rechtstreeks aan de provincie Jemen, dus aan de Hoge Porte, worden gebonden — die orde duurde tot 1888, toen Frankrijk Zeila bezette.", "343c16cf"]},
"OLAYLAR_EK5:1884-05-08:0":{"b": ["Moord op Midhat Pasja in de gevangenis van Ta'if", "f4562261"], "d": ["Midhat Pasja, de architect van de Kanûn-ı Esâsî en het symbool van de Eerste Constitutionele Periode, was in het Yıldız-proces over de dood van Abdülaziz schuldig bevonden en kreeg een doodstraf die in ballingschap werd omgezet; hij werd naar Ta'if gezonden. Volgens de TDV-aantekening werd hij in de nacht van 7-8 mei 1884 in zijn cel gewurgd, als officiële reden werd de ziekte 'şîrpençe' opgegeven. Zijn dood werd onder Abdülhamid II het symbool van de liquidatie van de constitutionele oppositie.", "06cc8d1c"]},
"OLAYLAR_EK5:1888-09-24:0":{"b": ["Concessie voor de spoorlijn Haydarpaşa–Ankara aan de Duitsers", "5705b163"], "d": ["Met sultansirade werd de concessie voor bouw en exploitatie van de lijn Haydarpaşa–Ankara verleend aan de bankier Alfred von Kaulla, die de Deutsche Bank vertegenwoordigde, en de Anatolische Spoorwegmaatschappij werd opgericht. Deze concessie werd het keerpunt dat in het Osmaanse vervoer en buitenlands beleid het Engels-Franse monopolie brak en de Duitse invloed vestigde. Samen met de concessie voor de Bagdadlijn die elf jaar later aan dezelfde maatschappij zou worden verleend, ontstond de droom van 'Berlijn–Bagdad', die een van de hoofdassen van de grote-machtenrivaliteit voor de Eerste Wereldoorlog zou worden.", "9974f219"]},
"OLAYLAR_EK5:1889-06-02:0":{"b": ["Stichting van het Ittihad-ı Osmani Genootschap in Constantinopel", "b7187939"], "d": ["Vier studenten van de Militaire Geneeskundeschool richtten het Ittihad-ı Osmani Genootschap op als geheime organisatie tegen het despotische bestuur; deze structuur veranderde snel in het Comité voor Eenheid en Vooruitgang, dat alle oppositionele elementen van de Jongturkse beweging onder zijn dak zou verzamelen. De organisatie op basis van cellen verenigde zich met de ballingen in Europa en de officieren in Thessaloniki. Het kader dat in 1908 de Tweede Constitutionele Periode zou afdwingen en na 1913 de staat alleen zou besturen, kwam voort uit deze kleine studentencel.", "f2417434"]},
"OLAYLAR_EK5:1896-08-26:0":{"b": ["Overval op de Osmaanse Bank: actie van Dasjnak-activisten in Galata", "08b3095f"], "d": ["Een gewapende groep van de Armeense organisatie Dasjnaktsoetjoen overviel het hoofdkantoor van de Osmaanse Bank in Galata, nam gijzelaars en dreigde het gebouw op te blazen, met als doel de aandacht van Europa op de Armeense kwestie te vestigen. De crisis eindigde door tussenkomst van de ambassadeurs, in ruil voor het per schip uit het land brengen van de activisten. De bloedige gebeurtenissen in Constantinopel in de dagen na de overval waren bepalend voor de verandering van de Armeense kwestie in een hefboom voor internationale interventie.", "8fb5eb98"]},
"OLAYLAR_EK5:1897-04-17:0":{"b": ["Begin van de Osmaans-Griekse oorlog van 1897: front van Thessalië", "33e490ab"], "d": ["Na de landing van Griekenland met vloot en soldaten op Kreta en de bendeaanvallen aan de grens met Rumelië verklaarde de Osmaanse staat de oorlog. Het Osmaanse leger, getraind door de Duitse hervormingsmissie, rukte in Thessalië snel op en nam binnen een maand Yenişehir (Larissa), Çatalca en Domokos in; het Griekse leger viel uiteen. Door tussenkomst van de grote mogendheden werden de veroverde gebieden teruggegeven, maar de oorlog bleef de enige beslissende militaire overwinning uit de tijd van Abdülhamid II en kon het feitelijke verlies van Kreta niet verhinderen.", "405fd8a7"]},
"OLAYLAR_EK5:1899-11-27:0":{"b": ["Concessie voor de lijn Konya–Bagdad aan de Duitsers", "fd8b6cbd"], "d": ["Na het bezoek van keizer Wilhelm II aan Constantinopel en Damascus in 1898 werd aan de Anatolische Spoorwegmaatschappij de voorconcessie verleend voor een lijn van Konya naar Bagdad en Basra. Het Bagdad-spoorwegproject betekende voor de Osmanen het versterken van de centrale controle over de Arabische provincies en voor Duitsland het bereiken van de Perzische Golf. Dit project, waartegen Engeland en Rusland zich hevig verzetten, werd een van de meest omstreden dossiers van de imperialistische rivaliteit die naar de Eerste Wereldoorlog leidde.", "0de9d1cf"]},
"OLAYLAR_EK5:1900-09-01:0":{"b": ["Begin van de bouw van de Hidjaz-spoorlijn in Damascus", "62f58f68"], "d": ["De lijn die Abdülhamid II beval met zijn irade van 2 mei 1900, begon met de bouw op 1 september 1900 in een officiële ceremonie in Damascus. Het project, dat volledig werd uitgevoerd met donaties uit de islamitische wereld en de arbeid van Osmaanse ingenieur-soldaten, bracht de reis van pelgrims tussen Damascus en Medina terug van veertig dagen tot vijf dagen. Het was zowel een prestigewerk dat het morele gezag van het kalifaat versterkte als een strategische investering die de militaire controle over de Hidjaz versterkte.", "5dedd229"]},
"OLAYLAR_EK5:1903-10-02:0":{"b": ["Mürzsteg-programma: internationale hervormingscontrole in Macedonië", "4c7464da"], "d": ["Na de Ilinden-opstand ontmoetten de Russische en Oostenrijkse keizers elkaar in Mürzsteg en bereidden een nieuw hervormingspakket voor Macedonië voor. Het programma voorzag in het plaatsen van twee buitenlandse burgerlijke agenten naast de Osmaanse inspecteur-generaal, het herorganiseren van de gendarmerie door Europese officieren en het wijzigen van de administratieve grenzen op basis van nationaliteit. Hoewel de Hoge Porte zich verzette met als reden dat haar soevereine rechten werden geschonden, moest zij onder gezamenlijke druk aanvaarden; het programma werd een van de voornaamste factoren die de Unionistische organisatie onder de jonge officieren versnelde.", "b56ab15c"]},
"OLAYLAR_EK5:1905-04-01:0":{"b": ["Verlies van Sanaa aan Imam Yahya", "e7f876cb"], "d": ["De opstand die de Zaidi-imam Yahya Hamid ad-Din in 1904 begon, eindigde in april 1905 met de val van Sanaa na een beleg; de stad verliet het Osmaanse bestuur en tijdens het beleg braken honger en epidemieën uit. De bergachtige geografie van Jemen, de lengte van de bevoorradingslijnen en de lokale legitimiteit van het Zaidi-imamaat maakten de Osmaanse heerschappij daar vanaf haar stichting kwetsbaar. De stad zou vijf maanden later tegen zware verliezen worden teruggenomen, maar het Jemen-probleem zou tot 1918 niet worden gesloten.", "702b0ff5"]},
"OLAYLAR_EK5:1905-07-21:0":{"b": ["Aanslag in Yıldız: bomaanslag op Abdülhamid II", "1ee2e1a6"], "d": ["De Dasjnaktsoetjoen-organisatie pleegde een aanslag door een landauer met tijdbom te laten ontploffen bij de koets van de sultan die van het vrijdagse selamlık kwam; dat Abdülhamid enkele minuten vertraging had doordat hij met de sjeik-ul-islam sprak, redde zijn leven. Bij de explosie kwamen zesentwintig mensen om en meer dan vijftig raakten gewond. Het voorval verhardde de veiligheidsobsessie van de sultan en zijn op de spionagedienst gebaseerde despotische bestuur nog meer; het werd ook het onderwerp van het gedicht 'Bir Lahza-i Taahhur' van Tevfik Fikret.", "d4f10280"]},
"OLAYLAR_EK5:1905-09-01:0":{"b": ["Herovering van Sanaa: neerslaging van de opstand van Imam Yahya", "dec3b8f9"], "d": ["De opstand die in 1904 begon onder leiding van de Zaidi-imam Yahya eindigde in april 1905 met de val van Sanaa en in de stad braken honger en epidemieën uit. De versterkingslegers onder bevel van Ali Rızâ Pasja en Ahmed Feyzi Pasja namen met de campagne die zij tussen 15 juli en 1 september 1905 voerden, ondersteund door de strijdkrachten in Taiz, de stad tegen zware verliezen terug en de opstand werd neergeslagen. De Jemen-campagne bracht het Osmaanse leger tienduizenden verliezen en een enorme financiële last; onder de officieren in Rumelië was de vrees voor 'verbanning naar Jemen' een van de voornaamste grieven die de Unionistische organisatie voedden.", "667bb98c"]},
"OLAYLAR_EK5:1908-12-17:0":{"b": ["Bijeenkomst van de eerste Meclis-i Meb'ûsan van de Tweede Constitutionele Periode", "e7fd2716"], "d": ["Het parlement, gevormd door de na dertig jaar gehouden tweetrapsverkiezingen, werd op 17 december 1908 geopend met de troonrede van de sultan en Ahmed Rızâ Bey, de leider van de Jongturkse beweging, werd tot voorzitter gekozen. Het parlement, bestaande uit Turkse, Arabische, Albanese, Griekse, Armeense en Joodse afgevaardigden, was de laatste grote proef van het ideaal van het Osmanisme. Maar de onafhankelijkheid van Bulgarije, de annexatie van Bosnië en de proclamatie van de aansluiting van Kreta bij Griekenland hadden dit optimisme al overschaduwd voordat het parlement was geopend.", "b408f232"]},
"OLAYLAR_EK5:1909-04-27:0":{"b": ["Actieleger en afzetting van Abdülhamid II: troonsbestijging van Mehmed V Reşad", "6a65a704"], "d": ["Het Actieleger, dat na het Incident van 31 maart uit Thessaloniki vertrok, trok in de nacht van 22-23 april in vier colonnes Constantinopel binnen en op 24 april gaf het Yıldız-paleis zich over. De Meclis-i Umûmî-i Millî besloot op 27 april tot de afzetting van Abdülhamid II; de sultan werd naar Thessaloniki gezonden en zijn broer Mehmed V Reşad werd op de troon gezet. Het persoonlijke bewind van drieëndertig jaar kwam zo ten einde, maar werd opgevolgd door een nieuw tijdperk waarin de sultan een symbool werd en het Comité voor Eenheid en Vooruitgang met steun van het leger regeerde.", "496ff2f2"]},
"OLAYLAR_EK5:1910-04-01:0":{"b": ["Albanese opstand: gewapend verzet in Kosovo en Shkodër", "93ed30c6"], "d": ["Het centralistische belastingbeleid van de Unionistische regering, de wapeninzamelingscampagne en de discussie over het Latijnse alfabet brachten de Albanese stammen, die tot dan toe tot de trouwste elementen van de staat werden gerekend, in opstand. Hoewel het leger onder bevel van Mahmud Şevket Pasja de opstand hard neersloeg, laaide de onrust in 1911 en 1912 opnieuw op. Deze opstanden putten het Osmaanse leger aan de vooravond van de Balkanoorlog uit en versnelden ook de geboorte van de Albanese nationale beweging.", "18d0ffb5"]},
"OLAYLAR_EK5:1912-10-18:0":{"b": ["Verdrag van Ouchy: Tripolitanië en Benghazi aan Italië gelaten", "4ffa1fd2"], "d": ["De Hoge Porte, die tegenover de oorlogsvoorbereiding van de Balkanstaten een gevecht aan twee fronten niet aandurfde, sloot in het Zwitserse stadje Ouchy een geheime vrede met Italië en liet Tripolitanië en Benghazi achter. De Osmaanse staat verloor zo zijn laatste grondgebied in Afrika; daartegenover werd de teruggave van het door Italië bezette Rhodos en de Dodekanesos beloofd, maar deze belofte werd nooit nagekomen. Toen het verdrag werd ondertekend, was de Balkanoorlog al begonnen. Met deze gebeurtenis gingen Murzuk (Fezzan), Ghat, Sabha, Ubari, Traghan, Zawila en al-Qatrun (Fezzan (sandjak van de provincie Tripolitanië)) over naar Italiaans bestuur.", "5896634d"]},
"OLAYLAR_EK5:1913-06-11:0":{"b": ["Moord op grootvizier Mahmud Şevket Pasja in Constantinopel", "68e60e63"], "d": ["Mahmud Şevket Pasja, die na de Overval op de Hoge Porte tot grootvizier was benoemd, werd op weg naar het ministerie van Oorlog bij Çarşıkapı gedood door vuur op zijn koets. Het Comité voor Eenheid en Vooruitgang schoof de aanslag in de schoenen van de oppositie en begon een brede golf van arrestaties en executies; de Partij voor Vrijheid en Overeenstemming werd feitelijk geliquideerd. Met dit voorval werd de eenpartijdictatuur van de Unionisten, gebaseerd op het trio Enver-Talat-Cemal, definitief gevestigd.", "203085f0"]},
"OLAYLAR_EK5:1913-06-29:0":{"b": ["Begin van de Tweede Balkanoorlog: verdelingsstrijd van de bondgenoten", "48d088a2"], "d": ["De Balkanbondgenoten, die de met het Verdrag van Londen op de Osmanen veroverde gebieden niet konden verdelen, raakten met elkaar slaags; de tweede oorlog begon doordat Bulgarije de Servische en Griekse stellingen aanviel. Toen ook Roemenië en Montenegro tegen Bulgarije het front betraden, stortte het Bulgaarse leger in. De Osmaanse staat maakte van deze gelegenheid gebruik, overschreed de door het Verdrag van Londen getrokken lijn Midye-Enez en nam Oost-Thracië samen met Edirne terug.", "33183400"]},
"OLAYLAR_EK5:1913-09-29:0":{"b": ["Verdrag van Constantinopel: vrede met Bulgarije en bevestiging van Edirne", "c8c18b2d"], "d": ["Het verdrag dat na de Tweede Balkanoorlog tussen de Osmaanse staat en Bulgarije werd ondertekend, aanvaardde de Maritsa als grens en bevestigde juridisch dat Edirne, Kırklareli, Dimetoka en Oost-Thracië Osmaans bleven. Dedeağaç (Alexandroupoli) werd aan Bulgarije gelaten (Kavala was na de Bulgaarse bezetting van de herfst van 1912 in juli 1913 naar Griekenland gegaan en werd op 10 augustus 1913 met het Verdrag van Boekarest in Griekenland bevestigd); de wederzijdse bevolkingsuitwisseling tussen de twee landen en de rechten van de moslims in Bulgarije werden geregeld. De garantie voor het enige stuk grondgebied dat uit de Balkanramp kon worden teruggenomen, is deze tekst. Andere plaatsen die op dezelfde datum werden toegevoegd: Gümülcine.", "1fe8a2f6"]},
"OLAYLAR_EK5:1913-11-14:0":{"b": ["Verdrag van Athene: vrede met Griekenland en overdracht van Thessaloniki-Ioannina", "8e94def7"], "d": ["Het verdrag dat tussen de Osmaanse staat en Griekenland werd ondertekend, erkende formeel de overgang naar Griekenland van Thessaloniki, Ioannina en Zuid-Macedonië, die in de Balkanoorlog waren verloren, en er werd afgezien van de Osmaanse rechten over Kreta. De rechten op godsdienst en eigendom van de in Griekenland achtergebleven moslims, de status van de vakoefs en de benoeming van muftis werden gedetailleerd geregeld. De status van de Egeïsche eilanden werd onopgelost gelaten en bleef een bron van voortdurende spanning tussen beide staten.", "a5ae7115"]},
"OLAYLAR_EK5:1914-08-02:0":{"b": ["Ondertekening van het geheime Osmaans-Duitse bondgenootschapsverdrag in Constantinopel", "0472efb3"], "d": ["Zodra in Europa de oorlog uitbrak, werd in het herenhuis van grootvizier Said Halim Pasja een geheim bondgenootschapsverdrag tussen de Osmaanse staat en Duitsland ondertekend; de tekst voorzag dat de Osmanen zich aan Duitse zijde zouden scharen indien Rusland tegen Duitsland ten strijde trok. Het verdrag werd zelfs voor het kabinet verborgen gehouden en was slechts aan vier personen bekend. Drie maanden later zou de Osmaanse staat met de overval op de Zwarte Zee feitelijk in de oorlog worden meegesleept, het lot van het rijk was met dit document verbonden.", "063ef809"]},
"OLAYLAR_EK5:1914-09-09:0":{"b": ["Eenzijdige afschaffing van de capitulaties", "ec773d18"], "d": ["De Osmaanse regering verklaarde op een moment dat Europa met de oorlog bezig was, dat zij de capitulaties, die aan buitenlanders gerechtelijke, financiële en douaneprivileges verleenden, met ingang van 1 oktober 1914 eenzijdig had afgeschaft. Het einde van deze vierhonderd jaar oude privilegeorde werd in het land met groot enthousiasme voor de onafhankelijkheid ontvangen en in Constantinopel werden feesten gehouden. Alle staten, ook de bondgenoot Duitsland, protesteerden tegen het besluit; de capitulaties zouden pas in 1923 in Lausanne definitief tot het verleden gaan behoren.", "b30c11aa"]},
"OLAYLAR_EK5:1914-10-29:0":{"b": ["Overval op de Zwarte Zee: bombardement van Russische havens door de Osmaanse vloot", "8ad4ef61"], "d": ["De uit Duitsland ontsnapte en 'gekochte' Goeben en Breslau (Yavuz en Midilli), die zich bij de Osmaanse vloot voegden, voeren onder bevel van admiraal Souchon naar de Zwarte Zee, beschoten Russische havens en lieten schepen zinken. Dit bevel, dat Enver Pasja buiten het kabinet om gaf, maakte feitelijk een einde aan de neutraliteit. Binnen een week verklaarden Rusland, Engeland en Frankrijk de oorlog en de Osmaanse staat trad onherroepelijk de Eerste Wereldoorlog in.", "bdd1c93a"]},
"OLAYLAR_EK5:1914-11-06:0":{"b": ["Inname van Fao door Brits-Indische strijdkrachten — opening van het Iraakse front", "08663813"], "d": ["Op de ochtend na de dag dat de Entente-mogendheden de Osmaanse staat de oorlog verklaarden, ging de Brits-Indische brigade die in Bahrein wachtte aan land bij Fao aan de monding van de Shatt al-Arab. De kleine Osmaanse eenheid in de vervallen burcht van Fao trok zich onder vuur van de oorlogsschepen terug en het station van de Indische telegraaflijn kwam in Britse handen. Zo werd het Iraakse front geopend.", "7da97cb0"]},
"OLAYLAR_EK5:1914-11-14:0":{"b": ["Afkondiging van de Grote Jihad: voorlezing van de jihad-fatwa in de Fatih-moskee", "2a6174e8"], "d": ["De vijf fatwa's die sjeik-ul-islam Ürgüplü Hayri Efendi gaf, werden in naam van de kalief-sultan in de Fatih-moskee voorgelezen en alle moslims werden opgeroepen tot de jihad tegen de Entente-mogendheden. Deze zet, waarop Duitsland grote hoop vestigde, was erop gericht de moslims in de Britse en Franse koloniën in opstand te brengen. De verwachte algemene opstand kwam niet; integendeel, de opstand van sjerief Hoessein, de emir van Mekka, twee jaar later met Britse steun toonde op pijnlijke wijze de grenzen van de politieke invloed van het kalifaat.", "e5a86763"]},
"OLAYLAR_EK5:1914-12-09:0":{"b": ["Overgave van Qurna aan de Britten", "621d36b0"], "d": ["De strijdkrachten van Subhi Bey, de gouverneur van Basra, die zich na de val van Basra hadden teruggetrokken naar Qurna, waar de Tigris en de Eufraat samenvloeien, gaven zich na de gevechten van 4-8 december op de ochtend van 9 december 1914 over.", "ff45626a"]},
"OLAYLAR_EK5:1914-12-18:0":{"b": ["Egypte onder Britse bescherming gebracht en sultanaat uitgeroepen", "55d4e520"], "d": ["Toen de Osmaanse staat de oorlog inging, verklaarde Engeland dat het Egypte, dat het sinds 1882 feitelijk bezet hield, formeel onder zijn bescherming nam; khedive Abbas Hilmi Pasja, die trouw aan de Osmanen bleef, werd afgezet en Hüseyin Kâmil werd met de titel 'sultan' in zijn plaats gezet. Zo werd de sinds 1517 durende juridische Osmaanse soevereiniteit eenzijdig beëindigd. De Hoge Porte erkende het besluit niet en deed twee maanden later met de Kanaalcampagne een poging Egypte terug te nemen.", "0eae0c0c"]},
"OLAYLAR_EK5:1914-12-22:0":{"b": ["Campagne van Sarıkamış: ramp aan het Kaukasusfront", "5cbde7f0"], "d": ["Enver Pasja, die de in 1878 verloren Kars-Ardahan-Batoem wilde terugnemen en de Turken in de Kaukasus in opstand wilde brengen, stuurde het 3e Leger in de winter over de Allahuekber-bergen in een manoeuvre om de Russische strijdkrachten te omsingelen. Door onvoldoende winteruitrusting, uitgeputte bevoorrading en sneeuwstormen tot min dertig graden smolt het leger weg voordat het in de strijd kwam; tienduizenden soldaten stierven door bevriezing. De campagne werd een van de zwaarste rampen van de Osmanen in de oorlog en liet het oostfront twee jaar onverdedigd.", "f5289317"]},
"OLAYLAR_EK5:1915-01-14:0":{"b": ["Eerste Kanaalcampagne: aanval op Suez over de Sinaïwoestijn", "02dd72f5"], "d": ["Cemal Pasja, de commandant van het 4e Leger, voerde een offensief over de Sinaïwoestijn uit om Egypte van de Britse bezetting te bevrijden en het Suezkanaal voor het verkeer te sluiten. Hoewel de Osmaanse troepen de oostoever van het kanaal bereikten en een deel erin slaagde over te steken, trokken zij zich terug wegens de Britse overmacht en omdat de verwachte Egyptische volksopstand uitbleef. De campagne bereikte haar doel niet, maar had een indirect strategisch effect doordat zij Engeland dwong een grote troepenmacht in Egypte te houden.", "d9d0152c"]},
"OLAYLAR_EK5:1915-05-27:0":{"b": ["Uitvaardiging van de Wet op Verzending en Vestiging (Tehcir)", "2f2bc22c"], "d": ["Na de opstand in Van en de Russische opmars vaardigde de regering de tijdelijke wet uit die de legercommandanten toestond de bevolking die werd geacht de veiligheid achter het front te verstoren naar andere regio's over te brengen, en de sultan bekrachtigde haar op 27 mei 1915. Als gevolg van de toepassing werd het grootste deel van de Armeense bevolking in de oostelijke en zuidelijke provincies van Anatolië in de richting van Syrië en Mosul verzonden; tijdens het transport vielen door ziekte, honger en aanvallen zeer grote aantallen doden. Het besluit is gebleven als de zwaarste en ook vandaag nog meest omstreden kwestie van de laatste jaren van de Osmanen.", "e8af8dee"]},
"OLAYLAR_EK5:1918-02-10:0":{"b": ["Overlijden van Abdülhamid II in het Beylerbeyi-paleis", "c9662582"], "d": ["Abdülhamid II, die in 1909 was afgezet en eerst naar Thessaloniki en na het verlies van de stad in de Balkanoorlog naar Constantinopel was gebracht en in het Beylerbeyi-paleis onder huisarrest werd gehouden, stierf. Tijdens zijn regering van drieëndertig jaar had hij geprobeerd tijd te winnen door de staat uit oorlogen te houden, maar werd ook herinnerd om zijn despotische bestuur. Zijn lichaam werd met een grote menigte begraven in het mausoleum van Mahmud I aan de Divanyolu; zijn dood viel in een oorlogsjaar waarin de orde die hij had gevestigd al lang was geliquideerd.", "241489b4"]},
"OLAYLAR_EK5:1918-03-03:0":{"b": ["Verdrag van Brest-Litovsk: herovering van Kars, Ardahan en Batoem", "da82636f"], "d": ["Het verdrag dat werd ondertekend tussen het Rusland dat zich na de bolsjewistische revolutie uit de oorlog had teruggetrokken en de Centrale Mogendheden, sloot het oostfront en gaf de Osmaanse staat Kars, Ardahan en Batoem (Elviye-i Selâse) terug, die met het Verdrag van Berlijn van 1878 waren verloren. Dit was de enige gebiedswinst die de Osmanen na veertig jaar behaalden. Maar na de Wapenstilstand van Moudros zou de regio opnieuw verloren gaan, de definitieve oplossing kwam met het Verdrag van Kars van 1921.", "f6f15123"]},
"OLAYLAR_EK5:1918-07-03:0":{"b": ["Overlijden van Mehmed V Reşad en troonsbestijging van Mehmed VI Vahdeddin", "d302ba07"], "d": ["Mehmed V Reşad, wiens regering van negen jaar werd doorgebracht met de Tripolitaanse, Balkan- en Wereldoorlogen, stierf in de meest kritieke periode van de oorlog en zijn broer Vahdeddin besteeg als Mehmed VI de troon. De nieuwe sultan probeerde zich van de voogdij van het Unionistische kader te bevrijden; toen vier maanden later de wapenstilstand werd getekend, zou hij de liquidatie van het rijk moeten leiden. Hij was de zesendertigste en laatste sultan van de Osmaanse dynastie.", "2d9306b3"]},
"OLAYLAR_EK5:1918-11-13:0":{"b": ["Komst van de Entente-vloot voor Constantinopel en feitelijke bezetting van de stad", "d10cb14d"], "d": ["Na de Wapenstilstand van Moudros ging een geallieerde vloot van meer dan zestig schepen, bestaande uit Britse, Franse, Italiaanse en Griekse schepen, voor Dolmabahçe voor anker en werd Constantinopel feitelijk bezet. Na vierhonderdvijfenzestig jaar kwam de hoofdstad voor het eerst onder controle van buitenlandse soldaten. De uitspraak 'Zoals ze gekomen zijn, zullen ze gaan', die Mustafa Kemal Pasja volgens de overlevering deed toen hij op dezelfde dag in Haydarpaşa aankwam en het tafereel zag, zou een van de symbolische zinnen van de Nationale Strijd worden.", "30db4974"]},
"OLAYLAR_EK5:1919-07-23:0":{"b": ["Congres van Erzurum: nationaal verzetsbesluit van de oostelijke provincies", "41ef0457"], "d": ["Het congres, bijeengeroepen door het Genootschap voor Verdediging van de Rechten van Oost-Anatolië, werd na uitstel door Britse druk met zesenvijftig afgevaardigden geopend en Mustafa Kemal Pasja, die uit het leger was getreden, werd tot voorzitter gekozen. Het congres verklaarde dat het vaderland binnen de nationale grenzen een geheel was, dat mandaat en protectoraat niet konden worden aanvaard en dat de natie, indien de regering uiteenviel, haar eigen lot in handen zou nemen. Deze besluiten zouden zes maanden later de kern van de tekst van het Nationale Pact vormen.", "925ca450"]},
"OLAYLAR_EK5:1919-09-04:0":{"b": ["Congres van Sivas: nationaal verzet verenigd onder één dak", "0e9ad36b"], "d": ["Het congres, dat op 4 september 1919 zijn werkzaamheden begon in de Sivas Sultânîsi, verenigde de genootschappen voor verdediging van de rechten uit alle delen van het land onder de naam Genootschap voor Verdediging van de Rechten van Anatolië en Rumelië en koos een Vertegenwoordigend Comité (Heyet-i Temsîliyye). Het voorstel voor een Amerikaans mandaat werd na lange discussies verworpen. Met de op 11 september gepubliceerde verklaring werd de Nationale Strijd een legitieme politieke beweging met één centrum en begon een openlijke machtsstrijd met de regering van Constantinopel.", "9e4ba0a0"]},
"OLAYLAR_EK5:1919-10-22:0":{"b": ["Protocol van Amasya: gesprekken tussen de regering van Constantinopel en het Vertegenwoordigend Comité", "40e6a6ab"], "d": ["Nadat Damat Ferid was gevallen en de regering van Ali Rızâ Pasja was gevormd, werd minister van Marine Salih Pasja naar Amasya gezonden om met het Vertegenwoordigend Comité te spreken. Met de bereikte protocollen erkende de regering van Constantinopel feitelijk het bestaan van de Anatolische beweging; de bijeenroeping van de Meclis-i Meb'ûsan, vrije verkiezingen en het behoud van de nationale grenzen werden aanvaard. Dit is de eerste officiële politieke winst die de Nationale Strijd tegenover Constantinopel behaalde.", "721d202a"]},
"OLAYLAR_EK5:1920-01-28:0":{"b": ["Aanvaarding van het Nationale Pact in de laatste Osmaanse Vergadering", "6322865e"], "d": ["De tekst van het Misâk-ı Millî (Ahd-i Millî), ondertekend door 121 afgevaardigden in de laatste Osmaanse Meclis-i Meb'ûsan, stelde als voorwaarde de ondeelbare eenheid van de gebieden binnen de lijn van Moudros waar de Turks-moslimse meerderheid woonde, een volksstemming in de Arabische provincies en West-Thracië, de afschaffing van de capitulaties en volledige politieke en financiële onafhankelijkheid. De tekst werd op 17 februari 1920 met algemene stemmen aanvaard en aan de wereld bekendgemaakt. Deze verklaring was zowel het politieke programma van de Nationale Strijd als de kaart van de grenzen die in Lausanne zouden worden verdedigd; zij werd de directe reden dat de Entente-mogendheden op 16 maart Constantinopel formeel bezetten.", "576d2af5"]}
});
